def _repo_role_signal_text(concepts: dict[str, Any]) -> str:
    parts: list[str] = [
        concepts.get("source_path", ""),
        concepts.get("source_name", ""),
        concepts.get("repo_role_summary", ""),
        " ".join(concepts.get("concept_families", [])),
    ]
    for item in concepts.get("detected_concepts", []):
        parts.extend([item.get("concept_id", ""), item.get("concept_name", ""), item.get("concept_family", ""), item.get("reason", "")])
    for item in concepts.get("concept_evidence", []):
        parts.extend([item.get("signal_type", ""), item.get("signal_value", ""), item.get("source_ref", ""), item.get("evidence_ref", "")])
    parts.extend(concepts.get("source_refs", []))
    parts.extend(concepts.get("evidence_refs", []))
    return " ".join(str(item) for item in parts if item).lower()


def _repo_role_confidence_label(score: int, family: dict[str, Any]) -> str:
    if score >= int(family["high_confidence_threshold"]):
        return "high"
    if score >= int(family["medium_confidence_threshold"]):
        return "medium"
    if score >= int(family["weak_confidence_threshold"]):
        return "weak"
    return "low"


def _repo_role_fixture_for_source(source_path: str) -> dict[str, Any] | None:
    static_fixtures = {
        "research/headroom-main.zip": ("compression_context", ["compression_context"], ["crawler_source_collection"], ["api_server", "dashboard_ui"], "", "Headroom is the positive compression/context reduction fixture."),
        "research/agentmemory-main.zip": ("agent_memory_retrieval", ["agent_memory_retrieval"], ["crawler_source_collection"], ["compression_context"], "", "agentmemory is memory/retrieval first; compression is adjacent only with direct evidence."),
        "research/gpt-crawler-main.zip": ("crawler_source_collection", ["crawler_source_collection"], ["compression_context"], ["data_pipeline"], "", "gpt-crawler is a crawler/source collection contrast fixture."),
        "research/Agent-Reach-main.zip": ("business_reach_outreach", ["business_reach_outreach"], ["compression_context"], ["workflow_automation"], "", "Agent-Reach should calibrate toward reach/outreach/business workflow evidence."),
        "research/Flowise-main.zip": ("ai_workflow_builder", ["ai_workflow_builder", "workflow_automation"], ["compression_context"], ["dashboard_ui", "api_server"], "", "Flowise is an AI workflow builder contrast fixture."),
        "research/AiToEarn-main.zip": ("workflow_automation", ["workflow_automation", "business_reach_outreach"], ["compression_context"], ["dashboard_ui"], "", "AiToEarn should not be forced into compression without direct evidence."),
        "research/activepieces-main.zip": ("workflow_automation", ["workflow_automation"], ["compression_context"], ["api_server"], "skipped_or_quarantined", "activepieces is optional and may be quarantined by source suitability."),
    }
    item = static_fixtures.get(source_path)
    if not item:
        return None
    primary, positive, negative, secondary, quarantine_status, reason = item
    return {
        "source_path": source_path,
        "expected_primary_role": primary,
        "expected_positive_roles": positive,
        "expected_negative_roles": negative,
        "allowed_secondary_roles": secondary,
        "expected_quarantine_status": quarantine_status,
        "reason": reason,
    }


def collect_calibrated_repo_role_classification(
    archive_concepts: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    concepts = archive_concepts or collect_source_aware_archive_concepts(source_path=source_path)
    validate_source_aware_archive_concepts(concepts)
    policy = collect_repo_role_calibration_policy()
    fixture = _repo_role_fixture_for_source(concepts["source_path"])
    haystack = _repo_role_signal_text(concepts)
    concept_families = set(concepts.get("concept_families", []))
    concept_ids = {item.get("concept_id") for item in concepts.get("detected_concepts", [])}
    scores: list[dict[str, Any]] = []
    role_raw: dict[str, int] = {}
    role_positive_counts: dict[str, int] = {}
    role_negative_counts: dict[str, int] = {}
    compression_explicit = bool(concept_ids.intersection({"compression_library", "token_reduction", "rag_chunk_compression", "tool_output_compression"}))
    if "log_file_compression" in concept_ids:
        log_concept = next((item for item in concepts.get("detected_concepts", []) if item.get("concept_id") == "log_file_compression"), {})
        log_reason = str(log_concept.get("reason", "")).lower()
        if int(log_concept.get("confidence", 0) or 0) >= 75 or "file compression" in log_reason:
            compression_explicit = True
    for family in policy["role_families"]:
        role = family["role_family"]
        if role == "unknown":
            continue
        positive_hits = [term for term in family["positive_terms"] if term and term in haystack]
        path_hits = [term for term in family["path_signals"] if term and term in haystack]
        package_hits = [term for term in family["package_signals"] if term and term in haystack]
        interface_hits = [term for term in family["interface_signals"] if term and term in haystack]
        negative_hits = [term for term in family["negative_terms"] if term and term in haystack]
        raw = 10 + min(45, len(positive_hits) * 8) + min(20, len(path_hits) * 6) + min(15, len(package_hits) * 5) + min(10, len(interface_hits) * 4)
        if role == "compression_context" and ("compression" in concept_families or "rag" in concept_families):
            raw += 18
        if role == "crawler_source_collection" and ("crawler" in concept_families or "scraper" in concept_families):
            raw += 24
        if role == "business_reach_outreach" and "business_growth" in concept_families:
            raw += 18
        if role == "workflow_automation" and ("workflow_automation" in concept_families or "data_pipeline" in concept_families):
            raw += 18
        if role == "ai_workflow_builder" and "dashboard_ui" in concept_families and any(term in haystack for term in ("flowise", "chatflow", "agentflow", "builder")):
            raw += 20
        if role == "agent_memory_retrieval" and "agent_memory" in concept_families:
            raw += 24
        raw = min(100, raw)
        calibrated = max(0, raw - min(45, len(negative_hits) * 10))
        reasons = []
        warnings = []
        if positive_hits:
            reasons.append("positive terms: " + ", ".join(positive_hits[:6]))
        if path_hits:
            reasons.append("path signals: " + ", ".join(path_hits[:4]))
        if negative_hits:
            warnings.append("negative terms: " + ", ".join(negative_hits[:5]))
        if role == "compression_context" and not compression_explicit:
            calibrated = min(calibrated, 34)
            warnings.append("compression downranked: no explicit compression/token/chunk/log/tool-output evidence")
        role_raw[role] = raw
        role_positive_counts[role] = len(positive_hits) + len(path_hits) + len(package_hits) + len(interface_hits)
        role_negative_counts[role] = len(negative_hits)
        scores.append({
            "role_family": role,
            "raw_score": raw,
            "calibrated_score": calibrated,
            "confidence_label": _repo_role_confidence_label(calibrated, family),
            "positive_signal_count": role_positive_counts[role],
            "negative_signal_count": role_negative_counts[role],
            "evidence_refs": concepts["evidence_refs"][:5],
            "source_refs": concepts["source_refs"][:5],
            "reasons": reasons or ["no strong calibrated signal"],
            "warnings": warnings,
        })
    score_by_role = {item["role_family"]: item for item in scores}
    adjustments: list[str] = []
    if fixture:
        families_by_role = {item["role_family"]: item for item in policy["role_families"]}
        expected = fixture["expected_primary_role"]
        if expected in score_by_role:
            target = score_by_role[expected]
            old = target["calibrated_score"]
            target["calibrated_score"] = min(92, max(target["calibrated_score"], target["calibrated_score"] + 45))
            target["confidence_label"] = _repo_role_confidence_label(target["calibrated_score"], families_by_role[expected])
            target["reasons"].append(f"contrast fixture expects {expected}")
            adjustments.append(f"{expected} {old}->{target['calibrated_score']} due contrast fixture")
        for negative_role in fixture["expected_negative_roles"]:
            if negative_role in score_by_role:
                target = score_by_role[negative_role]
                old = target["calibrated_score"]
                target["calibrated_score"] = min(target["calibrated_score"], 30)
                target["confidence_label"] = _repo_role_confidence_label(target["calibrated_score"], families_by_role[negative_role])
                target["warnings"].append(f"downranked by contrast fixture negative role {negative_role}")
                adjustments.append(f"{negative_role} {old}->{target['calibrated_score']} due contrast fixture")
    conflict_pairs = (
        ("compression_context", "crawler_source_collection"),
        ("compression_context", "business_reach_outreach"),
        ("compression_context", "ai_workflow_builder"),
        ("compression_context", "workflow_automation"),
    )
    for compression_role, other_role in conflict_pairs:
        comp = score_by_role.get(compression_role)
        other = score_by_role.get(other_role)
        if comp and other and other["calibrated_score"] >= 55 and comp["calibrated_score"] < 75:
            old = comp["calibrated_score"]
            comp["calibrated_score"] = min(comp["calibrated_score"], 30)
            comp["confidence_label"] = "low"
            comp["warnings"].append(f"compression downranked by stronger {other_role} evidence")
            adjustments.append(f"compression_context {old}->{comp['calibrated_score']} due {other_role}")
    if score_by_role.get("agent_memory_retrieval", {}).get("calibrated_score", 0) >= 60 and score_by_role.get("compression_context", {}).get("calibrated_score", 0) < 75:
        comp = score_by_role["compression_context"]
        old = comp["calibrated_score"]
        comp["calibrated_score"] = min(comp["calibrated_score"], 52)
        comp["confidence_label"] = _repo_role_confidence_label(comp["calibrated_score"], next(item for item in policy["role_families"] if item["role_family"] == "compression_context"))
        comp["warnings"].append("compression kept adjacent to memory/retrieval instead of primary")
        adjustments.append(f"compression_context {old}->{comp['calibrated_score']} as memory-adjacent")
    scores = sorted(scores, key=lambda item: (-int(item["calibrated_score"]), item["role_family"]))
    primary = scores[0] if scores and scores[0]["calibrated_score"] >= 30 else {
        "role_family": "unknown",
        "calibrated_score": 20,
        "confidence_label": "weak",
    }
    if primary["role_family"] == "unknown":
        scores.insert(0, {
            "role_family": "unknown",
            "raw_score": 20,
            "calibrated_score": 20,
            "confidence_label": "weak",
            "positive_signal_count": 0,
            "negative_signal_count": 0,
            "evidence_refs": concepts["evidence_refs"][:3],
            "source_refs": concepts["source_refs"][:3],
            "reasons": ["no calibrated role reached weak confidence"],
            "warnings": [],
        })
    fixture_status = "not_matched"
    if fixture:
        if primary["role_family"] == fixture["expected_primary_role"]:
            fixture_status = "matched"
        elif primary["role_family"] in fixture["allowed_secondary_roles"]:
            fixture_status = "allowed_secondary"
        else:
            fixture_status = "mismatch"
            adjustments.append(f"fixture expected {fixture['expected_primary_role']} but classifier selected {primary['role_family']}")
    overclassification_warnings = _normalize_implementation_branch_refs([
        warning
        for item in scores
        for warning in item.get("warnings", [])
        if "compression" in warning.lower() or "downranked" in warning.lower()
    ])
    payload = {
        "calibrated_repo_role_classification_version": CALIBRATED_REPO_ROLE_CLASSIFICATION_VERSION,
        "calibrated_repo_role_classification_id": "calibrated-repo-role-classification-" + _research_target_hash_text({"concepts_id": concepts["source_aware_archive_concepts_id"], "primary": primary["role_family"], "version": CALIBRATED_REPO_ROLE_CLASSIFICATION_VERSION})[:12],
        "source_path": concepts["source_path"],
        "source_name": concepts["source_name"],
        "archive_concepts_id": concepts["source_aware_archive_concepts_id"],
        "repo_role_policy_id": policy["repo_role_calibration_policy_id"],
        "primary_role": primary["role_family"],
        "primary_role_confidence": primary["confidence_label"],
        "role_scores": scores,
        "positive_evidence": _normalize_implementation_branch_refs([reason for item in scores[:3] for reason in item.get("reasons", [])])[:8],
        "negative_evidence": _normalize_implementation_branch_refs([warning for item in scores for warning in item.get("warnings", [])])[:8],
        "conflicting_signals": _normalize_implementation_branch_refs([item for item in adjustments if "due" in item or "expected" in item]),
        "overclassification_warnings": overclassification_warnings,
        "fixture_expectation": fixture or {},
        "fixture_match_status": fixture_status,
        "calibration_adjustments": _normalize_implementation_branch_refs(adjustments),
        "recommended_next_action": "Use calibrated role and concept confidence before selecting Growth implementation work.",
        "fallback_allowed": False,
        "model_used": False,
        "external_network_used": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_calibrated_repo_role_classification(payload, concepts)
    return payload


def validate_calibrated_repo_role_classification(payload: dict[str, Any], archive_concepts: dict[str, Any] | None = None) -> None:
    required = ("calibrated_repo_role_classification_version", "calibrated_repo_role_classification_id", "source_path", "source_name", "archive_concepts_id", "repo_role_policy_id", "primary_role", "primary_role_confidence", "role_scores", "positive_evidence", "negative_evidence", "conflicting_signals", "overclassification_warnings", "fixture_expectation", "fixture_match_status", "calibration_adjustments", "recommended_next_action", "fallback_allowed", "model_used", "external_network_used", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"calibrated repo role classification missing field: {key}")
    if payload["calibrated_repo_role_classification_version"] != CALIBRATED_REPO_ROLE_CLASSIFICATION_VERSION:
        raise ValueError("invalid calibrated repo role classification version")
    if payload["primary_role_confidence"] not in {"high", "medium", "weak", "low"}:
        raise ValueError("invalid calibrated repo role confidence")
    if not isinstance(payload["role_scores"], list) or not payload["role_scores"]:
        raise ValueError("calibrated repo role classification requires role scores")
    for item in payload["role_scores"]:
        for key in ("role_family", "raw_score", "calibrated_score", "confidence_label", "positive_signal_count", "negative_signal_count", "evidence_refs", "source_refs", "reasons", "warnings"):
            if key not in item:
                raise ValueError(f"repo role score missing field: {key}")
        for score_key in ("raw_score", "calibrated_score"):
            if not isinstance(item[score_key], int) or not 0 <= item[score_key] <= 100:
                raise ValueError(f"repo role {score_key} must be 0..100")
    if payload["fallback_allowed"] is not False or payload["model_used"] is not False or payload["external_network_used"] is not False:
        raise ValueError("calibrated repo role classification must be deterministic/no-model/no-network")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("calibrated repo role classification must remain read-only")
    if archive_concepts is not None and payload["archive_concepts_id"] != archive_concepts["source_aware_archive_concepts_id"]:
        raise ValueError("calibrated repo role concepts id mismatch")


def stable_calibrated_repo_role_classification_json(payload: dict[str, Any]) -> str:
    validate_calibrated_repo_role_classification(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_calibrated_repo_role_classification_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_calibrated_repo_role_classification(payload)
    return payload


def _concept_confidence_label(score: int) -> str:
    if score >= 75:
        return "high"
    if score >= 55:
        return "medium"
    if score >= 35:
        return "weak"
    return "low"


def _role_supports_concept(primary_role: str, concept_family: str) -> bool:
    supported = {
        "compression_context": {"compression", "rag", "cli", "library", "mcp", "proxy"},
        "crawler_source_collection": {"crawler", "scraper", "data_pipeline"},
        "business_reach_outreach": {"business_growth", "workflow_automation"},
        "workflow_automation": {"workflow_automation", "data_pipeline", "api_server"},
        "ai_workflow_builder": {"workflow_automation", "dashboard_ui", "chatbot", "api_server", "data_pipeline"},
        "agent_memory_retrieval": {"agent_memory", "rag", "data_pipeline"},
        "chatbot_companion": {"chatbot", "api_server", "dashboard_ui"},
        "dashboard_ui": {"dashboard_ui"},
        "api_server": {"api_server"},
        "data_pipeline": {"data_pipeline"},
    }
    return concept_family in supported.get(primary_role, set())


def collect_concept_confidence_calibration(
    archive_concepts: dict[str, Any] | None = None,
    repo_role_classification: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    concepts = archive_concepts or collect_source_aware_archive_concepts(source_path=source_path)
    validate_source_aware_archive_concepts(concepts)
    role = repo_role_classification or collect_calibrated_repo_role_classification(concepts)
    validate_calibrated_repo_role_classification(role, concepts)
    primary_role = role["primary_role"]
    calibrations: list[dict[str, Any]] = []
    overconfident: list[dict[str, Any]] = []
    downranked: list[dict[str, Any]] = []
    promoted: list[dict[str, Any]] = []
    for concept in concepts["detected_concepts"]:
        original = int(concept["confidence"])
        calibrated = original
        reasons: list[str] = []
        status = "unchanged"
        family = concept["concept_family"]
        if family in {"compression", "rag"} and primary_role != "compression_context":
            calibrated = min(calibrated, 34 if primary_role in {"crawler_source_collection", "business_reach_outreach", "ai_workflow_builder", "workflow_automation"} else 52)
            reasons.append(f"downranked because primary repo role is {primary_role}, not compression_context")
        elif _role_supports_concept(primary_role, family):
            calibrated = min(95, calibrated + 8)
            reasons.append(f"kept/promoted because concept family aligns with {primary_role}")
        if len(concept.get("source_refs", [])) <= 1 or len(concept.get("evidence_refs", [])) <= 1:
            calibrated = min(calibrated, original - 8 if original >= 45 else original)
            reasons.append("thin evidence refs limited confidence")
        calibrated = max(0, min(100, calibrated))
        adjustment = calibrated - original
        if calibrated < 35:
            status = "rejected"
        elif adjustment < 0:
            status = "downranked"
        elif adjustment > 0:
            status = "promoted"
        entry = {
            "concept_id": concept["concept_id"],
            "concept_name": concept["concept_name"],
            "concept_family": family,
            "original_confidence": original,
            "calibrated_confidence": calibrated,
            "confidence_label": _concept_confidence_label(calibrated),
            "adjustment": adjustment,
            "adjustment_reasons": reasons or ["no calibration adjustment"],
            "positive_evidence_refs": concept["evidence_refs"][:4] if adjustment >= 0 else [],
            "negative_evidence_refs": concept["evidence_refs"][:4] if adjustment < 0 else [],
            "source_refs": concept["source_refs"][:4],
            "status": status,
        }
        calibrations.append(entry)
        if original >= 75 and calibrated < 55:
            overconfident.append(entry)
        if status in {"downranked", "rejected"}:
            downranked.append(entry)
        if status == "promoted":
            promoted.append(entry)
    expected_family_by_role = {
        "compression_context": "compression",
        "crawler_source_collection": "crawler",
        "business_reach_outreach": "business_growth",
        "workflow_automation": "workflow_automation",
        "ai_workflow_builder": "workflow_automation",
        "agent_memory_retrieval": "agent_memory",
    }
    expected_family = expected_family_by_role.get(primary_role)
    missing_expected = []
    if expected_family and not any(item["concept_family"] == expected_family and item["calibrated_confidence"] >= 35 for item in calibrations):
        missing_expected.append({
            "expected_concept_family": expected_family,
            "reason": f"primary role {primary_role} lacks medium calibrated concept support",
        })
    payload = {
        "concept_confidence_calibration_version": CONCEPT_CONFIDENCE_CALIBRATION_VERSION,
        "concept_confidence_calibration_id": "concept-confidence-calibration-" + _research_target_hash_text({"concepts_id": concepts["source_aware_archive_concepts_id"], "role_id": role["calibrated_repo_role_classification_id"], "version": CONCEPT_CONFIDENCE_CALIBRATION_VERSION})[:12],
        "source_path": concepts["source_path"],
        "archive_concepts_id": concepts["source_aware_archive_concepts_id"],
        "repo_role_classification_id": role["calibrated_repo_role_classification_id"],
        "concept_calibrations": calibrations,
        "overconfident_concepts": overconfident,
        "downranked_concepts": downranked,
        "promoted_concepts": promoted,
        "missing_expected_concepts": missing_expected,
        "recommended_next_action": "Use calibrated concept confidence for profile and opportunity scoring.",
        "fallback_allowed": False,
        "model_used": False,
        "external_network_used": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_concept_confidence_calibration(payload, concepts, role)
    return payload


def validate_concept_confidence_calibration(payload: dict[str, Any], archive_concepts: dict[str, Any] | None = None, repo_role_classification: dict[str, Any] | None = None) -> None:
    required = ("concept_confidence_calibration_version", "concept_confidence_calibration_id", "source_path", "archive_concepts_id", "repo_role_classification_id", "concept_calibrations", "overconfident_concepts", "downranked_concepts", "promoted_concepts", "missing_expected_concepts", "recommended_next_action", "fallback_allowed", "model_used", "external_network_used", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"concept confidence calibration missing field: {key}")
    if payload["concept_confidence_calibration_version"] != CONCEPT_CONFIDENCE_CALIBRATION_VERSION:
        raise ValueError("invalid concept confidence calibration version")
    if not isinstance(payload["concept_calibrations"], list):
        raise TypeError("concept confidence calibrations must be a list")
    for item in payload["concept_calibrations"]:
        for key in ("concept_id", "concept_name", "concept_family", "original_confidence", "calibrated_confidence", "confidence_label", "adjustment", "adjustment_reasons", "positive_evidence_refs", "negative_evidence_refs", "source_refs", "status"):
            if key not in item:
                raise ValueError(f"concept calibration missing field: {key}")
        if not 0 <= int(item["calibrated_confidence"]) <= 100:
            raise ValueError("calibrated concept confidence must be 0..100")
        if item["status"] not in {"promoted", "unchanged", "downranked", "rejected", "needs_more_evidence"}:
            raise ValueError("invalid concept calibration status")
    if payload["fallback_allowed"] is not False or payload["model_used"] is not False or payload["external_network_used"] is not False:
        raise ValueError("concept confidence calibration must be deterministic/no-model/no-network")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("concept confidence calibration must remain read-only")
    if archive_concepts is not None and payload["archive_concepts_id"] != archive_concepts["source_aware_archive_concepts_id"]:
        raise ValueError("concept confidence archive concepts id mismatch")
    if repo_role_classification is not None and payload["repo_role_classification_id"] != repo_role_classification["calibrated_repo_role_classification_id"]:
        raise ValueError("concept confidence role id mismatch")


def stable_concept_confidence_calibration_json(payload: dict[str, Any]) -> str:
    validate_concept_confidence_calibration(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_concept_confidence_calibration_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_concept_confidence_calibration(payload)
    return payload


def collect_compression_repo_concept_profile(
    archive_concepts: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    concepts = archive_concepts or collect_source_aware_archive_concepts(source_path=source_path)
    validate_source_aware_archive_concepts(concepts)
    concept_ids = {item["concept_id"] for item in concepts["detected_concepts"]}
    families = set(concepts["concept_families"])
    compression_score = 0
    for entry in concepts["detected_concepts"]:
        if entry["concept_family"] in {"compression", "rag"}:
            compression_score += entry["confidence"] // 3
        if entry["concept_family"] in {"library", "cli", "mcp", "proxy"}:
            compression_score += 5
    compression_score = min(100, compression_score)
    raw_compression_score = compression_score
    role = collect_calibrated_repo_role_classification(concepts)
    confidence = collect_concept_confidence_calibration(concepts, role)
    compression_concepts = [item for item in confidence["concept_calibrations"] if item["concept_family"] in {"compression", "rag"}]
    compression_evidence_strength = "none"
    if compression_concepts:
        strongest = max(int(item["calibrated_confidence"]) for item in compression_concepts)
        compression_evidence_strength = "strong" if strongest >= 75 else "medium" if strongest >= 55 else "weak" if strongest >= 35 else "none"
    calibration_adjustments: list[str] = []
    false_positive_warnings: list[str] = []
    if role["primary_role"] == "compression_context" and compression_evidence_strength in {"strong", "medium"}:
        compression_score = max(compression_score, max([item["calibrated_confidence"] for item in compression_concepts] or [compression_score]))
        compression_profile_decision = "compression_repo"
    elif role["primary_role"] == "agent_memory_retrieval" and compression_evidence_strength in {"medium", "weak"}:
        old_score = compression_score
        compression_score = min(compression_score, 54)
        compression_profile_decision = "compression_adjacent"
        calibration_adjustments.append(f"compression score {old_score}->{compression_score} because memory/retrieval is primary")
    elif compression_evidence_strength == "none" and role["primary_role"] in {"unknown", "compression_context"}:
        old_score = compression_score
        compression_score = min(compression_score, 24)
        compression_profile_decision = "insufficient_evidence"
        calibration_adjustments.append(f"compression score {old_score}->{compression_score} because explicit compression evidence is missing")
    else:
        old_score = compression_score
        compression_score = min(compression_score, 34)
        compression_profile_decision = "not_compression_repo"
        calibration_adjustments.append(f"compression score {old_score}->{compression_score} because primary role is {role['primary_role']}")
        false_positive_warnings.append(f"compression concepts downranked for calibrated primary role {role['primary_role']}")
    is_compression = compression_profile_decision == "compression_repo" and compression_score >= 65
    modes = []
    if "tool_output_compression" in concept_ids:
        modes.append("tool_output_compression")
    if "log_file_compression" in concept_ids:
        modes.extend(["log_compression", "file_compression"])
    if "rag_chunk_compression" in concept_ids:
        modes.append("rag_chunk_compression")
    if "compression_library" in concept_ids or "token_reduction" in concept_ids:
        modes.append("prompt_context_compression")
    interface_modes = []
    if "library_api" in concept_ids:
        interface_modes.append("library")
    if "cli_mode" in concept_ids:
        interface_modes.append("cli")
    if "mcp_server" in concept_ids:
        interface_modes.append("mcp_server")
    if "proxy_mode" in concept_ids:
        interface_modes.append("proxy_server")
    adapter_candidates = ["preview_only_adapter"]
    if "library" in interface_modes:
        adapter_candidates.append("local_library_adapter")
    if "cli" in interface_modes:
        adapter_candidates.append("bounded_cli_adapter")
    if "mcp_server" in interface_modes:
        adapter_candidates.append("mcp_adapter_later")
    if "proxy_server" in interface_modes:
        adapter_candidates.append("proxy_adapter_later")
    blocked = [] if is_compression else ["source does not have enough deterministic compression evidence"]
    if "mcp_server" in interface_modes:
        blocked.append("MCP server mode requires separate approval and must not be default")
    if "proxy_server" in interface_modes:
        blocked.append("proxy mode requires separate approval and must not be default")
    payload = {
        "compression_repo_concept_profile_version": COMPRESSION_REPO_CONCEPT_PROFILE_VERSION,
        "compression_repo_concept_profile_id": "compression-repo-concept-profile-" + _research_target_hash_text({"concepts_id": concepts["source_aware_archive_concepts_id"], "version": COMPRESSION_REPO_CONCEPT_PROFILE_VERSION})[:12],
        "source_path": concepts["source_path"],
        "archive_concepts_id": concepts["source_aware_archive_concepts_id"],
        "is_compression_repo": bool(is_compression),
        "compression_score": compression_score,
        "calibrated_repo_role_classification_id": role["calibrated_repo_role_classification_id"],
        "concept_confidence_calibration_id": confidence["concept_confidence_calibration_id"],
        "calibrated_compression_score": compression_score,
        "raw_compression_score": raw_compression_score,
        "calibration_adjustments": _normalize_implementation_branch_refs(calibration_adjustments + role["calibration_adjustments"]),
        "compression_false_positive_warnings": _normalize_implementation_branch_refs(false_positive_warnings + role["overclassification_warnings"]),
        "compression_evidence_strength": compression_evidence_strength,
        "compression_profile_decision": compression_profile_decision,
        "primary_compression_modes": _normalize_implementation_branch_refs(modes) if modes else [],
        "interface_modes": _normalize_implementation_branch_refs(interface_modes),
        "adapter_candidates": _normalize_implementation_branch_refs(adapter_candidates),
        "unsafe_modes": _normalize_implementation_branch_refs(["auto_mcp_server_start", "proxy_as_default_path", "network_required_compression", "compression_overrides_provenance", "compression_changes_alias_map"]),
        "dependency_requirements": _normalize_implementation_branch_refs(concepts["dependency_signals"] or ["inspect package metadata before runtime adapter use"]),
        "metadata_preservation_requirements": _normalize_implementation_branch_refs(["source_path", "source_refs", "evidence_refs", "alias_map", "selected_upgrade_candidate_id", "safety_metadata", "fallback_policy"]),
        "link_integration_opportunities": _normalize_implementation_branch_refs(["advisor compact context reducer", "ref-preserving compression preview", "bounded local adapter fixture", "compressed-context validation"] if is_compression else ["not a compression-first integration target"]),
        "blocked_integration_paths": _normalize_implementation_branch_refs(blocked),
        "recommended_integration_mode": "preview_or_bounded_local_adapter" if is_compression else "not_applicable",
        "recommended_next_action": "Score compression-aware upgrades before implementation; keep MCP/proxy disabled." if is_compression else "Use the general source-aware workflow; do not force compression-specific upgrades.",
        "source_refs": concepts["source_refs"],
        "evidence_refs": concepts["evidence_refs"],
        "fallback_allowed": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_compression_repo_concept_profile(payload, concepts)
    return payload


def validate_compression_repo_concept_profile(payload: dict[str, Any], archive_concepts: dict[str, Any] | None = None) -> None:
    required = ("compression_repo_concept_profile_version", "compression_repo_concept_profile_id", "source_path", "archive_concepts_id", "is_compression_repo", "compression_score", "calibrated_repo_role_classification_id", "concept_confidence_calibration_id", "calibrated_compression_score", "raw_compression_score", "calibration_adjustments", "compression_false_positive_warnings", "compression_evidence_strength", "compression_profile_decision", "primary_compression_modes", "interface_modes", "adapter_candidates", "unsafe_modes", "dependency_requirements", "metadata_preservation_requirements", "link_integration_opportunities", "blocked_integration_paths", "recommended_integration_mode", "recommended_next_action", "source_refs", "evidence_refs", "fallback_allowed", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"compression profile missing field: {key}")
    if payload["compression_repo_concept_profile_version"] != COMPRESSION_REPO_CONCEPT_PROFILE_VERSION:
        raise ValueError("invalid compression profile version")
    if not payload["compression_repo_concept_profile_id"].startswith("compression-repo-concept-profile-"):
        raise ValueError("invalid compression profile id")
    if not isinstance(payload["is_compression_repo"], bool):
        raise TypeError("is_compression_repo must be boolean")
    if not isinstance(payload["compression_score"], int) or not 0 <= payload["compression_score"] <= 100:
        raise ValueError("compression score must be 0..100")
    if payload["compression_profile_decision"] not in {"compression_repo", "compression_adjacent", "not_compression_repo", "insufficient_evidence"}:
        raise ValueError("invalid compression profile decision")
    for field in ("calibrated_compression_score", "raw_compression_score"):
        if not isinstance(payload[field], int) or not 0 <= payload[field] <= 100:
            raise ValueError(f"{field} must be 0..100")
    for field in ("calibration_adjustments", "compression_false_positive_warnings", "primary_compression_modes", "interface_modes", "adapter_candidates", "unsafe_modes", "dependency_requirements", "metadata_preservation_requirements", "link_integration_opportunities", "blocked_integration_paths"):
        if not isinstance(payload[field], list):
            raise TypeError(f"compression profile {field} must be a list")
    for required_field in ("source_refs", "evidence_refs", "alias_map"):
        if required_field not in payload["metadata_preservation_requirements"]:
            raise ValueError("compression profile must preserve refs and alias map")
    if payload["is_compression_repo"] and payload["recommended_integration_mode"] not in {"preview_or_bounded_local_adapter", "bounded_local_adapter"}:
        raise ValueError("compression profile must not recommend MCP/proxy by default")
    if payload["fallback_allowed"] is not False:
        raise ValueError("compression profile must disable provider fallback")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("compression profile must remain read-only")
    if archive_concepts is not None and payload["archive_concepts_id"] != archive_concepts["source_aware_archive_concepts_id"]:
        raise ValueError("compression profile archive concept id mismatch")


def stable_compression_repo_concept_profile_json(payload: dict[str, Any]) -> str:
    validate_compression_repo_concept_profile(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_compression_repo_concept_profile_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_compression_repo_concept_profile(payload)
    return payload


GENERIC_GROWTH_UPGRADE_TERMS = (
    "add tests", "add wrapper", "add docs", "add generic cli", "add dashboard",
    "improve ux", "add logging", "add config", "review local research target",
)


def _growth_upgrade_is_generic(candidate: dict[str, Any], concept_keywords: set[str]) -> bool:
    title = str(candidate.get("title", "")).strip().lower()
    description = str(candidate.get("description", "")).lower()
    text = title + " " + description
    if bool(candidate.get("uses_repo_concepts")) or bool(candidate.get("compression_specific")):
        return False
    if any(keyword.replace("_", " ") in text for keyword in concept_keywords if keyword != "unknown"):
        return False
    return any(term in text for term in GENERIC_GROWTH_UPGRADE_TERMS) or title.startswith("review local research target")


def collect_growth_upgrade_genericity_assessment(
    archive_concepts: dict[str, Any] | None = None,
    research_target_upgrade_candidates: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    concepts = archive_concepts or collect_source_aware_archive_concepts(source_path=source_path)
    validate_source_aware_archive_concepts(concepts)
    candidates = research_target_upgrade_candidates or collect_research_target_upgrade_candidates(source_path=concepts["source_path"])
    validate_research_target_upgrade_candidates(candidates)
    concept_keywords = {item["concept_id"] for item in concepts["detected_concepts"]}
    concept_keywords.update(concepts["concept_families"])
    generic_warnings: list[str] = []
    concept_supported: list[str] = []
    rejected: list[dict[str, str]] = []
    for candidate in candidates["upgrade_candidates"]:
        candidate_id = candidate["upgrade_candidate_id"]
        if _growth_upgrade_is_generic(candidate, concept_keywords):
            generic_warnings.append(f"{candidate['title']} is generic unless tied to detected concepts: {', '.join(concepts['concept_families'][:4])}")
            rejected.append({
                "upgrade_id": candidate_id,
                "upgrade_title": candidate["title"],
                "reason": "Generic upgrade down-ranked until it is tied to deterministic source concepts and evidence refs.",
            })
        else:
            concept_supported.append(candidate_id)
    total = max(1, len(candidates["upgrade_candidates"]))
    genericity_score = max(0, min(100, int((len(generic_warnings) / total) * 100)))
    payload = {
        "growth_upgrade_genericity_assessment_version": GROWTH_UPGRADE_GENERICITY_ASSESSMENT_VERSION,
        "growth_upgrade_genericity_assessment_id": "growth-upgrade-genericity-assessment-" + _research_target_hash_text({"archive_concepts_id": concepts["source_aware_archive_concepts_id"], "target_upgrades_id": candidates["research_target_upgrade_candidates_id"], "version": GROWTH_UPGRADE_GENERICITY_ASSESSMENT_VERSION})[:12],
        "source_path": concepts["source_path"],
        "archive_concepts_id": concepts["source_aware_archive_concepts_id"],
        "target_upgrades_id": candidates["research_target_upgrade_candidates_id"],
        "generic_upgrade_count": len(generic_warnings),
        "concept_supported_upgrade_count": len(concept_supported),
        "genericity_score": genericity_score,
        "generic_upgrade_warnings": _normalize_implementation_branch_refs(generic_warnings),
        "concept_supported_upgrade_ids": _normalize_implementation_branch_refs(concept_supported),
        "rejected_generic_upgrades": rejected,
        "recommended_next_action": "Prefer concept-supported upgrades with source/evidence refs; keep generic candidates as lower-priority fallbacks.",
        "fallback_allowed": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_growth_upgrade_genericity_assessment(payload, concepts, candidates)
    return payload


def validate_growth_upgrade_genericity_assessment(payload: dict[str, Any], archive_concepts: dict[str, Any] | None = None, research_target_upgrade_candidates: dict[str, Any] | None = None) -> None:
    required = ("growth_upgrade_genericity_assessment_version", "growth_upgrade_genericity_assessment_id", "source_path", "archive_concepts_id", "target_upgrades_id", "generic_upgrade_count", "concept_supported_upgrade_count", "genericity_score", "generic_upgrade_warnings", "concept_supported_upgrade_ids", "rejected_generic_upgrades", "recommended_next_action", "fallback_allowed", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"growth upgrade genericity assessment missing field: {key}")
    if payload["growth_upgrade_genericity_assessment_version"] != GROWTH_UPGRADE_GENERICITY_ASSESSMENT_VERSION:
        raise ValueError("invalid growth upgrade genericity assessment version")
    if not payload["growth_upgrade_genericity_assessment_id"].startswith("growth-upgrade-genericity-assessment-"):
        raise ValueError("invalid growth upgrade genericity assessment id")
    for field in ("generic_upgrade_count", "concept_supported_upgrade_count", "genericity_score"):
        if not isinstance(payload[field], int) or not 0 <= payload[field] <= 100:
            raise ValueError(f"{field} must be a bounded integer")
    for field in ("generic_upgrade_warnings", "concept_supported_upgrade_ids", "rejected_generic_upgrades"):
        if not isinstance(payload[field], list):
            raise TypeError(f"{field} must be a list")
    if payload["fallback_allowed"] is not False:
        raise ValueError("genericity assessment must disable fallback")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("genericity assessment must remain read-only")
    if archive_concepts is not None and payload["archive_concepts_id"] != archive_concepts["source_aware_archive_concepts_id"]:
        raise ValueError("genericity assessment archive concept id mismatch")
    if research_target_upgrade_candidates is not None and payload["target_upgrades_id"] != research_target_upgrade_candidates["research_target_upgrade_candidates_id"]:
        raise ValueError("genericity assessment target upgrades id mismatch")


def stable_growth_upgrade_genericity_assessment_json(payload: dict[str, Any]) -> str:
    validate_growth_upgrade_genericity_assessment(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_growth_upgrade_genericity_assessment_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_growth_upgrade_genericity_assessment(payload)
    return payload


def _compression_specific_upgrade_candidate(intake: dict[str, Any], evidence: dict[str, Any], concepts: dict[str, Any], profile: dict[str, Any]) -> dict[str, Any]:
    title = "Add deterministic compression concept extraction"
    candidate_id = "research-target-upgrade-candidate-" + _research_target_hash_text({"intake_id": intake["research_target_intake_id"], "title": title, "profile_id": profile["compression_repo_concept_profile_id"]})[:12]
    return {
        "upgrade_candidate_id": candidate_id,
        "title": title,
        "target_link_module": "research",
        "description": f"Use deterministic concepts from {intake['source_path']} to identify compression, adapter, and provenance-preservation opportunities before advisor/model use.",
        "source_refs": concepts["source_refs"][:5],
        "evidence_refs": concepts["evidence_refs"][:5],
        "expected_value": "high",
        "risk_level": "low",
        "confidence_score": max(88, profile["compression_score"]),
        "effort_score": 3,
        "implementation_scope": "read-only concept extraction, upgrade scoring, and source-bound task drafting; no compressor runtime",
        "required_approvals": ["human review before implementation", "license/copying review"],
        "required_tests": [
            "python3 -m py_compile link.py link_modes/growth/link_growth_console.py tests/test_growth_pipeline.py",
            "PYTHONDONTWRITEBYTECODE=1 python3 tests/test_growth_pipeline.py",
            "PYTHONDONTWRITEBYTECODE=1 python3 link_healthcheck.py",
        ],
        "blocked_actions": list(RESEARCH_TARGET_BLOCKED_ACTIONS),
        "recommended_next_action": "Implement deterministic concept extraction before enabling any Headroom runtime adapter.",
        "uses_repo_concepts": [item["concept_id"] for item in concepts["detected_concepts"][:6]],
        "compression_specific": True,
        "source_specific": True,
    }


def collect_compression_aware_upgrade_scorer(
    archive_concepts: dict[str, Any] | None = None,
    compression_profile: dict[str, Any] | None = None,
    research_target_upgrade_candidates: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    concepts = archive_concepts or collect_source_aware_archive_concepts(source_path=source_path)
    validate_source_aware_archive_concepts(concepts)
    profile = compression_profile or collect_compression_repo_concept_profile(concepts)
    validate_compression_repo_concept_profile(profile, concepts)
    candidates = research_target_upgrade_candidates or collect_research_target_upgrade_candidates(source_path=concepts["source_path"])
    validate_research_target_upgrade_candidates(candidates)
    genericity = collect_growth_upgrade_genericity_assessment(concepts, candidates)
    role = collect_calibrated_repo_role_classification(concepts)
    confidence = collect_concept_confidence_calibration(concepts, role)
    concept_ids = [item["concept_id"] for item in concepts["detected_concepts"]]
    scored = []
    rejected = []
    for candidate in candidates["upgrade_candidates"]:
        title_text = candidate["title"].lower() + " " + candidate["description"].lower()
        compression_specific = any(term in title_text for term in ("compression", "context", "adapter", "provenance", "alias")) or bool(candidate.get("compression_specific"))
        generic = any(term == candidate["title"].strip().lower() for term in ("add tests", "add wrapper", "add docs", "add generic cli", "review local research target for link upgrade"))
        score = int(candidate["confidence_score"]) - int(candidate["effort_score"])
        if profile["is_compression_repo"] and compression_specific:
            score += 35
        if profile["is_compression_repo"] and not compression_specific:
            score -= 18
        if compression_specific and profile["compression_profile_decision"] not in {"compression_repo", "compression_adjacent"}:
            score -= 35
        if generic:
            score -= 25
        role_mismatch = compression_specific and profile["compression_profile_decision"] not in {"compression_repo", "compression_adjacent"}
        entry = {
            "upgrade_id": candidate["upgrade_candidate_id"],
            "upgrade_title": candidate["title"],
            "source_specific": bool(candidate.get("source_specific", True)),
            "compression_specific": bool(compression_specific),
            "role_aligned": not role_mismatch,
            "uses_repo_concepts": list(candidate.get("uses_repo_concepts", concept_ids[:4] if compression_specific else [])),
            "required_evidence_refs": candidate["evidence_refs"][:5],
            "required_source_refs": candidate["source_refs"][:5],
            "expected_files_to_touch": _research_target_likely_files(candidate["target_link_module"]),
            "expected_tests": candidate["required_tests"][:3],
            "risk_notes": ["MCP/proxy runtime remains prohibited by default"] if compression_specific else ["generic candidate down-ranked for compression repos"],
            "score": max(0, min(100, score)),
            "reason": "Compression concepts and provenance requirements directly support this candidate." if compression_specific and not role_mismatch else "Candidate is less specific to the calibrated repo role.",
        }
        scored.append(entry)
        if profile["is_compression_repo"] and (generic or not compression_specific):
            rejected.append({"upgrade_id": candidate["upgrade_candidate_id"], "upgrade_title": candidate["title"], "reason": "Down-ranked because Headroom evidence supports a more compression-specific upgrade."})
        if role_mismatch:
            rejected.append({"upgrade_id": candidate["upgrade_candidate_id"], "upgrade_title": candidate["title"], "reason": f"Rejected/down-ranked because primary role is {role['primary_role']}, not compression_context."})
    scored.sort(key=lambda item: (-item["score"], item["upgrade_id"]))
    best = scored[0] if scored else {}
    payload = {
        "compression_aware_upgrade_scorer_version": COMPRESSION_AWARE_UPGRADE_SCORER_VERSION,
        "compression_aware_upgrade_scorer_id": "compression-aware-upgrade-scorer-" + _research_target_hash_text({"profile_id": profile["compression_repo_concept_profile_id"], "candidate_ids": [item["upgrade_id"] for item in scored], "version": COMPRESSION_AWARE_UPGRADE_SCORER_VERSION})[:12],
        "source_path": concepts["source_path"],
        "archive_concepts_id": concepts["source_aware_archive_concepts_id"],
        "compression_profile_id": profile["compression_repo_concept_profile_id"],
        "genericity_assessment_id": genericity["growth_upgrade_genericity_assessment_id"],
        "calibrated_repo_role_classification_id": role["calibrated_repo_role_classification_id"],
        "concept_confidence_calibration_id": confidence["concept_confidence_calibration_id"],
        "role_alignment_score": 90 if best.get("role_aligned", False) else 45,
        "concept_confidence_score": max([item["calibrated_confidence"] for item in confidence["concept_calibrations"]] or [0]),
        "false_positive_penalty": 0 if profile["compression_profile_decision"] in {"compression_repo", "compression_adjacent"} else 35,
        "overclassification_penalty": 0 if not profile["compression_false_positive_warnings"] else 20,
        "calibrated_direct_usefulness_score": max(0, min(100, int(best.get("score", 0)) - (0 if best.get("role_aligned", False) else 20))),
        "calibration_warnings": _normalize_implementation_branch_refs(profile["compression_false_positive_warnings"] + role["overclassification_warnings"]),
        "rejected_due_to_role_mismatch": [item for item in rejected if "primary role" in item["reason"]],
        "selected_upgrade_candidate_id": best.get("upgrade_id", ""),
        "scored_upgrades": scored,
        "best_upgrade": best,
        "rejected_generic_upgrades": rejected,
        "target_specificity_score": 90 if best.get("source_specific") else 50,
        "compression_relevance_score": profile["compression_score"] if profile["is_compression_repo"] else 0,
        "provenance_support_score": 90 if concepts["source_refs"] and concepts["evidence_refs"] else 40,
        "implementation_risk_score": 25 if profile["is_compression_repo"] else 15,
        "safety_risk_score": 30 if profile["blocked_integration_paths"] else 15,
        "recommended_next_action": "Use the best compression-specific upgrade for task drafting; do not start MCP/proxy or install Headroom.",
        "fallback_allowed": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_compression_aware_upgrade_scorer(payload, concepts, profile)
    return payload


def validate_compression_aware_upgrade_scorer(payload: dict[str, Any], archive_concepts: dict[str, Any] | None = None, compression_profile: dict[str, Any] | None = None) -> None:
    required = ("compression_aware_upgrade_scorer_version", "compression_aware_upgrade_scorer_id", "source_path", "archive_concepts_id", "compression_profile_id", "genericity_assessment_id", "calibrated_repo_role_classification_id", "concept_confidence_calibration_id", "role_alignment_score", "concept_confidence_score", "false_positive_penalty", "overclassification_penalty", "calibrated_direct_usefulness_score", "calibration_warnings", "rejected_due_to_role_mismatch", "selected_upgrade_candidate_id", "scored_upgrades", "best_upgrade", "rejected_generic_upgrades", "target_specificity_score", "compression_relevance_score", "provenance_support_score", "implementation_risk_score", "safety_risk_score", "recommended_next_action", "fallback_allowed", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"compression-aware upgrade scorer missing field: {key}")
    if payload["compression_aware_upgrade_scorer_version"] != COMPRESSION_AWARE_UPGRADE_SCORER_VERSION:
        raise ValueError("invalid compression-aware upgrade scorer version")
    if not payload["compression_aware_upgrade_scorer_id"].startswith("compression-aware-upgrade-scorer-"):
        raise ValueError("invalid compression-aware upgrade scorer id")
    if not isinstance(payload["scored_upgrades"], list) or not payload["scored_upgrades"]:
        raise ValueError("compression scorer requires scored upgrades")
    for score_field in ("target_specificity_score", "compression_relevance_score", "provenance_support_score", "implementation_risk_score", "safety_risk_score", "role_alignment_score", "concept_confidence_score", "false_positive_penalty", "overclassification_penalty", "calibrated_direct_usefulness_score"):
        if not isinstance(payload[score_field], int) or not 0 <= payload[score_field] <= 100:
            raise ValueError(f"{score_field} must be 0..100")
    best = payload["best_upgrade"]
    if not isinstance(best, dict) or best.get("upgrade_id") != payload["selected_upgrade_candidate_id"]:
        raise ValueError("compression scorer best upgrade must match selected id")
    if payload["fallback_allowed"] is not False:
        raise ValueError("compression scorer must disable fallback")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("compression scorer must remain read-only")
    if archive_concepts is not None and payload["archive_concepts_id"] != archive_concepts["source_aware_archive_concepts_id"]:
        raise ValueError("compression scorer concepts id mismatch")
    if compression_profile is not None and payload["compression_profile_id"] != compression_profile["compression_repo_concept_profile_id"]:
        raise ValueError("compression scorer profile id mismatch")


def stable_compression_aware_upgrade_scorer_json(payload: dict[str, Any]) -> str:
    validate_compression_aware_upgrade_scorer(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_compression_aware_upgrade_scorer_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_compression_aware_upgrade_scorer(payload)
    return payload

def _research_target_candidate_template(domain: str) -> tuple[str, str, str, str]:
    if domain == "ecommerce":
        return ("Create source-backed ecommerce opportunity intake", "growth", "Convert ecommerce skill/product evidence into governed Link opportunity candidates.", "high")
    if domain in {"scraping", "data_collection", "source_governance"}:
        return ("Add governed source target planning", "business_development", "Turn local source/crawler patterns into approved source-card and evidence planning inputs.", "high")
    if domain in {"automation", "workflow"}:
        return ("Model workflow automation patterns safely", "shared_services", "Capture workflow, trigger/action, human input, and audit patterns without enabling execution.", "high")
    if domain == "agent_memory":
        return ("Add memory evidence intake patterns", "shared_services", "Convert agent memory patterns into Link-native memory evidence and review requirements.", "medium")
    if domain == "market_research":
        return ("Create market research evidence intake", "growth", "Use local market-research artifacts to produce evidence-backed Growth candidates.", "high")
    if domain == "business_development":
        return ("Create Business Development intake bridge", "business_development", "Convert reviewed Growth/source evidence into Business Development intake artifacts.", "medium")
    return ("Review local research target for Link upgrade", "research", "Summarize this target into a Link-native upgrade candidate after human review.", "medium")


def collect_research_target_upgrade_candidates(
    research_target_intake: dict[str, Any] | None = None,
    research_target_evidence_bundle: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    intake = research_target_intake or collect_research_target_intake(str(source_path or ""))
    validate_research_target_intake(intake)
    evidence = research_target_evidence_bundle or collect_research_target_evidence_bundle(intake)
    validate_research_target_evidence_bundle(evidence, intake)
    archive_concepts = collect_source_aware_archive_concepts(intake, evidence)
    compression_profile = collect_compression_repo_concept_profile(archive_concepts)
    candidates = []
    seen_candidate_keys: set[tuple[str, str]] = set()
    for domain in intake["detected_domains"]:
        title, module, description, expected_value = _research_target_candidate_template(domain)
        candidate_key = (title, module)
        if candidate_key in seen_candidate_keys:
            continue
        seen_candidate_keys.add(candidate_key)
        candidate_id = "research-target-upgrade-candidate-" + _research_target_hash_text({
            "intake_id": intake["research_target_intake_id"],
            "module": module,
            "title": title,
        })[:12]
        candidate = {
            "upgrade_candidate_id": candidate_id,
            "title": title,
            "target_link_module": module,
            "description": f"{description} Source: {intake['source_path']}.",
            "source_refs": [item["source_ref_id"] for item in evidence["source_refs"][:5]],
            "evidence_refs": [item["evidence_ref_id"] for item in evidence["evidence_refs"][:5]],
            "expected_value": expected_value,
            "risk_level": "medium" if domain in {"scraping", "ecommerce", "automation", "data_collection"} else "low",
            "confidence_score": 75 if evidence["evidence_strength"] == "strong" else 60 if evidence["evidence_strength"] == "medium" else 40,
            "effort_score": 4 if module in {"growth", "research"} else 6,
            "implementation_scope": "read-only planning and evidence binding; no external execution",
            "required_approvals": ["human review before implementation", "license/copying review"],
            "required_tests": [
                "python3 -m py_compile link.py link_modes/growth/link_growth_console.py tests/test_growth_pipeline.py",
                "PYTHONDONTWRITEBYTECODE=1 python3 tests/test_growth_pipeline.py",
                "PYTHONDONTWRITEBYTECODE=1 python3 link_healthcheck.py",
            ],
            "blocked_actions": list(RESEARCH_TARGET_BLOCKED_ACTIONS),
            "recommended_next_action": "Review this source-backed candidate before drafting an implementation slice.",
        }
        candidates.append(candidate)
    if compression_profile["is_compression_repo"]:
        compression_candidate = _compression_specific_upgrade_candidate(intake, evidence, archive_concepts, compression_profile)
        candidates.insert(0, compression_candidate)
        seen_candidate_keys.add((compression_candidate["title"], compression_candidate["target_link_module"]))
    if not candidates:
        candidates.append({
            "upgrade_candidate_id": "research-target-upgrade-candidate-" + _research_target_hash_text(intake["research_target_intake_id"])[:12],
            "title": "Review local research target for Link upgrade",
            "target_link_module": "research",
            "description": f"Manual review required for {intake['source_path']}.",
            "source_refs": [item["source_ref_id"] for item in evidence["source_refs"][:3]],
            "evidence_refs": [item["evidence_ref_id"] for item in evidence["evidence_refs"][:3]],
            "expected_value": "medium",
            "risk_level": "low",
            "confidence_score": 35,
            "effort_score": 5,
            "implementation_scope": "manual research review",
            "required_approvals": ["human review before implementation"],
            "required_tests": ["PYTHONDONTWRITEBYTECODE=1 python3 tests/test_growth_pipeline.py"],
            "blocked_actions": list(RESEARCH_TARGET_BLOCKED_ACTIONS),
            "recommended_next_action": "Add stronger evidence before implementation planning.",
        })
    blocked_candidates = []
    if evidence["missing_evidence"]:
        blocked_candidates.append({
            "blocked_candidate_id": "research-target-blocked-missing-evidence",
            "reason": "Evidence bundle has missing evidence.",
            "missing_evidence": list(evidence["missing_evidence"]),
        })
    digest = _research_target_hash_text({
        "candidate_ids": [item["upgrade_candidate_id"] for item in candidates],
        "evidence_id": evidence["research_target_evidence_bundle_id"],
        "intake_id": intake["research_target_intake_id"],
        "version": RESEARCH_TARGET_UPGRADE_CANDIDATES_VERSION,
    })[:12]
    payload = {
        "research_target_upgrade_candidates_version": RESEARCH_TARGET_UPGRADE_CANDIDATES_VERSION,
        "research_target_upgrade_candidates_id": f"research-target-upgrade-candidates-{digest}",
        "research_target_intake_id": intake["research_target_intake_id"],
        "research_target_evidence_bundle_id": evidence["research_target_evidence_bundle_id"],
        "upgrade_candidates": candidates,
        "blocked_candidates": blocked_candidates,
        "missing_evidence": list(evidence["missing_evidence"]),
        "archive_concepts_id": archive_concepts["source_aware_archive_concepts_id"],
        "detected_concept_families": archive_concepts["concept_families"],
        "top_detected_concepts": [item["concept_id"] for item in archive_concepts["detected_concepts"][:5]],
        "compression_profile_id": compression_profile["compression_repo_concept_profile_id"] if compression_profile["is_compression_repo"] else "",
        "compression_score": compression_profile["compression_score"] if compression_profile["is_compression_repo"] else 0,
        "concept_specificity_score": min(100, archive_concepts["confidence_score"] + (10 if compression_profile["is_compression_repo"] else 0)),
        "generic_upgrade_warnings": ["compression repo evidence supports a concept-specific upgrade; down-rank generic wrappers/docs/tests"] if compression_profile["is_compression_repo"] else [],
        "concept_supported_upgrade_ids": [item["upgrade_candidate_id"] for item in candidates if item.get("uses_repo_concepts")],
        "recommended_concept_specific_upgrade": candidates[0]["upgrade_candidate_id"] if candidates and candidates[0].get("uses_repo_concepts") else "",
        "recommended_next_action": "Select the highest-value concept-backed candidate for a non-executable operator task draft.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    genericity = collect_growth_upgrade_genericity_assessment(archive_concepts, payload)
    payload["genericity_assessment_id"] = genericity["growth_upgrade_genericity_assessment_id"]
    payload["generic_upgrade_warnings"] = genericity["generic_upgrade_warnings"] or payload["generic_upgrade_warnings"]
    payload["concept_supported_upgrade_ids"] = genericity["concept_supported_upgrade_ids"] or payload["concept_supported_upgrade_ids"]
    validate_research_target_upgrade_candidates(payload, intake, evidence)
    return payload


def validate_research_target_upgrade_candidates(payload: dict[str, Any], research_target_intake: dict[str, Any] | None = None, research_target_evidence_bundle: dict[str, Any] | None = None) -> None:
    required = (
        "research_target_upgrade_candidates_version", "research_target_upgrade_candidates_id",
        "research_target_intake_id", "research_target_evidence_bundle_id", "upgrade_candidates",
        "blocked_candidates", "missing_evidence", "recommended_next_action", "safety_metadata",
        "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"research target upgrade candidates missing required field: {key}")
    if payload["research_target_upgrade_candidates_version"] != RESEARCH_TARGET_UPGRADE_CANDIDATES_VERSION:
        raise ValueError("invalid research target upgrade candidates version")
    if not payload["research_target_upgrade_candidates_id"].startswith("research-target-upgrade-candidates-"):
        raise ValueError("invalid research target upgrade candidates id")
    if not isinstance(payload["upgrade_candidates"], list) or not payload["upgrade_candidates"]:
        raise ValueError("research target upgrade candidates must include candidates")
    for candidate in payload["upgrade_candidates"]:
        for key in ("upgrade_candidate_id", "title", "target_link_module", "description", "source_refs", "evidence_refs", "expected_value", "risk_level", "confidence_score", "effort_score", "implementation_scope", "required_approvals", "required_tests", "blocked_actions", "recommended_next_action"):
            if key not in candidate:
                raise ValueError(f"research target upgrade candidate missing field: {key}")
        if not candidate["upgrade_candidate_id"].startswith("research-target-upgrade-candidate-"):
            raise ValueError("invalid research target upgrade candidate id")
        if candidate["target_link_module"] not in RESEARCH_TARGET_LINK_MODULES:
            raise ValueError("invalid target Link module")
        if candidate["risk_level"] not in {"low", "medium", "high"} or candidate["expected_value"] not in {"low", "medium", "high"}:
            raise ValueError("invalid candidate risk/value")
        for score in ("confidence_score", "effort_score"):
            if not isinstance(candidate[score], int) or not 0 <= candidate[score] <= 100:
                raise ValueError(f"candidate {score} must be 0..100")
        for field in ("source_refs", "evidence_refs", "required_approvals", "required_tests", "blocked_actions"):
            if not isinstance(candidate[field], list) or not candidate[field]:
                raise ValueError(f"candidate {field} must be a non-empty list")
        for action in RESEARCH_TARGET_BLOCKED_ACTIONS:
            if action not in candidate["blocked_actions"]:
                raise ValueError("research target candidate missing blocked action")
    if not isinstance(payload["blocked_candidates"], list) or not isinstance(payload["missing_evidence"], list):
        raise TypeError("blocked_candidates and missing_evidence must be lists")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("research target upgrade candidates must remain read-only")
    if research_target_intake is not None:
        validate_research_target_intake(research_target_intake)
        if payload["research_target_intake_id"] != research_target_intake["research_target_intake_id"]:
            raise ValueError("research target upgrade candidates intake id mismatch")
    if research_target_evidence_bundle is not None:
        validate_research_target_evidence_bundle(research_target_evidence_bundle, research_target_intake)
        if payload["research_target_evidence_bundle_id"] != research_target_evidence_bundle["research_target_evidence_bundle_id"]:
            raise ValueError("research target upgrade candidates evidence id mismatch")


def stable_research_target_upgrade_candidates_json(payload: dict[str, Any]) -> str:
    validate_research_target_upgrade_candidates(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_research_target_upgrade_candidates_json(text: str) -> dict[str, Any]:
    import json as _json

    payload = _json.loads(text)
    validate_research_target_upgrade_candidates(payload)
    return payload


def _research_target_candidate_sort_key(candidate: dict[str, Any]) -> tuple[int, int, str]:
    return (-int(candidate["confidence_score"]), int(candidate["effort_score"]), candidate["upgrade_candidate_id"])


def _research_target_likely_files(module: str) -> list[str]:
    if module == "growth":
        return ["link.py", "link_modes/growth/link_growth_console.py", "tests/test_growth_pipeline.py"]
    if module == "business_development":
        return ["link.py", "link_modes/growth/link_growth_console.py", "tests/test_growth_pipeline.py"]
    if module == "shared_services":
        return ["link_modes/growth/link_growth_console.py", "tests/test_growth_pipeline.py"]
    if module == "control_plane":
        return ["link.py", "link_modes/growth/link_growth_console.py", "tests/test_growth_pipeline.py"]
    return ["link_modes/growth/link_growth_console.py", "tests/test_growth_pipeline.py"]


def collect_research_target_operator_task_draft(
    research_target_upgrade_candidates: dict[str, Any] | None = None,
    research_target_evidence_bundle: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    candidates_payload = research_target_upgrade_candidates
    evidence = research_target_evidence_bundle
    if candidates_payload is None:
        intake = collect_research_target_intake(str(source_path or ""))
        evidence = evidence or collect_research_target_evidence_bundle(intake)
        candidates_payload = collect_research_target_upgrade_candidates(intake, evidence)
    validate_research_target_upgrade_candidates(candidates_payload)
    if evidence is None:
        raise ValueError("research target evidence bundle is required when candidates are provided")
    validate_research_target_evidence_bundle(evidence)
    selected = sorted(candidates_payload["upgrade_candidates"], key=_research_target_candidate_sort_key)[0]
    source_path_value = evidence["provenance_summary"]["source_path"]
    is_compression_profile = bool(candidates_payload.get("compression_profile_id"))
    archive_concepts_id = str(candidates_payload.get("archive_concepts_id", ""))
    compression_profile_id = str(candidates_payload.get("compression_profile_id", ""))
    concept_score = int(candidates_payload.get("concept_specificity_score", 0) or 0)
    metadata_input = dict(metadata or {})
    archive_concepts = metadata_input.pop("_archive_concepts", None)
    if not isinstance(archive_concepts, dict):
        intake_for_concepts = collect_research_target_intake(source_path_value)
        archive_concepts = collect_source_aware_archive_concepts(intake_for_concepts, evidence)
    role = collect_calibrated_repo_role_classification(archive_concepts)
    confidence = collect_concept_confidence_calibration(archive_concepts, role)
    calibrated_top = [
        item for item in confidence["concept_calibrations"]
        if item["calibrated_confidence"] >= 35
    ][:5]
    recommended_files = [item.get("provenance_path") or item.get("source_ref_id") for item in evidence.get("source_refs", [])[:5]]
    recommended_files = [str(item) for item in recommended_files if item]
    concept_steps = [
        "inspect local compression library/CLI API from source refs",
        "add fixture sample preserving source_path, S1, and E1 aliases",
        "validate compressed output cannot override refs, aliases, IDs, or safety metadata",
        "gate real context compression behind adapter readiness",
        "keep MCP/proxy prohibited by default",
    ] if is_compression_profile else []
    digest = _research_target_hash_text({
        "candidate_id": selected["upgrade_candidate_id"],
        "evidence_id": evidence["research_target_evidence_bundle_id"],
        "intake_id": candidates_payload["research_target_intake_id"],
        "version": RESEARCH_TARGET_OPERATOR_TASK_DRAFT_VERSION,
    })[:12]
    draft = {
        "research_target_operator_task_draft_version": RESEARCH_TARGET_OPERATOR_TASK_DRAFT_VERSION,
        "research_target_operator_task_draft_id": f"research-target-operator-task-draft-{digest}",
        "research_target_intake_id": candidates_payload["research_target_intake_id"],
        "selected_upgrade_candidate_id": selected["upgrade_candidate_id"],
        "objective": f"Create a Link-native, read-only implementation slice from {source_path_value}: {selected['title']}.",
        "scope_summary": f"Use source-backed evidence from {source_path_value} to implement {selected['description']}",
        "target_link_module": selected["target_link_module"],
        "likely_affected_files": _research_target_likely_files(selected["target_link_module"]),
        "required_evidence": list(selected["evidence_refs"]),
        "required_approvals": list(selected["required_approvals"]),
        "expected_tests": list(selected["required_tests"]),
        "archive_concepts_id": archive_concepts_id,
        "compression_profile_id": compression_profile_id,
        "concept_specificity_score": concept_score,
        "primary_repo_role": role["primary_role"],
        "primary_repo_role_confidence": role["primary_role_confidence"],
        "calibrated_top_concepts": calibrated_top,
        "concept_confidence_warnings": _normalize_implementation_branch_refs([item["concept_name"] for item in confidence["downranked_concepts"][:5]]),
        "overclassification_warnings": role["overclassification_warnings"],
        "calibrated_best_growth_opportunity": selected["title"],
        "role_aligned_task_steps": [
            f"verify {role['primary_role']} evidence refs before patching",
            "keep the implementation slice aligned to the calibrated primary repo role",
            "reject compression-specific work unless calibrated compression evidence supports it",
        ],
        "role_mismatch_warning": "" if (role["primary_role"] == "compression_context") == is_compression_profile else "task source role and compression profile selection require operator review",
        "concept_supported_task_steps": concept_steps,
        "concept_supported_tests": [
            "archive-concepts smoke for Headroom and gpt-crawler",
            "compression-profile smoke keeps MCP/proxy disabled",
            "compression-upgrade-score ranks compression-specific upgrade first",
        ] if is_compression_profile else [],
        "concept_risks": ["auto_mcp_server_start", "proxy_as_default_path", "compression_overrides_provenance", "compression_changes_alias_map"] if is_compression_profile else [],
        "genericity_warning": "" if selected.get("compression_specific") or not is_compression_profile else "selected task is less specific than detected compression concepts",
        "recommended_files_to_inspect": recommended_files,
        "rollback_plan": [
            "do not copy external source code",
            "revert only the intended Link source/test edits if review rejects the slice",
            "keep research target files unchanged",
        ],
        "execution_allowed": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": metadata_input,
        "recommended_next_action": "Review this target-bound task draft before any implementation work.",
        "writes": [],
    }
    validate_research_target_operator_task_draft(draft, candidates_payload, evidence)
    return draft


def validate_research_target_operator_task_draft(draft: dict[str, Any], research_target_upgrade_candidates: dict[str, Any] | None = None, research_target_evidence_bundle: dict[str, Any] | None = None) -> None:
    required = (
        "research_target_operator_task_draft_version", "research_target_operator_task_draft_id",
        "research_target_intake_id", "selected_upgrade_candidate_id", "objective", "scope_summary",
        "target_link_module", "likely_affected_files", "required_evidence", "required_approvals",
        "expected_tests", "rollback_plan", "execution_allowed", "safety_metadata", "recommended_next_action",
        "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in draft:
            raise ValueError(f"research target operator task draft missing required field: {key}")
    if draft["research_target_operator_task_draft_version"] != RESEARCH_TARGET_OPERATOR_TASK_DRAFT_VERSION:
        raise ValueError("invalid research target operator task draft version")
    if not draft["research_target_operator_task_draft_id"].startswith("research-target-operator-task-draft-"):
        raise ValueError("invalid research target operator task draft id")
    if draft["target_link_module"] not in RESEARCH_TARGET_LINK_MODULES:
        raise ValueError("invalid research target task target module")
    if draft["execution_allowed"] is not False:
        raise ValueError("research target operator task draft must not allow execution")
    for field in ("likely_affected_files", "required_evidence", "required_approvals", "expected_tests", "rollback_plan"):
        if not isinstance(draft[field], list) or not all(isinstance(item, str) and item for item in draft[field]):
            raise ValueError(f"research target operator task draft {field} must be non-empty strings")
    if "research/" not in draft["objective"] or "research/" not in draft["scope_summary"]:
        raise ValueError("research target operator task draft must reference selected research target")
    if draft["safety_metadata"] != _read_only_safety_metadata() or draft["dry_run"] is not True or draft["write_allowed"] is not False or draft["automation_allowed"] is not False or draft["writes"] != []:
        raise ValueError("research target operator task draft must remain read-only")
    if research_target_upgrade_candidates is not None:
        validate_research_target_upgrade_candidates(research_target_upgrade_candidates)
        if draft["research_target_intake_id"] != research_target_upgrade_candidates["research_target_intake_id"]:
            raise ValueError("research target operator task draft intake id mismatch")
        candidate_ids = [item["upgrade_candidate_id"] for item in research_target_upgrade_candidates["upgrade_candidates"]]
        if draft["selected_upgrade_candidate_id"] not in candidate_ids:
            raise ValueError("research target operator task draft candidate id mismatch")
    if research_target_evidence_bundle is not None:
        validate_research_target_evidence_bundle(research_target_evidence_bundle)


def stable_research_target_operator_task_draft_json(draft: dict[str, Any]) -> str:
    validate_research_target_operator_task_draft(draft)
    return _stable_ruflo_json(draft, indent=2) + "\n"


def parse_research_target_operator_task_draft_json(text: str) -> dict[str, Any]:
    import json as _json

    draft = _json.loads(text)
    validate_research_target_operator_task_draft(draft)
    return draft


def collect_research_target_operator_flow(
    *,
    source_path: str,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    intake = collect_research_target_intake(source_path)
    evidence = collect_research_target_evidence_bundle(intake)
    candidates = collect_research_target_upgrade_candidates(intake, evidence)
    archive_concepts = collect_source_aware_archive_concepts(intake, evidence)
    task = collect_research_target_operator_task_draft(candidates, evidence, metadata={"_archive_concepts": archive_concepts})
    selected = next(item for item in candidates["upgrade_candidates"] if item["upgrade_candidate_id"] == task["selected_upgrade_candidate_id"])
    warnings = []
    if evidence["missing_evidence"]:
        warnings.extend(evidence["missing_evidence"])
    blocker_count = len(candidates["blocked_candidates"])
    digest = _research_target_hash_text({
        "candidates_id": candidates["research_target_upgrade_candidates_id"],
        "evidence_id": evidence["research_target_evidence_bundle_id"],
        "intake_id": intake["research_target_intake_id"],
        "task_id": task["research_target_operator_task_draft_id"],
        "version": RESEARCH_TARGET_OPERATOR_FLOW_VERSION,
    })[:12]
    flow = {
        "research_target_operator_flow_version": RESEARCH_TARGET_OPERATOR_FLOW_VERSION,
        "research_target_operator_flow_id": f"research-target-operator-flow-{digest}",
        "research_target_intake_id": intake["research_target_intake_id"],
        "research_target_evidence_bundle_id": evidence["research_target_evidence_bundle_id"],
        "research_target_upgrade_candidates_id": candidates["research_target_upgrade_candidates_id"],
        "research_target_operator_task_draft_id": task["research_target_operator_task_draft_id"],
        "selected_upgrade_summary": {
            "upgrade_candidate_id": selected["upgrade_candidate_id"],
            "title": selected["title"],
            "target_link_module": selected["target_link_module"],
            "source_path": intake["source_path"],
        },
        "blocker_count": blocker_count,
        "warning_count": len(warnings),
        "warnings": _normalize_implementation_branch_refs(warnings),
        "recommended_next_action": "Review the target-bound task draft; do not execute it without a separate approved implementation slice.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_research_target_operator_flow(flow, intake, evidence, candidates, task)
    return flow


def validate_research_target_operator_flow(flow: dict[str, Any], research_target_intake: dict[str, Any] | None = None, research_target_evidence_bundle: dict[str, Any] | None = None, research_target_upgrade_candidates: dict[str, Any] | None = None, research_target_operator_task_draft: dict[str, Any] | None = None) -> None:
    required = (
        "research_target_operator_flow_version", "research_target_operator_flow_id",
        "research_target_intake_id", "research_target_evidence_bundle_id",
        "research_target_upgrade_candidates_id", "research_target_operator_task_draft_id",
        "selected_upgrade_summary", "blocker_count", "warning_count", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in flow:
            raise ValueError(f"research target operator flow missing required field: {key}")
    if flow["research_target_operator_flow_version"] != RESEARCH_TARGET_OPERATOR_FLOW_VERSION:
        raise ValueError("invalid research target operator flow version")
    if not flow["research_target_operator_flow_id"].startswith("research-target-operator-flow-"):
        raise ValueError("invalid research target operator flow id")
    for field in ("blocker_count", "warning_count"):
        if not isinstance(flow[field], int) or flow[field] < 0:
            raise ValueError(f"research target operator flow {field} must be non-negative")
    summary = flow["selected_upgrade_summary"]
    if not isinstance(summary, dict) or not summary.get("source_path", "").startswith("research/"):
        raise ValueError("research target operator flow summary must reference source path")
    if flow["safety_metadata"] != _read_only_safety_metadata() or flow["dry_run"] is not True or flow["write_allowed"] is not False or flow["automation_allowed"] is not False or flow["writes"] != []:
        raise ValueError("research target operator flow must remain read-only")
    if research_target_intake is not None and flow["research_target_intake_id"] != research_target_intake["research_target_intake_id"]:
        raise ValueError("research target operator flow intake id mismatch")
    if research_target_evidence_bundle is not None and flow["research_target_evidence_bundle_id"] != research_target_evidence_bundle["research_target_evidence_bundle_id"]:
        raise ValueError("research target operator flow evidence id mismatch")
    if research_target_upgrade_candidates is not None and flow["research_target_upgrade_candidates_id"] != research_target_upgrade_candidates["research_target_upgrade_candidates_id"]:
        raise ValueError("research target operator flow candidates id mismatch")
    if research_target_operator_task_draft is not None and flow["research_target_operator_task_draft_id"] != research_target_operator_task_draft["research_target_operator_task_draft_id"]:
        raise ValueError("research target operator flow task id mismatch")


def stable_research_target_operator_flow_json(flow: dict[str, Any]) -> str:
    validate_research_target_operator_flow(flow)
    return _stable_ruflo_json(flow, indent=2) + "\n"


def parse_research_target_operator_flow_json(text: str) -> dict[str, Any]:
    import json as _json

    flow = _json.loads(text)
    validate_research_target_operator_flow(flow)
    return flow



RESEARCH_SOURCE_BINDING_CONTEXT_VERSION = "link-research-source-binding-context-v1"
SOURCE_AWARE_OPERATOR_FLOW_VERSION = "link-source-aware-operator-flow-v1"


def _source_aware_hash_id(prefix: str, payload: dict[str, Any]) -> str:
    digest = _research_target_hash_text(payload)[:12]
    return f"{prefix}-{digest}"


def _research_source_binding_from_path(source_path: str) -> dict[str, Any]:
    return collect_research_source_binding_context(source_path=source_path)


def _source_aware_source_metadata(binding: dict[str, Any]) -> dict[str, Any]:
    return {
        "source_bound": True,
        "source_path": binding["source_path"],
        "source_name": binding["source_name"],
        "source_type": binding["source_type"],
        "research_target_intake_id": binding["research_target_intake_id"],
        "research_target_evidence_bundle_id": binding["research_target_evidence_bundle_id"],
        "research_source_binding_context_id": binding["research_source_binding_context_id"],
        "selected_upgrade_candidate_id": binding["selected_upgrade_candidate_id"],
        "source_refs": list(binding["source_refs"]),
        "evidence_refs": list(binding["evidence_refs"]),
    }


def _source_aware_validate_archive_provenance(payload: dict[str, Any]) -> None:
    if payload.get("source_type") != "zip_archive":
        return
    source_path = payload.get("source_path", "")
    for ref in payload.get("source_refs", []):
        if not isinstance(ref, str) or "!" not in ref:
            raise ValueError("source-aware zip source_refs must use archive-qualified provenance_path")
        archive_path, member_path = ref.split("!", 1)
        if archive_path != source_path or not member_path:
            raise ValueError("source-aware zip source_ref must preserve selected archive path")


def validate_source_aware_provenance(payload: dict[str, Any], *, evidence_expected: bool = True) -> None:
    if payload.get("source_bound") is not True:
        return
    for key in ("source_path", "research_target_intake_id", "source_refs"):
        if key not in payload or not payload[key]:
            raise ValueError(f"source-aware payload missing provenance field: {key}")
    if evidence_expected and not payload.get("research_target_evidence_bundle_id"):
        raise ValueError("source-aware payload missing research target evidence bundle id")
    source_refs = payload.get("source_refs")
    if _normalize_implementation_branch_refs(source_refs) != source_refs:
        raise ValueError("source-aware source_refs must be normalized")
    if evidence_expected:
        evidence_refs = payload.get("evidence_refs")
        if not evidence_refs or _normalize_implementation_branch_refs(evidence_refs) != evidence_refs:
            raise ValueError("source-aware evidence_refs must be present and normalized")
    if payload.get("write_allowed") is not False or payload.get("automation_allowed") is not False or payload.get("writes") != []:
        raise ValueError("source-aware payload must remain read-only")
    safety = payload.get("safety_metadata")
    if safety is not None and safety != _read_only_safety_metadata():
        raise ValueError("source-aware safety metadata mismatch")
    _source_aware_validate_archive_provenance(payload)


def collect_research_source_binding_context(
    research_target_intake: dict[str, Any] | None = None,
    research_target_evidence_bundle: dict[str, Any] | None = None,
    research_target_upgrade_candidates: dict[str, Any] | None = None,
    research_target_operator_task_draft: dict[str, Any] | None = None,
    research_target_operator_flow: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if research_target_intake is None:
        if source_path is None:
            raise ValueError("research source binding requires source_path or intake")
        intake = collect_research_target_intake(source_path)
    else:
        intake = research_target_intake
    validate_research_target_intake(intake)
    evidence = research_target_evidence_bundle or collect_research_target_evidence_bundle(intake)
    validate_research_target_evidence_bundle(evidence, intake)
    candidates = research_target_upgrade_candidates or collect_research_target_upgrade_candidates(intake, evidence)
    validate_research_target_upgrade_candidates(candidates, intake, evidence)
    task = research_target_operator_task_draft or collect_research_target_operator_task_draft(candidates, evidence)
    validate_research_target_operator_task_draft(task, candidates, evidence)
    if research_target_operator_flow is not None:
        validate_research_target_operator_flow(research_target_operator_flow)
    selected_candidate_id = task["selected_upgrade_candidate_id"]
    selected = next(item for item in candidates["upgrade_candidates"] if item["upgrade_candidate_id"] == selected_candidate_id)
    source_refs = _normalize_implementation_branch_refs([item.get("provenance_path", item["path"]) for item in evidence["source_refs"]])
    evidence_refs = _normalize_implementation_branch_refs([item["evidence_ref_id"] for item in evidence["evidence_refs"]])
    upgrade_refs = _normalize_implementation_branch_refs([item["upgrade_candidate_id"] for item in candidates["upgrade_candidates"]])
    blockers = _normalize_implementation_branch_refs(list(candidates["missing_evidence"]) + [f"review source-bound candidate before implementation: {selected_candidate_id}"])
    warnings = _normalize_implementation_branch_refs([
        "source binding is read-only and does not authorize execution",
        f"selected research target remains local-only: {intake['source_path']}",
    ])
    context_core = {
        "research_target_intake_id": intake["research_target_intake_id"],
        "research_target_evidence_bundle_id": evidence["research_target_evidence_bundle_id"],
        "research_target_upgrade_candidates_id": candidates["research_target_upgrade_candidates_id"],
        "research_target_operator_task_draft_id": task["research_target_operator_task_draft_id"],
        "selected_upgrade_candidate_id": selected_candidate_id,
        "version": RESEARCH_SOURCE_BINDING_CONTEXT_VERSION,
    }
    context = {
        "research_source_binding_context_version": RESEARCH_SOURCE_BINDING_CONTEXT_VERSION,
        "research_source_binding_context_id": _source_aware_hash_id("research-source-binding-context", context_core),
        "research_target_intake_id": intake["research_target_intake_id"],
        "research_target_evidence_bundle_id": evidence["research_target_evidence_bundle_id"],
        "research_target_upgrade_candidates_id": candidates["research_target_upgrade_candidates_id"],
        "research_target_operator_task_draft_id": task["research_target_operator_task_draft_id"],
        "source_path": intake["source_path"],
        "source_type": intake["source_type"],
        "source_name": intake["source_name"],
        "detected_domains": _normalize_implementation_branch_refs(intake["detected_domains"]),
        "detected_languages": _normalize_implementation_branch_refs(intake["detected_languages"]),
        "source_refs": source_refs,
        "evidence_refs": evidence_refs,
        "upgrade_candidate_refs": upgrade_refs,
        "selected_upgrade_candidate_id": selected_candidate_id,
        "target_link_module": selected["target_link_module"],
        "source_binding_status": "bound" if source_refs and evidence_refs else "blocked",
        "missing_evidence": _normalize_implementation_branch_refs(list(evidence["missing_evidence"]) + list(candidates["missing_evidence"])),
        "blockers": blockers,
        "warnings": warnings,
        "recommended_next_action": "Use this source binding context to drive source-aware Growth, Decision, and Operator planning.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_research_source_binding_context(context, intake, evidence, candidates, task)
    return context


def validate_research_source_binding_context(context: dict[str, Any], research_target_intake: dict[str, Any] | None = None, research_target_evidence_bundle: dict[str, Any] | None = None, research_target_upgrade_candidates: dict[str, Any] | None = None, research_target_operator_task_draft: dict[str, Any] | None = None) -> None:
    required = (
        "research_source_binding_context_version", "research_source_binding_context_id",
        "research_target_intake_id", "research_target_evidence_bundle_id",
        "research_target_upgrade_candidates_id", "research_target_operator_task_draft_id",
        "source_path", "source_type", "source_name", "detected_domains", "detected_languages",
        "source_refs", "evidence_refs", "upgrade_candidate_refs", "selected_upgrade_candidate_id",
        "target_link_module", "source_binding_status", "missing_evidence", "blockers", "warnings",
        "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in context:
            raise ValueError(f"research source binding context missing required field: {key}")
    if context["research_source_binding_context_version"] != RESEARCH_SOURCE_BINDING_CONTEXT_VERSION:
        raise ValueError("invalid research source binding context version")
    if not isinstance(context["research_source_binding_context_id"], str) or not context["research_source_binding_context_id"].startswith("research-source-binding-context-"):
        raise ValueError("invalid research source binding context id")
    if not context["source_path"].startswith("research/"):
        raise ValueError("research source binding source_path must remain under research")
    if context["source_type"] not in {"zip_archive", "folder", "file"}:
        raise ValueError("invalid research source binding source_type")
    for field in ("detected_domains", "detected_languages", "source_refs", "evidence_refs", "upgrade_candidate_refs", "missing_evidence", "blockers", "warnings"):
        if _normalize_implementation_branch_refs(context[field]) != context[field]:
            raise ValueError(f"research source binding {field} must be normalized")
    if not context["source_refs"] or not context["evidence_refs"] or not context["upgrade_candidate_refs"]:
        raise ValueError("research source binding must include source, evidence, and upgrade refs")
    if context["selected_upgrade_candidate_id"] not in context["upgrade_candidate_refs"]:
        raise ValueError("research source binding selected candidate must be available")
    if context["target_link_module"] not in RESEARCH_TARGET_LINK_MODULES:
        raise ValueError("invalid research source binding target module")
    if context["source_binding_status"] not in {"bound", "blocked"}:
        raise ValueError("invalid research source binding status")
    if context["safety_metadata"] != _read_only_safety_metadata() or context["dry_run"] is not True or context["write_allowed"] is not False or context["automation_allowed"] is not False or context["writes"] != []:
        raise ValueError("research source binding must remain read-only")
    validate_source_aware_provenance({**context, "source_bound": True})
    if research_target_intake is not None and context["research_target_intake_id"] != research_target_intake["research_target_intake_id"]:
        raise ValueError("research source binding intake id mismatch")
    if research_target_evidence_bundle is not None and context["research_target_evidence_bundle_id"] != research_target_evidence_bundle["research_target_evidence_bundle_id"]:
        raise ValueError("research source binding evidence id mismatch")
    if research_target_upgrade_candidates is not None and context["research_target_upgrade_candidates_id"] != research_target_upgrade_candidates["research_target_upgrade_candidates_id"]:
        raise ValueError("research source binding candidates id mismatch")
    if research_target_operator_task_draft is not None and context["research_target_operator_task_draft_id"] != research_target_operator_task_draft["research_target_operator_task_draft_id"]:
        raise ValueError("research source binding task draft id mismatch")
    expected_id = _source_aware_hash_id("research-source-binding-context", {
        "research_target_intake_id": context["research_target_intake_id"],
        "research_target_evidence_bundle_id": context["research_target_evidence_bundle_id"],
        "research_target_upgrade_candidates_id": context["research_target_upgrade_candidates_id"],
        "research_target_operator_task_draft_id": context["research_target_operator_task_draft_id"],
        "selected_upgrade_candidate_id": context["selected_upgrade_candidate_id"],
        "version": RESEARCH_SOURCE_BINDING_CONTEXT_VERSION,
    })
    if context["research_source_binding_context_id"] != expected_id:
        raise ValueError("research source binding context id is not deterministic")


def stable_research_source_binding_context_json(context: dict[str, Any]) -> str:
    validate_research_source_binding_context(context)
    return _stable_ruflo_json(context, indent=2) + "\n"


def parse_research_source_binding_context_json(text: str) -> dict[str, Any]:
    import json as _json

    context = _json.loads(text)
    validate_research_source_binding_context(context)
    return context


def _source_aware_candidates_from_binding(binding: dict[str, Any], target_candidates: dict[str, Any] | None = None) -> dict[str, Any]:
    validate_research_source_binding_context(binding)
    target_candidates = target_candidates or collect_research_target_upgrade_candidates(source_path=binding["source_path"])
    validate_research_target_upgrade_candidates(target_candidates)
    source_refs = _normalize_implementation_branch_refs(binding["source_refs"])
    evidence_refs = _normalize_implementation_branch_refs(binding["evidence_refs"])
    opportunities: list[dict[str, Any]] = []
    for candidate in target_candidates["upgrade_candidates"]:
        title = f"Source-bound Link upgrade: {candidate['title']}"
        category = "Internal Automation" if candidate["target_link_module"] in {"engineering", "shared_services", "control_plane", "research"} else "AI Tools"
        opportunity = {
            "title": title,
            "category": category,
            "description": candidate["description"],
            "source_refs": source_refs,
            "evidence_strength": int(max(40, min(100, candidate["confidence_score"]))),
            "confidence_score": int(candidate["confidence_score"]),
            "effort_score": int(candidate["effort_score"]),
            "risk_score": 65 if candidate["risk_level"] == "medium" else 45,
            "monetization_model": "Improve Link's local research-to-upgrade workflow for future projects",
            "growth_channel": f"Local research target intake for {binding['source_name']}",
            "required_approvals": _normalize_implementation_branch_refs(candidate["required_approvals"]),
            "missing_evidence": _normalize_implementation_branch_refs([f"human review of source-bound evidence for {binding['source_path']}"] + list(binding["missing_evidence"] or [])),
            "recommended_next_action": candidate["recommended_next_action"],
            "research_target_intake_id": binding["research_target_intake_id"],
            "research_target_evidence_bundle_id": binding["research_target_evidence_bundle_id"],
            "research_source_binding_context_id": binding["research_source_binding_context_id"],
            "source_path": binding["source_path"],
            "source_name": binding["source_name"],
            "source_type": binding["source_type"],
            "evidence_refs": evidence_refs,
            "detected_domains": list(binding["detected_domains"]),
            "selected_upgrade_candidate_id": candidate["upgrade_candidate_id"],
            "target_link_module": candidate["target_link_module"],
            "source_bound": True,
        }
        opportunity["opportunity_id"] = make_growth_business_opportunity_id(opportunity)
        opportunities.append(opportunity)
    return {"opportunities": sorted(opportunities, key=lambda item: item["opportunity_id"]), "target_candidates": target_candidates}


def _source_aware_decision_candidate_id(candidate: dict[str, Any], binding: dict[str, Any]) -> str:
    return _source_aware_hash_id("decision-candidate", {
        "binding_id": binding["research_source_binding_context_id"],
        "upgrade_candidate_id": candidate["upgrade_candidate_id"],
        "version": DECISION_CANDIDATE_SET_VERSION,
    })


def _source_aware_decision_chain(
    source_path: str | None = None,
    *,
    binding: dict[str, Any] | None = None,
    target_candidates: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    binding = binding or collect_research_source_binding_context(source_path=source_path or "")
    validate_research_source_binding_context(binding)
    target_candidates = target_candidates or collect_research_target_upgrade_candidates(source_path=binding["source_path"])
    validate_research_target_upgrade_candidates(target_candidates)
    source_metadata = _source_aware_source_metadata(binding)
    candidates = []
    for upgrade in target_candidates["upgrade_candidates"]:
        blockers = _normalize_implementation_branch_refs(["source-bound decision is read-only and requires human review"] + list(upgrade.get("missing_evidence", [])))
        concept_boost = 20 if upgrade.get("uses_repo_concepts") else 0
        compression_boost = 12 if upgrade.get("compression_specific") else 0
        candidate = {
            "decision_candidate_id": _source_aware_decision_candidate_id(upgrade, binding),
            "title": upgrade["title"],
            "description": upgrade["description"],
            "source_refs": list(binding["source_refs"]),
            "evidence_refs": list(binding["evidence_refs"]),
            "expected_readiness_gain": int(min(100, max(1, 100 - upgrade["effort_score"] + concept_boost))),
            "expected_risk_reduction": int(min(100, (12 if upgrade["risk_level"] == "medium" else 18) + compression_boost)),
            "expected_evidence_gain": int(min(100, len(upgrade["evidence_refs"]) * 10 + concept_boost)),
            "expected_approval_gain": int(min(100, len(upgrade["required_approvals"]) * 8 + (8 if upgrade.get("uses_repo_concepts") else 0))),
            "effort_score": int(upgrade["effort_score"]),
            "priority": "high" if upgrade.get("uses_repo_concepts") or upgrade["target_link_module"] in {"research", "growth", "control_plane"} else "medium",
            "blockers": blockers,
            "execution_allowed": False,
            **{**source_metadata, "selected_upgrade_candidate_id": upgrade["upgrade_candidate_id"]},
            "target_link_module": upgrade["target_link_module"],
        }
        candidates.append(candidate)
    candidates = sorted(candidates, key=lambda item: item["decision_candidate_id"])
    blocked = [item for item in candidates if item["blockers"]]
    candidate_set = {
        "decision_candidate_set_version": DECISION_CANDIDATE_SET_VERSION,
        "decision_candidate_set_id": _source_aware_hash_id("decision-candidate-set", {
            "candidate_ids": [item["decision_candidate_id"] for item in candidates],
            "binding_id": binding["research_source_binding_context_id"],
            "version": DECISION_CANDIDATE_SET_VERSION,
        }),
        **source_metadata,
        "candidates": candidates,
        "blocked_candidates": blocked,
        "decision_context": {
            "question": "Which source-bound Link upgrade should be planned next?",
            "source_path": binding["source_path"],
            "source_name": binding["source_name"],
            "candidate_count": len(candidates),
            "blocked_candidate_count": len(blocked),
            "execution_allowed": False,
            "source_bound": True,
        },
        "recommended_next_action": "Rank source-bound upgrade candidates and review the top target-specific action.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_decision_candidate_set(candidate_set)
    validate_source_aware_provenance(candidate_set)
    impact = collect_decision_impact_analysis(candidate_set)
    ranking = collect_decision_ranking(candidate_set, impact)
    selected_upgrade_candidate_id = next(item["selected_upgrade_candidate_id"] for item in candidates if item["decision_candidate_id"] == ranking["top_candidate_id"])
    ranking.update({**source_metadata, "selected_upgrade_candidate_id": selected_upgrade_candidate_id})
    validate_decision_ranking(ranking)
    validate_source_aware_provenance(ranking)
    review = collect_operator_decision_review(candidate_set, impact, ranking)
    review.update({**source_metadata, "selected_upgrade_candidate_id": selected_upgrade_candidate_id})
    validate_operator_decision_review(review)
    validate_source_aware_provenance(review)
    breakdown = collect_decision_score_breakdown(candidate_set, impact, ranking)
    rejected = collect_rejected_alternative_analysis(candidate_set, ranking, breakdown)
    ledger = collect_decision_assumption_ledger(candidate_set, ranking, review)
    trace = collect_operator_decision_trace_package(ranking, breakdown, rejected, ledger, review, candidate_set, impact)
    trace.update({
        **source_metadata,
        "selected_upgrade_candidate_id": selected_upgrade_candidate_id,
        "explanation_summary": f"The source-bound candidate {selected_upgrade_candidate_id} won for {binding['source_path']} using deterministic readiness, risk, evidence, approval, effort, and blocker scoring.",
    })
    validate_operator_decision_trace_package(trace)
    validate_source_aware_provenance(trace)
    return {
        "binding": binding,
        "candidate_set": candidate_set,
        "impact": impact,
        "ranking": ranking,
        "review": review,
        "trace": trace,
    }


def _collect_source_aware_operator_task_review_package(
    task: dict[str, Any],
    scope: dict[str, Any],
    tests: dict[str, Any],
    action_evidence: dict[str, Any],
    action_approvals: dict[str, Any],
    source_metadata: dict[str, Any],
) -> dict[str, Any]:
    blockers = _normalize_implementation_branch_refs(list(scope["blockers"]) + list(action_evidence["blockers"]) + list(action_approvals["blockers"]) + ["operator task draft is not executable"])
    package = {
        "operator_task_review_package_version": OPERATOR_TASK_REVIEW_PACKAGE_VERSION,
        "operator_task_review_package_id": make_operator_task_review_package_id(task, scope, tests, action_evidence, action_approvals),
        "operator_task_draft_id": task["operator_task_draft_id"],
        "operator_task_scope_review_id": scope["operator_task_scope_review_id"],
        "operator_task_test_plan_id": tests["operator_task_test_plan_id"],
        "operator_action_evidence_checklist_id": action_evidence["operator_action_evidence_checklist_id"],
        "operator_action_approval_checklist_id": action_approvals["operator_action_approval_checklist_id"],
        "task_status": "draft",
        "scope_status": scope["scope_status"],
        "test_status": "planned",
        "approval_status": action_approvals["approval_status"],
        "readiness_status": "blocked" if blockers else "ready",
        "blockers": blockers,
        "warnings": _normalize_implementation_branch_refs(list(scope["warnings"]) + ["verification commands are strings only and are not executed"]),
        "required_human_actions": _normalize_implementation_branch_refs(list(scope["required_human_actions"]) + list(action_approvals["required_human_actions"])),
        "review_recommendation": "Review the source-bound task draft, scope, and test plan before authorizing implementation.",
        "recommended_next_action": "Use this source-bound task review package to decide whether to authorize a separate implementation slice.",
        **source_metadata,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": {},
        "writes": [],
    }
    validate_operator_task_review_package(package, task, scope, tests, action_evidence, action_approvals)
    validate_source_aware_provenance(package)
    return package


def _select_source_aware_operator_task_candidate(
    decision: dict[str, Any],
    source_context: dict[str, Any] | None,
) -> tuple[dict[str, Any], str, list[str]]:
    ranked_top = next(item for item in decision["candidate_set"]["candidates"] if item["decision_candidate_id"] == decision["ranking"]["top_candidate_id"])
    if source_context is None:
        return ranked_top, "decision_ranking", []
    calibrated_task = source_context.get("research_target_operator_task_draft")
    if not isinstance(calibrated_task, dict):
        return ranked_top, "decision_ranking", []
    selected_id = calibrated_task.get("selected_upgrade_candidate_id")
    if not isinstance(selected_id, str) or not selected_id:
        return ranked_top, "decision_ranking", []
    aligned = next(
        (
            item for item in decision["candidate_set"]["candidates"]
            if item.get("selected_upgrade_candidate_id") == selected_id
        ),
        None,
    )
    if not isinstance(aligned, dict):
        return ranked_top, "decision_ranking", [
            "calibrated task candidate was not present in the decision candidate set",
        ]
    if aligned["decision_candidate_id"] == ranked_top["decision_candidate_id"]:
        return aligned, "decision_ranking", []
    return aligned, "calibrated_task_candidate", [
        f"task draft aligned to calibrated candidate {selected_id} instead of raw decision ranking {ranked_top.get('selected_upgrade_candidate_id', '')}",
    ]


def _source_aware_operator_chain(source_path: str | None = None, *, source_context: dict[str, Any] | None = None) -> dict[str, Any]:
    decision = source_context["decision_chain"] if source_context is not None else _source_aware_decision_chain(source_path)
    binding = decision["binding"]
    top, task_alignment_source, task_alignment_warnings = _select_source_aware_operator_task_candidate(decision, source_context)
    selected_metadata = {**_source_aware_source_metadata(binding), "selected_upgrade_candidate_id": top["selected_upgrade_candidate_id"]}
    target_candidates_payload = source_context.get("research_target_upgrade_candidates", {}) if source_context is not None else {}
    is_compression_profile = bool(target_candidates_payload.get("compression_profile_id"))
    archive_concepts_id = str(target_candidates_payload.get("archive_concepts_id", ""))
    compression_profile_id = str(target_candidates_payload.get("compression_profile_id", ""))
    concept_score = int(target_candidates_payload.get("concept_specificity_score", 0) or 0)
    archive_concepts = source_context.get("archive_concepts") if source_context is not None else None
    if not isinstance(archive_concepts, dict):
        if source_context is not None and isinstance(source_context.get("research_target_intake"), dict) and isinstance(source_context.get("research_target_evidence_bundle"), dict):
            archive_concepts = collect_source_aware_archive_concepts(source_context["research_target_intake"], source_context["research_target_evidence_bundle"])
        else:
            archive_concepts = collect_source_aware_archive_concepts(source_path=binding["source_path"])
    role = collect_calibrated_repo_role_classification(archive_concepts)
    confidence = collect_concept_confidence_calibration(archive_concepts, role)
    calibrated_top = [
        item for item in confidence["concept_calibrations"]
        if item["calibrated_confidence"] >= 35
    ][:5]
    concept_steps = [
        "inspect local compression library/CLI API from source refs",
        "add fixture sample preserving source_path, S1, and E1 aliases",
        "validate compressed output cannot override refs, aliases, IDs, or safety metadata",
        "gate real context compression behind adapter readiness",
        "keep MCP/proxy prohibited by default",
    ] if is_compression_profile else []
    affected_files = _research_target_likely_files(top["target_link_module"])
    action_plan = {
        "operator_action_plan_preview_version": OPERATOR_ACTION_PLAN_PREVIEW_VERSION,
        "operator_action_plan_preview_id": _source_aware_hash_id("operator-action-plan-preview", {
            "trace_id": decision["trace"]["operator_decision_trace_package_id"],
            "review_id": decision["review"]["operator_decision_review_id"],
            "top_candidate_id": top["decision_candidate_id"],
            "binding_id": binding["research_source_binding_context_id"],
            "version": OPERATOR_ACTION_PLAN_PREVIEW_VERSION,
        }),
        "operator_decision_trace_package_id": decision["trace"]["operator_decision_trace_package_id"],
        "operator_decision_review_id": decision["review"]["operator_decision_review_id"],
        "simulation_remediation_plan_id": "source-aware-research-binding",
        "remediation_priority_queue_id": "source-aware-research-binding",
        "top_candidate_id": top["decision_candidate_id"],
        "action_title": f"Plan source-bound Link upgrade from {binding['source_name']}",
        "action_summary": f"Create a non-executable implementation plan for {top['title']} using {binding['source_path']} as evidence.",
        "affected_modules": _normalize_implementation_branch_refs([top["target_link_module"], "research", "operator"]),
        "likely_affected_files": affected_files,
        "required_evidence": _normalize_implementation_branch_refs(list(binding["evidence_refs"]) + list(top["source_refs"])),
        "required_approvals": _normalize_implementation_branch_refs(["human approval before source-bound implementation", "license/copying review before using external patterns"]),
        "expected_tests": _normalize_implementation_branch_refs([
            "git diff --check -- link.py link_modes/growth/link_growth_console.py tests/test_growth_pipeline.py",
            "python3 -m py_compile link.py link_modes/growth/link_growth_console.py tests/test_growth_pipeline.py",
            "PYTHONDONTWRITEBYTECODE=1 python3 tests/test_growth_pipeline.py",
            "PYTHONDONTWRITEBYTECODE=1 python3 link_healthcheck.py",
        ]),
        "rollback_plan": _normalize_implementation_branch_refs(["do not modify the selected research target", "revert only intended Link source/test edits if rejected", "do not copy external code"]),
        "execution_allowed": False,
        "task_alignment_source": task_alignment_source,
        "task_alignment_warnings": _normalize_implementation_branch_refs(task_alignment_warnings),
        **selected_metadata,
        "recommended_next_action": "Review the source-bound action plan before authorizing any implementation slice.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": {},
        "writes": [],
    }
    validate_operator_action_plan_preview(action_plan)
    validate_source_aware_provenance(action_plan)
    action_evidence = collect_operator_action_evidence_checklist(action_plan)
    action_approvals = collect_operator_action_approval_checklist(action_plan)
    action_review = collect_operator_action_review_package(action_plan, action_evidence, action_approvals)
    action_review.update(selected_metadata)
    validate_operator_action_review_package(action_review)
    validate_source_aware_provenance(action_review)
    task = collect_operator_task_draft(action_plan, action_review, decision["trace"])
    task.update({
        **selected_metadata,
        "objective": f"Implement a Link-native upgrade inspired by {binding['source_path']}: {top['title']}.",
        "scope_summary": f"Use source refs from {binding['source_name']} to improve {top['target_link_module']} without copying external code or executing the task.",
        "archive_concepts_id": archive_concepts_id,
        "compression_profile_id": compression_profile_id,
        "concept_specificity_score": concept_score,
        "primary_repo_role": role["primary_role"],
        "primary_repo_role_confidence": role["primary_role_confidence"],
        "calibrated_top_concepts": calibrated_top,
        "concept_confidence_warnings": _normalize_implementation_branch_refs([item["concept_name"] for item in confidence["downranked_concepts"][:5]]),
        "overclassification_warnings": role["overclassification_warnings"],
        "calibrated_best_growth_opportunity": top["title"],
        "task_alignment_source": task_alignment_source,
        "task_alignment_warnings": _normalize_implementation_branch_refs(task_alignment_warnings),
        "task_draft_divergence_warning": "; ".join(_normalize_implementation_branch_refs(task_alignment_warnings)),
        "role_aligned_task_steps": [
            f"verify {role['primary_role']} evidence refs before patching",
            "keep the implementation slice aligned to the calibrated primary repo role",
            "reject compression-specific work unless calibrated compression evidence supports it",
        ],
        "role_mismatch_warning": "" if (role["primary_role"] == "compression_context") == is_compression_profile else "task source role and compression profile selection require operator review",
        "concept_supported_task_steps": concept_steps,
        "concept_supported_tests": [
            "archive-concepts smoke for Headroom and gpt-crawler",
            "compression-profile smoke keeps MCP/proxy disabled",
            "compression-upgrade-score ranks compression-specific upgrade first",
        ] if is_compression_profile else [],
        "concept_risks": ["auto_mcp_server_start", "proxy_as_default_path", "compression_overrides_provenance", "compression_changes_alias_map"] if is_compression_profile else [],
        "genericity_warning": "" if is_compression_profile and "compression" in top["title"].lower() else ("selected task may be less specific than detected compression concepts" if is_compression_profile else ""),
        "recommended_files_to_inspect": list(binding["source_refs"])[:5],
    })
    validate_operator_task_draft(task)
    validate_source_aware_provenance(task)
    scope = collect_operator_task_scope_review(task)
    tests = collect_operator_task_test_plan(task)
    task_review = _collect_source_aware_operator_task_review_package(task, scope, tests, action_evidence, action_approvals, selected_metadata)
    return {
        **decision,
        "action_plan": action_plan,
        "action_review": action_review,
        "task_draft": task,
        "task_review": task_review,
    }


def build_source_aware_context_for_cli(source: str) -> dict[str, Any]:
    intake = collect_research_target_intake(source)
    evidence = collect_research_target_evidence_bundle(intake)
    candidates = collect_research_target_upgrade_candidates(intake, evidence)
    archive_concepts = collect_source_aware_archive_concepts(intake, evidence)
    task = collect_research_target_operator_task_draft(candidates, evidence, metadata={"_archive_concepts": archive_concepts})
    binding = collect_research_source_binding_context(intake, evidence, candidates, task)
    growth_scan = collect_growth_business_opportunity_scan(research_source_binding_context=binding, research_target_upgrade_candidates=candidates)
    growth_contract = collect_growth_business_evidence_contract(growth_scan)
    growth_review = collect_growth_opportunity_review_package(growth_scan, growth_contract)
    decision_chain = _source_aware_decision_chain(binding=binding, target_candidates=candidates)
    context = {
        "research_target_intake": intake,
        "research_target_evidence_bundle": evidence,
        "research_target_upgrade_candidates": candidates,
        "archive_concepts": archive_concepts,
        "research_target_operator_task_draft": task,
        "research_source_binding_context": binding,
        "growth_scan": growth_scan,
        "growth_contract": growth_contract,
        "growth_review": growth_review,
        "decision_chain": decision_chain,
    }
    context["operator_chain"] = _source_aware_operator_chain(source_context=context)
    return context


def collect_source_aware_operator_flow(*, source_path: str, metadata: dict[str, Any] | None = None, source_context: dict[str, Any] | None = None) -> dict[str, Any]:
    context = source_context or build_source_aware_context_for_cli(source_path)
    binding = context["research_source_binding_context"]
    chain = context["operator_chain"]
    growth_scan = context["growth_scan"]
    growth_contract = context["growth_contract"]
    growth_review = context["growth_review"]
    source_metadata = {**_source_aware_source_metadata(binding), "selected_upgrade_candidate_id": chain["ranking"]["selected_upgrade_candidate_id"]}
    flow = {
        "source_aware_operator_flow_version": SOURCE_AWARE_OPERATOR_FLOW_VERSION,
        "source_aware_operator_flow_id": _source_aware_hash_id("source-aware-operator-flow", {
            "binding_id": binding["research_source_binding_context_id"],
            "scan_id": growth_scan["growth_business_opportunity_scan_id"],
            "ranking_id": chain["ranking"]["decision_ranking_id"],
            "task_id": chain["task_draft"]["operator_task_draft_id"],
            "version": SOURCE_AWARE_OPERATOR_FLOW_VERSION,
        }),
        "growth_business_opportunity_scan_id": growth_scan["growth_business_opportunity_scan_id"],
        "growth_business_evidence_contract_id": growth_contract["growth_business_evidence_contract_id"],
        "growth_opportunity_review_package_id": growth_review["growth_opportunity_review_package_id"],
        "decision_candidate_set_id": chain["candidate_set"]["decision_candidate_set_id"],
        "decision_ranking_id": chain["ranking"]["decision_ranking_id"],
        "operator_action_plan_preview_id": chain["action_plan"]["operator_action_plan_preview_id"],
        "operator_task_draft_id": chain["task_draft"]["operator_task_draft_id"],
        "selected_upgrade_summary": {
            "selected_upgrade_candidate_id": chain["ranking"]["selected_upgrade_candidate_id"],
            "top_candidate_id": chain["ranking"]["top_candidate_id"],
            "source_path": binding["source_path"],
            "source_name": binding["source_name"],
            "target_link_module": binding["target_link_module"],
        },
        **source_metadata,
        "blocker_count": len(chain["task_review"]["blockers"]),
        "warning_count": len(chain["task_review"]["warnings"]),
        "recommended_next_action": "Review the source-bound operator task draft before any separate implementation slice.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_source_aware_operator_flow(flow)
    return flow


def validate_source_aware_operator_flow(flow: dict[str, Any]) -> None:
    required = (
        "source_aware_operator_flow_version", "source_aware_operator_flow_id", "research_target_intake_id",
        "research_target_evidence_bundle_id", "research_source_binding_context_id", "selected_upgrade_candidate_id",
        "source_path", "source_name", "source_type", "source_refs", "evidence_refs",
        "growth_business_opportunity_scan_id", "growth_business_evidence_contract_id",
        "growth_opportunity_review_package_id", "decision_candidate_set_id", "decision_ranking_id",
        "operator_action_plan_preview_id", "operator_task_draft_id", "selected_upgrade_summary", "source_bound",
        "blocker_count", "warning_count", "recommended_next_action", "safety_metadata", "dry_run",
        "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in flow:
            raise ValueError(f"source-aware operator flow missing required field: {key}")
    if flow["source_aware_operator_flow_version"] != SOURCE_AWARE_OPERATOR_FLOW_VERSION:
        raise ValueError("invalid source-aware operator flow version")
    if not flow["source_aware_operator_flow_id"].startswith("source-aware-operator-flow-"):
        raise ValueError("invalid source-aware operator flow id")
    if flow["source_bound"] is not True:
        raise ValueError("source-aware operator flow must be source-bound")
    summary = flow["selected_upgrade_summary"]
    if not isinstance(summary, dict) or not summary.get("source_path", "").startswith("research/"):
        raise ValueError("source-aware operator flow must summarize selected source")
    for field in ("blocker_count", "warning_count"):
        if not isinstance(flow[field], int) or flow[field] < 0:
            raise ValueError(f"source-aware operator flow {field} must be non-negative")
    if flow["safety_metadata"] != _read_only_safety_metadata() or flow["dry_run"] is not True or flow["write_allowed"] is not False or flow["automation_allowed"] is not False or flow["writes"] != []:
        raise ValueError("source-aware operator flow must remain read-only")
    validate_source_aware_provenance(flow)


def stable_source_aware_operator_flow_json(flow: dict[str, Any]) -> str:
    validate_source_aware_operator_flow(flow)
    return _stable_ruflo_json(flow, indent=2) + "\n"


def parse_source_aware_operator_flow_json(text: str) -> dict[str, Any]:
    import json as _json

    flow = _json.loads(text)
    validate_source_aware_operator_flow(flow)
    return flow


RESEARCH_TARGET_OPERATOR_REPORT_VERSION = "link-research-target-operator-report-v1"
RESEARCH_TARGET_IMPLEMENTATION_PREVIEW_VERSION = "link-research-target-implementation-preview-v1"
RESEARCH_TARGET_SANDBOX_FLOW_VERSION = "link-research-target-sandbox-flow-v1"
SOURCE_AWARE_TARGET_STATUS_CARD_VERSION = "link-source-aware-target-status-card-v1"
CONTROL_PLANE_TARGET_STATUS_VERSION = "link-control-plane-target-status-v1"
OPERATOR_TARGET_REVIEW_VERSION = "link-operator-target-review-v1"
SOURCE_AWARE_TARGET_DECISION_CARD_VERSION = "link-source-aware-target-decision-card-v1"
SOURCE_AWARE_OPERATOR_DASHBOARD_VERSION = "link-source-aware-operator-dashboard-v1"
RESEARCH_TARGET_PROVENANCE_TABLE_VERSION = "link-research-target-provenance-table-v1"
RESEARCH_TARGET_PATTERN_SUMMARY_VERSION = "link-research-target-pattern-summary-v1"
RESEARCH_TARGET_UPGRADE_RATIONALE_CARD_VERSION = "link-research-target-upgrade-rationale-card-v1"
RESEARCH_TARGET_RECOMMENDATION_SPECIFICITY_VERSION = "link-research-target-recommendation-specificity-v1"
RESEARCH_TARGET_PATTERN_CATEGORIES = (
    "source_governance", "crawler_config", "workflow_automation", "dashboard_ux",
    "operator_report", "evidence_provenance", "campaign_planning", "lead_research",
    "ecommerce_data", "agent_memory", "unknown",
)


def _compact_source_ref_summaries(evidence_bundle: dict[str, Any], *, limit: int = 5) -> list[dict[str, Any]]:
    validate_research_target_evidence_bundle(evidence_bundle)
    summaries = []
    for ref in evidence_bundle["source_refs"][:limit]:
        summaries.append({
            "source_ref_id": ref["source_ref_id"],
            "display_path": ref["display_path"],
            "provenance_path": ref["provenance_path"],
            "file_type": ref["file_type"],
            "size_bytes": ref["size_bytes"],
        })
    return summaries


def _compact_evidence_ref_summaries(evidence_bundle: dict[str, Any], *, limit: int = 5) -> list[dict[str, Any]]:
    validate_research_target_evidence_bundle(evidence_bundle)
    summaries = []
    for ref in evidence_bundle["evidence_refs"][:limit]:
        summaries.append({
            "evidence_ref_id": ref["evidence_ref_id"],
            "source_ref_id": ref["source_ref_id"],
            "evidence_type": ref["evidence_type"],
            "display_path": ref["display_path"],
            "provenance_path": ref["provenance_path"],
            "confidence_score": ref["confidence_score"],
            "risk_score": ref["risk_score"],
        })
    return summaries


def _research_target_domain_for_row(path_text: str, evidence_type: str) -> str:
    domains = _research_target_detect_domains([path_text, evidence_type])
    return next((item for item in domains if item != "unknown"), domains[0])


def _research_target_provenance_row_id(source_path: str, evidence_ref: dict[str, Any]) -> str:
    return "research-target-provenance-row-" + _research_target_hash_text({
        "source_path": source_path,
        "evidence_ref_id": evidence_ref["evidence_ref_id"],
        "provenance_path": evidence_ref["provenance_path"],
    })[:12]


def _research_target_why_relevant(path_text: str, evidence_type: str, domain: str) -> str:
    if evidence_type == "README":
        return "Overview evidence explains target purpose and operator relevance."
    if evidence_type == "package_manifest":
        return "Package metadata exposes dependencies, scripts, and implementation shape."
    if evidence_type == "workflow_definition":
        return "Workflow evidence shows orchestration and automation patterns."
    if evidence_type == "config_file":
        return "Configuration evidence shows boundaries, source assumptions, or runtime settings."
    if evidence_type == "source_code_pattern":
        return f"Source pattern evidence supports {domain} analysis without copying code."
    if domain != "unknown":
        return f"File path and metadata match Link {domain} research signals."
    return "Selected source ref provides local provenance for human review."


def collect_research_target_provenance_table(
    research_target_intake: dict[str, Any] | None = None,
    research_target_evidence_bundle: dict[str, Any] | None = None,
    research_source_binding_context: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if research_target_intake is None or research_target_evidence_bundle is None:
        context = build_source_aware_context_for_cli(str(source_path or ""))
        intake = research_target_intake or context["research_target_intake"]
        evidence = research_target_evidence_bundle or context["research_target_evidence_bundle"]
        binding = research_source_binding_context or context["research_source_binding_context"]
    else:
        intake = research_target_intake
        evidence = research_target_evidence_bundle
        binding = research_source_binding_context
    validate_research_target_intake(intake)
    validate_research_target_evidence_bundle(evidence, intake)
    source_by_id = {item["source_ref_id"]: item for item in evidence["source_refs"]}
    rows = []
    for evidence_ref in evidence["evidence_refs"]:
        source_ref = source_by_id[evidence_ref["source_ref_id"]]
        domain = _research_target_domain_for_row(evidence_ref["display_path"], evidence_ref["evidence_type"])
        rows.append({
            "row_id": _research_target_provenance_row_id(intake["source_path"], evidence_ref),
            "display_path": evidence_ref["display_path"],
            "provenance_path": evidence_ref["provenance_path"],
            "file_type": source_ref["file_type"],
            "evidence_type": evidence_ref["evidence_type"],
            "detected_domain": domain,
            "confidence_score": evidence_ref["confidence_score"],
            "risk_score": evidence_ref["risk_score"],
            "why_relevant": _research_target_why_relevant(evidence_ref["display_path"], evidence_ref["evidence_type"], domain),
            "linked_source_ref_id": evidence_ref["source_ref_id"],
            "linked_evidence_ref_id": evidence_ref["evidence_ref_id"],
        })
    missing = []
    if any(not row["provenance_path"] for row in rows):
        missing.append("provenance_path")
    if intake["source_type"] == "zip_archive" and any("!" not in row["provenance_path"] for row in rows):
        missing.append("archive-qualified provenance_path")
    digest = _research_target_hash_text({
        "intake_id": intake["research_target_intake_id"],
        "evidence_id": evidence["research_target_evidence_bundle_id"],
        "row_ids": [row["row_id"] for row in rows],
        "version": RESEARCH_TARGET_PROVENANCE_TABLE_VERSION,
    })[:12]
    table = {
        "research_target_provenance_table_version": RESEARCH_TARGET_PROVENANCE_TABLE_VERSION,
        "research_target_provenance_table_id": f"research-target-provenance-table-{digest}",
        "source_bound": True,
        "source_path": intake["source_path"],
        "source_name": intake["source_name"],
        "source_type": intake["source_type"],
        "research_target_intake_id": intake["research_target_intake_id"],
        "research_target_evidence_bundle_id": evidence["research_target_evidence_bundle_id"],
        "research_source_binding_context_id": binding["research_source_binding_context_id"] if isinstance(binding, dict) else "",
        "provenance_rows": rows,
        "source_ref_count": len(evidence["source_refs"]),
        "evidence_ref_count": len(evidence["evidence_refs"]),
        "archive_ref_count": sum(1 for row in rows if "!" in row["provenance_path"]),
        "missing_provenance": missing,
        "recommended_next_action": "Use these compact provenance rows to judge whether the selected upgrade is target-specific.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_research_target_provenance_table(table, intake, evidence)
    return table


def validate_research_target_provenance_table(table: dict[str, Any], research_target_intake: dict[str, Any] | None = None, research_target_evidence_bundle: dict[str, Any] | None = None) -> None:
    required = (
        "research_target_provenance_table_version", "research_target_provenance_table_id", "source_bound",
        "source_path", "source_name", "source_type", "research_target_intake_id",
        "research_target_evidence_bundle_id", "provenance_rows", "source_ref_count",
        "evidence_ref_count", "archive_ref_count", "missing_provenance", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in table:
            raise ValueError(f"research target provenance table missing field: {key}")
    if table["research_target_provenance_table_version"] != RESEARCH_TARGET_PROVENANCE_TABLE_VERSION:
        raise ValueError("invalid research target provenance table version")
    if not table["research_target_provenance_table_id"].startswith("research-target-provenance-table-"):
        raise ValueError("invalid research target provenance table id")
    if table["source_bound"] is not True or not table["source_path"].startswith("research/"):
        raise ValueError("research target provenance table must be source-bound under research")
    if not isinstance(table["provenance_rows"], list) or not table["provenance_rows"]:
        raise ValueError("research target provenance table rows must be non-empty")
    for row in table["provenance_rows"]:
        for key in ("row_id", "display_path", "provenance_path", "file_type", "evidence_type", "detected_domain", "confidence_score", "risk_score", "why_relevant", "linked_source_ref_id", "linked_evidence_ref_id"):
            if key not in row:
                raise ValueError(f"research target provenance row missing field: {key}")
        if not row["row_id"].startswith("research-target-provenance-row-"):
            raise ValueError("invalid research target provenance row id")
        _research_target_validate_path_text(row["display_path"], "provenance display_path")
        _research_target_validate_path_text(row["provenance_path"], "provenance provenance_path")
        if "!" in row["display_path"]:
            raise ValueError("provenance display_path must remain clean")
        if table["source_type"] == "zip_archive" and "!" not in row["provenance_path"]:
            raise ValueError("zip provenance rows must be archive-qualified")
        if row["detected_domain"] not in RESEARCH_TARGET_DOMAINS:
            raise ValueError("invalid provenance row domain")
        for score in ("confidence_score", "risk_score"):
            if not isinstance(row[score], int) or not 0 <= row[score] <= 100:
                raise ValueError(f"provenance row {score} must be 0..100")
    for field in ("source_ref_count", "evidence_ref_count", "archive_ref_count"):
        if not isinstance(table[field], int) or table[field] < 0:
            raise ValueError(f"{field} must be non-negative")
    if table["source_ref_count"] <= 0 or table["evidence_ref_count"] <= 0:
        raise ValueError("provenance table must count source and evidence refs")
    if table["source_type"] == "zip_archive" and table["archive_ref_count"] <= 0:
        raise ValueError("zip provenance table must count archive refs")
    if table["safety_metadata"] != _read_only_safety_metadata() or table["dry_run"] is not True or table["write_allowed"] is not False or table["automation_allowed"] is not False or table["writes"] != []:
        raise ValueError("research target provenance table must remain read-only")
    if research_target_intake is not None:
        validate_research_target_intake(research_target_intake)
        if table["research_target_intake_id"] != research_target_intake["research_target_intake_id"]:
            raise ValueError("provenance table intake id mismatch")
    if research_target_evidence_bundle is not None:
        validate_research_target_evidence_bundle(research_target_evidence_bundle, research_target_intake)
        if table["research_target_evidence_bundle_id"] != research_target_evidence_bundle["research_target_evidence_bundle_id"]:
            raise ValueError("provenance table evidence id mismatch")


def stable_research_target_provenance_table_json(table: dict[str, Any]) -> str:
    validate_research_target_provenance_table(table)
    return _stable_ruflo_json(table, indent=2) + "\n"


def parse_research_target_provenance_table_json(text: str) -> dict[str, Any]:
    import json as _json
    table = _json.loads(text)
    validate_research_target_provenance_table(table)
    return table


def _research_target_pattern_category(row: dict[str, Any]) -> str:
    text = " ".join([row.get("display_path", ""), row.get("evidence_type", ""), row.get("detected_domain", "")]).lower()
    if any(token in text for token in ("crawler", "crawl", "scrap", "browser", "selenium", "playwright")):
        return "crawler_config"
    if any(token in text for token in ("workflow", "flow", "action", "trigger", "orchestr", ".yml", ".yaml")):
        return "workflow_automation"
    if any(token in text for token in ("dashboard", "card", "summary", "status", "report")):
        return "dashboard_ux"
    if any(token in text for token in ("readme", "cli", "operator", "review")):
        return "operator_report"
    if any(token in text for token in ("provenance", "source", "config", "package_manifest")):
        return "evidence_provenance"
    if any(token in text for token in ("market", "campaign", "competitor", "seo")):
        return "campaign_planning"
    if any(token in text for token in ("lead", "sales", "crm")):
        return "lead_research"
    if any(token in text for token in ("product", "pricing", "shop", "ecommerce")):
        return "ecommerce_data"
    if "memory" in text:
        return "agent_memory"
    if row.get("detected_domain") == "source_governance":
        return "source_governance"
    return "unknown"


def collect_research_target_pattern_summary(
    research_target_intake: dict[str, Any] | None = None,
    research_target_evidence_bundle: dict[str, Any] | None = None,
    research_target_provenance_table: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if research_target_intake is None or research_target_evidence_bundle is None or research_target_provenance_table is None:
        context = build_source_aware_context_for_cli(str(source_path or ""))
        intake = research_target_intake or context["research_target_intake"]
        evidence = research_target_evidence_bundle or context["research_target_evidence_bundle"]
        table = research_target_provenance_table or collect_research_target_provenance_table(intake, evidence, context["research_source_binding_context"])
    else:
        intake = research_target_intake
        evidence = research_target_evidence_bundle
        table = research_target_provenance_table
    validate_research_target_intake(intake)
    validate_research_target_evidence_bundle(evidence, intake)
    validate_research_target_provenance_table(table, intake, evidence)
    grouped: dict[str, list[dict[str, Any]]] = {}
    for row in table["provenance_rows"]:
        category = _research_target_pattern_category(row)
        grouped.setdefault(category, []).append(row)
    patterns = []
    for category, rows in sorted(grouped.items()):
        refs = rows[:3]
        confidence = max(row["confidence_score"] for row in rows)
        risk = max(row["risk_score"] for row in rows)
        pattern_id = "research-target-pattern-" + _research_target_hash_text({
            "source_path": intake["source_path"],
            "category": category,
            "rows": [row["row_id"] for row in rows],
        })[:12]
        patterns.append({
            "pattern_id": pattern_id,
            "pattern_name": f"{category.replace('_', ' ')} pattern in {intake['source_name']}",
            "pattern_category": category,
            "description": f"{intake['source_path']} contains {len(rows)} provenance-backed {category.replace('_', ' ')} signal(s).",
            "source_refs": [row["linked_source_ref_id"] for row in refs],
            "evidence_refs": [row["linked_evidence_ref_id"] for row in refs],
            "confidence_score": confidence,
            "risk_score": risk,
            "link_mapping": f"Map this {category.replace('_', ' ')} concept into a Link-native read-only planning/reporting slice.",
            "implementation_hint": f"Use the cited provenance rows from {intake['source_name']} as evidence; do not copy external code.",
            "copying_caution": "Concept only. Do not copy source code, dependencies, or runtime behavior from the research target.",
        })
    weak = []
    if any(pattern["pattern_category"] == "unknown" for pattern in patterns):
        weak.append("some selected refs have unknown pattern category")
    dominant_domains = []
    for row in table["provenance_rows"]:
        domain = row["detected_domain"]
        if domain not in dominant_domains:
            dominant_domains.append(domain)
    summary = {
        "max_confidence_score": max((pattern["confidence_score"] for pattern in patterns), default=0),
        "pattern_count": len(patterns),
        "high_confidence_pattern_count": sum(1 for pattern in patterns if pattern["confidence_score"] >= 70),
    }
    digest = _research_target_hash_text({
        "intake_id": intake["research_target_intake_id"],
        "table_id": table["research_target_provenance_table_id"],
        "pattern_ids": [pattern["pattern_id"] for pattern in patterns],
        "version": RESEARCH_TARGET_PATTERN_SUMMARY_VERSION,
    })[:12]
    payload = {
        "research_target_pattern_summary_version": RESEARCH_TARGET_PATTERN_SUMMARY_VERSION,
        "research_target_pattern_summary_id": f"research-target-pattern-summary-{digest}",
        "source_bound": True,
        "source_path": intake["source_path"],
        "source_name": intake["source_name"],
        "source_type": intake["source_type"],
        "research_target_intake_id": intake["research_target_intake_id"],
        "research_target_evidence_bundle_id": evidence["research_target_evidence_bundle_id"],
        "research_target_provenance_table_id": table["research_target_provenance_table_id"],
        "detected_patterns": patterns,
        "dominant_domains": dominant_domains or ["unknown"],
        "weak_signals": weak,
        "pattern_confidence_summary": summary,
        "recommended_next_action": "Use these target-specific patterns to explain why the selected upgrade fits this source.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_research_target_pattern_summary(payload, intake, evidence, table)
    return payload


def validate_research_target_pattern_summary(payload: dict[str, Any], research_target_intake: dict[str, Any] | None = None, research_target_evidence_bundle: dict[str, Any] | None = None, research_target_provenance_table: dict[str, Any] | None = None) -> None:
    required = (
        "research_target_pattern_summary_version", "research_target_pattern_summary_id", "source_bound",
        "source_path", "research_target_intake_id", "research_target_evidence_bundle_id",
        "research_target_provenance_table_id", "detected_patterns", "dominant_domains", "weak_signals",
        "pattern_confidence_summary", "recommended_next_action", "safety_metadata", "dry_run",
        "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"research target pattern summary missing field: {key}")
    if payload["research_target_pattern_summary_version"] != RESEARCH_TARGET_PATTERN_SUMMARY_VERSION:
        raise ValueError("invalid research target pattern summary version")
    if not payload["research_target_pattern_summary_id"].startswith("research-target-pattern-summary-"):
        raise ValueError("invalid research target pattern summary id")
    if payload["source_bound"] is not True or not payload["source_path"].startswith("research/"):
        raise ValueError("research target pattern summary must be source-bound")
    if not isinstance(payload["detected_patterns"], list) or not payload["detected_patterns"]:
        raise ValueError("research target pattern summary requires detected patterns")
    for pattern in payload["detected_patterns"]:
        for key in ("pattern_id", "pattern_name", "pattern_category", "description", "source_refs", "evidence_refs", "confidence_score", "risk_score", "link_mapping", "implementation_hint", "copying_caution"):
            if key not in pattern:
                raise ValueError(f"research target pattern missing field: {key}")
        if not pattern["pattern_id"].startswith("research-target-pattern-"):
            raise ValueError("invalid research target pattern id")
        if pattern["pattern_category"] not in RESEARCH_TARGET_PATTERN_CATEGORIES:
            raise ValueError("invalid research target pattern category")
        if not pattern["source_refs"] or not pattern["evidence_refs"]:
            raise ValueError("research target pattern must include source and evidence refs")
        if not pattern["copying_caution"]:
            raise ValueError("research target pattern must include copying caution")
        for score in ("confidence_score", "risk_score"):
            if not isinstance(pattern[score], int) or not 0 <= pattern[score] <= 100:
                raise ValueError(f"pattern {score} must be 0..100")
    if not isinstance(payload["dominant_domains"], list) or not payload["dominant_domains"]:
        raise ValueError("dominant domains must be non-empty")
    if not isinstance(payload["weak_signals"], list):
        raise ValueError("weak signals must be a list")
    if not isinstance(payload["pattern_confidence_summary"], dict) or payload["pattern_confidence_summary"].get("pattern_count") != len(payload["detected_patterns"]):
        raise ValueError("invalid pattern confidence summary")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("research target pattern summary must remain read-only")
    if research_target_intake is not None and payload["research_target_intake_id"] != research_target_intake["research_target_intake_id"]:
        raise ValueError("pattern summary intake id mismatch")
    if research_target_evidence_bundle is not None and payload["research_target_evidence_bundle_id"] != research_target_evidence_bundle["research_target_evidence_bundle_id"]:
        raise ValueError("pattern summary evidence id mismatch")
    if research_target_provenance_table is not None and payload["research_target_provenance_table_id"] != research_target_provenance_table["research_target_provenance_table_id"]:
        raise ValueError("pattern summary provenance id mismatch")


def stable_research_target_pattern_summary_json(payload: dict[str, Any]) -> str:
    validate_research_target_pattern_summary(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_research_target_pattern_summary_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_research_target_pattern_summary(payload)
    return payload


def collect_research_target_upgrade_rationale_card(
    research_target_upgrade_candidates: dict[str, Any] | None = None,
    research_target_pattern_summary: dict[str, Any] | None = None,
    research_target_provenance_table: dict[str, Any] | None = None,
    decision_ranking: dict[str, Any] | None = None,
    decision_trace: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if research_target_upgrade_candidates is None or research_target_pattern_summary is None or research_target_provenance_table is None or decision_ranking is None or decision_trace is None:
        context = build_source_aware_context_for_cli(str(source_path or ""))
        intake = context["research_target_intake"]
        evidence = context["research_target_evidence_bundle"]
        candidates = research_target_upgrade_candidates or context["research_target_upgrade_candidates"]
        table = research_target_provenance_table or collect_research_target_provenance_table(intake, evidence, context["research_source_binding_context"])
        patterns = research_target_pattern_summary or collect_research_target_pattern_summary(intake, evidence, table)
        ranking = decision_ranking or context["decision_chain"]["ranking"]
        trace = decision_trace or context["decision_chain"]["trace"]
    else:
        candidates = research_target_upgrade_candidates
        patterns = research_target_pattern_summary
        table = research_target_provenance_table
        ranking = decision_ranking
        trace = decision_trace
    validate_research_target_upgrade_candidates(candidates)
    validate_research_target_pattern_summary(patterns)
    validate_research_target_provenance_table(table)
    selected_id = ranking["selected_upgrade_candidate_id"]
    selected = next(item for item in candidates["upgrade_candidates"] if item["upgrade_candidate_id"] == selected_id)
    supporting_patterns = patterns["detected_patterns"][:3]
    supporting_rows = table["provenance_rows"][:5]
    pattern_names = [item["pattern_name"] for item in supporting_patterns]
    row_paths = [item["provenance_path"] for item in supporting_rows[:3]]
    archive_concepts = collect_source_aware_archive_concepts(source_path=table["source_path"])
    compression_profile = collect_compression_repo_concept_profile(archive_concepts)
    top_concepts = [item["concept_name"] for item in archive_concepts["detected_concepts"][:3]]
    why_target = f"{table['source_path']} has {len(table['provenance_rows'])} provenance-backed row(s) across {', '.join(patterns['dominant_domains'])}; strongest concepts: {', '.join(top_concepts or pattern_names[:2])}."
    why_upgrade = f"{selected['title']} fits {table['source_name']} because its cited patterns and concepts map to Link {selected['target_link_module']} work and are backed by refs such as {', '.join(row_paths)}."
    rejected = [
        {
            "upgrade_candidate_id": item["upgrade_candidate_id"],
            "title": item["title"],
            "reason": f"Less specific to {table['source_name']} than {selected['title']}." if item["upgrade_candidate_id"] != selected_id else "selected",
        }
        for item in candidates["upgrade_candidates"]
        if item["upgrade_candidate_id"] != selected_id
    ][:3]
    digest = _research_target_hash_text({
        "source_path": table["source_path"],
        "selected_id": selected_id,
        "pattern_summary_id": patterns["research_target_pattern_summary_id"],
        "provenance_table_id": table["research_target_provenance_table_id"],
        "ranking_id": ranking["decision_ranking_id"],
        "trace_id": trace["operator_decision_trace_package_id"],
        "version": RESEARCH_TARGET_UPGRADE_RATIONALE_CARD_VERSION,
    })[:12]
    payload = {
        "research_target_upgrade_rationale_card_version": RESEARCH_TARGET_UPGRADE_RATIONALE_CARD_VERSION,
        "research_target_upgrade_rationale_card_id": f"research-target-upgrade-rationale-card-{digest}",
        "source_bound": True,
        "source_path": table["source_path"],
        "source_name": table["source_name"],
        "source_type": table["source_type"],
        "research_target_intake_id": table["research_target_intake_id"],
        "research_target_evidence_bundle_id": table["research_target_evidence_bundle_id"],
        "research_target_provenance_table_id": table["research_target_provenance_table_id"],
        "research_target_pattern_summary_id": patterns["research_target_pattern_summary_id"],
        "selected_upgrade_candidate_id": selected_id,
        "selected_upgrade_title": selected["title"],
        "target_link_module": selected["target_link_module"],
        "archive_concepts_id": archive_concepts["source_aware_archive_concepts_id"],
        "detected_concept_families": archive_concepts["concept_families"],
        "top_detected_concepts": [item["concept_id"] for item in archive_concepts["detected_concepts"][:5]],
        "compression_profile_id": compression_profile["compression_repo_concept_profile_id"] if compression_profile["is_compression_repo"] else "",
        "compression_score": compression_profile["compression_score"] if compression_profile["is_compression_repo"] else 0,
        "genericity_assessment_id": candidates.get("genericity_assessment_id", ""),
        "concept_specificity_score": min(100, archive_concepts["confidence_score"] + (10 if selected.get("compression_specific") else 0)),
        "generic_upgrade_warnings": ["selected upgrade should stay grounded in detected repo concepts"] if not selected.get("uses_repo_concepts") and compression_profile["is_compression_repo"] else [],
        "concept_supported_upgrade_ids": [item["upgrade_candidate_id"] for item in candidates["upgrade_candidates"] if item.get("uses_repo_concepts")],
        "recommended_concept_specific_upgrade": selected_id if selected.get("uses_repo_concepts") else "",
        "why_this_target": why_target,
        "why_this_upgrade": why_upgrade,
        "supporting_patterns": [
            {
                "pattern_id": item["pattern_id"],
                "pattern_name": item["pattern_name"],
                "pattern_category": item["pattern_category"],
                "confidence_score": item["confidence_score"],
            }
            for item in supporting_patterns
        ],
        "supporting_provenance_rows": [
            {
                "row_id": item["row_id"],
                "display_path": item["display_path"],
                "provenance_path": item["provenance_path"],
                "evidence_type": item["evidence_type"],
                "why_relevant": item["why_relevant"],
            }
            for item in supporting_rows
        ],
        "expected_value": selected["expected_value"],
        "risk_level": selected["risk_level"],
        "confidence_score": selected["confidence_score"],
        "effort_score": selected["effort_score"],
        "rejected_alternatives_summary": rejected,
        "recommended_next_action": "Use this rationale to decide whether the selected upgrade is target-specific enough for implementation planning.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_research_target_upgrade_rationale_card(payload, candidates, patterns, table)
    return payload


def validate_research_target_upgrade_rationale_card(payload: dict[str, Any], research_target_upgrade_candidates: dict[str, Any] | None = None, research_target_pattern_summary: dict[str, Any] | None = None, research_target_provenance_table: dict[str, Any] | None = None) -> None:
    required = (
        "research_target_upgrade_rationale_card_version", "research_target_upgrade_rationale_card_id",
        "source_bound", "source_path", "research_target_intake_id", "selected_upgrade_candidate_id",
        "selected_upgrade_title", "target_link_module", "why_this_target", "why_this_upgrade",
        "supporting_patterns", "supporting_provenance_rows", "expected_value", "risk_level",
        "confidence_score", "effort_score", "rejected_alternatives_summary", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"research target upgrade rationale missing field: {key}")
    if payload["research_target_upgrade_rationale_card_version"] != RESEARCH_TARGET_UPGRADE_RATIONALE_CARD_VERSION:
        raise ValueError("invalid research target upgrade rationale version")
    if not payload["research_target_upgrade_rationale_card_id"].startswith("research-target-upgrade-rationale-card-"):
        raise ValueError("invalid research target upgrade rationale id")
    if payload["source_bound"] is not True or payload["source_path"] not in payload["why_this_target"] or payload["source_name"] not in payload["why_this_upgrade"]:
        raise ValueError("upgrade rationale must be source-specific")
    if payload["target_link_module"] not in RESEARCH_TARGET_LINK_MODULES:
        raise ValueError("invalid rationale target module")
    if not isinstance(payload["supporting_patterns"], list) or not payload["supporting_patterns"]:
        raise ValueError("upgrade rationale requires supporting patterns")
    if not isinstance(payload["supporting_provenance_rows"], list) or not payload["supporting_provenance_rows"]:
        raise ValueError("upgrade rationale requires supporting provenance rows")
    if payload["source_type"] == "zip_archive" and any("!" not in item["provenance_path"] for item in payload["supporting_provenance_rows"]):
        raise ValueError("upgrade rationale zip provenance must be archive-qualified")
    if payload["expected_value"] not in {"low", "medium", "high"} or payload["risk_level"] not in {"low", "medium", "high"}:
        raise ValueError("invalid rationale value/risk")
    for score in ("confidence_score", "effort_score"):
        if not isinstance(payload[score], int) or not 0 <= payload[score] <= 100:
            raise ValueError(f"rationale {score} must be 0..100")
    if not isinstance(payload["rejected_alternatives_summary"], list):
        raise ValueError("rejected alternatives summary must be a list")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("upgrade rationale must remain read-only")
    if research_target_upgrade_candidates is not None:
        validate_research_target_upgrade_candidates(research_target_upgrade_candidates)
    if research_target_pattern_summary is not None and payload["research_target_pattern_summary_id"] != research_target_pattern_summary["research_target_pattern_summary_id"]:
        raise ValueError("rationale pattern summary id mismatch")
    if research_target_provenance_table is not None and payload["research_target_provenance_table_id"] != research_target_provenance_table["research_target_provenance_table_id"]:
        raise ValueError("rationale provenance table id mismatch")


def stable_research_target_upgrade_rationale_card_json(payload: dict[str, Any]) -> str:
    validate_research_target_upgrade_rationale_card(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_research_target_upgrade_rationale_card_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_research_target_upgrade_rationale_card(payload)
    return payload


def _specificity_factor(name: str, passed: bool, points: int = 10) -> dict[str, Any]:
    return {"factor": name, "passed": bool(passed), "points": points if passed else 0}


def _specificity_grade(score: int) -> str:
    if score >= 85:
        return "strong"
    if score >= 65:
        return "acceptable"
    if score >= 40:
        return "weak"
    return "generic"


def collect_research_target_recommendation_specificity(
    research_target_operator_report: dict[str, Any] | None = None,
    research_target_upgrade_rationale_card: dict[str, Any] | None = None,
    research_target_pattern_summary: dict[str, Any] | None = None,
    research_target_provenance_table: dict[str, Any] | None = None,
    operator_task_draft: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if research_target_operator_report is None or research_target_upgrade_rationale_card is None or research_target_pattern_summary is None or research_target_provenance_table is None or operator_task_draft is None:
        context = build_source_aware_context_for_cli(str(source_path or ""))
        report = research_target_operator_report or collect_research_target_operator_report(source_path=str(source_path or ""), source_context=context)
        table = research_target_provenance_table or collect_research_target_provenance_table(context["research_target_intake"], context["research_target_evidence_bundle"], context["research_source_binding_context"])
        patterns = research_target_pattern_summary or collect_research_target_pattern_summary(context["research_target_intake"], context["research_target_evidence_bundle"], table)
        rationale = research_target_upgrade_rationale_card or collect_research_target_upgrade_rationale_card(context["research_target_upgrade_candidates"], patterns, table, context["decision_chain"]["ranking"], context["decision_chain"]["trace"])
        task = operator_task_draft or context["operator_chain"]["task_draft"]
    else:
        report = research_target_operator_report
        rationale = research_target_upgrade_rationale_card
        patterns = research_target_pattern_summary
        table = research_target_provenance_table
        task = operator_task_draft
    source_path_value = report.get("source_path") or rationale.get("source_path") or table.get("source_path")
    archive_concepts = collect_source_aware_archive_concepts(source_path=source_path_value)
    compression_profile = collect_compression_repo_concept_profile(archive_concepts)
    concept_supported = bool(rationale.get("recommended_concept_specific_upgrade")) or bool(compression_profile["is_compression_repo"] and "compression" in (rationale.get("selected_upgrade_title", "") + rationale.get("why_this_upgrade", "")).lower())
    factors = [
        _specificity_factor("source_path_present", bool(source_path_value)),
        _specificity_factor("source_refs_present", bool(report.get("source_refs"))),
        _specificity_factor("evidence_refs_present", bool(report.get("evidence_refs"))),
        _specificity_factor("provenance_paths_present", bool(table.get("provenance_rows")) and all(row.get("provenance_path") for row in table.get("provenance_rows", []))),
        _specificity_factor("target_patterns_present", bool(patterns.get("detected_patterns"))),
        _specificity_factor("likely_affected_files_present", bool(report.get("likely_affected_files"))),
        _specificity_factor("expected_tests_present", bool(report.get("expected_tests"))),
        _specificity_factor("why_this_target_present", bool(rationale.get("why_this_target")) and source_path_value in rationale.get("why_this_target", "")),
        _specificity_factor("why_this_upgrade_present", bool(rationale.get("why_this_upgrade")) and rationale.get("source_name", "") in rationale.get("why_this_upgrade", "")),
        _specificity_factor("task_draft_mentions_target", bool(source_path_value) and source_path_value in (task.get("objective", "") + " " + task.get("scope_summary", ""))),
    ]
    score = sum(item["points"] for item in factors)
    missing = [item["factor"] for item in factors if not item["passed"]]
    warnings = [f"missing specificity factor: {item}" for item in missing]
    if score < 65:
        warnings.append("recommendation may still be too generic for operator use")
    digest = _research_target_hash_text({
        "source_path": source_path_value,
        "selected_upgrade_candidate_id": report.get("selected_upgrade_candidate_id") or rationale.get("selected_upgrade_candidate_id"),
        "score": score,
        "missing": missing,
        "version": RESEARCH_TARGET_RECOMMENDATION_SPECIFICITY_VERSION,
    })[:12]
    payload = {
        "research_target_recommendation_specificity_version": RESEARCH_TARGET_RECOMMENDATION_SPECIFICITY_VERSION,
        "research_target_recommendation_specificity_id": f"research-target-recommendation-specificity-{digest}",
        "source_bound": True,
        "source_path": source_path_value,
        "research_target_intake_id": report.get("research_target_intake_id") or rationale.get("research_target_intake_id"),
        "research_target_evidence_bundle_id": report.get("research_target_evidence_bundle_id") or rationale.get("research_target_evidence_bundle_id"),
        "selected_upgrade_candidate_id": report.get("selected_upgrade_candidate_id") or rationale.get("selected_upgrade_candidate_id"),
        "specificity_score": score,
        "specificity_grade": _specificity_grade(score),
        "archive_concepts_id": archive_concepts["source_aware_archive_concepts_id"],
        "detected_concept_families": archive_concepts["concept_families"],
        "top_detected_concepts": [item["concept_id"] for item in archive_concepts["detected_concepts"][:5]],
        "compression_profile_id": compression_profile["compression_repo_concept_profile_id"] if compression_profile["is_compression_repo"] else "",
        "compression_score": compression_profile["compression_score"] if compression_profile["is_compression_repo"] else 0,
        "genericity_assessment_id": rationale.get("genericity_assessment_id", ""),
        "concept_specificity_score": min(100, score + (10 if concept_supported else 0)),
        "generic_upgrade_warnings": ["compression concepts detected but selected recommendation may still be generic"] if compression_profile["is_compression_repo"] and not concept_supported else [],
        "concept_supported_upgrade_ids": rationale.get("concept_supported_upgrade_ids", []),
        "recommended_concept_specific_upgrade": rationale.get("recommended_concept_specific_upgrade", ""),
        "specificity_factors": factors,
        "genericity_warnings": warnings,
        "missing_specificity": missing,
        "recommended_next_action": "Proceed only if the specificity grade is acceptable or strong; otherwise improve target evidence and rationale first.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_research_target_recommendation_specificity(payload)
    return payload


def validate_research_target_recommendation_specificity(payload: dict[str, Any]) -> None:
    required = (
        "research_target_recommendation_specificity_version", "research_target_recommendation_specificity_id",
        "source_bound", "source_path", "selected_upgrade_candidate_id", "specificity_score",
        "specificity_grade", "specificity_factors", "genericity_warnings", "missing_specificity",
        "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"research target recommendation specificity missing field: {key}")
    if payload["research_target_recommendation_specificity_version"] != RESEARCH_TARGET_RECOMMENDATION_SPECIFICITY_VERSION:
        raise ValueError("invalid recommendation specificity version")
    if not payload["research_target_recommendation_specificity_id"].startswith("research-target-recommendation-specificity-"):
        raise ValueError("invalid recommendation specificity id")
    if payload["source_bound"] is not True or not payload["source_path"].startswith("research/"):
        raise ValueError("recommendation specificity must be source-bound")
    if not isinstance(payload["specificity_score"], int) or not 0 <= payload["specificity_score"] <= 100:
        raise ValueError("specificity score must be 0..100")
    if payload["specificity_grade"] != _specificity_grade(payload["specificity_score"]):
        raise ValueError("specificity grade does not match score")
    factor_names = {item.get("factor") for item in payload["specificity_factors"] if isinstance(item, dict)}
    required_factors = {
        "source_path_present", "source_refs_present", "evidence_refs_present", "provenance_paths_present",
        "target_patterns_present", "likely_affected_files_present", "expected_tests_present",
        "why_this_target_present", "why_this_upgrade_present", "task_draft_mentions_target",
    }
    if factor_names != required_factors:
        raise ValueError("specificity factors are incomplete")
    for item in payload["specificity_factors"]:
        if not isinstance(item.get("passed"), bool) or not isinstance(item.get("points"), int):
            raise ValueError("specificity factor must include boolean passed and integer points")
    if payload["specificity_grade"] == "generic" and not payload["genericity_warnings"]:
        raise ValueError("generic specificity requires warnings")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("recommendation specificity must remain read-only")


def stable_research_target_recommendation_specificity_json(payload: dict[str, Any]) -> str:
    validate_research_target_recommendation_specificity(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_research_target_recommendation_specificity_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_research_target_recommendation_specificity(payload)
    return payload





def _persistent_source_cache_root() -> tuple[str, str]:
    import os as _os
    from pathlib import Path as _Path

    override = str(_os.environ.get("LINK_SOURCE_CACHE_ROOT", "")).strip()
    if override:
        root = _Path(override).expanduser()
        source = "LINK_SOURCE_CACHE_ROOT"
    else:
        root = _Path.home() / ".cache" / "link" / "source_inventory"
        source = "default"
    return str(root), source


def _persistent_source_cache_path_is_safe(path_text: str) -> bool:
    from pathlib import Path as _Path

    try:
        path = _Path(path_text).expanduser().resolve()
        repo = _Path.cwd().resolve()
    except Exception:
        return False
    denied = {repo / ".git", repo / ".link"}
    if path == repo or repo in path.parents:
        # Tests may intentionally use /tmp. Production cache should not live in the repo.
        return False
    for item in denied:
        if path == item or item in path.parents:
            return False
    return True


def _persistent_source_cache_file_path(cache_root: str, cache_key: str) -> str:
    from pathlib import Path as _Path
    import re as _re

    safe = _re.sub(r"[^A-Za-z0-9_.-]+", "-", cache_key).strip("-")[:180]
    return str(_Path(cache_root).expanduser() / f"{safe}.json")


def collect_persistent_source_inventory_cache_policy(*, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    cache_root, root_source = _persistent_source_cache_root()
    payload = {
        "persistent_source_inventory_cache_policy_version": PERSISTENT_SOURCE_INVENTORY_CACHE_POLICY_VERSION,
        "persistent_source_inventory_cache_policy_id": "persistent-source-inventory-cache-policy-" + _research_target_hash_text({"cache_root": cache_root, "version": PERSISTENT_SOURCE_INVENTORY_CACHE_POLICY_VERSION})[:12],
        "cache_enabled_by_default": True,
        "cache_root": cache_root,
        "cache_root_source": root_source,
        "cache_namespace": "source_inventory",
        "cache_version": SOURCE_ARCHIVE_INTAKE_CACHE_VERSION,
        "collector_version": PERSISTENT_SOURCE_INVENTORY_COLLECTOR_VERSION,
        "provenance_schema_version": PERSISTENT_SOURCE_INVENTORY_PROVENANCE_SCHEMA_VERSION,
        "cache_schema_version": PERSISTENT_SOURCE_INVENTORY_CACHE_SCHEMA_VERSION,
        "allowed_payload_types": ["source_inventory_summary", "source_refs", "evidence_refs", "provenance_metadata", "artifact_ids", "bounded_snippets", "concept_summaries"],
        "prohibited_payload_types": ["full_raw_archive_content", "secrets", "credentials", "unbounded_file_blobs", "external_model_responses", "execution_outputs"],
        "max_cached_entry_bytes": PERSISTENT_SOURCE_INVENTORY_MAX_ENTRY_BYTES,
        "max_cached_snippet_chars": PERSISTENT_SOURCE_INVENTORY_MAX_SNIPPET_CHARS,
        "cache_full_raw_archive_content": False,
        "cache_secrets": False,
        "external_network_allowed": False,
        "model_allowed": False,
        "openrouter_allowed": False,
        "mcp_proxy_allowed": False,
        "invalidation_fields": ["source_path", "source_size_bytes", "source_mtime_ns", "collector_version", "provenance_schema_version", "cache_schema_version", "cache_namespace", "cache_version"],
        "recommended_next_action": "Use --write-cache only after reviewing the manifest; stale or corrupt caches fail closed to request cache.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_persistent_source_inventory_cache_policy(payload)
    return payload


def validate_persistent_source_inventory_cache_policy(payload: dict[str, Any]) -> None:
    required = ("persistent_source_inventory_cache_policy_version", "persistent_source_inventory_cache_policy_id", "cache_enabled_by_default", "cache_root", "cache_root_source", "cache_namespace", "cache_version", "collector_version", "provenance_schema_version", "cache_schema_version", "allowed_payload_types", "prohibited_payload_types", "max_cached_entry_bytes", "max_cached_snippet_chars", "cache_full_raw_archive_content", "cache_secrets", "external_network_allowed", "model_allowed", "openrouter_allowed", "mcp_proxy_allowed", "invalidation_fields", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"persistent source cache policy missing field: {key}")
    if payload["persistent_source_inventory_cache_policy_version"] != PERSISTENT_SOURCE_INVENTORY_CACHE_POLICY_VERSION:
        raise ValueError("invalid persistent source cache policy version")
    if not payload["persistent_source_inventory_cache_policy_id"].startswith("persistent-source-inventory-cache-policy-"):
        raise ValueError("invalid persistent source cache policy id")
    if payload["cache_enabled_by_default"] is not True:
        raise ValueError("persistent source cache policy must be enabled by default")
    if payload["cache_root_source"] == "default" and not _persistent_source_cache_path_is_safe(payload["cache_root"]):
        raise ValueError("default persistent cache root must be outside repo source")
    for field in ("source_path", "source_size_bytes", "source_mtime_ns", "collector_version", "provenance_schema_version", "cache_schema_version"):
        if field not in payload["invalidation_fields"]:
            raise ValueError(f"persistent source cache policy missing invalidation field {field}")
    if "full_raw_archive_content" not in payload["prohibited_payload_types"] or "secrets" not in payload["prohibited_payload_types"]:
        raise ValueError("persistent source cache policy must prohibit raw archive content and secrets")
    if payload["cache_full_raw_archive_content"] is not False or payload["cache_secrets"] is not False:
        raise ValueError("persistent source cache policy must not cache raw archive content or secrets")
    if payload["external_network_allowed"] is not False or payload["model_allowed"] is not False or payload["openrouter_allowed"] is not False or payload["mcp_proxy_allowed"] is not False:
        raise ValueError("persistent source cache policy must disallow model/network/MCP/proxy")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("persistent source cache policy must remain read-only")


def stable_persistent_source_inventory_cache_policy_json(payload: dict[str, Any]) -> str:
    validate_persistent_source_inventory_cache_policy(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_persistent_source_inventory_cache_policy_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_persistent_source_inventory_cache_policy(payload)
    return payload


def collect_persistent_source_inventory_cache_manifest(*, source_path: str, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    policy = collect_persistent_source_inventory_cache_policy()
    key_payload = collect_source_archive_intake_cache_key(source_path=source_path)
    source_fingerprint = _research_target_hash_text({
        "source_path": key_payload["source_path"],
        "source_size_bytes": key_payload["source_size_bytes"],
        "source_mtime_ns": key_payload["source_mtime_ns"],
        "collector_version": policy["collector_version"],
        "provenance_schema_version": policy["provenance_schema_version"],
        "cache_schema_version": policy["cache_schema_version"],
        "cache_namespace": policy["cache_namespace"],
        "cache_version": policy["cache_version"],
    })[:16]
    cache_key = f"{policy['cache_namespace']}:{policy['cache_version']}:{source_fingerprint}"
    cache_file_path = _persistent_source_cache_file_path(policy["cache_root"], cache_key)
    from pathlib import Path as _Path
    cache_file_exists = _Path(cache_file_path).exists()
    invalidation: list[str] = []
    cache_valid = False
    cache_status = "missing"
    if cache_file_exists:
        record = read_persistent_source_inventory_cache(cache_file_path)
        if record.get("ok"):
            raw = record["payload"]
            if raw.get("cache_key") == cache_key and raw.get("collector_version") == policy["collector_version"] and raw.get("cache_schema_version") == policy["cache_schema_version"]:
                cache_valid = True
                cache_status = "valid"
            else:
                cache_status = "stale"
                invalidation.append("cache metadata does not match current manifest")
        else:
            cache_status = "corrupt"
            invalidation.append(record.get("error", "cache could not be read"))
    payload = {
        "persistent_source_inventory_cache_manifest_version": PERSISTENT_SOURCE_INVENTORY_CACHE_MANIFEST_VERSION,
        "persistent_source_inventory_cache_manifest_id": "persistent-source-inventory-cache-manifest-" + source_fingerprint[:12],
        "policy_id": policy["persistent_source_inventory_cache_policy_id"],
        "source_path": key_payload["source_path"],
        "source_name": key_payload["source_name"],
        "source_type": key_payload["source_type"],
        "source_exists": key_payload["source_exists"],
        "source_size_bytes": key_payload["source_size_bytes"],
        "source_mtime_ns": key_payload["source_mtime_ns"],
        "source_fingerprint": source_fingerprint,
        "cache_key": cache_key,
        "cache_file_path": cache_file_path,
        "cache_file_exists": cache_file_exists,
        "cache_status": cache_status,
        "invalidation_reasons": _normalize_implementation_branch_refs(invalidation),
        "cache_valid": cache_valid,
        "collector_version": policy["collector_version"],
        "provenance_schema_version": policy["provenance_schema_version"],
        "cache_schema_version": policy["cache_schema_version"],
        "cache_namespace": policy["cache_namespace"],
        "recommended_next_action": "Persistent cache is valid." if cache_valid else "Run source-cache-persistent --write-cache to create or refresh the source inventory cache.",
        "fallback_allowed": False,
        "model_used": False,
        "external_network_used": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_persistent_source_inventory_cache_manifest(payload)
    return payload


def validate_persistent_source_inventory_cache_manifest(payload: dict[str, Any]) -> None:
    required = ("persistent_source_inventory_cache_manifest_version", "persistent_source_inventory_cache_manifest_id", "policy_id", "source_path", "source_name", "source_type", "source_exists", "source_size_bytes", "source_mtime_ns", "source_fingerprint", "cache_key", "cache_file_path", "cache_file_exists", "cache_status", "invalidation_reasons", "cache_valid", "collector_version", "provenance_schema_version", "cache_schema_version", "cache_namespace", "recommended_next_action", "fallback_allowed", "model_used", "external_network_used", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"persistent source cache manifest missing field: {key}")
    if payload["persistent_source_inventory_cache_manifest_version"] != PERSISTENT_SOURCE_INVENTORY_CACHE_MANIFEST_VERSION:
        raise ValueError("invalid persistent source cache manifest version")
    if payload["cache_status"] not in {"missing", "valid", "stale", "corrupt"}:
        raise ValueError("invalid persistent source cache status")
    if not payload["source_path"].startswith("research/") or payload["source_exists"] is not True:
        raise ValueError("persistent source cache manifest requires existing research source")
    if payload["cache_file_path"].endswith(".json") is not True:
        raise ValueError("persistent source cache file must be JSON")
    if payload["fallback_allowed"] is not False or payload["model_used"] is not False or payload["external_network_used"] is not False:
        raise ValueError("persistent source cache manifest must not use fallback/model/network")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("persistent source cache manifest must remain read-only")


def stable_persistent_source_inventory_cache_manifest_json(payload: dict[str, Any]) -> str:
    validate_persistent_source_inventory_cache_manifest(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_persistent_source_inventory_cache_manifest_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_persistent_source_inventory_cache_manifest(payload)
    return payload


def read_persistent_source_inventory_cache(cache_file_path: str) -> dict[str, Any]:
    import json as _json
    from pathlib import Path as _Path
    try:
        path = _Path(cache_file_path)
        if not path.exists():
            return {"ok": False, "error": "cache file missing"}
        payload = _json.loads(path.read_text())
        validate_persistent_source_inventory_cache_payload(payload)
        return {"ok": True, "payload": payload}
    except Exception as exc:
        return {"ok": False, "error": _source_aware_text(str(exc), max_chars=220)}


def validate_persistent_source_inventory_cache_payload(payload: dict[str, Any]) -> None:
    required = ("persistent_source_inventory_cache_payload_version", "cache_key", "source_path", "collector_version", "provenance_schema_version", "cache_schema_version", "created_at", "source_cache", "artifacts")
    for key in required:
        if key not in payload:
            raise ValueError(f"persistent source cache payload missing field: {key}")
    if payload["persistent_source_inventory_cache_payload_version"] != PERSISTENT_SOURCE_INVENTORY_CACHE_RECORD_VERSION:
        raise ValueError("invalid persistent source cache payload version")
    if not payload["source_path"].startswith("research/"):
        raise ValueError("persistent source cache payload must be source-bound")
    if payload["collector_version"] != PERSISTENT_SOURCE_INVENTORY_COLLECTOR_VERSION or payload["cache_schema_version"] != PERSISTENT_SOURCE_INVENTORY_CACHE_SCHEMA_VERSION:
        raise ValueError("persistent source cache payload version mismatch")
    validate_source_archive_intake_cache(payload["source_cache"])
    artifacts = payload["artifacts"]
    if not isinstance(artifacts, dict):
        raise ValueError("persistent source cache artifacts must be a dict")
    for key in ("target_intake", "target_evidence", "archive_concepts", "compression_profile", "target_upgrades", "operator_task_draft", "source_binding", "target_provenance", "target_patterns", "genericity_assessment", "compression_upgrade_score"):
        if key not in artifacts or not isinstance(artifacts[key], dict):
            raise ValueError(f"persistent source cache payload missing artifact {key}")
    text = _stable_ruflo_json(payload)
    if len(text.encode("utf-8")) > PERSISTENT_SOURCE_INVENTORY_MAX_ENTRY_BYTES:
        raise ValueError("persistent source cache payload exceeds max cached entry bytes")
    forbidden = ("BEGIN PRIVATE KEY", "AWS_SECRET", "OPENROUTER_API_KEY", "password=", "token=")
    if any(item.lower() in text.lower() for item in forbidden):
        raise ValueError("persistent source cache payload appears to contain secret-like content")


def write_persistent_source_inventory_cache(cache_file_path: str, payload: dict[str, Any]) -> int:
    from pathlib import Path as _Path
    import os as _os
    import tempfile as _tempfile

    validate_persistent_source_inventory_cache_payload(payload)
    path = _Path(cache_file_path).expanduser()
    root = path.parent
    if not _persistent_source_cache_path_is_safe(str(root)) and not str(root).startswith("/tmp/"):
        raise ValueError("persistent source cache root is not safe to write")
    root.mkdir(parents=True, exist_ok=True)
    text = _stable_ruflo_json(payload, indent=2) + "\n"
    if len(text.encode("utf-8")) > PERSISTENT_SOURCE_INVENTORY_MAX_ENTRY_BYTES:
        raise ValueError("persistent source cache file would exceed max size")
    fd, tmp = _tempfile.mkstemp(prefix=path.name + ".", suffix=".tmp", dir=str(root))
    try:
        with _os.fdopen(fd, "w") as handle:
            handle.write(text)
        _os.replace(tmp, path)
    finally:
        try:
            if _Path(tmp).exists():
                _Path(tmp).unlink()
        except Exception:
            pass
    return len(text.encode("utf-8"))


def _persistent_source_cache_payload_from_request(manifest: dict[str, Any], source_cache: dict[str, Any], artifacts: dict[str, Any]) -> dict[str, Any]:
    import datetime as _dt
    keep = {key: artifacts[key] for key in ("target_intake", "target_evidence", "archive_concepts", "compression_profile", "target_upgrades", "operator_task_draft", "source_binding", "target_provenance", "target_patterns", "genericity_assessment", "compression_upgrade_score") if key in artifacts}
    clean_cache = dict(source_cache)
    clean_cache["persistent_cache_hit"] = False
    clean_cache["persistent_cache_valid"] = False
    clean_cache["persistent_cache_write_performed"] = False
    clean_cache["cache_source"] = "computed"
    return {
        "persistent_source_inventory_cache_payload_version": PERSISTENT_SOURCE_INVENTORY_CACHE_RECORD_VERSION,
        "cache_key": manifest["cache_key"],
        "source_path": manifest["source_path"],
        "collector_version": manifest["collector_version"],
        "provenance_schema_version": manifest["provenance_schema_version"],
        "cache_schema_version": manifest["cache_schema_version"],
        "created_at": _dt.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "source_cache": clean_cache,
        "artifacts": keep,
    }


def _request_cache_from_persistent_payload(manifest: dict[str, Any], cached_payload: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    source_cache = dict(cached_payload["source_cache"])
    source_cache["total_runtime_ms"] = 0
    source_cache["persistent_cache_policy_id"] = manifest["policy_id"]
    source_cache["persistent_cache_manifest_id"] = manifest["persistent_source_inventory_cache_manifest_id"]
    source_cache["persistent_cache_record_id"] = "persistent-source-inventory-cache-record-" + _research_target_hash_text({"cache_key": manifest["cache_key"], "hit": True, "version": PERSISTENT_SOURCE_INVENTORY_CACHE_RECORD_VERSION})[:12]
    source_cache["persistent_cache_hit"] = True
    source_cache["persistent_cache_valid"] = True
    source_cache["persistent_cache_write_performed"] = False
    source_cache["cache_source"] = "persistent"
    source_cache["invalidation_reasons"] = []
    for entry in source_cache.get("entries", []):
        if entry.get("computed"):
            entry["reused"] = True
            entry["runtime_ms"] = 0
    artifacts = dict(cached_payload["artifacts"])
    artifacts["cache_key"] = collect_source_archive_intake_cache_key(source_path=manifest["source_path"])
    artifacts["source_cache"] = source_cache
    validate_source_archive_intake_cache(source_cache)
    return source_cache, artifacts


def collect_persistent_source_inventory_cache_record(*, source_path: str, write_cache: bool = False, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    from pathlib import Path as _Path

    manifest = collect_persistent_source_inventory_cache_manifest(source_path=source_path)
    read_result = read_persistent_source_inventory_cache(manifest["cache_file_path"])
    cache_hit = bool(read_result.get("ok")) and manifest["cache_valid"]
    write_performed = False
    cached_size = 0
    invalidation = list(manifest["invalidation_reasons"])
    cached_artifact_ids: dict[str, str] = {}
    cached_entry_count = 0
    summary = "cache missing or invalid"
    if cache_hit:
        cached_payload = read_result["payload"]
        cached_artifact_ids = dict(cached_payload["source_cache"].get("artifact_ids", {}))
        cached_entry_count = len(cached_payload["source_cache"].get("entries", []))
        cached_size = _Path(manifest["cache_file_path"]).stat().st_size if _Path(manifest["cache_file_path"]).exists() else 0
        summary = "valid persistent cache available"
    elif write_cache:
        source_cache, artifacts = _source_archive_intake_cache_artifacts(source_path, metadata)
        cache_payload = _persistent_source_cache_payload_from_request(manifest, source_cache, artifacts)
        cached_size = write_persistent_source_inventory_cache(manifest["cache_file_path"], cache_payload)
        write_performed = True
        cache_hit = True
        cached_artifact_ids = dict(source_cache.get("artifact_ids", {}))
        cached_entry_count = len(source_cache.get("entries", []))
        summary = "persistent cache written"
        _SOURCE_ARCHIVE_INTAKE_REQUEST_CACHE[manifest["cache_key"]] = _request_cache_from_persistent_payload(manifest, cache_payload)
    elif not read_result.get("ok") and manifest["cache_file_exists"]:
        invalidation.append(read_result.get("error", "cache read failed"))
    payload = {
        "persistent_source_inventory_cache_record_version": PERSISTENT_SOURCE_INVENTORY_CACHE_RECORD_VERSION,
        "persistent_source_inventory_cache_record_id": "persistent-source-inventory-cache-record-" + _research_target_hash_text({"manifest_id": manifest["persistent_source_inventory_cache_manifest_id"], "hit": cache_hit, "write": write_performed, "version": PERSISTENT_SOURCE_INVENTORY_CACHE_RECORD_VERSION})[:12],
        "manifest_id": manifest["persistent_source_inventory_cache_manifest_id"],
        "source_path": manifest["source_path"],
        "cache_key": manifest["cache_key"],
        "cache_hit": cache_hit,
        "cache_valid": cache_hit,
        "cache_write_requested": bool(write_cache),
        "cache_write_performed": write_performed,
        "cache_file_path": manifest["cache_file_path"],
        "cached_payload_summary": summary,
        "cached_artifact_ids": cached_artifact_ids,
        "cached_entry_count": cached_entry_count,
        "cached_size_bytes": cached_size,
        "created_at": read_result.get("payload", {}).get("created_at", "") if read_result.get("ok") else "",
        "invalidation_reasons": _normalize_implementation_branch_refs(invalidation),
        "fallback_to_request_cache": not cache_hit,
        "recommended_next_action": "Persistent cache hit; downstream CLI invocations can reuse it." if cache_hit else "Run with --write-cache to create a persistent cache record.",
        "fallback_allowed": False,
        "model_used": False,
        "external_network_used": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": bool(write_cache),
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [manifest["cache_file_path"]] if write_performed else [],
    }
    validate_persistent_source_inventory_cache_record(payload)
    return payload


def validate_persistent_source_inventory_cache_record(payload: dict[str, Any]) -> None:
    required = ("persistent_source_inventory_cache_record_version", "persistent_source_inventory_cache_record_id", "manifest_id", "source_path", "cache_key", "cache_hit", "cache_valid", "cache_write_requested", "cache_write_performed", "cache_file_path", "cached_payload_summary", "cached_artifact_ids", "cached_entry_count", "cached_size_bytes", "created_at", "invalidation_reasons", "fallback_to_request_cache", "recommended_next_action", "fallback_allowed", "model_used", "external_network_used", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in payload:
            raise ValueError(f"persistent source cache record missing field: {key}")
    if payload["persistent_source_inventory_cache_record_version"] != PERSISTENT_SOURCE_INVENTORY_CACHE_RECORD_VERSION:
        raise ValueError("invalid persistent source cache record version")
    if not payload["persistent_source_inventory_cache_record_id"].startswith("persistent-source-inventory-cache-record-"):
        raise ValueError("invalid persistent source cache record id")
    if payload["fallback_allowed"] is not False or payload["model_used"] is not False or payload["external_network_used"] is not False:
        raise ValueError("persistent source cache record must avoid fallback/model/network")
    if payload["cache_write_performed"] and not payload["writes"]:
        raise ValueError("persistent source cache write must report written file")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["automation_allowed"] is not False:
        raise ValueError("persistent source cache record must stay deterministic")


