def _growth_operator_cache_dashboard_issues(
    source_summary: dict[str, Any],
    queue_summary: dict[str, Any],
    queue: dict[str, Any],
) -> list[dict[str, Any]]:
    issues: list[dict[str, Any]] = []
    if source_summary["miss_count"] or source_summary["stale_count"] or source_summary["invalid_count"]:
        issues.append({
            "issue_id": "source_inventory_cache_missing",
            "severity": "high" if source_summary["hit_count"] == 0 else "medium",
            "category": "cache",
            "title": "Source inventory cache is not fully hot",
            "observed_behavior": f"{source_summary['hit_count']} hits, {source_summary['miss_count']} misses, {source_summary['stale_count']} stale, {source_summary['invalid_count']} invalid.",
            "expected_behavior": "All suitable selected sources should have valid source inventory cache entries before repeated operator reports.",
            "recommended_fix": source_summary["refresh_command"],
            "evidence_scope": "current_dashboard",
            "implement_now_candidate": False,
        })
    if not queue_summary["cache_hit"]:
        issues.append({
            "issue_id": "queue_e2e_compact_cache_missing",
            "severity": "high",
            "category": "cache",
            "title": "Compact queue E2E summary cache is not ready",
            "observed_behavior": f"Queue E2E compact cache status is {queue_summary['summary_source']}.",
            "expected_behavior": "A valid compact queue E2E cache should exist before hot direct-upgrade-eval and concept-calibration-report fast runs.",
            "recommended_fix": queue_summary["refresh_command"],
            "evidence_scope": "current_dashboard",
            "implement_now_candidate": False,
        })
    for item in queue.get("quarantine_records", []):
        if item.get("quarantine_status") != "not_quarantined":
            issues.append({
                "issue_id": "activepieces_quarantined" if item.get("source_path", "").endswith("activepieces-main.zip") else "source_quarantined_" + _research_target_hash_text(item.get("source_path", ""))[:8],
                "severity": "medium",
                "category": "queue",
                "title": f"{item.get('source_path', 'source')} is quarantined",
                "observed_behavior": item.get("quarantine_reason") or item.get("failure_category") or "source is excluded from default queue",
                "expected_behavior": "Unsuitable optional sources should be skipped without breaking the operator cache dashboard.",
                "recommended_fix": item.get("recommended_fix") or "Keep skipped until deterministic suitability is fixed.",
                "evidence_scope": "current_dashboard",
                "implement_now_candidate": False,
            })
    quality = queue_summary.get("calibration_quality_score")
    if isinstance(quality, int | float) and quality < 70:
        issues.append({
            "issue_id": "calibration_quality_weak",
            "severity": "medium",
            "category": "idea_quality",
            "title": "Cached calibration quality remains weak",
            "observed_behavior": f"Cached calibration quality score is {quality}.",
            "expected_behavior": "Role/concept calibration should expose weak sources and avoid overconfident ideas.",
            "recommended_fix": "Review concept-calibration-report --mode fast output and add source-specific fixtures in a separate batch.",
            "evidence_scope": "cached_summary",
            "implement_now_candidate": False,
        })
    issues.append({
        "issue_id": "execution_deterministic_checkpoint_prior_observed",
        "severity": "low",
        "category": "test_coverage",
        "title": "execution-deterministic is now the largest normal base component",
        "observed_behavior": "Prior measured execution-deterministic runtime is about 17.5s.",
        "expected_behavior": "Normal checkpoint tiers should remain small enough for frequent use.",
        "recommended_fix": "Profile execution-deterministic per-check timing in a separate test-speed batch.",
        "evidence_scope": "prior_observed",
        "implement_now_candidate": False,
    })
    return issues


def collect_growth_operator_cache_dashboard(*, sources: list[str] | None = None, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    import datetime as _dt
    explicit_sources = [str(item).strip() for item in (sources or []) if str(item).strip()]
    queue = collect_growth_source_queue(sources=explicit_sources or None)
    policy = collect_growth_source_queue_policy()
    status = collect_growth_source_queue_cache_status(sources=explicit_sources or None)
    queue_cache = collect_growth_source_queue_e2e_summary_cache_record(sources=explicit_sources or None)
    source_summary = _growth_operator_cache_dashboard_source_inventory_summary(status, queue)
    queue_summary = _growth_operator_cache_dashboard_queue_e2e_summary(queue_cache)
    source_ready = bool(source_summary["ready_for_hot_path"])
    queue_ready = bool(queue_summary["ready_for_fast_queue_e2e"])
    command_hints = _growth_operator_cache_dashboard_command_hints()
    direct_ready = source_ready and queue_ready
    concept_ready = queue_ready
    if direct_ready:
        operator_status = "ready"
        reason = "Both source inventory and compact queue E2E caches are ready."
        next_command = command_hints["run_direct_upgrade_eval_hot"]
    elif source_ready or queue_ready:
        operator_status = "partial"
        reason = "One cache layer is ready and one cache layer needs refresh."
        next_command = command_hints["write_queue_e2e_cache"] if source_ready else command_hints["warm_source_inventory"]
    else:
        operator_status = "cold"
        reason = "Source inventory and compact queue E2E caches need warming."
        next_command = command_hints["warm_full_hot_path"]
    issues = _growth_operator_cache_dashboard_issues(source_summary, queue_summary, queue)
    stale_or_missing = []
    if not source_ready:
        stale_or_missing.append("source inventory cache is not ready for all selected sources")
    if not queue_ready:
        stale_or_missing.append("compact queue E2E cache is missing, stale, or invalid")
    payload = {
        "growth_operator_cache_dashboard_version": GROWTH_OPERATOR_CACHE_DASHBOARD_VERSION,
        "dashboard_version": GROWTH_OPERATOR_CACHE_DASHBOARD_VERSION,
        "growth_operator_cache_dashboard_id": "growth-operator-cache-dashboard-" + _research_target_hash_text({
            "queue": queue["growth_source_queue_id"],
            "status": status["growth_source_queue_cache_status_id"],
            "queue_cache": queue_cache["growth_source_queue_e2e_cache_record_id"],
            "version": GROWTH_OPERATOR_CACHE_DASHBOARD_VERSION,
        })[:12],
        "generated_at": _dt.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "source_queue_id": queue["growth_source_queue_id"],
        "source_queue_policy_id": policy["growth_source_queue_policy_id"],
        "cache_root": source_summary["cache_root"],
        "selected_sources": queue["selected_sources"],
        "skipped_sources": queue["skipped_sources"],
        "quarantined_sources": [item for item in queue.get("quarantine_records", []) if item.get("quarantine_status") != "not_quarantined"],
        "source_inventory_cache_summary": source_summary,
        "queue_e2e_cache_summary": queue_summary,
        "direct_upgrade_eval_hot_path": {
            "ready": direct_ready,
            "source_inventory_ready": source_ready,
            "queue_e2e_compact_ready": queue_ready,
            "expected_cache_layers": ["source_inventory", "queue_e2e_compact"],
            "missing_cache_layers": [name for name, ready in (("source_inventory", source_ready), ("queue_e2e_compact", queue_ready)) if not ready],
            "cold_path_command": command_hints["warm_full_hot_path"],
            "warm_path_command": command_hints["warm_full_hot_path"],
            "hot_path_command": command_hints["run_direct_upgrade_eval_hot"],
            "expected_behavior": "Hot direct-upgrade-eval should avoid full queue E2E compute and per-target archive touches when both cache layers are ready.",
            "recommended_next_action": command_hints["run_direct_upgrade_eval_hot"] if direct_ready else command_hints["warm_full_hot_path"],
        },
        "concept_calibration_hot_path": {
            "ready": concept_ready,
            "queue_e2e_compact_ready": queue_ready,
            "fast_mode_available": True,
            "deep_mode_available": True,
            "hot_path_command": command_hints["run_concept_calibration_fast"],
            "deep_command": "python3 link.py growth concept-calibration-report --mode deep --json",
            "recommended_next_action": command_hints["run_concept_calibration_fast"] if concept_ready else command_hints["write_queue_e2e_cache"],
        },
        "operator_readiness": {
            "status": operator_status,
            "reason": reason,
            "next_command": next_command,
            "safe_to_run_direct_eval": True,
            "safe_to_run_concept_report_fast": True,
            "cache_refresh_required": not direct_ready,
            "clear_required": False,
            "warnings": _normalize_implementation_branch_refs(stale_or_missing),
        },
        "recommended_next_action": next_command,
        "command_hints": command_hints,
        "stale_or_missing_reasons": _normalize_implementation_branch_refs(stale_or_missing),
        "broken_unoptimized_items": issues,
        "fallback_allowed": False,
        "model_used": False,
        "external_network_used": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_growth_operator_cache_dashboard(payload)
    return payload


def validate_growth_operator_cache_dashboard(payload: dict[str, Any]) -> None:
    required = (
        "growth_operator_cache_dashboard_version", "dashboard_version",
        "growth_operator_cache_dashboard_id", "generated_at", "source_queue_id",
        "source_queue_policy_id", "cache_root", "selected_sources", "skipped_sources",
        "quarantined_sources", "source_inventory_cache_summary", "queue_e2e_cache_summary",
        "direct_upgrade_eval_hot_path", "concept_calibration_hot_path", "operator_readiness",
        "recommended_next_action", "command_hints", "stale_or_missing_reasons",
        "broken_unoptimized_items", "fallback_allowed", "model_used", "external_network_used",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"growth operator cache dashboard missing {key}")
    if payload["growth_operator_cache_dashboard_version"] != GROWTH_OPERATOR_CACHE_DASHBOARD_VERSION or payload["dashboard_version"] != GROWTH_OPERATOR_CACHE_DASHBOARD_VERSION:
        raise ValueError("invalid growth operator cache dashboard version")
    if not payload["growth_operator_cache_dashboard_id"].startswith("growth-operator-cache-dashboard-"):
        raise ValueError("invalid growth operator cache dashboard id")
    source_summary = payload["source_inventory_cache_summary"]
    for key in ("cache_root", "source_count", "hit_count", "miss_count", "stale_count", "invalid_count", "skipped_count", "ready_count", "ready_for_hot_path", "total_cached_size_bytes", "oldest_cache_age_seconds", "newest_cache_age_seconds", "sources", "refresh_command", "clear_command", "recommended_next_action"):
        if key not in source_summary:
            raise ValueError(f"source inventory cache summary missing {key}")
    for item in source_summary["sources"]:
        for key in ("source_path", "source_name", "suitability_status", "quarantine_status", "cache_status", "cache_hit", "cache_valid", "cache_age_seconds", "cached_size_bytes", "invalidation_reasons", "stale_reasons", "action_required", "refresh_command", "clear_command"):
            if key not in item:
                raise ValueError(f"source inventory cache source summary missing {key}")
    queue_summary = payload["queue_e2e_cache_summary"]
    for key in ("cache_key_id", "cache_record_id", "cache_root", "cache_file_path", "cache_file_exists", "cache_hit", "cache_valid", "cache_age_seconds", "cached_size_bytes", "selected_source_count", "skipped_source_count", "summary_source", "best_cached_opportunity_title", "calibration_quality_score", "invalidation_reasons", "stale_reasons", "ready_for_fast_queue_e2e", "refresh_command", "clear_command", "recommended_next_action"):
        if key not in queue_summary:
            raise ValueError(f"queue E2E cache summary missing {key}")
    if queue_summary["summary_source"] not in {"compact_cache", "missing", "stale", "invalid"}:
        raise ValueError("invalid queue E2E cache summary source")
    for section in ("direct_upgrade_eval_hot_path", "concept_calibration_hot_path", "operator_readiness"):
        if not isinstance(payload[section], dict):
            raise TypeError(f"{section} must be a dict")
    for key, command in payload["command_hints"].items():
        if not isinstance(key, str) or not isinstance(command, str) or not command.startswith("python3 "):
            raise ValueError("growth operator cache dashboard command hints must be python commands")
    for item in payload["broken_unoptimized_items"]:
        for key in ("issue_id", "severity", "category", "title", "observed_behavior", "expected_behavior", "recommended_fix", "evidence_scope", "implement_now_candidate"):
            if key not in item:
                raise ValueError(f"growth operator cache dashboard issue missing {key}")
        if item["evidence_scope"] not in {"current_dashboard", "cached_summary", "prior_observed"}:
            raise ValueError("invalid growth operator cache dashboard issue evidence scope")
    if payload["fallback_allowed"] is not False or payload["model_used"] is not False or payload["external_network_used"] is not False:
        raise ValueError("growth operator cache dashboard must avoid model/network/fallback")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False:
        raise ValueError("growth operator cache dashboard must be read-only")
    if payload["writes"] != []:
        raise ValueError("growth operator cache dashboard must not report writes")


def stable_growth_operator_cache_dashboard_json(payload: dict[str, Any]) -> str:
    validate_growth_operator_cache_dashboard(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_growth_operator_cache_dashboard_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_growth_operator_cache_dashboard(payload)
    return payload


def _growth_direct_eval_per_target_summary(source_path: str, queue: dict[str, Any], status: dict[str, Any], queue_e2e: dict[str, Any]) -> dict[str, Any]:
    source_entry = next((item for item in queue["selected_sources"] if item["source_path"] == source_path), {})
    source_status = next((item for item in status["source_statuses"] if item["source_path"] == source_path), {})
    queue_summary = summarize_queue_e2e_source_for_direct_eval(source_path, queue_e2e)
    e2e_item = dict(queue_summary.get("summary", {}))
    recomputed_fields: list[str] = []
    reuse_warnings: list[str] = []
    archive_touch_required = False
    archive_touch_reason = ""
    cache: dict[str, Any] = {}
    artifacts: dict[str, Any] = {}
    if queue_summary["reuse_status"] == "missing_from_queue_e2e":
        archive_touch_required = True
        archive_touch_reason = "queue E2E summary did not include this selected source"
        summary = collect_source_aware_growth_e2e_summary(source_path=source_path)
        score = collect_growth_opportunity_decision_score(source_path=source_path, summary=summary)
        best_title = summary["best_growth_opportunity"]["title"]
        e2e_item = {
            "best_growth_opportunity_title": best_title,
            "calibrated_best_opportunity": best_title,
            "primary_repo_role": "unknown",
            "primary_repo_role_confidence": "low",
            "calibrated_top_concepts": [],
            "calibrated_direct_usefulness_score": score["calibrated_direct_usefulness_score"],
            "role_alignment_score": score["role_alignment_score"],
            "evidence_support_score": score["evidence_support_score"],
            "safety_risk_score": score["safety_risk_score"],
            "operator_confidence_score": score["operator_confidence_score"],
            "recommended_next_action": score["recommended_next_action"],
            "cache_status": source_status.get("cache_status", "miss"),
        }
        recomputed_fields.extend(["e2e_summary", "opportunity_score"])
    elif queue_summary["reuse_status"] == "incomplete_queue_e2e_summary":
        reuse_warnings.append("queue E2E summary was reused with missing optional direct-eval fields")
    if archive_touch_required:
        cache, artifacts = get_or_collect_source_archive_intake_cache_for_request(source_path)
    profile = artifacts.get("compression_profile", {})
    task = artifacts.get("operator_task_draft", {})
    best_title = str(e2e_item.get("best_growth_opportunity_title") or e2e_item.get("calibrated_best_opportunity") or "unavailable")
    task_title = str(task.get("calibrated_best_growth_opportunity") or task.get("objective") or best_title)
    dashboard_title = best_title
    e2e_title = best_title
    divergence = []
    if archive_touch_required and task_title and task_title != e2e_title and e2e_title not in task_title:
        divergence.append(f"task draft title differs from E2E best: {task_title}")
    if archive_touch_required:
        task_alignment_source = str(task.get("task_alignment_source") or ("calibrated_task_candidate" if not divergence else "diverged"))
    elif queue_e2e.get("queue_e2e_cache_used"):
        task_alignment_source = "queue_e2e_compact_cache"
    else:
        task_alignment_source = "queue_e2e_source_summary"
    task_alignment_warnings = _normalize_implementation_branch_refs(list(task.get("task_alignment_warnings", [])) + divergence)
    reused_fields = list(queue_summary.get("reused_fields", []))
    if archive_touch_required:
        reused_fields.extend(["source_archive_intake_request_cache", "compression_profile", "operator_task_draft"])
    else:
        reused_fields.extend(["source_queue_status", "queue_e2e_per_target_summary"])
    missing_fields = list(queue_summary.get("missing_fields", []))
    if queue_e2e.get("queue_e2e_cache_used") and not archive_touch_required:
        summary_reuse_source = "queue_e2e_compact_cache"
    elif not archive_touch_required:
        summary_reuse_source = "queue_e2e_computed"
    else:
        summary_reuse_source = "mixed"
    if queue_summary["reuse_status"] == "incomplete_queue_e2e_summary":
        summary_reuse_source = "mixed" if archive_touch_required else summary_reuse_source
    if queue_summary["reuse_status"] == "missing_from_queue_e2e":
        summary_reuse_source = "recomputed"
    primary_role = e2e_item.get("primary_repo_role", "unknown")
    if profile:
        compression_decision = profile.get("compression_profile_decision", "insufficient_evidence")
    elif primary_role == "compression_context":
        compression_decision = "compression_repo"
    elif primary_role == "unknown":
        compression_decision = "insufficient_evidence"
    else:
        compression_decision = "not_compression_repo"
    source_inventory_cache_hit = bool(source_status.get("cache_hit", False))
    source_inventory_cache_used = source_inventory_cache_hit and not archive_touch_required
    archive_recompute_avoided = not archive_touch_required and queue_summary["reuse_status"] in {"reused_from_queue_e2e", "incomplete_queue_e2e_summary"}
    return {
        "source_path": source_path,
        "source_name": source_entry.get("source_name", source_path.rsplit("/", 1)[-1]),
        "suitability_status": source_entry.get("suitability_status", "suitable"),
        "quarantine_status": source_entry.get("quarantine_status", "not_quarantined"),
        "cache_status": source_status.get("cache_status", e2e_item.get("cache_status", "miss")),
        "primary_repo_role": primary_role,
        "primary_repo_role_confidence": e2e_item.get("primary_repo_role_confidence", "low"),
        "calibrated_top_concepts": e2e_item.get("calibrated_top_concepts", [])[:5],
        "compression_profile_decision": compression_decision,
        "best_growth_opportunity_title": best_title,
        "calibrated_direct_usefulness_score": e2e_item.get("calibrated_direct_usefulness_score", 0),
        "role_alignment_score": e2e_item.get("role_alignment_score", 0),
        "evidence_support_score": e2e_item.get("evidence_support_score", 0),
        "safety_risk_score": e2e_item.get("safety_risk_score", 10),
        "operator_confidence_score": e2e_item.get("operator_confidence_score", 0),
        "task_draft_title": task_title,
        "task_alignment_source": task_alignment_source,
        "task_alignment_warnings": task_alignment_warnings,
        "dashboard_best_opportunity_title": dashboard_title,
        "e2e_best_opportunity_title": e2e_title,
        "divergence_warnings": _normalize_implementation_branch_refs(divergence),
        "source_archive_intake_cache_id": cache.get("source_archive_intake_cache_id", ""),
        "source_inventory_cache_hit": source_inventory_cache_hit,
        "source_inventory_cache_used": source_inventory_cache_used,
        "source_inventory_cache_record_id": source_status.get("cache_observability_card_id", ""),
        "archive_touch_required": archive_touch_required,
        "archive_touch_reason": archive_touch_reason,
        "per_target_archive_recompute_avoided": archive_recompute_avoided,
        "recommended_next_action": e2e_item.get("recommended_next_action", "Review queue E2E opportunity before implementation."),
        "summary_reuse_source": summary_reuse_source,
        "recomputed_fields": recomputed_fields,
        "reused_fields": _normalize_implementation_branch_refs(reused_fields),
        "missing_fields": _normalize_implementation_branch_refs(missing_fields),
        "reuse_warnings": _normalize_implementation_branch_refs(reuse_warnings),
    }


def _growth_direct_eval_build_candidates(per_target: list[dict[str, Any]], issues: list[dict[str, Any]]) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    for item in per_target:
        blocked = bool(item["divergence_warnings"]) or item["suitability_status"] not in {"suitable", "suitable_with_warnings"}
        safety_score = max(0, 10 - int(item["safety_risk_score"]))
        candidate_type = "source_growth_upgrade"
        if "source" in item["best_growth_opportunity_title"].lower() or "planning" in item["best_growth_opportunity_title"].lower():
            candidate_type = "queue_cache_observability"
        if "compression" in item["best_growth_opportunity_title"].lower():
            candidate_type = "repo_role_calibration"
        candidates.append(_growth_direct_eval_candidate(
            candidate_id="growth-direct-upgrade-candidate-" + _research_target_hash_text({"source": item["source_path"], "title": item["best_growth_opportunity_title"], "version": GROWTH_DIRECT_UPGRADE_EVAL_VERSION})[:12],
            source_path=item["source_path"],
            title=item["best_growth_opportunity_title"],
            candidate_type=candidate_type,
            direct_value=item["calibrated_direct_usefulness_score"],
            friction=8 if candidate_type in {"queue_cache_observability", "repo_role_calibration"} else 6,
            test_speed=2,
            source_specificity=9 if item["primary_repo_role"] != "unknown" else 4,
            confidence=item["operator_confidence_score"],
            safety=safety_score,
            verification=8 if item["task_alignment_source"] else 6,
            maintenance=3 if item["role_alignment_score"] >= 7 else 5,
            evidence=f"{item['primary_repo_role']} / {item['primary_repo_role_confidence']}; task alignment {item['task_alignment_source']}",
            next_slice=item["recommended_next_action"],
            blocked=blocked,
            rejection_reason="task/dashboard/E2E divergence must be resolved first" if blocked else "",
            candidate_source_artifact="queue_e2e_source_summary" if item["summary_reuse_source"] in {"queue_e2e", "mixed", "queue_e2e_compact_cache", "queue_e2e_computed"} else "recomputed_opportunity_score",
            reused_queue_score=item["summary_reuse_source"] in {"queue_e2e", "mixed", "queue_e2e_compact_cache", "queue_e2e_computed"} and "opportunity_score" not in item["recomputed_fields"],
            recompute_reason="; ".join(item["recomputed_fields"]),
        ))
    if any(issue["issue_id"] == "planning-deterministic-hotspot" for issue in issues):
        candidates.append(_growth_direct_eval_candidate(
            candidate_id="growth-direct-upgrade-candidate-planning-speed",
            source_path="",
            title="Split or optimize planning-deterministic hotspot checks",
            candidate_type="planning_test_speed",
            direct_value=5,
            friction=7,
            test_speed=10,
            source_specificity=5,
            confidence=7,
            safety=10,
            verification=8,
            maintenance=3,
            evidence="Prior measured planning-deterministic runtime remains about 69-70s.",
            next_slice="Add per-check timings and move expensive console data coverage behind an explicit deeper planning suite.",
            candidate_source_artifact="direct_eval_issue",
        ))
    if any(issue["issue_id"] == "activepieces-quarantined" for issue in issues):
        candidates.append(_growth_direct_eval_candidate(
            candidate_id="growth-direct-upgrade-candidate-source-ref-normalization",
            source_path="research/activepieces-main.zip",
            title="Normalize unsupported activepieces source refs",
            candidate_type="source_ref_normalization",
            direct_value=5,
            friction=4,
            test_speed=1,
            source_specificity=8,
            confidence=4,
            safety=7,
            verification=4,
            maintenance=6,
            evidence="activepieces remains quarantined by deterministic source-ref generation checks.",
            next_slice="Inspect source-ref path normalization failure and add a fail-closed adapter only if the archive shape is clearly supported.",
            candidate_source_artifact="direct_eval_issue",
        ))
    candidates.append(_growth_direct_eval_candidate(
        candidate_id="growth-direct-upgrade-candidate-model-status",
        source_path="",
        title="Improve local model timeout status reporting",
        candidate_type="model_status_clarity",
        direct_value=3,
        friction=4,
        test_speed=1,
        source_specificity=2,
        confidence=7,
        safety=8,
        verification=7,
        maintenance=2,
        evidence="Prior operator run observed local model timeout; this deterministic evaluator did not call models.",
        next_slice="Keep model work out of Growth deterministic path; only improve status text if needed.",
        blocked=True,
        rejection_reason="model path is out of scope for deterministic Growth evaluator",
        candidate_source_artifact="prior_observed_issue",
    ))
    return _growth_direct_eval_rank_candidates(candidates)


def _growth_direct_eval_build_issues(status: dict[str, Any], warmup: dict[str, Any], queue_e2e: dict[str, Any], calibration: dict[str, Any], per_target: list[dict[str, Any]], queue: dict[str, Any]) -> list[dict[str, Any]]:
    issues = [
        _growth_direct_eval_issue(
            "manual-operator-chain-recomputation",
            "high",
            "UX",
            "Manual Growth operator loop is command-heavy",
            "Previous operator runs required queue, E2E, calibration, per-target dashboard, task-draft, and target-command invocations.",
            "One deterministic command should emit the compact direct-upgrade report.",
            "Current direct evaluator composes queue/status/warm/E2E/calibration/per-target summaries in one process.",
            "Use growth direct-upgrade-eval as the operator starting point and keep adding reuse metrics.",
            implement_now=True,
        ),
        _growth_direct_eval_issue(
            "planning-deterministic-hotspot",
            "high",
            "test_coverage",
            "planning-deterministic remains slow",
            "Prior measured planning-deterministic runtime is about 69-70s.",
            "Broad deterministic planning checks should have a faster checkpoint tier or per-check timings.",
            "Prior-observed; not remeasured by this evaluator command.",
            "Split check_growth_console_data or add planning-deep so frequent checkpoints stay fast.",
        ),
    ]
    if int(queue_e2e.get("performance_summary", {}).get("total_runtime_ms", 0)) > 30000:
        issues.append(_growth_direct_eval_issue(
            "queue-e2e-runtime",
            "high",
            "performance",
            "Queue E2E remains expensive even with caches",
            f"Queue E2E runtime was {queue_e2e['performance_summary']['total_runtime_ms']}ms.",
            "Warmed queue E2E should reuse compact artifacts and make hotspot sources obvious.",
            f"Slowest sources: {queue_e2e['performance_summary'].get('slowest_sources', [])[:3]}",
            "Use direct evaluator performance summary to target repeated downstream recomputation.",
        ))
    if status["cache_miss_count"] or warmup["estimated_work_count"]:
        issues.append(_growth_direct_eval_issue(
            "cache-not-warm",
            "medium",
            "cache",
            "Source queue cache needs warming",
            f"Cache status has {status['cache_hit_count']} hits and {status['cache_miss_count']} misses; warmup work count {warmup['estimated_work_count']}.",
            "Operator should see whether --write-cache is needed before E2E.",
            "Direct evaluator reports cache_summary and write_cache_requested/write_cache_performed.",
            "Run growth direct-upgrade-eval --write-cache before repeated repo snowball evaluation.",
        ))
    for quarantine in queue.get("quarantine_records", []):
        if quarantine.get("quarantine_status") != "not_quarantined":
            issues.append(_growth_direct_eval_issue(
                "activepieces-quarantined" if quarantine["source_path"].endswith("activepieces-main.zip") else "source-quarantined-" + _research_target_hash_text(quarantine["source_path"])[:8],
                "medium",
                "queue",
                f"{quarantine['source_path']} is quarantined",
                quarantine.get("quarantine_reason", "source skipped by queue quarantine"),
                "Problematic optional archives should not break the default queue.",
                quarantine.get("failure_category", "unknown"),
                quarantine.get("recommended_fix", "Keep skipped until deterministic suitability is fixed."),
            ))
    if int(calibration.get("calibration_quality_score", 100)) < 70:
        issues.append(_growth_direct_eval_issue(
            "calibration-quality-low",
            "medium",
            "idea_quality",
            "Concept calibration quality is still weak",
            f"Calibration quality score is {calibration.get('calibration_quality_score')}.",
            "Source roles and opportunity templates should be confident only when evidence supports them.",
            f"Needs profile work: {[item.get('source_path') for item in calibration.get('needs_profile_work', [])[:4]]}",
            "Add source-specific profile fixtures/templates for weak business/workflow sources.",
        ))
    scores = [item["calibrated_direct_usefulness_score"] for item in per_target]
    if scores and max(scores) - min(scores) < 2:
        issues.append(_growth_direct_eval_issue(
            "score-spread-too-tight",
            "medium",
            "idea_quality",
            "Direct usefulness scores are tightly clustered",
            f"Per-target usefulness score range is {min(scores)}..{max(scores)}.",
            "Ranking should expose meaningful confidence differences.",
            "Current evidence comes from direct evaluator per-target summaries.",
            "Add a small score-spread guard using role alignment, evidence strength, and maintenance burden.",
        ))
    for item in per_target:
        if item["divergence_warnings"]:
            issues.append(_growth_direct_eval_issue(
                "task-draft-divergence-" + _research_target_hash_text(item["source_path"])[:8],
                "high",
                "operator_handoff",
                f"Task draft diverges for {item['source_name']}",
                "; ".join(item["divergence_warnings"]),
                "Task draft, dashboard, and E2E should point to the same calibrated opportunity.",
                f"task={item['task_draft_title']} e2e={item['e2e_best_opportunity_title']}",
                "Align source-aware task draft selection with calibrated E2E opportunity.",
                implement_now=True,
            ))
    issues.append(_growth_direct_eval_issue(
        "local-model-timeout-prior-observed",
        "low",
        "model",
        "Local model timeout path remains outside deterministic Growth",
        "Prior operator run observed local model timeout; this command intentionally did not call local models.",
        "Deterministic Growth should remain useful without model availability.",
        "Prior-observed; no model smoke was run in this batch.",
        "Only improve read-only status reporting in a separate model-status slice.",
        blocked_reason="model calls are out of scope for this deterministic evaluator",
    ))
    return issues


def collect_growth_direct_upgrade_eval(*, sources: list[str] | None = None, write_cache: bool = False, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    import time as _time

    started = _time.perf_counter()
    before_cache_keys = set(_SOURCE_ARCHIVE_INTAKE_REQUEST_CACHE)
    explicit_sources = [str(item).strip() for item in (sources or []) if str(item).strip()]
    policy = collect_growth_source_queue_policy()
    queue = collect_growth_source_queue(sources=explicit_sources or None)
    cache_plan = collect_growth_direct_eval_cache_plan(sources=explicit_sources or None, write_cache_requested=write_cache)
    status_before = collect_growth_source_queue_cache_status(sources=explicit_sources or None)
    warmup = collect_growth_source_queue_warmup_plan(sources=explicit_sources or None, write_cache=write_cache)
    status = collect_growth_source_queue_cache_status(sources=explicit_sources or None) if write_cache else status_before
    queue_e2e = collect_growth_source_queue_e2e_summary(sources=explicit_sources or None, mode="fast", write_cache=write_cache)
    calibration = collect_repo_concept_calibration_report_from_queue_e2e(queue_e2e, queue)
    selected_sources = [item["source_path"] for item in queue["selected_sources"]]
    per_target_started = _time.perf_counter()
    per_target = [_growth_direct_eval_per_target_summary(source, queue, status, queue_e2e) for source in selected_sources]
    per_target_runtime_ms = int((_time.perf_counter() - per_target_started) * 1000)
    issues = _growth_direct_eval_build_issues(status, warmup, queue_e2e, calibration, per_target, queue)
    candidate_started = _time.perf_counter()
    candidates = _growth_direct_eval_build_candidates(per_target, issues)
    candidate_runtime_ms = int((_time.perf_counter() - candidate_started) * 1000)
    accepted = [item for item in candidates if item["decision"] == "accept"]
    runners = [item for item in candidates if item["decision"] == "runner_up"]
    rejected = [item for item in candidates if item["decision"] in {"reject", "blocked", "needs_more_evidence"}]
    best = accepted[0] if accepted else (candidates[0] if candidates else {})
    after_cache_keys = set(_SOURCE_ARCHIVE_INTAKE_REQUEST_CACHE)
    computed = sum(1 for item in per_target if item.get("archive_touch_required"))
    reused = sum(1 for item in per_target if item.get("per_target_archive_recompute_avoided"))
    queue_reuse_sources = {"queue_e2e", "mixed", "queue_e2e_compact_cache", "queue_e2e_computed"}
    reused_queue_targets = sum(1 for item in per_target if item.get("summary_reuse_source") in queue_reuse_sources)
    per_target_e2e_recompute_count = sum(1 for item in per_target if "e2e_summary" in item.get("recomputed_fields", []))
    opportunity_recompute_count = sum(1 for item in per_target if "opportunity_score" in item.get("recomputed_fields", []))
    repo_role_recompute_count = sum(1 for item in per_target if "repo_role" in item.get("recomputed_fields", []))
    concept_confidence_recompute_count = sum(1 for item in per_target if "concept_confidence" in item.get("recomputed_fields", []))
    task_draft_recompute_count = sum(1 for item in per_target if "task_draft" in item.get("recomputed_fields", []))
    dashboard_recompute_count = sum(1 for item in per_target if "dashboard" in item.get("recomputed_fields", []))
    avoided_per_target_recompute_count = max(0, reused_queue_targets * 2 - per_target_e2e_recompute_count - opportunity_recompute_count)
    source_inventory_used_for_targets = sum(1 for item in per_target if item.get("source_inventory_cache_used"))
    per_target_archive_touch_avoided_count = sum(1 for item in per_target if item.get("per_target_archive_recompute_avoided"))
    per_target_archive_touch_required_count = sum(1 for item in per_target if item.get("archive_touch_required"))
    cache_layers_warmed = []
    if warmup.get("write_cache_performed"):
        cache_layers_warmed.append("source_inventory")
    if queue_e2e.get("queue_e2e_cache_write_performed"):
        cache_layers_warmed.append("queue_e2e_compact")
    source_inventory_before = _growth_source_inventory_cache_status_summary(status_before)
    source_inventory_after = _growth_source_inventory_cache_status_summary(status)
    reuse_notes = [
        "per-target summaries prefer compact queue E2E fields before archive-derived artifacts",
        "persistent cache writes are controlled only by --write-cache",
        "queue E2E source summaries are reused for per-target direct evaluator title/role/score fields",
    ]
    if per_target_archive_touch_avoided_count:
        reuse_notes.append("per-target archive touches were avoided when queue E2E summaries were sufficient")
    if avoided_per_target_recompute_count:
        reuse_notes.append("avoided_per_target_recompute_count is a conservative E2E plus opportunity-score estimate")
    slowest_steps = sorted([
        {"step": "queue_e2e", "runtime_ms": int(queue_e2e["performance_summary"]["total_runtime_ms"])},
        {"step": "warmup", "runtime_ms": int(warmup["total_runtime_ms"])},
        {"step": "per_target_summary", "runtime_ms": per_target_runtime_ms},
        {"step": "candidate_ranking", "runtime_ms": candidate_runtime_ms},
    ], key=lambda item: item["runtime_ms"], reverse=True)
    payload = {
        "growth_direct_upgrade_eval_version": GROWTH_DIRECT_UPGRADE_EVAL_VERSION,
        "eval_version": GROWTH_DIRECT_UPGRADE_EVAL_VERSION,
        "growth_direct_upgrade_eval_id": "growth-direct-upgrade-eval-" + _research_target_hash_text({"queue_id": queue["growth_source_queue_id"], "best": best.get("candidate_id", ""), "write": write_cache, "version": GROWTH_DIRECT_UPGRADE_EVAL_VERSION})[:12],
        "source_queue_id": queue["growth_source_queue_id"],
        "source_queue_policy_id": policy["growth_source_queue_policy_id"],
        "source_queue_cache_status_id": status["growth_source_queue_cache_status_id"],
        "source_queue_warmup_plan_id": warmup["growth_source_queue_warmup_plan_id"],
        "source_queue_warmup_result_id": warmup["growth_source_queue_warmup_plan_id"] if write_cache else "",
        "source_queue_e2e_summary_id": queue_e2e["growth_source_queue_e2e_summary_id"],
        "concept_calibration_report_id": calibration["repo_concept_calibration_report_id"],
        "cache_plan_id": cache_plan["growth_direct_eval_cache_plan_id"],
        "queue_e2e_cache_hit": bool(queue_e2e.get("queue_e2e_cache_hit", False)),
        "queue_e2e_cache_used": bool(queue_e2e.get("queue_e2e_cache_used", False)),
        "queue_e2e_cache_write_performed": bool(queue_e2e.get("queue_e2e_cache_write_performed", False)),
        "queue_e2e_summary_source": str(queue_e2e.get("queue_e2e_summary_source", "computed")),
        "source_inventory_cache_before": source_inventory_before,
        "source_inventory_cache_after": source_inventory_after,
        "source_inventory_cache_warm_performed": bool(warmup.get("write_cache_performed", False)),
        "source_inventory_cache_warmed_count": int(warmup.get("warmed_count", 0) or 0),
        "source_inventory_cache_failed_count": int(warmup.get("failed_count", 0) or 0),
        "source_inventory_cache_skipped_count": int(warmup.get("skipped_count", 0) or 0),
        "cache_layers_warmed": cache_layers_warmed,
        "targets_evaluated": selected_sources,
        "skipped_sources": queue["skipped_sources"],
        "cache_summary": {
            "cache_root": status["cache_root"],
            "before_hit_count": status_before["cache_hit_count"],
            "before_miss_count": status_before["cache_miss_count"],
            "after_hit_count": status["cache_hit_count"],
            "after_miss_count": status["cache_miss_count"],
            "stale_count": status["stale_count"],
            "invalid_count": status["invalid_count"],
            "queue_ready_for_e2e": status["queue_ready_for_e2e"],
        },
        "queue_summary": {
            "selected_count": len(selected_sources),
            "skipped_count": queue["skipped_source_count"],
            "quarantined_count": queue["quarantined_source_count"],
            "unsuitable_count": queue["unsuitable_source_count"],
            "queue_ready_for_warmup": queue["queue_ready_for_warmup"],
            "queue_ready_for_e2e": queue["queue_ready_for_e2e"],
        },
        "per_target_summaries": per_target,
        "candidate_upgrades": candidates,
        "best_direct_upgrade": best,
        "runner_up_upgrades": runners[:5],
        "rejected_candidates": rejected[:8],
        "broken_unoptimized_items": issues,
        "operator_notes": _normalize_implementation_branch_refs([
            "direct-upgrade-eval is deterministic and does not implement upgrades",
            "use --write-cache only when persistent source cache warming is desired",
            "review best_direct_upgrade before authorizing a separate implementation slice",
        ]),
        "recommended_next_implementation_slice": best.get("recommended_implementation_slice", "No high-quality deterministic implementation candidate is available."),
        "recommended_next_action": "Review best_direct_upgrade and broken_unoptimized_items; implement one focused deterministic slice only after review.",
        "request_reuse_summary": {
            "request_cache_id": "growth-direct-upgrade-request-cache-" + _research_target_hash_text({"before": sorted(before_cache_keys), "after": sorted(after_cache_keys), "sources": selected_sources, "version": GROWTH_DIRECT_UPGRADE_EVAL_VERSION})[:12],
            "request_cache_enabled": True,
            "source_artifacts_reused_count": reused,
            "source_artifacts_computed_count": computed,
            "repeated_rebuilds_avoided_count": max(0, reused + len(selected_sources) * 2),
            "source_queue_e2e_reused_for_targets_count": reused_queue_targets,
            "per_target_e2e_recompute_count": per_target_e2e_recompute_count,
            "opportunity_score_recompute_count": opportunity_recompute_count,
            "repo_role_recompute_count": repo_role_recompute_count,
            "concept_confidence_recompute_count": concept_confidence_recompute_count,
            "task_draft_recompute_count": task_draft_recompute_count,
            "dashboard_recompute_count": dashboard_recompute_count,
            "avoided_per_target_recompute_count": avoided_per_target_recompute_count,
            "source_inventory_cache_before_hit_count": status_before["cache_hit_count"],
            "source_inventory_cache_before_miss_count": status_before["cache_miss_count"],
            "source_inventory_cache_after_hit_count": status["cache_hit_count"],
            "source_inventory_cache_after_miss_count": status["cache_miss_count"],
            "source_inventory_cache_warm_performed": bool(warmup.get("write_cache_performed", False)),
            "source_inventory_sources_warmed_count": int(warmup.get("warmed_count", 0) or 0),
            "source_inventory_cache_used_for_targets_count": source_inventory_used_for_targets,
            "per_target_archive_touch_avoided_count": per_target_archive_touch_avoided_count,
            "per_target_archive_touch_required_count": per_target_archive_touch_required_count,
            "queue_summary_reuse_enabled": True,
            "concept_calibration_report_reused_from_queue_e2e": True,
            "queue_e2e_compact_cache_used": bool(queue_e2e.get("queue_e2e_cache_used", False)),
            "queue_e2e_compact_cache_hit": bool(queue_e2e.get("queue_e2e_cache_hit", False)),
            "full_queue_e2e_compute_avoided": bool(queue_e2e.get("queue_e2e_cache_used", False)),
            "compact_cache_write_performed": bool(queue_e2e.get("queue_e2e_cache_write_performed", False)),
            "cache_layers_ready": bool(status["cache_miss_count"] == 0 and (queue_e2e.get("queue_e2e_cache_used") or queue_e2e.get("queue_e2e_cache_write_performed"))),
            "notes": _normalize_implementation_branch_refs(reuse_notes),
        },
        "performance_summary": {
            "total_runtime_ms": int((_time.perf_counter() - started) * 1000),
            "queue_e2e_runtime_ms": queue_e2e["performance_summary"]["total_runtime_ms"],
            "per_target_summary_runtime_ms": per_target_runtime_ms,
            "candidate_ranking_runtime_ms": candidate_runtime_ms,
            "warmup_runtime_ms": warmup["total_runtime_ms"],
            "reuse_optimization_enabled": True,
            "slowest_steps": slowest_steps,
            "hotspot_notes": _normalize_implementation_branch_refs([
                "queue E2E remains the dominant deterministic step when source summaries are cold",
                "direct evaluator no longer recomputes per-target E2E/opportunity scores when queue E2E summaries are complete",
            ]),
            "slowest_sources": queue_e2e["performance_summary"].get("slowest_sources", [])[:5],
        },
        "write_cache_requested": bool(write_cache),
        "write_cache_performed": bool(warmup["write_cache_performed"]),
        "fallback_allowed": False,
        "model_used": False,
        "external_network_used": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": bool(write_cache),
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": list(warmup.get("writes", [])) if write_cache else [],
    }
    validate_growth_direct_upgrade_eval(payload)
    return payload


def validate_growth_direct_upgrade_eval(payload: dict[str, Any]) -> None:
    required = (
        "growth_direct_upgrade_eval_version", "eval_version", "growth_direct_upgrade_eval_id",
        "source_queue_id", "source_queue_policy_id", "source_queue_cache_status_id",
        "source_queue_warmup_plan_id", "source_queue_warmup_result_id", "source_queue_e2e_summary_id",
        "concept_calibration_report_id", "cache_plan_id", "queue_e2e_cache_hit", "queue_e2e_cache_used", "queue_e2e_cache_write_performed", "queue_e2e_summary_source", "source_inventory_cache_before", "source_inventory_cache_after", "source_inventory_cache_warm_performed", "source_inventory_cache_warmed_count", "source_inventory_cache_failed_count", "source_inventory_cache_skipped_count", "cache_layers_warmed", "targets_evaluated", "skipped_sources", "cache_summary",
        "queue_summary", "per_target_summaries", "candidate_upgrades", "best_direct_upgrade",
        "runner_up_upgrades", "rejected_candidates", "broken_unoptimized_items", "operator_notes",
        "recommended_next_implementation_slice", "recommended_next_action", "request_reuse_summary",
        "performance_summary", "write_cache_requested", "write_cache_performed", "fallback_allowed",
        "model_used", "external_network_used", "safety_metadata", "dry_run", "write_allowed",
        "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"growth direct upgrade eval missing field: {key}")
    if payload["growth_direct_upgrade_eval_version"] != GROWTH_DIRECT_UPGRADE_EVAL_VERSION or payload["eval_version"] != GROWTH_DIRECT_UPGRADE_EVAL_VERSION:
        raise ValueError("invalid growth direct upgrade eval version")
    if not payload["growth_direct_upgrade_eval_id"].startswith("growth-direct-upgrade-eval-"):
        raise ValueError("invalid growth direct upgrade eval id")
    for item in payload["per_target_summaries"]:
        for key in ("source_path", "source_name", "suitability_status", "quarantine_status", "cache_status", "primary_repo_role", "primary_repo_role_confidence", "calibrated_top_concepts", "compression_profile_decision", "best_growth_opportunity_title", "calibrated_direct_usefulness_score", "role_alignment_score", "evidence_support_score", "safety_risk_score", "operator_confidence_score", "task_draft_title", "task_alignment_source", "task_alignment_warnings", "dashboard_best_opportunity_title", "e2e_best_opportunity_title", "divergence_warnings", "source_inventory_cache_hit", "source_inventory_cache_used", "source_inventory_cache_record_id", "archive_touch_required", "archive_touch_reason", "per_target_archive_recompute_avoided", "recommended_next_action", "summary_reuse_source", "recomputed_fields", "reused_fields", "missing_fields", "reuse_warnings"):
            if key not in item:
                raise ValueError(f"growth direct eval per-target summary missing {key}")
        if item["summary_reuse_source"] not in {"queue_e2e", "queue_e2e_compact_cache", "queue_e2e_computed", "concept_calibration_report", "cache_status", "source_inventory_cache", "recomputed", "mixed"}:
            raise ValueError("invalid growth direct eval per-target summary reuse source")
    for candidate in payload["candidate_upgrades"]:
        for key in ("candidate_id", "source_path", "title", "candidate_type", "direct_growth_functionality_value", "operator_friction_reduction", "test_checkpoint_speed_value", "source_specificity", "implementation_confidence", "safety_score", "verification_clarity", "expected_maintenance_burden", "total_roi_score", "decision", "rejection_reason", "evidence_summary", "recommended_implementation_slice", "candidate_source_artifact", "reused_queue_score", "recompute_reason"):
            if key not in candidate:
                raise ValueError(f"growth direct eval candidate missing {key}")
        if candidate["decision"] not in {"accept", "runner_up", "reject", "needs_more_evidence", "blocked"}:
            raise ValueError("invalid growth direct eval candidate decision")
    if payload["candidate_upgrades"] and not payload["best_direct_upgrade"]:
        raise ValueError("growth direct eval must include best direct upgrade when candidates exist")
    for issue in payload["broken_unoptimized_items"]:
        for key in ("issue_id", "severity", "category", "title", "observed_behavior", "expected_behavior", "evidence_summary", "recommended_fix", "implement_now_candidate", "blocked_reason"):
            if key not in issue:
                raise ValueError(f"growth direct eval issue missing {key}")
        if issue["severity"] not in {"critical", "high", "medium", "low"}:
            raise ValueError("invalid growth direct eval issue severity")
    reuse = payload["request_reuse_summary"]
    for key in ("request_cache_id", "request_cache_enabled", "source_artifacts_reused_count", "source_artifacts_computed_count", "repeated_rebuilds_avoided_count", "source_queue_e2e_reused_for_targets_count", "per_target_e2e_recompute_count", "opportunity_score_recompute_count", "repo_role_recompute_count", "concept_confidence_recompute_count", "task_draft_recompute_count", "dashboard_recompute_count", "avoided_per_target_recompute_count", "source_inventory_cache_before_hit_count", "source_inventory_cache_before_miss_count", "source_inventory_cache_after_hit_count", "source_inventory_cache_after_miss_count", "source_inventory_cache_warm_performed", "source_inventory_sources_warmed_count", "source_inventory_cache_used_for_targets_count", "per_target_archive_touch_avoided_count", "per_target_archive_touch_required_count", "queue_summary_reuse_enabled", "queue_e2e_compact_cache_used", "queue_e2e_compact_cache_hit", "full_queue_e2e_compute_avoided", "compact_cache_write_performed", "cache_layers_ready", "notes"):
        if key not in reuse:
            raise ValueError(f"growth direct eval reuse summary missing {key}")
    perf = payload["performance_summary"]
    for key in ("total_runtime_ms", "queue_e2e_runtime_ms", "per_target_summary_runtime_ms", "candidate_ranking_runtime_ms", "warmup_runtime_ms", "reuse_optimization_enabled", "slowest_steps", "hotspot_notes"):
        if key not in perf:
            raise ValueError(f"growth direct eval performance summary missing {key}")
    if payload["fallback_allowed"] is not False or payload["model_used"] is not False or payload["external_network_used"] is not False:
        raise ValueError("growth direct eval must avoid model/network/fallback")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["automation_allowed"] is not False:
        raise ValueError("growth direct eval must remain deterministic")
    if payload["write_allowed"] != payload["write_cache_requested"]:
        raise ValueError("growth direct eval write flag mismatch")
    if not payload["write_cache_requested"] and payload["writes"] != []:
        raise ValueError("growth direct eval must not report writes without --write-cache")


def stable_growth_direct_upgrade_eval_json(payload: dict[str, Any]) -> str:
    validate_growth_direct_upgrade_eval(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_growth_direct_upgrade_eval_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_growth_direct_upgrade_eval(payload)
    return payload


def collect_growth_e2e_performance_hotspots(*, source_path: str, cache: dict[str, Any] | None = None, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    cache_payload = cache or collect_source_aware_growth_context_cache(source_path=source_path)
    validate_source_aware_growth_context_cache(cache_payload)
    breakdown = [
        {"artifact_name": entry["artifact_name"], "runtime_ms": entry["runtime_ms"], "status": entry["status"], "cache_hit": entry["cache_hit"]}
        for entry in cache_payload["cache_entries"]
    ]
    slowest = sorted(breakdown, key=lambda item: item["runtime_ms"], reverse=True)[:5]
    repeated = [
        "separate CLI commands rebuild source-aware context; use growth e2e-summary for one-process operator decisions",
        "dashboard/sandbox/advisor surfaces are intentionally summarized instead of recursively rebuilt in the request cache",
    ]
    payload = {
        "growth_e2e_performance_hotspots_version": GROWTH_E2E_PERFORMANCE_HOTSPOTS_VERSION,
        "growth_e2e_performance_hotspots_id": "growth-e2e-performance-hotspots-" + _research_target_hash_text({"cache_id": cache_payload["source_aware_growth_context_cache_id"], "version": GROWTH_E2E_PERFORMANCE_HOTSPOTS_VERSION})[:12],
        "source_path": cache_payload["source_path"],
        "cache_id": cache_payload["source_aware_growth_context_cache_id"],
        "source_archive_intake_cache_id": cache_payload["source_archive_intake_cache_id"],
        "cache_key_id": cache_payload["cache_key_id"],
        "persistent_cache_policy_id": cache_payload.get("persistent_cache_policy_id", ""),
        "persistent_cache_manifest_id": cache_payload.get("persistent_cache_manifest_id", ""),
        "persistent_cache_record_id": cache_payload.get("persistent_cache_record_id", ""),
        "persistent_cache_hit": bool(cache_payload.get("persistent_cache_hit", False)),
        "persistent_cache_valid": bool(cache_payload.get("persistent_cache_valid", False)),
        "persistent_cache_write_performed": bool(cache_payload.get("persistent_cache_write_performed", False)),
        "cache_source": cache_payload.get("cache_source", "computed"),
        "invalidation_reasons": cache_payload.get("invalidation_reasons", []),
        "total_runtime_ms": cache_payload["total_runtime_ms"],
        "artifact_runtime_breakdown": breakdown,
        "slowest_artifacts": slowest,
        "repeated_context_rebuild_warnings": repeated,
        "cache_reuse_recommendations": [
            "Keep E2E summary, opportunity score, and performance views on the same request-scoped context.",
            "Promote safe persistent source artifact IDs only after cache invalidation rules are explicit.",
        ],
        "recommended_next_action": "Use growth e2e-summary as the operator entrypoint before running lower-level source-aware commands.",
        "fallback_allowed": False,
        "model_used": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_growth_e2e_performance_hotspots(payload)
    return payload


def validate_growth_e2e_performance_hotspots(payload: dict[str, Any]) -> None:
    required = (
        "growth_e2e_performance_hotspots_version", "growth_e2e_performance_hotspots_id", "source_path",
        "cache_id", "source_archive_intake_cache_id", "cache_key_id",
        "persistent_cache_policy_id", "persistent_cache_manifest_id", "persistent_cache_record_id",
        "persistent_cache_hit", "persistent_cache_valid", "persistent_cache_write_performed",
        "cache_source", "invalidation_reasons",
        "total_runtime_ms", "artifact_runtime_breakdown", "slowest_artifacts",
        "repeated_context_rebuild_warnings", "cache_reuse_recommendations", "recommended_next_action",
        "fallback_allowed", "model_used", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"growth e2e performance missing field: {key}")
    if payload["growth_e2e_performance_hotspots_version"] != GROWTH_E2E_PERFORMANCE_HOTSPOTS_VERSION:
        raise ValueError("invalid growth e2e performance version")
    if not payload["growth_e2e_performance_hotspots_id"].startswith("growth-e2e-performance-hotspots-"):
        raise ValueError("invalid growth e2e performance id")
    if not isinstance(payload["artifact_runtime_breakdown"], list) or not payload["artifact_runtime_breakdown"]:
        raise ValueError("growth e2e performance requires runtime breakdown")
    if not payload["cache_reuse_recommendations"]:
        raise ValueError("growth e2e performance requires cache recommendations")
    if payload["fallback_allowed"] is not False or payload["model_used"] is not False:
        raise ValueError("growth e2e performance must be deterministic and no-model")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("growth e2e performance must remain read-only")


def stable_growth_e2e_performance_hotspots_json(payload: dict[str, Any]) -> str:
    validate_growth_e2e_performance_hotspots(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_growth_e2e_performance_hotspots_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_growth_e2e_performance_hotspots(payload)
    return payload




