        _redacted_config_ref(CANONICAL_LOCAL_MODEL_WRAPPER_PATH, "LINK_LLAMACPP_BASE_URL default", "http://127.0.0.1:8084"),
        _redacted_config_ref(CANONICAL_LOCAL_MODEL_WRAPPER_PATH, "LINK_LLAMACPP_MODEL default", "local"),
