def _extract_llamacpp_assistant_content(response_json: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    shape = {
        "top_level_keys": sorted([str(key) for key in response_json.keys() if not str(key).startswith("_")])[:20],
        "choices_count": 0,
        "message_present": False,
        "content_present": False,
        "content_chars": 0,
        "finish_reason": "",
        "usage_present": bool(response_json.get("usage")),
        "http_status": response_json.get("_http_status", 0),
    }
    choices = response_json.get("choices")
    if isinstance(choices, list):
        shape["choices_count"] = len(choices)
        if choices:
            first = choices[0] if isinstance(choices[0], dict) else {}
            shape["finish_reason"] = str(first.get("finish_reason") or "")
            message = first.get("message") if isinstance(first, dict) else None
            if isinstance(message, dict):
                shape["message_present"] = True
                content = message.get("content")
                if isinstance(content, str) and content.strip():
                    shape["content_present"] = True
                    shape["content_chars"] = len(content)
                    return content, shape
    return "", shape


def _validate_json_contract_model_payload(model_json: dict[str, Any], contract: dict[str, Any]) -> tuple[bool, str]:
    validate_local_advisor_json_contract(contract)
    for key in contract["required_response_schema"]:
        if key not in model_json:
            return False, f"schema missing key: {key}"
    if model_json.get("ok") is not True:
        return False, "ok must be true"
    if model_json.get("advisor_role") != "local_source_bound_json_check":
        return False, "advisor_role mismatch"
    if model_json.get("source_path") != contract["source_path"]:
        return False, "source_path mismatch"
    if model_json.get("source_bound") is not True:
        return False, "source_bound must be true"
    if _research_advisor_forbidden_text(model_json):
        return False, "forbidden action recommendation detected"
    source_refs = model_json.get("source_refs")
    evidence_refs = model_json.get("evidence_refs")
    if not isinstance(source_refs, list) or not isinstance(evidence_refs, list):
        return False, "source_refs and evidence_refs must be lists"
    unknown_source = [ref for ref in source_refs if ref not in contract["allowed_source_refs"]]
    unknown_evidence = [ref for ref in evidence_refs if ref not in contract["allowed_evidence_refs"]]
    if unknown_source:
        return False, "unknown source_refs cited"
    if unknown_evidence:
        return False, "unknown evidence_refs cited"
    for list_key in ("missing_evidence", "risk_notes"):
        if not isinstance(model_json.get(list_key), list):
            return False, f"{list_key} must be a list"
    if not isinstance(model_json.get("critique"), str) or not model_json.get("critique", "").strip():
        return False, "critique must be non-empty string"
    return True, ""


def collect_local_advisor_json_contract_result(
    local_advisor_json_contract: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    use_local_model: bool = False,
    model_response_json: dict[str, Any] | None = None,
    raw_response: str | None = None,
    latency_ms: int = 0,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    import json as _json

    contract = local_advisor_json_contract or collect_local_advisor_json_contract(source_path=source_path)
    validate_local_advisor_json_contract(contract)
    prompt = render_minimal_local_json_contract_prompt(contract)
    response_hash = ""
    raw_preview = ""
    http_status = 0
    assistant_content = ""
    assistant_present = False
    assistant_chars = 0
    valid_json = False
    schema_valid = False
    source_bound_valid = False
    model_used = False
    fail_closed = False
    fail_reason = ""
    response_shape: dict[str, Any] = {}
    parsed: dict[str, Any] = {}
    if model_response_json is not None:
        model_used = True
        parsed = dict(model_response_json)
        assistant_content = _stable_ruflo_json(parsed)
        assistant_present = True
        assistant_chars = len(assistant_content)
        response_hash = _research_target_hash_text(raw_response or assistant_content)
        raw_preview = _sanitize_local_advisor_preview(raw_response or assistant_content)
        valid_json = True
        schema_valid, fail_reason = _validate_json_contract_model_payload(parsed, contract)
        source_bound_valid = parsed.get("source_path") == contract["source_path"] and parsed.get("source_bound") is True
    elif use_local_model:
        model_used = True
        try:
            response_json, raw, latency_ms = _call_canonical_llamacpp_chat_raw(
                prompt=prompt,
                system_prompt="Return strict JSON only. You are a local-only source-bound advisor check. Advisory only; no execution, writes, approvals, network, fallback, or patching.",
                timeout=int(contract["timeout_seconds"]),
                model_name=contract["model_name"],
                max_tokens=160,
            )
            http_status = int(response_json.get("_http_status", 0) or 0)
            response_shape = {key: value for key, value in _extract_llamacpp_assistant_content(response_json)[1].items()}
            assistant_content, response_shape = _extract_llamacpp_assistant_content(response_json)
            assistant_present = bool(assistant_content.strip())
            assistant_chars = len(assistant_content)
            response_hash = _research_target_hash_text(raw)
            raw_preview = _sanitize_local_advisor_preview(assistant_content or raw)
            if not assistant_present:
                fail_reason = "empty assistant content"
            else:
                parsed = _json.loads(assistant_content)
                valid_json = isinstance(parsed, dict)
                if not valid_json:
                    fail_reason = "assistant content was not a JSON object"
                else:
                    schema_valid, fail_reason = _validate_json_contract_model_payload(parsed, contract)
                    source_bound_valid = parsed.get("source_path") == contract["source_path"] and parsed.get("source_bound") is True
        except Exception as exc:
            fail_reason = str(exc)[:220]
            response_hash = _research_target_hash_text(fail_reason)
            raw_preview = _sanitize_local_advisor_preview(fail_reason)
    else:
        fail_reason = "preview_only; rerun with --local-model to perform local JSON contract check"
    smoke_ok = bool(model_used and valid_json and schema_valid and source_bound_valid and not fail_reason)
    fail_closed = not smoke_ok
    payload = {
        "local_advisor_json_contract_result_version": LOCAL_ADVISOR_JSON_CONTRACT_RESULT_VERSION,
        "local_advisor_json_contract_result_id": "local-advisor-json-contract-result-" + _local_advisor_safe_hash({
            "contract": contract["local_advisor_json_contract_id"],
            "model_used": model_used,
            "response_hash": response_hash,
            "smoke_ok": smoke_ok,
            "version": LOCAL_ADVISOR_JSON_CONTRACT_RESULT_VERSION,
        }),
        "local_advisor_json_contract_id": contract["local_advisor_json_contract_id"],
        "source_path": contract["source_path"],
        "provider_name": "llamacpp",
        "model_used": bool(model_used),
        "endpoint_type": "local",
        "prompt_hash": _research_target_hash_text(prompt),
        "response_hash": response_hash,
        "prompt_chars": len(prompt),
        "timeout_seconds": contract["timeout_seconds"],
        "latency_ms": int(latency_ms or 0),
        "http_status": int(http_status or 0),
        "raw_response_preview_sanitized": raw_preview,
        "assistant_content_present": bool(assistant_present),
        "assistant_content_chars": int(assistant_chars),
        "valid_json": bool(valid_json),
        "schema_valid": bool(schema_valid),
        "source_bound_valid": bool(source_bound_valid),
        "smoke_ok": bool(smoke_ok),
        "fail_closed": bool(fail_closed),
        "fail_closed_reason": "" if smoke_ok else (fail_reason or "local JSON contract check failed closed"),
        "response_shape": response_shape,
        "recommended_next_action": "Stage 1 passed; run two-stage advisor gate if richer advisory review is needed." if smoke_ok else "Do not run richer advisor review; inspect local-json-diagnostic or adjust local model/server strict JSON behavior.",
        "human_review_required": True,
        "fallback_allowed": False,
        "advisory_only": True,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_local_advisor_json_contract_result(payload, contract)
    return payload


def validate_local_advisor_json_contract_result(payload: dict[str, Any], contract: dict[str, Any] | None = None) -> None:
    required = (
        "local_advisor_json_contract_result_version", "local_advisor_json_contract_result_id",
        "local_advisor_json_contract_id", "source_path", "provider_name", "model_used",
        "endpoint_type", "prompt_hash", "response_hash", "prompt_chars", "timeout_seconds",
        "latency_ms", "http_status", "raw_response_preview_sanitized", "assistant_content_present",
        "assistant_content_chars", "valid_json", "schema_valid", "source_bound_valid", "smoke_ok",
        "fail_closed", "fail_closed_reason", "recommended_next_action", "human_review_required",
        "fallback_allowed", "advisory_only", "safety_metadata", "dry_run", "write_allowed",
        "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"local advisor JSON contract result missing field: {key}")
    if payload["local_advisor_json_contract_result_version"] != LOCAL_ADVISOR_JSON_CONTRACT_RESULT_VERSION:
        raise ValueError("invalid local advisor JSON contract result version")
    if payload["provider_name"] != "llamacpp" or payload["endpoint_type"] != "local":
        raise ValueError("local advisor JSON contract result must use local llama.cpp")
    if not payload["prompt_hash"] or not isinstance(payload["prompt_chars"], int) or payload["prompt_chars"] <= 0:
        raise ValueError("local advisor JSON contract result requires prompt hash and char count")
    if not 10 <= int(payload["timeout_seconds"]) <= 90:
        raise ValueError("local advisor JSON contract result timeout must be bounded")
    if len(str(payload["raw_response_preview_sanitized"])) > 260:
        raise ValueError("local advisor JSON contract result raw preview must be bounded")
    if payload["smoke_ok"] is True:
        if payload["fail_closed"] is not False or not payload["model_used"] or not payload["valid_json"] or not payload["schema_valid"] or not payload["source_bound_valid"]:
            raise ValueError("successful local JSON contract result must be model-used, valid JSON, schema-valid, source-bound, and not fail-closed")
    else:
        if payload["fail_closed"] is not True or not payload["fail_closed_reason"]:
            raise ValueError("failed local JSON contract result must fail closed with reason")
    if contract is not None and payload["source_path"] != contract["source_path"]:
        raise ValueError("local advisor JSON contract result source mismatch")
    text = _stable_ruflo_json(payload).lower()
    if "sk-" in text or "bearer " in text:
        raise ValueError("local advisor JSON contract result must not expose secrets")
    if payload["human_review_required"] is not True or payload["fallback_allowed"] is not False or payload["advisory_only"] is not True:
        raise ValueError("local advisor JSON contract result must be human-reviewed, advisory-only, and no-fallback")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("local advisor JSON contract result must remain read-only")


def stable_local_advisor_json_contract_result_json(payload: dict[str, Any]) -> str:
    validate_local_advisor_json_contract_result(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_local_advisor_json_contract_result_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_local_advisor_json_contract_result(payload)
    return payload




def _local_advisor_ref_summary(item: dict[str, Any]) -> str:
    for key in ("summary", "display_path", "provenance_path", "source_path", "source_name", "evidence_type", "source_ref_id", "evidence_ref_id"):
        value = item.get(key)
        if isinstance(value, str) and value.strip():
            text = value.strip()
            return text if len(text) <= 96 else text[:93] + "..."
    return "selected source reference"


def collect_local_advisor_ref_alias_map(
    research_advisor_prompt_package: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    max_source_refs: int = 2,
    max_evidence_refs: int = 2,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    package = research_advisor_prompt_package or collect_research_advisor_prompt_package(source_path=source_path)
    validate_research_advisor_prompt_package(package)
    source_entries = []
    for idx, item in enumerate(package["source_refs"][:max_source_refs], start=1):
        source_entries.append({
            "alias": f"S{idx}",
            "ref_type": "source_ref",
            "full_ref": item["source_ref_id"],
            "ref_summary": _local_advisor_ref_summary(item),
            "used_in_prompt": True,
        })
    evidence_entries = []
    for idx, item in enumerate(package["evidence_refs"][:max_evidence_refs], start=1):
        evidence_entries.append({
            "alias": f"E{idx}",
            "ref_type": "evidence_ref",
            "full_ref": item["evidence_ref_id"],
            "ref_summary": _local_advisor_ref_summary(item),
            "used_in_prompt": True,
        })
    payload = {
        "local_advisor_ref_alias_map_version": LOCAL_ADVISOR_REF_ALIAS_MAP_VERSION,
        "local_advisor_ref_alias_map_id": "local-advisor-ref-alias-map-" + _local_advisor_safe_hash({
            "source_path": package["source_path"],
            "source_refs": [item["full_ref"] for item in source_entries],
            "evidence_refs": [item["full_ref"] for item in evidence_entries],
            "version": LOCAL_ADVISOR_REF_ALIAS_MAP_VERSION,
        }),
        "source_path": package["source_path"],
        "source_name": package["source_name"],
        "research_target_intake_id": package["research_target_intake_id"],
        "selected_upgrade_candidate_id": package["deterministic_upgrade_candidates"][0]["upgrade_candidate_id"],
        "source_ref_aliases": source_entries,
        "evidence_ref_aliases": evidence_entries,
        "alias_policy": "Use short S#/E# aliases in local model prompts; Link deterministically expands aliases back to full refs.",
        "alias_count": len(source_entries) + len(evidence_entries),
        "fallback_allowed": False,
        "advisory_only": True,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_local_advisor_ref_alias_map(payload)
    return payload


def validate_local_advisor_ref_alias_map(payload: dict[str, Any]) -> None:
    required = (
        "local_advisor_ref_alias_map_version", "local_advisor_ref_alias_map_id", "source_path",
        "source_name", "research_target_intake_id", "selected_upgrade_candidate_id", "source_ref_aliases",
        "evidence_ref_aliases", "alias_policy", "alias_count", "fallback_allowed", "advisory_only",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"local advisor ref alias map missing field: {key}")
    if payload["local_advisor_ref_alias_map_version"] != LOCAL_ADVISOR_REF_ALIAS_MAP_VERSION:
        raise ValueError("invalid local advisor ref alias map version")
    aliases: list[str] = []
    for entries, prefix, ref_type in ((payload["source_ref_aliases"], "S", "source_ref"), (payload["evidence_ref_aliases"], "E", "evidence_ref")):
        if not isinstance(entries, list) or not entries:
            raise ValueError("local advisor alias map requires source/evidence aliases")
        for item in entries:
            for key in ("alias", "ref_type", "full_ref", "ref_summary", "used_in_prompt"):
                if key not in item:
                    raise ValueError(f"local advisor alias entry missing field: {key}")
            if not str(item["alias"]).startswith(prefix) or len(str(item["alias"])) > 4:
                raise ValueError("local advisor alias must be short and correctly prefixed")
            if item["ref_type"] != ref_type or not item["full_ref"]:
                raise ValueError("local advisor alias entry has invalid ref type/full ref")
            aliases.append(item["alias"])
    if len(aliases) != len(set(aliases)):
        raise ValueError("local advisor aliases must be unique")
    if payload["alias_count"] != len(aliases):
        raise ValueError("local advisor alias count mismatch")
    if payload["fallback_allowed"] is not False or payload["advisory_only"] is not True:
        raise ValueError("local advisor alias map must be advisory-only and no-fallback")
    text = _stable_ruflo_json(payload).lower()
    if "sk-" in text or "bearer " in text:
        raise ValueError("local advisor alias map must not expose secrets")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("local advisor alias map must remain read-only")


def stable_local_advisor_ref_alias_map_json(payload: dict[str, Any]) -> str:
    validate_local_advisor_ref_alias_map(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_local_advisor_ref_alias_map_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_local_advisor_ref_alias_map(payload)
    return payload


def expand_local_advisor_ref_aliases(alias_map: dict[str, Any], source_refs: list[Any], evidence_refs: list[Any]) -> dict[str, Any]:
    validate_local_advisor_ref_alias_map(alias_map)
    source_alias_to_full = {item["alias"]: item["full_ref"] for item in alias_map["source_ref_aliases"]}
    evidence_alias_to_full = {item["alias"]: item["full_ref"] for item in alias_map["evidence_ref_aliases"]}
    source_full = {item["full_ref"] for item in alias_map["source_ref_aliases"]}
    evidence_full = {item["full_ref"] for item in alias_map["evidence_ref_aliases"]}
    expanded_source: list[str] = []
    expanded_evidence: list[str] = []
    unknown: list[str] = []
    reasons: list[str] = []
    source_aliases_returned: list[str] = []
    evidence_aliases_returned: list[str] = []
    if not isinstance(source_refs, list) or not isinstance(evidence_refs, list):
        return {
            "expanded_source_refs": [],
            "expanded_evidence_refs": [],
            "source_ref_aliases_returned": [],
            "evidence_ref_aliases_returned": [],
            "unknown_aliases": [],
            "invalid_ref_reasons": ["source_refs and evidence_refs must be arrays"],
            "refs_used_aliases": False,
            "refs_valid": False,
        }
    for ref in source_refs:
        value = str(ref)
        if value in source_alias_to_full:
            source_aliases_returned.append(value)
            expanded_source.append(source_alias_to_full[value])
        elif value in evidence_alias_to_full:
            unknown.append(value)
            reasons.append(f"wrong-type alias in source_refs: {value}")
        elif value in source_full:
            expanded_source.append(value)
        else:
            unknown.append(value)
            reasons.append(f"unknown source ref alias: {value}")
    for ref in evidence_refs:
        value = str(ref)
        if value in evidence_alias_to_full:
            evidence_aliases_returned.append(value)
            expanded_evidence.append(evidence_alias_to_full[value])
        elif value in source_alias_to_full:
            unknown.append(value)
            reasons.append(f"wrong-type alias in evidence_refs: {value}")
        elif value in evidence_full:
            expanded_evidence.append(value)
        else:
            unknown.append(value)
            reasons.append(f"unknown evidence ref alias: {value}")
    refs_used_aliases = bool(source_aliases_returned or evidence_aliases_returned)
    refs_valid = not reasons
    return {
        "expanded_source_refs": expanded_source,
        "expanded_evidence_refs": expanded_evidence,
        "source_ref_aliases_returned": source_aliases_returned,
        "evidence_ref_aliases_returned": evidence_aliases_returned,
        "unknown_aliases": unknown,
        "invalid_ref_reasons": reasons,
        "refs_used_aliases": refs_used_aliases,
        "refs_valid": refs_valid,
    }


def validate_local_advisor_alias_response_refs(alias_map: dict[str, Any], source_refs: list[Any], evidence_refs: list[Any]) -> dict[str, Any]:
    result = expand_local_advisor_ref_aliases(alias_map, source_refs, evidence_refs)
    if not result["refs_valid"]:
        raise ValueError("; ".join(result["invalid_ref_reasons"]) or "invalid local advisor ref aliases")
    return result

LOCAL_ADVISOR_MICRO_STAGE_DEFINITIONS: dict[int, dict[str, Any]] = {
    0: {
        "stage_name": "minimal_ok",
        "max_prompt_chars": 300,
        "timeout_seconds": 20,
        "max_tokens": 24,
        "schema": {"ok": True},
    },
    1: {
        "stage_name": "source_bound",
        "max_prompt_chars": 700,
        "timeout_seconds": 25,
        "max_tokens": 64,
        "schema": {"ok": True, "source_bound": True, "source_path": "string"},
    },
    2: {
        "stage_name": "refs_bound",
        "max_prompt_chars": 1200,
        "timeout_seconds": 35,
        "max_tokens": 96,
        "schema": {"ok": True, "source_bound": True, "source_path": "string", "source_refs": [], "evidence_refs": []},
    },
    3: {
        "stage_name": "critique_bound",
        "max_prompt_chars": 2000,
        "timeout_seconds": 45,
        "max_tokens": 160,
        "schema": {
            "ok": True,
            "source_bound": True,
            "source_path": "string",
            "critique": "string",
            "missing_evidence": [],
            "risk_notes": [],
            "source_refs": [],
            "evidence_refs": [],
            "insufficient_evidence": False,
        },
    },
}
LOCAL_ADVISOR_REQUIRED_MICRO_STAGE = 2


def _local_advisor_micro_stage(stage: int | str) -> int:
    try:
        value = int(stage)
    except Exception as exc:
        raise ValueError("micro contract stage must be an integer 0-3") from exc
    if value not in LOCAL_ADVISOR_MICRO_STAGE_DEFINITIONS:
        raise ValueError("micro contract stage must be one of 0, 1, 2, or 3")
    return value


def collect_local_advisor_micro_contract(
    research_advisor_prompt_package: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    stage_number: int | str = 0,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    stage = _local_advisor_micro_stage(stage_number)
    package = research_advisor_prompt_package or collect_research_advisor_prompt_package(source_path=source_path)
    validate_research_advisor_prompt_package(package)
    config = collect_local_model_advisor_config()
    stage_def = LOCAL_ADVISOR_MICRO_STAGE_DEFINITIONS[stage]
    source_refs, evidence_refs = _local_json_contract_refs(package, source_limit=2, evidence_limit=2)
    alias_map = collect_local_advisor_ref_alias_map(package)
    uses_aliases = stage >= 2
    source_aliases = [item["alias"] for item in alias_map["source_ref_aliases"]]
    evidence_aliases = [item["alias"] for item in alias_map["evidence_ref_aliases"]]
    schema = dict(stage_def["schema"])
    if uses_aliases:
        schema["source_refs"] = [source_aliases[0]]
        schema["evidence_refs"] = [evidence_aliases[0]]
    payload = {
        "local_advisor_micro_contract_version": LOCAL_ADVISOR_MICRO_CONTRACT_VERSION,
        "local_advisor_micro_contract_id": "local-advisor-micro-contract-" + _local_advisor_safe_hash({
            "source_path": package["source_path"],
            "intake": package["research_target_intake_id"],
            "selected": package["deterministic_upgrade_candidates"][0]["upgrade_candidate_id"],
            "stage": stage,
            "version": LOCAL_ADVISOR_MICRO_CONTRACT_VERSION,
        }),
        "source_path": package["source_path"],
        "source_name": package["source_name"],
        "research_target_intake_id": package["research_target_intake_id"],
        "selected_upgrade_candidate_id": package["deterministic_upgrade_candidates"][0]["upgrade_candidate_id"],
        "stage_number": stage,
        "stage_name": stage_def["stage_name"],
        "provider_name": "llamacpp",
        "endpoint_type": config["endpoint_type"],
        "model_name": config["model_name"],
        "strict_json_required": True,
        "advisory_only": True,
        "fallback_allowed": False,
        "max_prompt_chars": stage_def["max_prompt_chars"],
        "timeout_seconds": stage_def["timeout_seconds"],
        "max_tokens": stage_def["max_tokens"],
        "required_response_schema": schema,
        "ref_alias_map_id": alias_map["local_advisor_ref_alias_map_id"],
        "uses_ref_aliases": uses_aliases,
        "allowed_source_aliases": source_aliases if uses_aliases else [],
        "allowed_evidence_aliases": evidence_aliases if uses_aliases else [],
        "allowed_source_refs": source_refs,
        "allowed_evidence_refs": evidence_refs,
        "forbidden_actions": [
            "execute task", "patch files", "approve proposal", "mutate source", "scrape now",
            "install package", "push commit", "OpenRouter fallback", "external provider fallback",
        ],
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_local_advisor_micro_contract(payload)
    return payload


def validate_local_advisor_micro_contract(payload: dict[str, Any]) -> None:
    required = (
        "local_advisor_micro_contract_version", "local_advisor_micro_contract_id", "source_path",
        "source_name", "research_target_intake_id", "selected_upgrade_candidate_id", "stage_number",
        "stage_name", "provider_name", "endpoint_type", "model_name", "strict_json_required",
        "advisory_only", "fallback_allowed", "max_prompt_chars", "timeout_seconds", "max_tokens",
        "required_response_schema", "ref_alias_map_id", "uses_ref_aliases", "allowed_source_aliases",
        "allowed_evidence_aliases", "allowed_source_refs", "allowed_evidence_refs", "forbidden_actions",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"local advisor micro contract missing field: {key}")
    if payload["local_advisor_micro_contract_version"] != LOCAL_ADVISOR_MICRO_CONTRACT_VERSION:
        raise ValueError("invalid local advisor micro contract version")
    if not str(payload["local_advisor_micro_contract_id"]).startswith("local-advisor-micro-contract-"):
        raise ValueError("invalid local advisor micro contract id")
    stage = _local_advisor_micro_stage(payload["stage_number"])
    stage_def = LOCAL_ADVISOR_MICRO_STAGE_DEFINITIONS[stage]
    if payload["stage_name"] != stage_def["stage_name"]:
        raise ValueError("local advisor micro contract stage name mismatch")
    if payload["provider_name"] != "llamacpp" or payload["endpoint_type"] != "local":
        raise ValueError("local advisor micro contract must use local llama.cpp")
    if payload["strict_json_required"] is not True or payload["advisory_only"] is not True or payload["fallback_allowed"] is not False:
        raise ValueError("local advisor micro contract must be strict JSON, advisory-only, and no-fallback")
    if int(payload["max_prompt_chars"]) != stage_def["max_prompt_chars"] or int(payload["max_tokens"]) != stage_def["max_tokens"]:
        raise ValueError("local advisor micro contract budget must match stage definition")
    if not 10 <= int(payload["timeout_seconds"]) <= 60:
        raise ValueError("local advisor micro contract timeout must be bounded")
    schema = payload["required_response_schema"]
    for key in stage_def["schema"]:
        if key not in schema:
            raise ValueError(f"local advisor micro contract schema missing key: {key}")
    if stage >= 1 and ("source_path" not in schema or "source_bound" not in schema):
        raise ValueError("micro contract stage 1+ must require source path and source bound")
    if stage >= 2 and ("source_refs" not in schema or "evidence_refs" not in schema):
        raise ValueError("micro contract stage 2+ must require refs arrays")
    if stage >= 2:
        if payload["uses_ref_aliases"] is not True or not payload["ref_alias_map_id"]:
            raise ValueError("micro contract stage 2+ must use ref aliases")
        if not payload["allowed_source_aliases"] or not payload["allowed_evidence_aliases"]:
            raise ValueError("micro contract stage 2+ must include allowed aliases")
    elif payload["uses_ref_aliases"] is not False or payload["allowed_source_aliases"] or payload["allowed_evidence_aliases"]:
        raise ValueError("micro contract stage 0/1 must not use ref aliases")
    if stage >= 3 and ("critique" not in schema or "missing_evidence" not in schema or "risk_notes" not in schema):
        raise ValueError("micro contract stage 3 must require critique arrays")
    if not payload["allowed_source_refs"] or not payload["allowed_evidence_refs"]:
        raise ValueError("local advisor micro contract must include allowed refs")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("local advisor micro contract must remain read-only")


def stable_local_advisor_micro_contract_json(payload: dict[str, Any]) -> str:
    validate_local_advisor_micro_contract(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_local_advisor_micro_contract_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_local_advisor_micro_contract(payload)
    return payload


def render_local_advisor_micro_prompt(contract: dict[str, Any]) -> str:
    validate_local_advisor_micro_contract(contract)
    stage = contract["stage_number"]
    source_path = contract["source_path"]
    if stage == 0:
        prompt = 'Return exactly this JSON object and nothing else: {"ok":true}'
    elif stage == 1:
        prompt = f'Return JSON only. Advisory only. No fallback. Use this source_path exactly: {source_path}. Schema: {{"ok":true,"source_bound":true,"source_path":"{source_path}"}}'
    elif stage == 2:
        source_alias = contract["allowed_source_aliases"][0]
        evidence_alias = contract["allowed_evidence_aliases"][0]
        prompt = f'Return JSON only. Advisory only. No fallback. Use source_path exactly: {source_path}. Aliases: {source_alias}=source ref, {evidence_alias}=evidence ref. Return only these aliases. Schema: {{"ok":true,"source_bound":true,"source_path":"{source_path}","source_refs":["{source_alias}"],"evidence_refs":["{evidence_alias}"]}}'
    else:
        source_alias = contract["allowed_source_aliases"][0]
        evidence_alias = contract["allowed_evidence_aliases"][0]
        prompt = f'Return JSON only. Advisory only. No fallback. One short critique sentence. Use source_path exactly: {source_path}. Aliases: {source_alias}=source ref, {evidence_alias}=evidence ref. Return only these aliases. Schema: {{"ok":true,"source_bound":true,"source_path":"{source_path}","critique":"short source-bound critique","missing_evidence":[],"risk_notes":[],"source_refs":["{source_alias}"],"evidence_refs":["{evidence_alias}"],"insufficient_evidence":false}}'
    validate_local_advisor_micro_prompt(prompt, contract)
    return prompt


def validate_local_advisor_micro_prompt(prompt: str, contract: dict[str, Any]) -> None:
    validate_local_advisor_micro_contract(contract)
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("local advisor micro prompt must be non-empty")
    if len(prompt) > int(contract["max_prompt_chars"]):
        raise ValueError("local advisor micro prompt exceeds stage budget")
    lower = prompt.lower()
    if "json" not in lower:
        raise ValueError("local advisor micro prompt must require JSON")
    if contract["stage_number"] >= 1 and contract["source_path"] not in prompt:
        raise ValueError("local advisor micro prompt must include source path for stage 1+")
    if contract["stage_number"] >= 1 and ("advisory" not in lower or "fallback" not in lower):
        raise ValueError("local advisor micro prompt must include advisory/no-fallback constraints")
    for key in contract["required_response_schema"]:
        if key not in prompt:
            raise ValueError(f"local advisor micro prompt missing schema key: {key}")
    if "research_target_evidence_bundle" in prompt or "prompt_package" in prompt:
        raise ValueError("local advisor micro prompt must not include giant nested payloads")


def _validate_micro_contract_model_payload(model_json: dict[str, Any], contract: dict[str, Any]) -> tuple[bool, str, dict[str, bool], dict[str, Any]]:
    validate_local_advisor_micro_contract(contract)
    stage = contract["stage_number"]
    flags = {"schema_valid": False, "source_bound_valid": stage == 0, "refs_valid": stage < 2, "critique_valid": stage < 3}
    alias_result = {
        "expanded_source_refs": [],
        "expanded_evidence_refs": [],
        "source_ref_aliases_returned": [],
        "evidence_ref_aliases_returned": [],
        "unknown_aliases": [],
        "invalid_ref_reasons": [],
        "refs_used_aliases": False,
        "refs_valid": stage < 2,
    }
    for key in contract["required_response_schema"]:
        if key not in model_json:
            return False, f"schema missing key: {key}", flags, alias_result
    if model_json.get("ok") is not True:
        return False, "ok must be true", flags, alias_result
    if _research_advisor_forbidden_text(model_json):
        return False, "forbidden action recommendation detected", flags, alias_result
    flags["schema_valid"] = True
    if stage >= 1:
        if model_json.get("source_path") != contract["source_path"]:
            return False, "source_path mismatch", flags, alias_result
        if model_json.get("source_bound") is not True:
            return False, "source_bound must be true", flags, alias_result
        flags["source_bound_valid"] = True
    if stage >= 2:
        source_refs = model_json.get("source_refs")
        evidence_refs = model_json.get("evidence_refs")
        if not isinstance(source_refs, list) or not isinstance(evidence_refs, list):
            return False, "source_refs and evidence_refs must be arrays", flags, alias_result
        alias_map = collect_local_advisor_ref_alias_map(source_path=contract["source_path"])
        alias_result = expand_local_advisor_ref_aliases(alias_map, source_refs, evidence_refs)
        if not alias_result["refs_valid"]:
            return False, "; ".join(alias_result["invalid_ref_reasons"]) or "alias expansion failed", flags, alias_result
        flags["refs_valid"] = True
    if stage >= 3:
        if not isinstance(model_json.get("critique"), str) or not model_json.get("critique", "").strip():
            return False, "critique must be non-empty string", flags, alias_result
        if not isinstance(model_json.get("missing_evidence"), list) or not isinstance(model_json.get("risk_notes"), list):
            return False, "missing_evidence and risk_notes must be arrays", flags, alias_result
        if not isinstance(model_json.get("insufficient_evidence"), bool):
            return False, "insufficient_evidence must be boolean", flags, alias_result
        flags["critique_valid"] = True
    return True, "", flags, alias_result

def _local_advisor_micro_failure_mode(stage: int, reason: str, assistant_present: bool, valid_json: bool) -> str:
    lower = reason.lower()
    if "timed out" in lower or "timeout" in lower:
        return f"timeout_stage_{stage}"
    if not assistant_present or "empty assistant" in lower:
        return "empty_assistant_content"
    if not valid_json or "json" in lower or "expecting value" in lower:
        return f"invalid_json_stage_{stage}"
    if stage == 1 and ("source_path" in lower or "source_bound" in lower):
        return "source_binding_failed_stage_1"
    if stage == 2 and "wrong-type alias" in lower:
        return "ref_alias_type_mismatch_stage_2"
    if stage == 2 and ("unknown" in lower or "alias" in lower):
        return "unknown_ref_alias_stage_2"
    if stage == 2 and "ref" in lower:
        return "refs_schema_failed_stage_2"
    if stage == 3 and ("alias" in lower or "ref" in lower):
        return "critique_alias_expansion_failed_stage_3"
    if stage == 3 and ("critique" in lower or "missing_evidence" in lower or "risk_notes" in lower):
        return "critique_schema_failed_stage_3"
    if "request" in lower or "connection" in lower:
        return "endpoint_unavailable"
    return "model_not_json_reliable"


def collect_local_advisor_micro_contract_result(
    local_advisor_micro_contract: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    stage_number: int | str = 0,
    use_local_model: bool = False,
    model_response_json: dict[str, Any] | None = None,
    raw_response: str | None = None,
    latency_ms: int = 0,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    import json as _json

    contract = local_advisor_micro_contract or collect_local_advisor_micro_contract(source_path=source_path, stage_number=stage_number)
    validate_local_advisor_micro_contract(contract)
    prompt = render_local_advisor_micro_prompt(contract)
    response_hash = ""
    raw_preview = ""
    http_status = 0
    assistant_content = ""
    assistant_present = False
    assistant_chars = 0
    valid_json = False
    flags = {"schema_valid": False, "source_bound_valid": contract["stage_number"] == 0, "refs_valid": contract["stage_number"] < 2, "critique_valid": contract["stage_number"] < 3}
    alias_result = {"expanded_source_refs": [], "expanded_evidence_refs": [], "source_ref_aliases_returned": [], "evidence_ref_aliases_returned": [], "unknown_aliases": [], "invalid_ref_reasons": [], "refs_used_aliases": False, "refs_valid": contract["stage_number"] < 2}
    model_used = False
    fail_reason = ""
    response_shape: dict[str, Any] = {}
    if model_response_json is not None:
        model_used = True
        assistant_content = _stable_ruflo_json(model_response_json)
        assistant_present = True
        assistant_chars = len(assistant_content)
        response_hash = _research_target_hash_text(raw_response or assistant_content)
        raw_preview = _sanitize_local_advisor_preview(raw_response or assistant_content)
        valid_json = True
        micro_ok, fail_reason, flags, alias_result = _validate_micro_contract_model_payload(dict(model_response_json), contract)
    elif use_local_model:
        model_used = True
        try:
            response_json, raw, latency_ms = _call_canonical_llamacpp_chat_raw(
                prompt=prompt,
                system_prompt="Return strict JSON only. Local-only advisor diagnostic. No markdown.",
                timeout=int(contract["timeout_seconds"]),
                model_name=contract["model_name"],
                max_tokens=int(contract["max_tokens"]),
            )
            http_status = int(response_json.get("_http_status", 0) or 0)
            assistant_content, response_shape = _extract_llamacpp_assistant_content(response_json)
            assistant_present = bool(assistant_content.strip())
            assistant_chars = len(assistant_content)
            response_hash = _research_target_hash_text(raw)
            raw_preview = _sanitize_local_advisor_preview(assistant_content or raw)
            if not assistant_present:
                fail_reason = "empty assistant content"
                micro_ok = False
            else:
                parsed = _json.loads(assistant_content)
                valid_json = isinstance(parsed, dict)
                if not valid_json:
                    fail_reason = "assistant content was not a JSON object"
                    micro_ok = False
                else:
                    micro_ok, fail_reason, flags, alias_result = _validate_micro_contract_model_payload(parsed, contract)
        except Exception as exc:
            fail_reason = str(exc)[:220]
            response_hash = _research_target_hash_text(fail_reason)
            raw_preview = _sanitize_local_advisor_preview(fail_reason)
            micro_ok = False
    else:
        fail_reason = "preview_only; rerun with --local-model to perform local micro-check"
        micro_ok = False
    likely = "passed" if micro_ok else _local_advisor_micro_failure_mode(contract["stage_number"], fail_reason, assistant_present, valid_json)
    payload = {
        "local_advisor_micro_contract_result_version": LOCAL_ADVISOR_MICRO_CONTRACT_RESULT_VERSION,
        "local_advisor_micro_contract_result_id": "local-advisor-micro-contract-result-" + _local_advisor_safe_hash({
            "contract": contract["local_advisor_micro_contract_id"],
            "model_used": model_used,
            "response_hash": response_hash,
            "micro_ok": micro_ok,
            "version": LOCAL_ADVISOR_MICRO_CONTRACT_RESULT_VERSION,
        }),
        "local_advisor_micro_contract_id": contract["local_advisor_micro_contract_id"],
        "source_path": contract["source_path"],
        "stage_number": contract["stage_number"],
        "stage_name": contract["stage_name"],
        "provider_name": "llamacpp",
        "model_used": bool(model_used),
        "endpoint_type": "local",
        "prompt_hash": _research_target_hash_text(prompt),
        "response_hash": response_hash,
        "prompt_chars": len(prompt),
        "timeout_seconds": contract["timeout_seconds"],
        "max_tokens": contract["max_tokens"],
        "latency_ms": int(latency_ms or 0),
        "http_status": int(http_status or 0),
        "raw_response_preview_sanitized": raw_preview,
        "assistant_content_present": bool(assistant_present),
        "assistant_content_chars": int(assistant_chars),
        "valid_json": bool(valid_json),
        "schema_valid": bool(flags["schema_valid"]),
        "source_bound_valid": bool(flags["source_bound_valid"]),
        "refs_valid": bool(flags["refs_valid"]),
        "critique_valid": bool(flags["critique_valid"]),
        "ref_alias_map_id": contract.get("ref_alias_map_id", ""),
        "refs_used_aliases": bool(alias_result["refs_used_aliases"]),
        "source_ref_aliases_returned": list(alias_result["source_ref_aliases_returned"]),
        "evidence_ref_aliases_returned": list(alias_result["evidence_ref_aliases_returned"]),
        "expanded_source_refs": list(alias_result["expanded_source_refs"]),
        "expanded_evidence_refs": list(alias_result["expanded_evidence_refs"]),
        "unknown_aliases": list(alias_result["unknown_aliases"]),
        "alias_expansion_valid": bool(alias_result["refs_valid"]),
        "micro_ok": bool(micro_ok),
        "fail_closed": not bool(micro_ok),
        "fail_closed_reason": "" if micro_ok else (fail_reason or "local advisor micro-check failed closed"),
        "likely_failure_mode": likely,
        "response_shape": response_shape,
        "recommended_next_action": "Proceed to the next micro stage or two-stage gate." if micro_ok else "Stop richer local advisor flow; inspect micro-diagnostic failure mode before retrying.",
        "human_review_required": True,
        "fallback_allowed": False,
        "advisory_only": True,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_local_advisor_micro_contract_result(payload, contract)
    return payload


def validate_local_advisor_micro_contract_result(payload: dict[str, Any], contract: dict[str, Any] | None = None) -> None:
    required = (
        "local_advisor_micro_contract_result_version", "local_advisor_micro_contract_result_id",
        "local_advisor_micro_contract_id", "source_path", "stage_number", "stage_name", "provider_name",
        "model_used", "endpoint_type", "prompt_hash", "response_hash", "prompt_chars", "timeout_seconds",
        "max_tokens", "latency_ms", "http_status", "raw_response_preview_sanitized",
        "assistant_content_present", "assistant_content_chars", "valid_json", "schema_valid",
        "source_bound_valid", "refs_valid", "critique_valid", "ref_alias_map_id", "refs_used_aliases",
        "source_ref_aliases_returned", "evidence_ref_aliases_returned", "expanded_source_refs",
        "expanded_evidence_refs", "unknown_aliases", "alias_expansion_valid", "micro_ok", "fail_closed",
        "fail_closed_reason", "likely_failure_mode", "recommended_next_action", "human_review_required",
        "fallback_allowed", "advisory_only", "safety_metadata", "dry_run", "write_allowed",
        "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"local advisor micro contract result missing field: {key}")
    if payload["local_advisor_micro_contract_result_version"] != LOCAL_ADVISOR_MICRO_CONTRACT_RESULT_VERSION:
        raise ValueError("invalid local advisor micro contract result version")
    stage = _local_advisor_micro_stage(payload["stage_number"])
    if payload["stage_name"] != LOCAL_ADVISOR_MICRO_STAGE_DEFINITIONS[stage]["stage_name"]:
        raise ValueError("local advisor micro contract result stage name mismatch")
    if payload["provider_name"] != "llamacpp" or payload["endpoint_type"] != "local":
        raise ValueError("local advisor micro contract result must use local llama.cpp")
    if len(str(payload["raw_response_preview_sanitized"])) > 260:
        raise ValueError("local advisor micro contract result raw preview must be bounded")
    if payload["micro_ok"] is True:
        if payload["fail_closed"] is not False or not payload["model_used"] or not payload["valid_json"] or not payload["schema_valid"]:
            raise ValueError("successful micro-check must use model, valid JSON, and valid schema")
        if stage >= 1 and payload["source_bound_valid"] is not True:
            raise ValueError("successful stage 1+ micro-check must be source-bound")
        if stage >= 2 and (payload["refs_valid"] is not True or payload["alias_expansion_valid"] is not True):
            raise ValueError("successful stage 2+ micro-check must have valid expanded refs")
        if stage >= 3 and payload["critique_valid"] is not True:
            raise ValueError("successful stage 3 micro-check must have valid critique")
    else:
        if payload["fail_closed"] is not True or not payload["fail_closed_reason"]:
            raise ValueError("failed micro-check must fail closed with reason")
    if contract is not None and payload["local_advisor_micro_contract_id"] != contract["local_advisor_micro_contract_id"]:
        raise ValueError("local advisor micro contract result contract mismatch")
    if payload["human_review_required"] is not True or payload["fallback_allowed"] is not False or payload["advisory_only"] is not True:
        raise ValueError("local advisor micro contract result must be advisory-only, human-reviewed, and no-fallback")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("local advisor micro contract result must remain read-only")


def stable_local_advisor_micro_contract_result_json(payload: dict[str, Any]) -> str:
    validate_local_advisor_micro_contract_result(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_local_advisor_micro_contract_result_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_local_advisor_micro_contract_result(payload)
    return payload


def collect_local_advisor_micro_diagnostic(
    *,
    source_path: str,
    use_local_model: bool = False,
    stage_results: list[dict[str, Any]] | None = None,
    stop_on_failure: bool = True,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    if stage_results is not None:
        results = list(stage_results)
    elif use_local_model:
        for stage in range(4):
            result = collect_local_advisor_micro_contract_result(source_path=source_path, stage_number=stage, use_local_model=True)
            results.append(result)
            if stop_on_failure and not result["micro_ok"]:
                break
    else:
        for stage in range(4):
            contract = collect_local_advisor_micro_contract(source_path=source_path, stage_number=stage)
            results.append({
                "stage_number": stage,
                "stage_name": contract["stage_name"],
                "planned": True,
                "micro_ok": False,
                "likely_failure_mode": "not_run",
                "local_advisor_micro_contract_id": contract["local_advisor_micro_contract_id"],
            })
    highest = -1
    first_fail: int | None = None
    likely = "not_run" if not use_local_model and stage_results is None else "all_micro_stages_passed"
    for item in results:
        stage = int(item["stage_number"])
        if item.get("micro_ok") is True:
            highest = max(highest, stage)
        elif first_fail is None:
            first_fail = stage
            likely = str(item.get("likely_failure_mode") or "model_not_json_reliable")
    if first_fail is None and results and all(item.get("micro_ok") is True for item in results):
        first_fail_value: int | None = None
        status = "passed"
    elif not use_local_model and stage_results is None:
        first_fail_value = 0
        status = "plan_only"
    else:
        first_fail_value = first_fail
        status = "failed_closed"
    stage2_result = next((item for item in results if int(item.get("stage_number", -1)) == 2), {})
    stage3_result = next((item for item in results if int(item.get("stage_number", -1)) == 3), {})
    payload = {
        "local_advisor_micro_diagnostic_version": LOCAL_ADVISOR_MICRO_DIAGNOSTIC_VERSION,
        "local_advisor_micro_diagnostic_id": "local-advisor-micro-diagnostic-" + _local_advisor_safe_hash({
            "source_path": source_path,
            "results": [item.get("local_advisor_micro_contract_result_id", item.get("local_advisor_micro_contract_id", "")) for item in results],
            "version": LOCAL_ADVISOR_MICRO_DIAGNOSTIC_VERSION,
        }),
        "source_path": source_path,
        "provider_name": "llamacpp",
        "endpoint_type": "local",
        "diagnostic_status": status,
        "stage_results": results,
        "highest_passing_stage": highest,
        "first_failing_stage": first_fail_value,
        "likely_failure_mode": likely,
        "uses_ref_aliases": True,
        "stage2_alias_expansion_valid": bool(stage2_result.get("alias_expansion_valid", False)),
        "stage3_alias_expansion_valid": bool(stage3_result.get("alias_expansion_valid", False)),
        "recommended_next_action": "Micro gate passed through refs stage; JSON contract may be attempted." if highest >= LOCAL_ADVISOR_REQUIRED_MICRO_STAGE else "Do not run richer advisor review; fix the first failing micro stage first.",
        "fallback_allowed": False,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_local_advisor_micro_diagnostic(payload)
    return payload


def validate_local_advisor_micro_diagnostic(payload: dict[str, Any]) -> None:
    required = (
        "local_advisor_micro_diagnostic_version", "local_advisor_micro_diagnostic_id", "source_path",
        "provider_name", "endpoint_type", "diagnostic_status", "stage_results", "highest_passing_stage",
        "first_failing_stage", "likely_failure_mode", "uses_ref_aliases", "stage2_alias_expansion_valid",
        "stage3_alias_expansion_valid", "recommended_next_action", "fallback_allowed",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"local advisor micro diagnostic missing field: {key}")
    if payload["local_advisor_micro_diagnostic_version"] != LOCAL_ADVISOR_MICRO_DIAGNOSTIC_VERSION:
        raise ValueError("invalid local advisor micro diagnostic version")
    if payload["provider_name"] != "llamacpp" or payload["endpoint_type"] != "local":
        raise ValueError("local advisor micro diagnostic must use local llama.cpp")
    if payload["fallback_allowed"] is not False:
        raise ValueError("local advisor micro diagnostic must disable fallback")
    if not isinstance(payload["stage_results"], list) or not payload["stage_results"]:
        raise ValueError("local advisor micro diagnostic requires stage results")
    for item in payload["stage_results"]:
        if "stage_number" not in item or "stage_name" not in item:
            raise ValueError("local advisor micro diagnostic stage result missing stage fields")
        _local_advisor_micro_stage(item["stage_number"])
    if not isinstance(payload["highest_passing_stage"], int) or payload["highest_passing_stage"] < -1 or payload["highest_passing_stage"] > 3:
        raise ValueError("invalid highest passing micro stage")
    if payload["first_failing_stage"] is not None:
        _local_advisor_micro_stage(payload["first_failing_stage"])
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("local advisor micro diagnostic must remain read-only")


