def _research_advisor_allowed_source_ids(prompt_package: dict[str, Any]) -> set[str]:
    return {item["source_ref_id"] for item in prompt_package["source_refs"]}


def _research_advisor_allowed_evidence_ids(prompt_package: dict[str, Any]) -> set[str]:
    return {item["evidence_ref_id"] for item in prompt_package["evidence_refs"]}


def _research_advisor_forbidden_text(value: Any) -> bool:
    text = _stable_ruflo_json(value).lower() if not isinstance(value, str) else value.lower()
    return any(term in text for term in LOCAL_ADVISOR_FORBIDDEN_RECOMMENDATIONS)


def validate_local_model_research_grounding(review: dict[str, Any], prompt_package: dict[str, Any] | None = None) -> None:
    package = prompt_package
    allowed_sources = set(review.get("_allowed_source_refs", []))
    allowed_evidence = set(review.get("_allowed_evidence_refs", []))
    if package is not None:
        validate_research_advisor_prompt_package(package)
        allowed_sources = _research_advisor_allowed_source_ids(package)
        allowed_evidence = _research_advisor_allowed_evidence_ids(package)
    if not allowed_sources:
        allowed_sources = {ref for item in review.get("patterns_found", []) for ref in item.get("source_refs", [])}
    grounding_warnings = review.setdefault("grounding_warnings", [])
    for pattern in review.get("patterns_found", []):
        if not pattern.get("source_refs"):
            raise ValueError("local research advisor patterns must cite source refs")
        unknown_sources = [ref for ref in pattern.get("source_refs", []) if ref not in allowed_sources]
        if unknown_sources:
            raise ValueError(f"local research advisor cited unknown source refs: {unknown_sources}")
        if int(pattern.get("confidence", 0)) >= 70 and not pattern.get("evidence_refs"):
            grounding_warnings.append(f"high-confidence pattern lacks evidence refs: {pattern.get('pattern_name', '')}")
        unknown_evidence = [ref for ref in pattern.get("evidence_refs", []) if allowed_evidence and ref not in allowed_evidence]
        if unknown_evidence:
            grounding_warnings.append(f"unknown evidence refs for pattern {pattern.get('pattern_name', '')}: {', '.join(unknown_evidence)}")
    for critique in review.get("upgrade_candidate_critiques", []):
        if int(critique.get("confidence", 0)) >= 70 and critique.get("source_grounding_status") not in {"grounded", "partially_grounded"}:
            grounding_warnings.append(f"high-confidence critique is not grounded: {critique.get('upgrade_candidate_id', '')}")
    checked_fields = {
        "best_upgrade_suggestion": review.get("best_upgrade_suggestion", {}),
        "recommended_next_action": review.get("recommended_next_action", ""),
        "task_draft_improvements": review.get("task_draft_improvements", []),
    }
    if _research_advisor_forbidden_text(checked_fields):
        raise ValueError("local research advisor output contains forbidden action recommendation")


def _deterministic_advisor_patterns(prompt_package: dict[str, Any]) -> list[dict[str, Any]]:
    patterns = []
    source_refs = [item["source_ref_id"] for item in prompt_package["source_refs"]]
    evidence_refs = [item["evidence_ref_id"] for item in prompt_package["evidence_refs"]]
    for candidate in prompt_package["deterministic_upgrade_candidates"][:3]:
        patterns.append({
            "pattern_name": f"Deterministic signal for {candidate['target_link_module']}",
            "why_it_matters": f"Link already found source-bound evidence for {candidate['title']} in {prompt_package['source_name']}.",
            "source_refs": candidate.get("source_refs")[:2] or source_refs[:1],
            "evidence_refs": candidate.get("evidence_refs")[:2] or evidence_refs[:1],
            "target_link_module": candidate["target_link_module"],
            "risk": candidate["risk_level"],
            "confidence": min(85, int(candidate["confidence_score"])),
        })
    return patterns


def _deterministic_advisor_critiques(prompt_package: dict[str, Any]) -> list[dict[str, Any]]:
    critiques = []
    for candidate in prompt_package["deterministic_upgrade_candidates"][:5]:
        missing = [] if candidate.get("evidence_refs") else ["candidate evidence refs"]
        critiques.append({
            "upgrade_candidate_id": candidate["upgrade_candidate_id"],
            "critique": f"Deterministic baseline supports {candidate['title']} but still requires human review for implementation specificity.",
            "source_grounding_status": "grounded" if candidate.get("source_refs") else "insufficient_evidence",
            "specificity_assessment": "source-bound" if candidate.get("source_refs") and candidate.get("evidence_refs") else "needs_more_evidence",
            "missing_evidence": missing,
            "confidence": int(candidate["confidence_score"]),
        })
    return critiques


def _normalize_local_research_advisor_model_json(model_json: dict[str, Any], prompt_package: dict[str, Any]) -> dict[str, Any]:
    source_ids = _research_advisor_allowed_source_ids(prompt_package)
    evidence_ids = _research_advisor_allowed_evidence_ids(prompt_package)

    if "advisor_role" in model_json and "patterns_found" not in model_json:
        first_source = next(iter(source_ids), "")
        first_evidence = next(iter(evidence_ids), "")
        selected_candidate = prompt_package["deterministic_upgrade_candidates"][0]
        quality = str(model_json.get("recommendation_quality") or "insufficient evidence")
        risk_notes = [str(item) for item in model_json.get("risk_notes", []) if isinstance(item, str)]
        task_feedback = [str(item) for item in model_json.get("task_draft_feedback", []) if isinstance(item, str)]
        cited_sources = [ref for ref in model_json.get("source_refs", []) if isinstance(ref, str)] or ([first_source] if first_source else [])
        cited_evidence = [ref for ref in model_json.get("evidence_refs", []) if isinstance(ref, str)] or ([first_evidence] if first_evidence else [])
        confidence = int(model_json.get("source_specificity_score", 0) or 0)
        model_json = {
            "patterns_found": [
                {
                    "pattern_name": "Local advisor specificity critique",
                    "why_it_matters": quality,
                    "source_refs": cited_sources,
                    "evidence_refs": cited_evidence,
                    "target_link_module": selected_candidate["target_link_module"],
                    "risk": "medium" if risk_notes else "low",
                    "confidence": max(0, min(100, confidence)),
                }
            ],
            "upgrade_candidate_critiques": [
                {
                    "upgrade_candidate_id": selected_candidate["upgrade_candidate_id"],
                    "critique": quality,
                    "source_grounding_status": "grounded" if cited_sources else "insufficient_evidence",
                    "specificity_assessment": "source-bound" if confidence >= 65 else "needs_more_evidence",
                    "missing_evidence": [str(item) for item in model_json.get("missing_evidence", []) if isinstance(item, str)][:8],
                    "confidence": max(0, min(100, confidence)),
                }
            ],
            "best_upgrade_suggestion": {
                "title": selected_candidate["title"],
                "target_link_module": selected_candidate["target_link_module"],
                "upgrade_candidate_id": selected_candidate["upgrade_candidate_id"],
                "why": str(model_json.get("suggested_next_step") or quality)[:360],
            },
            "genericity_warnings": ["local advisor marked insufficient_evidence"] if model_json.get("insufficient_evidence") else [],
            "missing_evidence": [str(item) for item in model_json.get("missing_evidence", []) if isinstance(item, str)][:10],
            "risks": risk_notes[:10],
            "task_draft_improvements": task_feedback[:10],
            "do_not_use": list(LOCAL_ADVISOR_FORBIDDEN_RECOMMENDATIONS[:5]),
        }

    def clean_pattern(item: dict[str, Any]) -> dict[str, Any]:
        refs = [ref for ref in item.get("source_refs", []) if isinstance(ref, str)]
        evs = [ref for ref in item.get("evidence_refs", []) if isinstance(ref, str)]
        return {
            "pattern_name": str(item.get("pattern_name") or "advisor pattern")[:120],
            "why_it_matters": str(item.get("why_it_matters") or "insufficient evidence")[:300],
            "source_refs": refs,
            "evidence_refs": evs,
            "target_link_module": str(item.get("target_link_module") or "unknown"),
            "risk": str(item.get("risk") or "medium"),
            "confidence": int(item.get("confidence", 0)),
        }

    def clean_critique(item: dict[str, Any]) -> dict[str, Any]:
        return {
            "upgrade_candidate_id": str(item.get("upgrade_candidate_id") or "unknown"),
            "critique": str(item.get("critique") or "insufficient evidence")[:400],
            "source_grounding_status": str(item.get("source_grounding_status") or "insufficient_evidence"),
            "specificity_assessment": str(item.get("specificity_assessment") or "needs_review"),
            "missing_evidence": [str(value) for value in item.get("missing_evidence", []) if isinstance(value, str)][:8],
            "confidence": int(item.get("confidence", 0)),
        }

    patterns = [clean_pattern(item) for item in model_json.get("patterns_found", []) if isinstance(item, dict)]
    critiques = [clean_critique(item) for item in model_json.get("upgrade_candidate_critiques", []) if isinstance(item, dict)]
    if not patterns:
        patterns = _deterministic_advisor_patterns(prompt_package)
    if not critiques:
        critiques = _deterministic_advisor_critiques(prompt_package)
    selected = prompt_package["deterministic_upgrade_candidates"][0]
    best = model_json.get("best_upgrade_suggestion") if isinstance(model_json.get("best_upgrade_suggestion"), dict) else {}
    return {
        "patterns_found": patterns,
        "upgrade_candidate_critiques": critiques,
        "best_upgrade_suggestion": {
            "title": str(best.get("title") or selected["title"])[:160],
            "target_link_module": str(best.get("target_link_module") or selected["target_link_module"]),
            "upgrade_candidate_id": str(best.get("upgrade_candidate_id") or selected["upgrade_candidate_id"]),
            "why": str(best.get("why") or "Advisor should review deterministic source-bound candidate.")[:360],
        },
        "genericity_warnings": [str(item) for item in model_json.get("genericity_warnings", []) if isinstance(item, str)][:10],
        "missing_evidence": [str(item) for item in model_json.get("missing_evidence", []) if isinstance(item, str)][:10],
        "risks": [str(item) for item in model_json.get("risks", []) if isinstance(item, str)][:10],
        "task_draft_improvements": [str(item) for item in model_json.get("task_draft_improvements", []) if isinstance(item, str)][:10],
        "do_not_use": [str(item) for item in model_json.get("do_not_use", []) if isinstance(item, str)][:10] or list(LOCAL_ADVISOR_FORBIDDEN_RECOMMENDATIONS[:5]),
        "grounding_warnings": [],
        "_allowed_source_refs": sorted(source_ids),
        "_allowed_evidence_refs": sorted(evidence_ids),
    }


def _call_local_research_advisor_model(
    config: dict[str, Any],
    prompt_package: dict[str, Any],
    *,
    timeout: int | None = None,
) -> tuple[dict[str, Any], str, int, dict[str, Any], dict[str, Any]]:
    validate_local_model_advisor_config(config)
    validate_research_advisor_prompt_package(prompt_package)
    if not config["usable_for_local_advisor"] or config["endpoint_type"] != "local":
        raise ValueError("canonical local advisor config is not usable for local inference")
    if config["provider"] != "llamacpp":
        raise ValueError("only canonical llama.cpp advisor calls are enabled; no Ollama/OpenRouter fallback")
    budget = collect_local_advisor_prompt_budget()
    compact_context = collect_compact_source_aware_advisor_context(prompt_package, prompt_budget=budget)
    prompt = render_compact_local_advisor_prompt(compact_context, budget)
    return (
        *_call_canonical_llamacpp_chat(
            prompt=prompt,
            system_prompt="You are a local-only advisory reviewer for Link. Return strict JSON only. You are advisory only: no execution, writes, approvals, network use, scraping, package installs, git, OpenRouter fallback, or copying external code.",
            timeout=int(timeout or budget["timeout_seconds"]),
            model_name=config["model_name"],
            max_tokens=384,
        ),
        compact_context,
        budget,
    )


def _call_openrouter_research_advisor_model(config: dict[str, Any], prompt_package: dict[str, Any], *, timeout: int = 30) -> tuple[dict[str, Any], str, int]:
    import json as _json
    import os as _os
    import time
    import urllib.error
    import urllib.request

    validate_openrouter_advisor_config(config)
    validate_research_advisor_prompt_package(prompt_package)
    if not config["enabled_for_advisor"]:
        raise ValueError("OpenRouter advisor is not enabled; explicit opt-in and API key are required")
    api_key = _os.environ.get("OPENROUTER_API_KEY")
    if not api_key:
        raise ValueError("OpenRouter API key is not present")
    prompt = _stable_ruflo_json({
        "task": "Review this Link research target and return strict JSON only.",
        "expected_schema": {
            "patterns_found": ["pattern_name", "why_it_matters", "source_refs", "evidence_refs", "target_link_module", "risk", "confidence"],
            "upgrade_candidate_critiques": ["upgrade_candidate_id", "critique", "source_grounding_status", "specificity_assessment", "missing_evidence", "confidence"],
            "best_upgrade_suggestion": {"title": "", "target_link_module": "", "upgrade_candidate_id": "", "why": ""},
            "genericity_warnings": [],
            "missing_evidence": [],
            "risks": [],
            "task_draft_improvements": [],
            "do_not_use": [],
        },
        "grounding_rules": [
            "cite only source_refs from the prompt",
            "cite evidence_refs for high-confidence claims",
            "say insufficient evidence when unsure",
            "do not recommend execution, writes, approvals, scraping, package installation, git, or network use",
        ],
        "prompt_package": prompt_package,
    })
    payload = {
        "model": config["model_name"],
        "messages": [
            {"role": "system", "content": "You are an explicitly requested OpenRouter advisory reviewer for Link. Return strict JSON only. Do not suggest execution, writes, approvals, network use beyond this requested provider call, scraping, package installs, git, or copying external code."},
            {"role": "user", "content": prompt},
        ],
        "temperature": 0,
        "max_tokens": 1200,
    }
    request = urllib.request.Request(
        config["endpoint_summary"],
        data=_json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json", "Authorization": "Bearer " + api_key},
        method="POST",
    )
    started = time.monotonic()
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read().decode("utf-8", errors="replace")
    except urllib.error.URLError as exc:
        raise ValueError(f"OpenRouter advisor request failed closed: {exc}") from exc
    latency_ms = int((time.monotonic() - started) * 1000)
    data = _json.loads(raw)
    try:
        content = data["choices"][0]["message"]["content"]
    except Exception as exc:
        raise ValueError("OpenRouter advisor response did not include chat content") from exc
    return _parse_strict_local_model_json(content), content, latency_ms


def collect_local_model_research_advisor_review(
    research_advisor_prompt_package: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    use_local_model: bool = False,
    model_response_json: dict[str, Any] | None = None,
    requested_provider: str | None = None,
    explicit_provider_flag: bool = False,
    openrouter_requested: bool = False,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    prompt_package = research_advisor_prompt_package or collect_research_advisor_prompt_package(source_path=source_path)
    validate_research_advisor_prompt_package(prompt_package)
    provider_name = requested_provider or "llamacpp"
    selection = collect_advisor_provider_selection_boundary(
        requested_provider=provider_name,
        command_context="research advisor-review",
        explicit_provider_flag=explicit_provider_flag,
        local_model_requested=use_local_model,
        openrouter_requested=openrouter_requested,
        source_path=prompt_package["source_path"],
    )
    config = collect_local_model_advisor_config()
    boundary = collect_local_model_provider_boundary()
    openrouter_config = collect_openrouter_advisor_config()
    prompt_hash = prompt_package["prompt_hash"]
    response_hash = ""
    latency_ms = 0
    valid_json = False
    advisor_status = "preview_only"
    compact_context: dict[str, Any] | None = None
    prompt_budget = collect_local_advisor_prompt_budget()
    prompt_chars = 0
    fail_closed = False
    fail_closed_reason = ""
    if model_response_json is not None:
        normalized = _normalize_local_research_advisor_model_json(model_response_json, prompt_package)
        response_hash = _research_target_hash_text(model_response_json)
        valid_json = True
        advisor_status = "model_fixture_validated"
        model_used = True
    elif use_local_model and provider_name == "llamacpp":
        try:
            model_json, raw_content, latency_ms, compact_context, prompt_budget = _call_local_research_advisor_model(config, prompt_package)
            prompt_hash = compact_context["prompt_hash"]
            prompt_chars = int(compact_context["estimated_prompt_chars"])
            normalized = _normalize_local_research_advisor_model_json(model_json, prompt_package)
            response_hash = _research_target_hash_text(raw_content)
            valid_json = True
            advisor_status = "model_reviewed"
            model_used = True
        except Exception as exc:
            compact_context = collect_compact_source_aware_advisor_context(prompt_package, prompt_budget=prompt_budget)
            prompt_hash = compact_context["prompt_hash"]
            prompt_chars = int(compact_context["estimated_prompt_chars"])
            fail_closed = True
            fail_closed_reason = str(exc)[:240]
            normalized = {
                "patterns_found": _deterministic_advisor_patterns(prompt_package),
                "upgrade_candidate_critiques": _deterministic_advisor_critiques(prompt_package),
                "best_upgrade_suggestion": {
                    "title": prompt_package["deterministic_upgrade_candidates"][0]["title"],
                    "target_link_module": prompt_package["deterministic_upgrade_candidates"][0]["target_link_module"],
                    "upgrade_candidate_id": prompt_package["deterministic_upgrade_candidates"][0]["upgrade_candidate_id"],
                    "why": "Local compact advisor failed closed; use deterministic source-aware recommendation until local inference succeeds.",
                },
                "genericity_warnings": ["Local compact advisor failed closed: " + fail_closed_reason],
                "missing_evidence": list(prompt_package.get("missing_evidence", [])),
                "risks": ["Local model advisor output unavailable; deterministic Link output remains authoritative."],
                "task_draft_improvements": ["Retry only after local smoke passes and prompt budget is still bounded."],
                "do_not_use": list(LOCAL_ADVISOR_FORBIDDEN_RECOMMENDATIONS),
                "grounding_warnings": [],
                "_allowed_source_refs": sorted(_research_advisor_allowed_source_ids(prompt_package)),
                "_allowed_evidence_refs": sorted(_research_advisor_allowed_evidence_ids(prompt_package)),
            }
            advisor_status = "fail_closed"
            model_used = False
    elif openrouter_requested and provider_name == "openrouter" and selection["provider_allowed"]:
        model_json, raw_content, latency_ms = _call_openrouter_research_advisor_model(openrouter_config, prompt_package)
        normalized = _normalize_local_research_advisor_model_json(model_json, prompt_package)
        response_hash = _research_target_hash_text(raw_content)
        valid_json = True
        advisor_status = "model_reviewed"
        model_used = True
    else:
        normalized = {
            "patterns_found": _deterministic_advisor_patterns(prompt_package),
            "upgrade_candidate_critiques": _deterministic_advisor_critiques(prompt_package),
            "best_upgrade_suggestion": {
                "title": prompt_package["deterministic_upgrade_candidates"][0]["title"],
                "target_link_module": prompt_package["deterministic_upgrade_candidates"][0]["target_link_module"],
                "upgrade_candidate_id": prompt_package["deterministic_upgrade_candidates"][0]["upgrade_candidate_id"],
                "why": "Preview only: rerun with explicit provider execution flag if advisor inference is intended.",
            },
            "genericity_warnings": ["No model was called; this is deterministic preview output."] + list(selection.get("blocked_reasons", [])),
            "missing_evidence": list(prompt_package.get("missing_evidence", [])),
            "risks": ["Advisor output has not been reviewed by a model."],
            "task_draft_improvements": ["Run with --local-model to request advisory critique of task specificity."],
            "do_not_use": list(LOCAL_ADVISOR_FORBIDDEN_RECOMMENDATIONS),
            "grounding_warnings": [],
            "_allowed_source_refs": sorted(_research_advisor_allowed_source_ids(prompt_package)),
            "_allowed_evidence_refs": sorted(_research_advisor_allowed_evidence_ids(prompt_package)),
        }
        model_used = False
    if compact_context is None:
        compact_context = collect_compact_source_aware_advisor_context(prompt_package, prompt_budget=prompt_budget)
        if prompt_hash == prompt_package["prompt_hash"]:
            prompt_hash = compact_context["prompt_hash"]
        prompt_chars = int(compact_context["estimated_prompt_chars"])
    source_refs_used = sorted({ref for item in normalized["patterns_found"] for ref in item.get("source_refs", [])}) or [item["source_ref_id"] for item in prompt_package["source_refs"][:1]]
    evidence_refs_used = sorted({ref for item in normalized["patterns_found"] for ref in item.get("evidence_refs", [])})
    model_metadata = collect_local_model_advisor_metadata(
        model_used=model_used,
        model_provider=provider_name if model_used else "none",
        model_name=(openrouter_config["model_name"] if provider_name == "openrouter" else config["model_name"]) if model_used else "none",
        model_endpoint_type=("external" if provider_name == "openrouter" else config["endpoint_type"]) if model_used else "none",
        prompt_hash=prompt_hash,
        response_hash=response_hash,
        source_refs_used=source_refs_used,
        evidence_refs_used=evidence_refs_used,
        latency_ms=latency_ms,
        valid_json=valid_json,
        metadata={
            "canonical_wrapper_path": boundary["canonical_wrapper_path"] if provider_name == "llamacpp" else "",
            "local_model_provider_boundary_id": boundary["local_model_provider_boundary_id"],
            "provider_selection_boundary_id": selection["advisor_provider_selection_boundary_id"],
            "selected_provider": provider_name,
            "external_fallback_allowed": False,
            "openrouter_fallback_allowed": False,
            "paid_call_possible": bool(provider_name == "openrouter"),
        },
    )
    review = {
        "local_model_research_advisor_review_version": LOCAL_MODEL_RESEARCH_ADVISOR_REVIEW_VERSION,
        "local_model_research_advisor_review_id": "local-model-research-advisor-review-" + _local_advisor_safe_hash({
            "prompt_package_id": prompt_package["research_advisor_prompt_package_id"],
            "model_used": model_used,
            "response_hash": response_hash,
            "version": LOCAL_MODEL_RESEARCH_ADVISOR_REVIEW_VERSION,
        }),
        "research_advisor_prompt_package_id": prompt_package["research_advisor_prompt_package_id"],
        "compact_context_id": compact_context["compact_source_aware_advisor_context_id"],
        "prompt_budget_id": prompt_budget["local_advisor_prompt_budget_id"],
        "prompt_hash": prompt_hash,
        "response_hash": response_hash,
        "prompt_chars": prompt_chars,
        "timeout_seconds": prompt_budget["timeout_seconds"],
        "fail_closed": fail_closed,
        "fail_closed_reason": fail_closed_reason,
        "local_model_latency_ms": latency_ms,
        "provider_selection_boundary_id": selection["advisor_provider_selection_boundary_id"],
        "selected_provider": provider_name,
        "local_model_provider_boundary_id": boundary["local_model_provider_boundary_id"],
        "canonical_wrapper_path": boundary["canonical_wrapper_path"] if provider_name == "llamacpp" else "",
        "external_call_used": bool(model_used and provider_name == "openrouter"),
        "paid_call_possible": bool(provider_name == "openrouter"),
        "fallback_allowed": False,
        "external_fallback_allowed": False,
        "openrouter_fallback_allowed": False,
        "research_target_intake_id": prompt_package["research_target_intake_id"],
        "research_target_evidence_bundle_id": prompt_package["research_target_evidence_bundle_id"],
        "source_path": prompt_package["source_path"],
        "source_name": prompt_package["source_name"],
        "advisor_status": advisor_status,
        "model_metadata": model_metadata,
        "patterns_found": normalized["patterns_found"],
        "upgrade_candidate_critiques": normalized["upgrade_candidate_critiques"],
        "best_upgrade_suggestion": normalized["best_upgrade_suggestion"],
        "genericity_warnings": normalized["genericity_warnings"],
        "missing_evidence": normalized["missing_evidence"],
        "risks": normalized["risks"],
        "task_draft_improvements": normalized["task_draft_improvements"],
        "do_not_use": normalized["do_not_use"],
        "grounding_warnings": normalized["grounding_warnings"],
        "recommended_next_action": "Review advisory findings manually; rerun with --local-model if this is preview-only." if not model_used else "Review grounded local advisor findings before changing deterministic Link plans.",
        "human_review_required": True,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
        "_allowed_source_refs": normalized["_allowed_source_refs"],
        "_allowed_evidence_refs": normalized["_allowed_evidence_refs"],
    }
    validate_local_model_research_advisor_review(review, prompt_package)
    review.pop("_allowed_source_refs", None)
    review.pop("_allowed_evidence_refs", None)
    return review


def validate_local_model_research_advisor_review(review: dict[str, Any], research_advisor_prompt_package: dict[str, Any] | None = None) -> None:
    required = (
        "local_model_research_advisor_review_version", "local_model_research_advisor_review_id",
        "research_advisor_prompt_package_id", "compact_context_id", "prompt_budget_id", "prompt_hash",
        "response_hash", "prompt_chars", "timeout_seconds", "fail_closed", "fail_closed_reason",
        "local_model_latency_ms", "provider_selection_boundary_id", "selected_provider",
        "local_model_provider_boundary_id", "canonical_wrapper_path", "external_call_used", "paid_call_possible",
        "fallback_allowed", "external_fallback_allowed", "openrouter_fallback_allowed", "research_target_intake_id", "source_path", "source_name",
        "advisor_status", "model_metadata", "patterns_found", "upgrade_candidate_critiques",
        "best_upgrade_suggestion", "genericity_warnings", "missing_evidence", "risks",
        "task_draft_improvements", "do_not_use", "grounding_warnings", "recommended_next_action",
        "human_review_required", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in review:
            raise ValueError(f"local model research advisor review missing field: {key}")
    if review["local_model_research_advisor_review_version"] != LOCAL_MODEL_RESEARCH_ADVISOR_REVIEW_VERSION:
        raise ValueError("invalid local model research advisor review version")
    if not review["local_model_research_advisor_review_id"].startswith("local-model-research-advisor-review-"):
        raise ValueError("invalid local model research advisor review id")
    if not review["source_path"].startswith("research/"):
        raise ValueError("local research advisor review source_path required")
    if review["selected_provider"] not in {"llamacpp", "openrouter"}:
        raise ValueError("local advisor review selected provider is invalid")
    if not str(review["compact_context_id"]).startswith("compact-source-aware-advisor-context-"):
        raise ValueError("local advisor review compact context id is invalid")
    if not str(review["prompt_budget_id"]).startswith("local-advisor-prompt-budget-"):
        raise ValueError("local advisor review prompt budget id is invalid")
    if not review["prompt_hash"]:
        raise ValueError("local advisor review prompt hash is required")
    if not isinstance(review["prompt_chars"], int) or review["prompt_chars"] <= 0 or review["prompt_chars"] > collect_local_advisor_prompt_budget()["max_prompt_chars"]:
        raise ValueError("local advisor review prompt chars must be positive and within budget")
    if not 30 <= int(review["timeout_seconds"]) <= 120:
        raise ValueError("local advisor review timeout must be bounded")
    if not isinstance(review["fail_closed"], bool):
        raise ValueError("local advisor review fail_closed must be boolean")
    if review["fail_closed"] is True and not review["fail_closed_reason"]:
        raise ValueError("local advisor review fail_closed must include reason")
    if review["fail_closed"] is False and review["advisor_status"] == "fail_closed":
        raise ValueError("local advisor review fail_closed status mismatch")
    if not isinstance(review["local_model_latency_ms"], int) or review["local_model_latency_ms"] < 0:
        raise ValueError("local advisor review latency must be non-negative")
    if review["selected_provider"] == "llamacpp" and review["canonical_wrapper_path"] != CANONICAL_LOCAL_MODEL_WRAPPER_PATH:
        raise ValueError("llamacpp advisor review must use canonical wrapper")
    if review["selected_provider"] == "openrouter" and review["external_call_used"] is True and review["model_metadata"]["model_provider"] != "openrouter":
        raise ValueError("OpenRouter advisor review must carry OpenRouter metadata")
    if review["fallback_allowed"] is not False or review["external_fallback_allowed"] is not False or review["openrouter_fallback_allowed"] is not False:
        raise ValueError("local advisor review must block fallback")
    validate_local_model_advisor_metadata(review["model_metadata"])
    for item in review["patterns_found"]:
        for key in ("pattern_name", "why_it_matters", "source_refs", "evidence_refs", "target_link_module", "risk", "confidence"):
            if key not in item:
                raise ValueError(f"local advisor pattern missing field: {key}")
        if item["target_link_module"] not in RESEARCH_TARGET_LINK_MODULES:
            raise ValueError("local advisor pattern target module is invalid")
        if item["risk"] not in {"low", "medium", "high"}:
            raise ValueError("local advisor pattern risk is invalid")
        if not isinstance(item["confidence"], int) or not 0 <= item["confidence"] <= 100:
            raise ValueError("local advisor pattern confidence must be 0..100")
    for item in review["upgrade_candidate_critiques"]:
        for key in ("upgrade_candidate_id", "critique", "source_grounding_status", "specificity_assessment", "missing_evidence", "confidence"):
            if key not in item:
                raise ValueError(f"local advisor critique missing field: {key}")
        if not isinstance(item["missing_evidence"], list):
            raise ValueError("local advisor critique missing_evidence must be a list")
        if not isinstance(item["confidence"], int) or not 0 <= item["confidence"] <= 100:
            raise ValueError("local advisor critique confidence must be 0..100")
    validate_local_model_research_grounding(review, research_advisor_prompt_package)
    if review["human_review_required"] is not True:
        raise ValueError("local advisor review must require human review")
    if review["safety_metadata"] != _read_only_safety_metadata() or review["dry_run"] is not True or review["write_allowed"] is not False or review["automation_allowed"] is not False or review["writes"] != []:
        raise ValueError("local advisor review must remain read-only")


def stable_local_model_research_advisor_review_json(review: dict[str, Any]) -> str:
    validate_local_model_research_advisor_review(review)
    return _stable_ruflo_json(review, indent=2) + "\n"


def parse_local_model_research_advisor_review_json(text: str) -> dict[str, Any]:
    import json as _json
    review = _json.loads(text)
    validate_local_model_research_advisor_review(review)
    return review


def collect_local_model_advisor_comparison_card(
    research_target_operator_report: dict[str, Any] | None = None,
    research_target_upgrade_rationale_card: dict[str, Any] | None = None,
    research_target_recommendation_specificity: dict[str, Any] | None = None,
    local_model_research_advisor_review: dict[str, Any] | None = None,
    *,
    source_path: str | None = None,
    use_local_model: bool = False,
    requested_provider: str | None = None,
    explicit_provider_flag: bool = False,
    openrouter_requested: bool = False,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if any(item is None for item in (research_target_operator_report, research_target_upgrade_rationale_card, research_target_recommendation_specificity, local_model_research_advisor_review)):
        context = build_source_aware_context_for_cli(str(source_path or ""))
        report = research_target_operator_report or collect_research_target_operator_report(source_path=str(source_path or ""), source_context=context)
        table = collect_research_target_provenance_table(context["research_target_intake"], context["research_target_evidence_bundle"], context["research_source_binding_context"])
        patterns = collect_research_target_pattern_summary(context["research_target_intake"], context["research_target_evidence_bundle"], table)
        rationale = research_target_upgrade_rationale_card or collect_research_target_upgrade_rationale_card(context["research_target_upgrade_candidates"], patterns, table, context["decision_chain"]["ranking"], context["decision_chain"]["trace"])
        specificity = research_target_recommendation_specificity or collect_research_target_recommendation_specificity(report, rationale, patterns, table, context["operator_chain"]["task_draft"])
        prompt_package = collect_research_advisor_prompt_package(context["research_target_intake"], context["research_target_evidence_bundle"], table, patterns, context["research_target_upgrade_candidates"], report, rationale, specificity)
        advisor = local_model_research_advisor_review or collect_local_model_research_advisor_review(
            prompt_package,
            use_local_model=use_local_model,
            requested_provider=requested_provider,
            explicit_provider_flag=explicit_provider_flag,
            openrouter_requested=openrouter_requested,
        )
    else:
        report = research_target_operator_report
        rationale = research_target_upgrade_rationale_card
        specificity = research_target_recommendation_specificity
        advisor = local_model_research_advisor_review
    validate_local_model_research_advisor_review(advisor)
    deterministic_id = report["selected_upgrade_candidate_id"]
    advisor_best = advisor["best_upgrade_suggestion"]
    if advisor["advisor_status"] in {"preview_only", "fail_closed"}:
        agreement = "advisor_unavailable" if advisor["advisor_status"] == "fail_closed" else "preview_only"
    else:
        agreement = "agrees" if advisor_best.get("upgrade_candidate_id") == deterministic_id else "differs"
    payload = {
        "local_model_advisor_comparison_card_version": LOCAL_MODEL_ADVISOR_COMPARISON_CARD_VERSION,
        "local_model_advisor_comparison_card_id": "local-model-advisor-comparison-card-" + _local_advisor_safe_hash({
            "source_path": report["source_path"],
            "deterministic": deterministic_id,
            "advisor_review": advisor["local_model_research_advisor_review_id"],
            "agreement": agreement,
            "version": LOCAL_MODEL_ADVISOR_COMPARISON_CARD_VERSION,
        }),
        "source_path": report["source_path"],
        "local_model_provider_boundary_id": advisor["local_model_provider_boundary_id"],
        "canonical_wrapper_path": advisor["canonical_wrapper_path"],
        "model_metadata": advisor["model_metadata"],
        "external_fallback_allowed": False,
        "openrouter_fallback_allowed": False,
        "research_target_intake_id": report["research_target_intake_id"],
        "deterministic_selected_upgrade_candidate_id": deterministic_id,
        "advisor_best_upgrade_title": advisor_best.get("title", ""),
        "agreement_status": agreement,
        "advisor_added_value": advisor["genericity_warnings"][:3] + advisor["task_draft_improvements"][:3] + (["local advisor failed closed; deterministic output remains authoritative"] if advisor["advisor_status"] == "fail_closed" else []),
        "advisor_risks": advisor["risks"][:5] + advisor["grounding_warnings"][:5],
        "deterministic_output_better_at": ["safety gates", "stable IDs", "source path validation", "approval status"],
        "local_model_output_better_at": ["semantic critique", "missing evidence suggestions", "human-readable rationale"] if advisor["model_metadata"]["model_used"] else [],
        "human_review_required": True,
        "recommended_next_action": "Use deterministic output as authority; use advisor comparison only as human-reviewed critique.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_local_model_advisor_comparison_card(payload)
    return payload


def validate_local_model_advisor_comparison_card(payload: dict[str, Any]) -> None:
    required = (
        "local_model_advisor_comparison_card_version", "local_model_advisor_comparison_card_id",
        "source_path", "local_model_provider_boundary_id", "canonical_wrapper_path", "model_metadata",
        "external_fallback_allowed", "openrouter_fallback_allowed", "deterministic_selected_upgrade_candidate_id", "advisor_best_upgrade_title",
        "agreement_status", "advisor_added_value", "advisor_risks", "deterministic_output_better_at",
        "local_model_output_better_at", "human_review_required", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"local model advisor comparison missing field: {key}")
    if payload["local_model_advisor_comparison_card_version"] != LOCAL_MODEL_ADVISOR_COMPARISON_CARD_VERSION:
        raise ValueError("invalid local model advisor comparison version")
    if not payload["local_model_advisor_comparison_card_id"].startswith("local-model-advisor-comparison-card-"):
        raise ValueError("invalid local model advisor comparison id")
    if payload["model_metadata"].get("model_provider") == "llamacpp" and payload["canonical_wrapper_path"] != CANONICAL_LOCAL_MODEL_WRAPPER_PATH:
        raise ValueError("llamacpp advisor comparison must use canonical wrapper path")
    if payload["model_metadata"].get("model_provider") == "openrouter" and payload["external_fallback_allowed"] is not False:
        raise ValueError("OpenRouter advisor comparison must still block fallback")
    if payload["external_fallback_allowed"] is not False or payload["openrouter_fallback_allowed"] is not False:
        raise ValueError("local advisor comparison must block external fallback")
    validate_local_model_advisor_metadata(payload["model_metadata"])
    if payload["agreement_status"] not in {"preview_only", "advisor_unavailable", "agrees", "differs"}:
        raise ValueError("invalid local advisor comparison agreement status")
    if payload["human_review_required"] is not True:
        raise ValueError("local advisor comparison requires human review")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("local advisor comparison must remain read-only")


def stable_local_model_advisor_comparison_card_json(payload: dict[str, Any]) -> str:
    validate_local_model_advisor_comparison_card(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_local_model_advisor_comparison_card_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_local_model_advisor_comparison_card(payload)
    return payload



def _source_aware_advisor_safe_command_source(source_path: str) -> str:
    return str(source_path).replace("\n", " ").strip()


def _source_aware_advisor_recommended_mode(local_status: str, local_available: bool, openrouter_enabled: bool) -> str:
    if local_available:
        return "local_advisor_available"
    if openrouter_enabled:
        return "openrouter_available_explicit_only"
    if local_status in {"configured", "unavailable"}:
        return "local_advisor_unavailable"
    if not openrouter_enabled:
        return "openrouter_disabled"
    return "advisor_unavailable"


def _source_aware_advisor_summary_fields(card: dict[str, Any]) -> dict[str, Any]:
    return {
        "advisor_provider_card_id": card["source_aware_advisor_provider_card_id"],
        "advisor_default_provider": card["default_provider"],
        "advisor_local_status": card["local_provider_status"],
        "advisor_local_endpoint_summary": card["local_endpoint_summary"],
        "advisor_openrouter_status": card["openrouter_status"],
        "advisor_review_available": card["advisor_review_available"],
        "recommended_advisor_mode": card["recommended_advisor_mode"],
        "recommended_advisor_command": card["recommended_advisor_command"],
        "advisor_fallback_allowed": card["fallback_allowed"],
    }


def collect_source_aware_advisor_provider_card(
    *,
    source_path: str,
    metadata: dict[str, Any] | None = None,
    dashboard_context: dict[str, Any] | None = None,
    operator_report: dict[str, Any] | None = None,
) -> dict[str, Any]:
    context = dashboard_context
    if operator_report is None:
        if context is None:
            context = build_source_aware_sandbox_context_for_cli(source_path)
        operator_report = context["operator_report"]
    report = operator_report
    validate_research_target_operator_report(report)
    registry = collect_advisor_provider_registry()
    local = collect_local_advisor_availability_card()
    openrouter = collect_openrouter_advisor_readiness_card()
    dashboard = collect_advisor_provider_status_dashboard()
    guidance = collect_advisor_provider_operator_guidance()
    local_available = local["provider_status"] == "reachable"
    openrouter_enabled = bool(openrouter["enabled_for_advisor"])
    recommended_mode = _source_aware_advisor_recommended_mode(local["provider_status"], local_available, openrouter_enabled)
    source_arg = _source_aware_advisor_safe_command_source(report["source_path"])
    deterministic_command = f"python3 link.py research advisor-review --source {source_arg} --json"
    ref_alias_map_command = f"python3 link.py advisor ref-alias-map --source {source_arg} --json"
    micro_diagnostic_command = f"python3 link.py advisor micro-diagnostic --source {source_arg} --local-model --json"
    micro_stage_commands = [
        f"python3 link.py advisor micro-check --source {source_arg} --stage {stage} --local-model --json"
        for stage in range(4)
    ]
    json_check_command = f"python3 link.py advisor json-check --source {source_arg} --local-model --json"
    two_stage_command = f"python3 link.py research advisor-two-stage --source {source_arg} --local-model --json"
    diagnostic_command = f"python3 link.py advisor local-json-diagnostic --source {source_arg} --local-model --json"
    local_command = f"python3 link.py research advisor-review --source {source_arg} --provider llamacpp --local-model --json"
    openrouter_command = f"python3 link.py research advisor-review --source {source_arg} --provider openrouter --openrouter --json"
    if local_available:
        recommended_command = two_stage_command
    else:
        recommended_command = deterministic_command
    blocked = _normalize_implementation_branch_refs(list(local["blocked_reasons"]) + list(openrouter["blocked_reasons"]))
    warnings = _normalize_implementation_branch_refs([
        "No advisor model call was made for this source-aware dashboard.",
        "OpenRouter is external, paid, explicit-only, and never fallback.",
        "Run local-smoke only after starting the local llama.cpp server.",
    ])
    if openrouter_enabled:
        warnings.append("OpenRouter appears enabled but still requires explicit --openrouter for any future call.")
    payload = {
        "source_aware_advisor_provider_card_version": SOURCE_AWARE_ADVISOR_PROVIDER_CARD_VERSION,
        "source_aware_advisor_provider_card_id": _source_aware_hash_id("source-aware-advisor-provider-card", {
            "source_path": report["source_path"],
            "research_target_intake_id": report["research_target_intake_id"],
            "selected_upgrade_candidate_id": report["selected_upgrade_candidate_id"],
            "registry_id": registry["advisor_provider_registry_id"],
            "local_status_id": local["local_advisor_availability_card_id"],
            "openrouter_status_id": openrouter["openrouter_advisor_readiness_card_id"],
            "dashboard_id": dashboard["advisor_provider_status_dashboard_id"],
            "guidance_id": guidance["advisor_provider_operator_guidance_id"],
            "version": SOURCE_AWARE_ADVISOR_PROVIDER_CARD_VERSION,
        }),
        "source_bound": True,
        "source_path": report["source_path"],
        "source_name": report["source_name"],
        "source_type": report["source_type"],
        "research_target_intake_id": report["research_target_intake_id"],
        "selected_upgrade_candidate_id": report["selected_upgrade_candidate_id"],
        "default_provider": registry["default_provider"],
        "local_provider_status": local["provider_status"],
        "local_endpoint_summary": local["endpoint_summary"],
        "local_model_name": local["model_name"],
        "local_available": local_available,
        "openrouter_status": "enabled" if openrouter_enabled else "disabled",
        "openrouter_enabled": openrouter_enabled,
        "openrouter_opt_in_required": openrouter["opt_in_required"],
        "openrouter_key_present": bool(openrouter["api_key_present"]),
        "paid_provider_warning": "OpenRouter is paid/external and explicit-only; no fallback is allowed.",
        "fallback_allowed": False,
        "advisor_review_available": local_available or openrouter_enabled,
        "recommended_advisor_mode": recommended_mode,
        "recommended_advisor_command": recommended_command,
        "deterministic_preview_command": deterministic_command,
        "local_advisor_command": local_command,
        "ref_alias_map_command": ref_alias_map_command,
        "alias_aware_micro_diagnostic_command": micro_diagnostic_command,
        "recommended_alias_tuning_note": "Stages 2/3 use S#/E# aliases; Link expands aliases back to full refs deterministically.",
        "recommended_micro_diagnostic_command": micro_diagnostic_command,
        "recommended_micro_stage_commands": micro_stage_commands,
        "recommended_json_check_command": json_check_command,
        "recommended_two_stage_local_command": two_stage_command,
        "recommended_two_stage_command": two_stage_command,
        "recommended_diagnostic_command": diagnostic_command,
        "richer_advisor_command": local_command,
        "recommended_rich_review_command": local_command,
        "openrouter_advisor_command": openrouter_command,
        "advisor_provider_registry_id": registry["advisor_provider_registry_id"],
        "local_advisor_availability_card_id": local["local_advisor_availability_card_id"],
        "openrouter_advisor_readiness_card_id": openrouter["openrouter_advisor_readiness_card_id"],
        "advisor_provider_status_dashboard_id": dashboard["advisor_provider_status_dashboard_id"],
        "advisor_provider_operator_guidance_id": guidance["advisor_provider_operator_guidance_id"],
        "blocked_reasons": blocked or ["local advisor endpoint was not probed; use deterministic advisor preview until local smoke passes"],
        "warnings": warnings,
        "recommended_next_action": "Use deterministic advisor preview now; run micro-diagnostic before local JSON check or richer advisor review.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_source_aware_advisor_provider_card(payload)
    return payload


def validate_source_aware_advisor_provider_card(payload: dict[str, Any]) -> None:
    required = (
        "source_aware_advisor_provider_card_version", "source_aware_advisor_provider_card_id",
        "source_bound", "source_path", "source_name", "source_type", "research_target_intake_id",
        "selected_upgrade_candidate_id", "default_provider", "local_provider_status", "local_endpoint_summary",
        "local_model_name", "local_available", "openrouter_status", "openrouter_enabled",
        "openrouter_opt_in_required", "openrouter_key_present", "paid_provider_warning",
        "fallback_allowed", "advisor_review_available", "recommended_advisor_mode",
        "recommended_advisor_command", "blocked_reasons", "warnings", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"source-aware advisor provider card missing field: {key}")
    if payload["source_aware_advisor_provider_card_version"] != SOURCE_AWARE_ADVISOR_PROVIDER_CARD_VERSION:
        raise ValueError("invalid source-aware advisor provider card version")
    if not payload["source_aware_advisor_provider_card_id"].startswith("source-aware-advisor-provider-card-"):
        raise ValueError("invalid source-aware advisor provider card id")
    if payload["source_bound"] is not True or not payload["source_path"]:
        raise ValueError("source-aware advisor provider card must be source-bound")
    if payload["default_provider"] != "llamacpp":
        raise ValueError("source-aware advisor provider card must preserve llamacpp default")
    if payload["fallback_allowed"] is not False:
        raise ValueError("source-aware advisor provider card must disable fallback")
    if payload["recommended_advisor_mode"] not in {"deterministic_only", "local_advisor_available", "local_advisor_unavailable", "openrouter_disabled", "openrouter_available_explicit_only", "advisor_unavailable"}:
        raise ValueError("invalid recommended advisor mode")
    if not isinstance(payload["openrouter_key_present"], bool):
        raise ValueError("OpenRouter key presence must be boolean only")
    if not isinstance(payload["blocked_reasons"], list) or not payload["blocked_reasons"]:
        raise ValueError("source-aware advisor card blocked reasons must be non-empty")
    if not isinstance(payload["warnings"], list) or not payload["warnings"]:
        raise ValueError("source-aware advisor card warnings must be non-empty")
    text = _stable_ruflo_json(payload).lower()
    if "sk-" in text or "bearer " in text:
        raise ValueError("source-aware advisor provider card must not expose secrets")
    if payload["safety_metadata"] != _read_only_safety_metadata() or payload["dry_run"] is not True or payload["write_allowed"] is not False or payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("source-aware advisor provider card must remain read-only")


def stable_source_aware_advisor_provider_card_json(payload: dict[str, Any]) -> str:
    validate_source_aware_advisor_provider_card(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_source_aware_advisor_provider_card_json(text: str) -> dict[str, Any]:
    import json as _json
    payload = _json.loads(text)
    validate_source_aware_advisor_provider_card(payload)
    return payload



