def make_control_plane_status_summary_id(
    control_plane_dashboard: dict[str, Any],
    control_plane_health_package: dict[str, Any],
    control_plane_review_package: dict[str, Any],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "control_plane_dashboard_id": control_plane_dashboard["control_plane_dashboard_id"],
        "control_plane_health_package_id": control_plane_health_package["control_plane_health_package_id"],
        "control_plane_review_package_id": control_plane_review_package["control_plane_review_package_id"],
        "version": CONTROL_PLANE_STATUS_SUMMARY_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"control-plane-status-summary-{digest}"


def collect_control_plane_status_summary(
    control_plane_dashboard: dict[str, Any] | None = None,
    control_plane_health_package: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Compress the whole control plane into a compact operator status object."""
    dashboard = control_plane_dashboard or collect_link_control_plane_dashboard()
    validate_link_control_plane_dashboard(dashboard)
    health = control_plane_health_package or collect_control_plane_health_package(dashboard)
    validate_control_plane_health_package(health, control_plane_dashboard=dashboard)
    review = control_plane_review_package or collect_control_plane_review_package(dashboard, health_package=health)
    validate_control_plane_review_package(review, control_plane_dashboard=dashboard, health_package=health)
    summary = {
        "control_plane_status_summary_version": CONTROL_PLANE_STATUS_SUMMARY_VERSION,
        "control_plane_status_summary_id": make_control_plane_status_summary_id(dashboard, health, review),
        "control_plane_dashboard_id": dashboard["control_plane_dashboard_id"],
        "control_plane_health_package_id": health["control_plane_health_package_id"],
        "control_plane_review_package_id": review["control_plane_review_package_id"],
        "overall_status": "block" if review["review_recommendation"] == "resolve_blockers" else ("review" if review["warnings"] else "pass"),
        "health_status": health["health_status"],
        "readiness_status": dashboard["readiness_status"],
        "blocker_count": len(review["blockers"]),
        "warning_count": len(review["warnings"]),
        "recommended_next_action": review["recommended_next_action"],
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_control_plane_status_summary(summary, dashboard, health, review)
    return summary


def validate_control_plane_status_summary(
    summary: dict[str, Any],
    control_plane_dashboard: dict[str, Any] | None = None,
    control_plane_health_package: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
) -> None:
    required = (
        "control_plane_status_summary_version", "control_plane_status_summary_id",
        "control_plane_dashboard_id", "control_plane_health_package_id",
        "control_plane_review_package_id", "overall_status", "health_status",
        "readiness_status", "blocker_count", "warning_count", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in summary:
            raise ValueError(f"control-plane status summary missing required field: {key}")
    if summary["control_plane_status_summary_version"] != CONTROL_PLANE_STATUS_SUMMARY_VERSION:
        raise ValueError("invalid control-plane status summary version")
    if not isinstance(summary["control_plane_status_summary_id"], str) or not summary["control_plane_status_summary_id"].startswith("control-plane-status-summary-"):
        raise ValueError("invalid control-plane status summary id")
    if summary["overall_status"] not in CONTROL_PLANE_STATUSES:
        raise ValueError("invalid control-plane status summary overall status")
    if summary["health_status"] not in CONTROL_PLANE_STATUSES:
        raise ValueError("invalid control-plane status summary health status")
    if summary["readiness_status"] not in GOVERNANCE_OVERALL_STATUSES:
        raise ValueError("invalid control-plane status summary readiness status")
    for field in ("blocker_count", "warning_count"):
        if not isinstance(summary[field], int) or summary[field] < 0:
            raise ValueError(f"control-plane status summary {field} must be non-negative")
    if summary["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("control-plane status summary safety metadata mismatch")
    if summary["dry_run"] is not True or summary["write_allowed"] is not False:
        raise ValueError("control-plane status summary must be read-only")
    if summary["automation_allowed"] is not False or summary["writes"] != []:
        raise ValueError("control-plane status summary must not allow automation or writes")
    if all(item is not None for item in (control_plane_dashboard, control_plane_health_package, control_plane_review_package)):
        expected_id = make_control_plane_status_summary_id(control_plane_dashboard, control_plane_health_package, control_plane_review_package)
        if summary["control_plane_status_summary_id"] != expected_id:
            raise ValueError("control-plane status summary id is not deterministic")


def stable_control_plane_status_summary_json(summary: dict[str, Any]) -> str:
    validate_control_plane_status_summary(summary)
    return _stable_ruflo_json(summary, indent=2) + "\n"


def parse_control_plane_status_summary_json(text: str) -> dict[str, Any]:
    import json as _json

    summary = _json.loads(text)
    validate_control_plane_status_summary(summary)
    return summary


def make_stale_artifact_report_id(control_plane_dashboard: dict[str, Any], control_plane_review_package: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "control_plane_dashboard_id": control_plane_dashboard["control_plane_dashboard_id"],
        "control_plane_review_package_id": control_plane_review_package["control_plane_review_package_id"],
        "version": STALE_ARTIFACT_REPORT_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"stale-artifact-report-{digest}"


def collect_stale_artifact_report(
    control_plane_dashboard: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Report stale generated dashboard/review artifacts without reading runtime state."""
    dashboard = control_plane_dashboard or collect_link_control_plane_dashboard()
    validate_link_control_plane_dashboard(dashboard)
    review = control_plane_review_package or collect_control_plane_review_package(dashboard)
    validate_control_plane_review_package(review, control_plane_dashboard=dashboard)
    stale_items = [
        {
            "artifact_id": dashboard["control_plane_dashboard_id"],
            "artifact_type": "control_plane_dashboard",
            "stale_reason": "live generated; no persisted freshness receipt",
            "recommended_refresh": "refresh control-plane dashboard before operator review",
        },
        {
            "artifact_id": review["control_plane_review_package_id"],
            "artifact_type": "control_plane_review_package",
            "stale_reason": "live generated; no persisted operator acknowledgement",
            "recommended_refresh": "refresh control-plane review before prioritizing runtime work",
        },
        {
            "artifact_id": dashboard["governance_executive_review_package_id"],
            "artifact_type": "governance_executive_review_package",
            "stale_reason": "upstream governance package should be refreshed with control-plane status",
            "recommended_refresh": "refresh governance review after operator UX changes",
        },
    ]
    recommended = _normalize_implementation_branch_refs([item["recommended_refresh"] for item in stale_items])
    report = {
        "stale_artifact_report_version": STALE_ARTIFACT_REPORT_VERSION,
        "stale_artifact_report_id": make_stale_artifact_report_id(dashboard, review),
        "control_plane_dashboard_id": dashboard["control_plane_dashboard_id"],
        "control_plane_review_package_id": review["control_plane_review_package_id"],
        "stale_items": stale_items,
        "warning_count": len(stale_items),
        "recommended_refreshes": recommended,
        "recommended_next_action": "Refresh stale generated summaries before using them as operator decision evidence.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_stale_artifact_report(report, dashboard, review)
    return report


def validate_stale_artifact_report(
    report: dict[str, Any],
    control_plane_dashboard: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
) -> None:
    required = (
        "stale_artifact_report_version", "stale_artifact_report_id",
        "control_plane_dashboard_id", "control_plane_review_package_id", "stale_items",
        "warning_count", "recommended_refreshes", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in report:
            raise ValueError(f"stale artifact report missing required field: {key}")
    if report["stale_artifact_report_version"] != STALE_ARTIFACT_REPORT_VERSION:
        raise ValueError("invalid stale artifact report version")
    if not isinstance(report["stale_artifact_report_id"], str) or not report["stale_artifact_report_id"].startswith("stale-artifact-report-"):
        raise ValueError("invalid stale artifact report id")
    if not isinstance(report["stale_items"], list) or not report["stale_items"]:
        raise ValueError("stale artifact report stale_items must be non-empty")
    for item in report["stale_items"]:
        if not isinstance(item, dict):
            raise TypeError("stale artifact item must be a dict")
        for field in ("artifact_id", "artifact_type", "stale_reason", "recommended_refresh"):
            if field not in item or not isinstance(item[field], str) or not item[field].strip():
                raise ValueError(f"stale artifact item missing valid {field}")
    if report["warning_count"] != len(report["stale_items"]):
        raise ValueError("stale artifact warning_count must match stale_items")
    if _normalize_implementation_branch_refs(report["recommended_refreshes"]) != report["recommended_refreshes"]:
        raise ValueError("stale artifact recommended_refreshes must be normalized and sorted")
    if report["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("stale artifact report safety metadata mismatch")
    if report["dry_run"] is not True or report["write_allowed"] is not False:
        raise ValueError("stale artifact report must be read-only")
    if report["automation_allowed"] is not False or report["writes"] != []:
        raise ValueError("stale artifact report must not allow automation or writes")
    if control_plane_dashboard is not None:
        validate_link_control_plane_dashboard(control_plane_dashboard)
        if report["control_plane_dashboard_id"] != control_plane_dashboard["control_plane_dashboard_id"]:
            raise ValueError("stale artifact report dashboard id mismatch")
    if control_plane_review_package is not None:
        validate_control_plane_review_package(control_plane_review_package)
        if report["control_plane_review_package_id"] != control_plane_review_package["control_plane_review_package_id"]:
            raise ValueError("stale artifact report review id mismatch")
    if control_plane_dashboard is not None and control_plane_review_package is not None:
        expected_id = make_stale_artifact_report_id(control_plane_dashboard, control_plane_review_package)
        if report["stale_artifact_report_id"] != expected_id:
            raise ValueError("stale artifact report id is not deterministic")


def stable_stale_artifact_report_json(report: dict[str, Any]) -> str:
    validate_stale_artifact_report(report)
    return _stable_ruflo_json(report, indent=2) + "\n"


def parse_stale_artifact_report_json(text: str) -> dict[str, Any]:
    import json as _json

    report = _json.loads(text)
    validate_stale_artifact_report(report)
    return report


def make_operator_cards_id(control_plane_dashboard: dict[str, Any], control_plane_review_package: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "control_plane_dashboard_id": control_plane_dashboard["control_plane_dashboard_id"],
        "control_plane_review_package_id": control_plane_review_package["control_plane_review_package_id"],
        "lanes": list(OPERATOR_LANE_IDS),
        "version": OPERATOR_CARDS_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-cards-{digest}"


def _operator_lane_status(control_plane_dashboard: dict[str, Any], lane_id: str) -> str:
    for item in control_plane_dashboard["module_statuses"]:
        if item["module_id"] == lane_id:
            status = item["status"]
            return "block" if status == "blocked" else status
    return "review"


def collect_operator_cards(
    control_plane_dashboard: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Create concise operator cards for the main Link lanes."""
    dashboard = control_plane_dashboard or collect_link_control_plane_dashboard()
    validate_link_control_plane_dashboard(dashboard)
    review = control_plane_review_package or collect_control_plane_review_package(dashboard)
    validate_control_plane_review_package(review, control_plane_dashboard=dashboard)
    labels = {
        "engineering": "Engineering",
        "growth": "Growth",
        "business_development": "Business Development",
        "business_operations": "Business Operations",
    }
    cards = []
    for lane_id in OPERATOR_LANE_IDS:
        status = _operator_lane_status(dashboard, lane_id)
        lane_blockers = [item for item in review["blockers"] if lane_id.replace("_", " ") in item.lower() or lane_id.split("_")[0] in item.lower()]
        lane_warnings = [item for item in review["warnings"] if lane_id.replace("_", " ") in item.lower() or lane_id.split("_")[0] in item.lower()]
        if not lane_blockers and status == "block":
            lane_blockers = [f"{labels[lane_id]} lane has unresolved control-plane blockers"]
        cards.append({
            "card_id": f"operator-card-{lane_id}",
            "lane_id": lane_id,
            "title": labels[lane_id],
            "status": status,
            "blocker_count": len(lane_blockers),
            "warning_count": len(lane_warnings),
            "recommended_next_action": f"Review {labels[lane_id]} blockers and warnings before operator approval.",
        })
    blockers = _normalize_implementation_branch_refs(list(review["blockers"]))
    warnings = _normalize_implementation_branch_refs(list(review["warnings"]))
    actions = _normalize_implementation_branch_refs([card["recommended_next_action"] for card in cards])
    payload = {
        "operator_cards_version": OPERATOR_CARDS_VERSION,
        "operator_cards_id": make_operator_cards_id(dashboard, review),
        "control_plane_dashboard_id": dashboard["control_plane_dashboard_id"],
        "control_plane_review_package_id": review["control_plane_review_package_id"],
        "cards": cards,
        "blockers": blockers,
        "warnings": warnings,
        "recommended_next_actions": actions,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_cards(payload, dashboard, review)
    return payload


def validate_operator_cards(
    payload: dict[str, Any],
    control_plane_dashboard: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
) -> None:
    required = (
        "operator_cards_version", "operator_cards_id", "control_plane_dashboard_id",
        "control_plane_review_package_id", "cards", "blockers", "warnings",
        "recommended_next_actions", "safety_metadata", "dry_run", "write_allowed",
        "automation_allowed", "writes",
    )
    for key in required:
        if key not in payload:
            raise ValueError(f"operator cards missing required field: {key}")
    if payload["operator_cards_version"] != OPERATOR_CARDS_VERSION:
        raise ValueError("invalid operator cards version")
    if not isinstance(payload["operator_cards_id"], str) or not payload["operator_cards_id"].startswith("operator-cards-"):
        raise ValueError("invalid operator cards id")
    if not isinstance(payload["cards"], list) or len(payload["cards"]) != len(OPERATOR_LANE_IDS):
        raise ValueError("operator cards must include all operator lanes")
    seen: set[str] = set()
    for card in payload["cards"]:
        if not isinstance(card, dict):
            raise TypeError("operator card must be a dict")
        for field in ("card_id", "lane_id", "title", "status", "blocker_count", "warning_count", "recommended_next_action"):
            if field not in card:
                raise ValueError(f"operator card missing {field}")
        if card["lane_id"] not in OPERATOR_LANE_IDS or card["lane_id"] in seen:
            raise ValueError("invalid or duplicate operator card lane")
        seen.add(card["lane_id"])
        if card["status"] not in CONTROL_PLANE_STATUSES:
            raise ValueError("invalid operator card status")
        for field in ("blocker_count", "warning_count"):
            if not isinstance(card[field], int) or card[field] < 0:
                raise ValueError(f"operator card {field} must be non-negative")
    for field in ("blockers", "warnings", "recommended_next_actions"):
        normalized = _normalize_implementation_branch_refs(payload[field])
        if normalized != payload[field]:
            raise ValueError(f"operator cards {field} must be normalized and sorted")
    if payload["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("operator cards safety metadata mismatch")
    if payload["dry_run"] is not True or payload["write_allowed"] is not False:
        raise ValueError("operator cards must be read-only")
    if payload["automation_allowed"] is not False or payload["writes"] != []:
        raise ValueError("operator cards must not allow automation or writes")
    if control_plane_dashboard is not None:
        validate_link_control_plane_dashboard(control_plane_dashboard)
        if payload["control_plane_dashboard_id"] != control_plane_dashboard["control_plane_dashboard_id"]:
            raise ValueError("operator cards dashboard id mismatch")
    if control_plane_review_package is not None:
        validate_control_plane_review_package(control_plane_review_package)
        if payload["control_plane_review_package_id"] != control_plane_review_package["control_plane_review_package_id"]:
            raise ValueError("operator cards review id mismatch")
    if control_plane_dashboard is not None and control_plane_review_package is not None:
        expected_id = make_operator_cards_id(control_plane_dashboard, control_plane_review_package)
        if payload["operator_cards_id"] != expected_id:
            raise ValueError("operator cards id is not deterministic")


def stable_operator_cards_json(payload: dict[str, Any]) -> str:
    validate_operator_cards(payload)
    return _stable_ruflo_json(payload, indent=2) + "\n"


def parse_operator_cards_json(text: str) -> dict[str, Any]:
    import json as _json

    payload = _json.loads(text)
    validate_operator_cards(payload)
    return payload


def make_operator_status_package_id(
    status_summary: dict[str, Any],
    stale_artifact_report: dict[str, Any],
    operator_cards: dict[str, Any],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "control_plane_status_summary_id": status_summary["control_plane_status_summary_id"],
        "operator_cards_id": operator_cards["operator_cards_id"],
        "stale_artifact_report_id": stale_artifact_report["stale_artifact_report_id"],
        "version": OPERATOR_STATUS_PACKAGE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-status-package-{digest}"


def collect_operator_status_package(
    control_plane_status_summary: dict[str, Any] | None = None,
    stale_artifact_report: dict[str, Any] | None = None,
    operator_cards: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Aggregate the compact operator status surface for Link."""
    if control_plane_status_summary is None or stale_artifact_report is None or operator_cards is None:
        dashboard = collect_link_control_plane_dashboard()
        health = collect_control_plane_health_package(dashboard)
        review = collect_control_plane_review_package(dashboard, health_package=health)
    summary = control_plane_status_summary or collect_control_plane_status_summary(dashboard, health, review)
    validate_control_plane_status_summary(summary)
    stale = stale_artifact_report or collect_stale_artifact_report(dashboard, review)
    validate_stale_artifact_report(stale)
    cards = operator_cards or collect_operator_cards(dashboard, review)
    validate_operator_cards(cards)
    blockers = _normalize_implementation_branch_refs(list(cards["blockers"]))
    warnings = _normalize_implementation_branch_refs(list(cards["warnings"]) + list(stale["recommended_refreshes"]))
    actions = _normalize_implementation_branch_refs(list(cards["recommended_next_actions"]) + [summary["recommended_next_action"], stale["recommended_next_action"]])
    package = {
        "operator_status_package_version": OPERATOR_STATUS_PACKAGE_VERSION,
        "operator_status_package_id": make_operator_status_package_id(summary, stale, cards),
        "control_plane_status_summary_id": summary["control_plane_status_summary_id"],
        "stale_artifact_report_id": stale["stale_artifact_report_id"],
        "operator_cards_id": cards["operator_cards_id"],
        "overall_status": summary["overall_status"],
        "blockers": blockers,
        "warnings": warnings,
        "stale_items": list(stale["stale_items"]),
        "recommended_next_actions": actions,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_status_package(package, summary, stale, cards)
    return package


def validate_operator_status_package(
    package: dict[str, Any],
    control_plane_status_summary: dict[str, Any] | None = None,
    stale_artifact_report: dict[str, Any] | None = None,
    operator_cards: dict[str, Any] | None = None,
) -> None:
    required = (
        "operator_status_package_version", "operator_status_package_id",
        "control_plane_status_summary_id", "stale_artifact_report_id", "operator_cards_id",
        "overall_status", "blockers", "warnings", "stale_items", "recommended_next_actions",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in package:
            raise ValueError(f"operator status package missing required field: {key}")
    if package["operator_status_package_version"] != OPERATOR_STATUS_PACKAGE_VERSION:
        raise ValueError("invalid operator status package version")
    if not isinstance(package["operator_status_package_id"], str) or not package["operator_status_package_id"].startswith("operator-status-package-"):
        raise ValueError("invalid operator status package id")
    if package["overall_status"] not in CONTROL_PLANE_STATUSES:
        raise ValueError("invalid operator status package overall status")
    if not isinstance(package["stale_items"], list):
        raise ValueError("operator status package stale_items must be a list")
    for field in ("blockers", "warnings", "recommended_next_actions"):
        normalized = _normalize_implementation_branch_refs(package[field])
        if normalized != package[field]:
            raise ValueError(f"operator status package {field} must be normalized and sorted")
    if package["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("operator status package safety metadata mismatch")
    if package["dry_run"] is not True or package["write_allowed"] is not False:
        raise ValueError("operator status package must be read-only")
    if package["automation_allowed"] is not False or package["writes"] != []:
        raise ValueError("operator status package must not allow automation or writes")
    if control_plane_status_summary is not None:
        validate_control_plane_status_summary(control_plane_status_summary)
        if package["control_plane_status_summary_id"] != control_plane_status_summary["control_plane_status_summary_id"]:
            raise ValueError("operator status package summary id mismatch")
    if stale_artifact_report is not None:
        validate_stale_artifact_report(stale_artifact_report)
        if package["stale_artifact_report_id"] != stale_artifact_report["stale_artifact_report_id"]:
            raise ValueError("operator status package stale report id mismatch")
    if operator_cards is not None:
        validate_operator_cards(operator_cards)
        if package["operator_cards_id"] != operator_cards["operator_cards_id"]:
            raise ValueError("operator status package cards id mismatch")
    if control_plane_status_summary is not None and stale_artifact_report is not None and operator_cards is not None:
        expected_id = make_operator_status_package_id(control_plane_status_summary, stale_artifact_report, operator_cards)
        if package["operator_status_package_id"] != expected_id:
            raise ValueError("operator status package id is not deterministic")


def stable_operator_status_package_json(package: dict[str, Any]) -> str:
    validate_operator_status_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_operator_status_package_json(text: str) -> dict[str, Any]:
    import json as _json

    package = _json.loads(text)
    validate_operator_status_package(package)
    return package


def make_business_execution_simulation_plan_id(
    business_execution_review_package: dict[str, Any],
    business_readiness_review_package: dict[str, Any],
    governance_executive_review_package: dict[str, Any],
    control_plane_review_package: dict[str, Any],
    module_boundary_registry: dict[str, Any],
    shared_services_registry: dict[str, Any],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "business_execution_review_package_id": business_execution_review_package["business_execution_review_package_id"],
        "business_readiness_review_package_id": business_readiness_review_package["business_readiness_review_package_id"],
        "control_plane_review_package_id": control_plane_review_package["control_plane_review_package_id"],
        "governance_executive_review_package_id": governance_executive_review_package["governance_executive_review_package_id"],
        "link_module_boundary_registry_id": module_boundary_registry["link_module_boundary_registry_id"],
        "shared_services_registry_id": shared_services_registry["shared_services_registry_id"],
        "version": BUSINESS_EXECUTION_SIMULATION_PLAN_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"business-execution-simulation-plan-{digest}"


def _business_execution_simulated_step_records() -> list[dict[str, Any]]:
    return [
        {
            "step_id": f"simulation-step-{index:02d}",
            "step_name": step,
            "simulation_only": True,
            "real_action_allowed": False,
        }
        for index, step in enumerate(BUSINESS_EXECUTION_SIMULATED_STEPS, start=1)
    ]


def collect_business_execution_simulation_plan(
    business_execution_review_package: dict[str, Any] | None = None,
    business_readiness_review_package: dict[str, Any] | None = None,
    governance_executive_review_package: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
    module_boundary_registry: dict[str, Any] | None = None,
    shared_services_registry: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Preview a fully simulated business execution path without real action."""
    registry = module_boundary_registry or collect_link_module_boundary_registry()
    validate_link_module_boundary_registry(registry)
    services = shared_services_registry or collect_link_shared_services_registry()
    validate_link_shared_services_registry(services)
    readiness = business_readiness_review_package or collect_business_readiness_review_package()
    validate_business_readiness_review_package(readiness)
    execution_review = business_execution_review_package or collect_business_execution_review_package(business_readiness_review_package=readiness)
    validate_business_execution_review_package(execution_review)
    governance_review = governance_executive_review_package or collect_governance_executive_review_package()
    validate_governance_executive_review_package(governance_review)
    control_review = control_plane_review_package or collect_control_plane_review_package()
    validate_control_plane_review_package(control_review)
    required_inputs = _normalize_implementation_branch_refs([
        execution_review["business_execution_review_package_id"],
        readiness["business_readiness_review_package_id"],
        governance_review["governance_executive_review_package_id"],
        control_review["control_plane_review_package_id"],
        registry["link_module_boundary_registry_id"],
        services["shared_services_registry_id"],
    ])
    expected_outputs = _normalize_implementation_branch_refs([
        "simulated execution path validation",
        "simulated evidence requirement inventory",
        "simulated blocked real action report",
        "simulated operator review summary",
    ])
    expected_artifacts = _normalize_implementation_branch_refs([
        "simulation evidence package",
        "simulation review",
        "simulation readiness check",
    ])
    assumptions = _normalize_implementation_branch_refs([
        "simulation does not contact external parties",
        "simulation does not collect live market or customer data",
        "simulation does not create campaigns or business records",
        "simulation uses existing governance payloads as inputs",
    ])
    plan = {
        "business_execution_simulation_plan_version": BUSINESS_EXECUTION_SIMULATION_PLAN_VERSION,
        "business_execution_simulation_plan_id": make_business_execution_simulation_plan_id(execution_review, readiness, governance_review, control_review, registry, services),
        "business_execution_review_package_id": execution_review["business_execution_review_package_id"],
        "readiness_review_package_id": readiness["business_readiness_review_package_id"],
        "governance_executive_review_package_id": governance_review["governance_executive_review_package_id"],
        "control_plane_review_package_id": control_review["control_plane_review_package_id"],
        "link_module_boundary_registry_id": registry["link_module_boundary_registry_id"],
        "shared_services_registry_id": services["shared_services_registry_id"],
        "simulated_steps": _business_execution_simulated_step_records(),
        "required_inputs": required_inputs,
        "expected_outputs": expected_outputs,
        "expected_artifacts": expected_artifacts,
        "blocked_real_actions": list(BUSINESS_EXECUTION_SIMULATION_BLOCKED_REAL_ACTIONS),
        "assumptions": assumptions,
        "recommended_next_action": "Review simulation blockers before designing any real business execution runtime.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_business_execution_simulation_plan(plan, execution_review, readiness, governance_review, control_review, registry, services)
    return plan


def validate_business_execution_simulation_plan(
    plan: dict[str, Any],
    business_execution_review_package: dict[str, Any] | None = None,
    business_readiness_review_package: dict[str, Any] | None = None,
    governance_executive_review_package: dict[str, Any] | None = None,
    control_plane_review_package: dict[str, Any] | None = None,
    module_boundary_registry: dict[str, Any] | None = None,
    shared_services_registry: dict[str, Any] | None = None,
) -> None:
    required = (
        "business_execution_simulation_plan_version", "business_execution_simulation_plan_id",
        "business_execution_review_package_id", "readiness_review_package_id",
        "simulated_steps", "required_inputs", "expected_outputs", "expected_artifacts",
        "blocked_real_actions", "assumptions", "recommended_next_action", "safety_metadata",
        "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in plan:
            raise ValueError(f"business execution simulation plan missing required field: {key}")
    if plan["business_execution_simulation_plan_version"] != BUSINESS_EXECUTION_SIMULATION_PLAN_VERSION:
        raise ValueError("invalid business execution simulation plan version")
    if not isinstance(plan["business_execution_simulation_plan_id"], str) or not plan["business_execution_simulation_plan_id"].startswith("business-execution-simulation-plan-"):
        raise ValueError("invalid business execution simulation plan id")
    if not isinstance(plan["business_execution_review_package_id"], str) or not plan["business_execution_review_package_id"].startswith("business-execution-review-package-"):
        raise ValueError("invalid business execution review package id in simulation plan")
    if not isinstance(plan["readiness_review_package_id"], str) or not plan["readiness_review_package_id"].startswith("business-readiness-review-package-"):
        raise ValueError("invalid readiness review package id in simulation plan")
    expected_steps = _business_execution_simulated_step_records()
    if plan["simulated_steps"] != expected_steps:
        raise ValueError("business execution simulation plan simulated_steps mismatch")
    for field in ("required_inputs", "expected_outputs", "expected_artifacts", "assumptions"):
        normalized = _normalize_implementation_branch_refs(plan[field])
        if not normalized or normalized != plan[field]:
            raise ValueError(f"business execution simulation plan {field} must be normalized and non-empty")
    if plan["blocked_real_actions"] != list(BUSINESS_EXECUTION_SIMULATION_BLOCKED_REAL_ACTIONS):
        raise ValueError("business execution simulation plan blocked_real_actions mismatch")
    if plan["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("business execution simulation plan safety metadata mismatch")
    if plan["dry_run"] is not True or plan["write_allowed"] is not False:
        raise ValueError("business execution simulation plan must be read-only")
    if plan["automation_allowed"] is not False or plan["writes"] != []:
        raise ValueError("business execution simulation plan must not allow automation or writes")
    if business_execution_review_package is not None:
        validate_business_execution_review_package(business_execution_review_package)
        if plan["business_execution_review_package_id"] != business_execution_review_package["business_execution_review_package_id"]:
            raise ValueError("business execution simulation plan execution review id mismatch")
    if business_readiness_review_package is not None:
        validate_business_readiness_review_package(business_readiness_review_package)
        if plan["readiness_review_package_id"] != business_readiness_review_package["business_readiness_review_package_id"]:
            raise ValueError("business execution simulation plan readiness id mismatch")
    if all(item is not None for item in (
        business_execution_review_package,
        business_readiness_review_package,
        governance_executive_review_package,
        control_plane_review_package,
        module_boundary_registry,
        shared_services_registry,
    )):
        expected_id = make_business_execution_simulation_plan_id(
            business_execution_review_package,
            business_readiness_review_package,
            governance_executive_review_package,
            control_plane_review_package,
            module_boundary_registry,
            shared_services_registry,
        )
        if plan["business_execution_simulation_plan_id"] != expected_id:
            raise ValueError("business execution simulation plan id is not deterministic")


def stable_business_execution_simulation_plan_json(plan: dict[str, Any]) -> str:
    validate_business_execution_simulation_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_business_execution_simulation_plan_json(text: str) -> dict[str, Any]:
    import json as _json

    plan = _json.loads(text)
    validate_business_execution_simulation_plan(plan)
    return plan


def make_business_execution_simulation_evidence_package_id(plan: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "business_execution_simulation_plan_id": plan["business_execution_simulation_plan_id"],
        "version": BUSINESS_EXECUTION_SIMULATION_EVIDENCE_PACKAGE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"business-execution-simulation-evidence-package-{digest}"


def collect_business_execution_simulation_evidence_package(
    business_execution_simulation_plan: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Inventory simulated evidence without creating real receipts or artifacts."""
    plan = business_execution_simulation_plan or collect_business_execution_simulation_plan()
    validate_business_execution_simulation_plan(plan)
    simulated_evidence_refs = _normalize_implementation_branch_refs([
        f"simulated-evidence:{item}" for item in plan["required_inputs"]
    ])
    simulated_receipt_refs = _normalize_implementation_branch_refs([
        "simulated-receipt:execution-boundary-check",
        "simulated-receipt:evidence-contract-check",
        "simulated-receipt:approval-checklist-check",
        "simulated-receipt:readiness-check",
    ])
    simulated_artifact_refs = _normalize_implementation_branch_refs([
        f"simulated-artifact:{item}" for item in plan["expected_artifacts"]
    ])
    missing_real_evidence = _normalize_implementation_branch_refs([
        "real execution approvals are not present in simulation",
        "real customer or market evidence is intentionally not collected",
        "real campaign, source, and operations receipts are intentionally simulated only",
    ])
    package = {
        "business_execution_simulation_evidence_package_version": BUSINESS_EXECUTION_SIMULATION_EVIDENCE_PACKAGE_VERSION,
        "business_execution_simulation_evidence_package_id": make_business_execution_simulation_evidence_package_id(plan),
        "business_execution_simulation_plan_id": plan["business_execution_simulation_plan_id"],
        "simulated_evidence_refs": simulated_evidence_refs,
        "simulated_receipt_refs": simulated_receipt_refs,
        "simulated_artifact_refs": simulated_artifact_refs,
        "missing_real_evidence": missing_real_evidence,
        "evidence_status": "block" if missing_real_evidence else "pass",
        "recommended_next_action": "Review missing real evidence before considering any future execution runtime.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_business_execution_simulation_evidence_package(package, plan)
    return package


def validate_business_execution_simulation_evidence_package(
    package: dict[str, Any],
    business_execution_simulation_plan: dict[str, Any] | None = None,
) -> None:
    required = (
        "business_execution_simulation_evidence_package_version", "business_execution_simulation_evidence_package_id",
        "business_execution_simulation_plan_id", "simulated_evidence_refs", "simulated_receipt_refs",
        "simulated_artifact_refs", "missing_real_evidence", "evidence_status", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in package:
            raise ValueError(f"business execution simulation evidence package missing required field: {key}")
    if package["business_execution_simulation_evidence_package_version"] != BUSINESS_EXECUTION_SIMULATION_EVIDENCE_PACKAGE_VERSION:
        raise ValueError("invalid business execution simulation evidence package version")
    if not isinstance(package["business_execution_simulation_evidence_package_id"], str) or not package["business_execution_simulation_evidence_package_id"].startswith("business-execution-simulation-evidence-package-"):
        raise ValueError("invalid business execution simulation evidence package id")
    if not isinstance(package["business_execution_simulation_plan_id"], str) or not package["business_execution_simulation_plan_id"].startswith("business-execution-simulation-plan-"):
        raise ValueError("invalid business execution simulation plan id in evidence package")
    for field in ("simulated_evidence_refs", "simulated_receipt_refs", "simulated_artifact_refs", "missing_real_evidence"):
        normalized = _normalize_implementation_branch_refs(package[field])
        if not normalized or normalized != package[field]:
            raise ValueError(f"business execution simulation evidence package {field} must be normalized and non-empty")
    if package["evidence_status"] not in BUSINESS_EXECUTION_SIMULATION_STATUSES:
        raise ValueError("invalid business execution simulation evidence status")
    if package["missing_real_evidence"] and package["evidence_status"] != "block":
        raise ValueError("missing real evidence must block simulation evidence status")
    if package["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("business execution simulation evidence package safety metadata mismatch")
    if package["dry_run"] is not True or package["write_allowed"] is not False:
        raise ValueError("business execution simulation evidence package must be read-only")
    if package["automation_allowed"] is not False or package["writes"] != []:
        raise ValueError("business execution simulation evidence package must not allow automation or writes")
    if business_execution_simulation_plan is not None:
        validate_business_execution_simulation_plan(business_execution_simulation_plan)
        if package["business_execution_simulation_plan_id"] != business_execution_simulation_plan["business_execution_simulation_plan_id"]:
            raise ValueError("business execution simulation evidence package plan id mismatch")
        expected_id = make_business_execution_simulation_evidence_package_id(business_execution_simulation_plan)
        if package["business_execution_simulation_evidence_package_id"] != expected_id:
            raise ValueError("business execution simulation evidence package id is not deterministic")


def stable_business_execution_simulation_evidence_package_json(package: dict[str, Any]) -> str:
    validate_business_execution_simulation_evidence_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_business_execution_simulation_evidence_package_json(text: str) -> dict[str, Any]:
    import json as _json

    package = _json.loads(text)
    validate_business_execution_simulation_evidence_package(package)
    return package


def make_business_execution_simulation_review_id(plan: dict[str, Any], evidence_package: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "business_execution_simulation_evidence_package_id": evidence_package["business_execution_simulation_evidence_package_id"],
        "business_execution_simulation_plan_id": plan["business_execution_simulation_plan_id"],
        "version": BUSINESS_EXECUTION_SIMULATION_REVIEW_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"business-execution-simulation-review-{digest}"


def collect_business_execution_simulation_review(
    business_execution_simulation_plan: dict[str, Any] | None = None,
    simulation_evidence_package: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Review the dry-run business execution simulation path."""
    plan = business_execution_simulation_plan or collect_business_execution_simulation_plan()
    validate_business_execution_simulation_plan(plan)
    evidence = simulation_evidence_package or collect_business_execution_simulation_evidence_package(plan)
    validate_business_execution_simulation_evidence_package(evidence, plan)
    missing_approvals = _normalize_implementation_branch_refs([
        "human approval for real business execution is absent",
        "operator approval for external effects is absent",
    ])
    blocked_actions = list(plan["blocked_real_actions"])
    predicted_failures = _normalize_implementation_branch_refs([
        "simulation would fail closed before real external action",
        "simulation would fail closed while required real evidence is missing",
        "simulation would fail closed while final human approvals are missing",
    ])
    warnings = _normalize_implementation_branch_refs([
        "future execution runtime still needs separate safety boundaries",
        "simulation only validates governance coherence, not live market facts",
    ])
    required_actions = _normalize_implementation_branch_refs([
        "review blocked real actions before runtime design",
        "review missing final approvals",
        "review missing real evidence",
    ])
    status = "block" if predicted_failures or evidence["missing_real_evidence"] or missing_approvals else "pass"
    review = {
        "business_execution_simulation_review_version": BUSINESS_EXECUTION_SIMULATION_REVIEW_VERSION,
        "business_execution_simulation_review_id": make_business_execution_simulation_review_id(plan, evidence),
        "business_execution_simulation_plan_id": plan["business_execution_simulation_plan_id"],
        "simulation_evidence_package_id": evidence["business_execution_simulation_evidence_package_id"],
        "simulation_status": status,
        "predicted_failures": predicted_failures,
        "blocked_actions": blocked_actions,
        "missing_evidence": list(evidence["missing_real_evidence"]),
        "missing_approvals": missing_approvals,
        "warnings": warnings,
        "required_human_actions": required_actions,
        "review_recommendation": "simulation_blocked" if status == "block" else "simulation_ready_for_operator_review",
        "recommended_next_action": "Use simulation findings to close evidence and approval gaps before any real execution design.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_business_execution_simulation_review(review, plan, evidence)
    return review


def validate_business_execution_simulation_review(
    review: dict[str, Any],
    business_execution_simulation_plan: dict[str, Any] | None = None,
    simulation_evidence_package: dict[str, Any] | None = None,
) -> None:
    required = (
        "business_execution_simulation_review_version", "business_execution_simulation_review_id",
        "business_execution_simulation_plan_id", "simulation_evidence_package_id", "simulation_status",
        "predicted_failures", "blocked_actions", "missing_evidence", "missing_approvals",
        "warnings", "required_human_actions", "review_recommendation", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in review:
            raise ValueError(f"business execution simulation review missing required field: {key}")
    if review["business_execution_simulation_review_version"] != BUSINESS_EXECUTION_SIMULATION_REVIEW_VERSION:
        raise ValueError("invalid business execution simulation review version")
    if not isinstance(review["business_execution_simulation_review_id"], str) or not review["business_execution_simulation_review_id"].startswith("business-execution-simulation-review-"):
        raise ValueError("invalid business execution simulation review id")
    if not isinstance(review["business_execution_simulation_plan_id"], str) or not review["business_execution_simulation_plan_id"].startswith("business-execution-simulation-plan-"):
        raise ValueError("invalid business execution simulation plan id in review")
    if not isinstance(review["simulation_evidence_package_id"], str) or not review["simulation_evidence_package_id"].startswith("business-execution-simulation-evidence-package-"):
        raise ValueError("invalid business execution simulation evidence package id in review")
    if review["simulation_status"] not in BUSINESS_EXECUTION_SIMULATION_STATUSES:
        raise ValueError("invalid business execution simulation status")
    if review["blocked_actions"] != list(BUSINESS_EXECUTION_SIMULATION_BLOCKED_REAL_ACTIONS):
        raise ValueError("business execution simulation review blocked actions mismatch")
    for field in ("predicted_failures", "missing_evidence", "missing_approvals", "warnings", "required_human_actions"):
        normalized = _normalize_implementation_branch_refs(review[field])
        if not normalized or normalized != review[field]:
            raise ValueError(f"business execution simulation review {field} must be normalized and non-empty")
    if review["review_recommendation"] not in BUSINESS_EXECUTION_SIMULATION_RECOMMENDATIONS:
        raise ValueError("invalid business execution simulation review recommendation")
    if review["simulation_status"] == "block" and not review["predicted_failures"]:
        raise ValueError("blocked business execution simulation review must include predicted failures")
    if review["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("business execution simulation review safety metadata mismatch")
    if review["dry_run"] is not True or review["write_allowed"] is not False:
        raise ValueError("business execution simulation review must be read-only")
    if review["automation_allowed"] is not False or review["writes"] != []:
        raise ValueError("business execution simulation review must not allow automation or writes")
    if business_execution_simulation_plan is not None:
        validate_business_execution_simulation_plan(business_execution_simulation_plan)
        if review["business_execution_simulation_plan_id"] != business_execution_simulation_plan["business_execution_simulation_plan_id"]:
            raise ValueError("business execution simulation review plan id mismatch")
    if simulation_evidence_package is not None:
        validate_business_execution_simulation_evidence_package(simulation_evidence_package, business_execution_simulation_plan)
        if review["simulation_evidence_package_id"] != simulation_evidence_package["business_execution_simulation_evidence_package_id"]:
            raise ValueError("business execution simulation review evidence id mismatch")
    if business_execution_simulation_plan is not None and simulation_evidence_package is not None:
        expected_id = make_business_execution_simulation_review_id(business_execution_simulation_plan, simulation_evidence_package)
        if review["business_execution_simulation_review_id"] != expected_id:
            raise ValueError("business execution simulation review id is not deterministic")


def stable_business_execution_simulation_review_json(review: dict[str, Any]) -> str:
    validate_business_execution_simulation_review(review)
    return _stable_ruflo_json(review, indent=2) + "\n"


def parse_business_execution_simulation_review_json(text: str) -> dict[str, Any]:
    import json as _json

    review = _json.loads(text)
    validate_business_execution_simulation_review(review)
    return review


def make_business_execution_simulation_readiness_id(review: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "business_execution_simulation_review_id": review["business_execution_simulation_review_id"],
        "version": BUSINESS_EXECUTION_SIMULATION_READINESS_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"business-execution-simulation-readiness-{digest}"


def collect_business_execution_simulation_readiness(
    business_execution_simulation_review: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Determine whether real business execution could theoretically proceed."""
    review = business_execution_simulation_review or collect_business_execution_simulation_review()
    validate_business_execution_simulation_review(review)
    blockers = _normalize_implementation_branch_refs(
        list(review["predicted_failures"]) +
        [f"blocked real action remains prohibited: {item}" for item in review["blocked_actions"]] +
        list(review["missing_evidence"]) +
        list(review["missing_approvals"])
    )
    readiness_status = "blocked" if blockers or review["simulation_status"] != "pass" else "ready"
    readiness = {
        "business_execution_simulation_readiness_version": BUSINESS_EXECUTION_SIMULATION_READINESS_VERSION,
        "business_execution_simulation_readiness_id": make_business_execution_simulation_readiness_id(review),
        "business_execution_simulation_review_id": review["business_execution_simulation_review_id"],
        "readiness_status": readiness_status,
        "execution_candidate_status": "blocked" if readiness_status == "blocked" else "candidate",
        "blockers": blockers,
        "warnings": list(review["warnings"]),
        "required_human_actions": list(review["required_human_actions"]),
        "recommended_next_action": "Keep business execution in simulation until evidence, approvals, and blocked real actions are resolved.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_business_execution_simulation_readiness(readiness, review)
    return readiness


def validate_business_execution_simulation_readiness(
    readiness: dict[str, Any],
    business_execution_simulation_review: dict[str, Any] | None = None,
) -> None:
    required = (
        "business_execution_simulation_readiness_version", "business_execution_simulation_readiness_id",
        "business_execution_simulation_review_id", "readiness_status", "execution_candidate_status",
        "blockers", "warnings", "required_human_actions", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in readiness:
            raise ValueError(f"business execution simulation readiness missing required field: {key}")
    if readiness["business_execution_simulation_readiness_version"] != BUSINESS_EXECUTION_SIMULATION_READINESS_VERSION:
        raise ValueError("invalid business execution simulation readiness version")
    if not isinstance(readiness["business_execution_simulation_readiness_id"], str) or not readiness["business_execution_simulation_readiness_id"].startswith("business-execution-simulation-readiness-"):
        raise ValueError("invalid business execution simulation readiness id")
    if not isinstance(readiness["business_execution_simulation_review_id"], str) or not readiness["business_execution_simulation_review_id"].startswith("business-execution-simulation-review-"):
        raise ValueError("invalid business execution simulation review id in readiness")
    if readiness["readiness_status"] not in BUSINESS_EXECUTION_SIMULATION_READINESS_STATUSES:
        raise ValueError("invalid business execution simulation readiness status")
    if readiness["execution_candidate_status"] not in BUSINESS_EXECUTION_SIMULATION_CANDIDATE_STATUSES:
        raise ValueError("invalid business execution simulation candidate status")
    for field in ("blockers", "warnings", "required_human_actions"):
        normalized = _normalize_implementation_branch_refs(readiness[field])
        if not normalized or normalized != readiness[field]:
            raise ValueError(f"business execution simulation readiness {field} must be normalized and non-empty")
    if readiness["readiness_status"] == "ready" and readiness["blockers"]:
        raise ValueError("ready business execution simulation must not include blockers")
    if readiness["readiness_status"] == "blocked" and not readiness["blockers"]:
        raise ValueError("blocked business execution simulation readiness must include blockers")
    if readiness["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("business execution simulation readiness safety metadata mismatch")
    if readiness["dry_run"] is not True or readiness["write_allowed"] is not False:
        raise ValueError("business execution simulation readiness must be read-only")
    if readiness["automation_allowed"] is not False or readiness["writes"] != []:
        raise ValueError("business execution simulation readiness must not allow automation or writes")
    if business_execution_simulation_review is not None:
        validate_business_execution_simulation_review(business_execution_simulation_review)
        if readiness["business_execution_simulation_review_id"] != business_execution_simulation_review["business_execution_simulation_review_id"]:
            raise ValueError("business execution simulation readiness review id mismatch")
        expected_id = make_business_execution_simulation_readiness_id(business_execution_simulation_review)
        if readiness["business_execution_simulation_readiness_id"] != expected_id:
            raise ValueError("business execution simulation readiness id is not deterministic")


def stable_business_execution_simulation_readiness_json(readiness: dict[str, Any]) -> str:
    validate_business_execution_simulation_readiness(readiness)
    return _stable_ruflo_json(readiness, indent=2) + "\n"


def parse_business_execution_simulation_readiness_json(text: str) -> dict[str, Any]:
    import json as _json

    readiness = _json.loads(text)
    validate_business_execution_simulation_readiness(readiness)
    return readiness



def make_simulation_dashboard_id(
    plan: dict[str, Any],
    evidence_package: dict[str, Any],
    review: dict[str, Any],
    readiness: dict[str, Any],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "business_execution_simulation_evidence_package_id": evidence_package["business_execution_simulation_evidence_package_id"],
        "business_execution_simulation_plan_id": plan["business_execution_simulation_plan_id"],
        "business_execution_simulation_readiness_id": readiness["business_execution_simulation_readiness_id"],
        "business_execution_simulation_review_id": review["business_execution_simulation_review_id"],
        "version": SIMULATION_DASHBOARD_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"simulation-dashboard-{digest}"


def _collect_simulation_chain(
    plan: dict[str, Any] | None = None,
    evidence_package: dict[str, Any] | None = None,
    review: dict[str, Any] | None = None,
    readiness: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any]]:
    selected_plan = plan or collect_business_execution_simulation_plan()
    validate_business_execution_simulation_plan(selected_plan)
    selected_evidence = evidence_package or collect_business_execution_simulation_evidence_package(selected_plan)
    validate_business_execution_simulation_evidence_package(selected_evidence, selected_plan)
    selected_review = review or collect_business_execution_simulation_review(selected_plan, selected_evidence)
    validate_business_execution_simulation_review(selected_review, selected_plan, selected_evidence)
    selected_readiness = readiness or collect_business_execution_simulation_readiness(selected_review)
    validate_business_execution_simulation_readiness(selected_readiness, selected_review)
    return selected_plan, selected_evidence, selected_review, selected_readiness


def collect_simulation_dashboard(
    business_execution_simulation_plan: dict[str, Any] | None = None,
    business_execution_simulation_evidence_package: dict[str, Any] | None = None,
    business_execution_simulation_review: dict[str, Any] | None = None,
    business_execution_simulation_readiness: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Summarize the business execution simulation state without executing anything."""
    plan, evidence, review, readiness = _collect_simulation_chain(
        business_execution_simulation_plan,
        business_execution_simulation_evidence_package,
        business_execution_simulation_review,
        business_execution_simulation_readiness,
    )
    blockers = _normalize_implementation_branch_refs(
        list(review["predicted_failures"]) +
        list(review["missing_evidence"]) +
        list(review["missing_approvals"]) +
        list(readiness["blockers"])
    )
    warnings = _normalize_implementation_branch_refs(list(review["warnings"]) + list(readiness["warnings"]))
    dashboard = {
        "simulation_dashboard_version": SIMULATION_DASHBOARD_VERSION,
        "simulation_dashboard_id": make_simulation_dashboard_id(plan, evidence, review, readiness),
        "business_execution_simulation_plan_id": plan["business_execution_simulation_plan_id"],
        "business_execution_simulation_evidence_package_id": evidence["business_execution_simulation_evidence_package_id"],
        "business_execution_simulation_review_id": review["business_execution_simulation_review_id"],
        "business_execution_simulation_readiness_id": readiness["business_execution_simulation_readiness_id"],
        "simulation_status": review["simulation_status"],
        "readiness_status": readiness["readiness_status"],
        "blocker_count": len(blockers),
        "warning_count": len(warnings),
        "recommended_next_action": "Resolve simulation blockers before designing any real execution runtime.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_simulation_dashboard(dashboard, plan, evidence, review, readiness)
    return dashboard


def validate_simulation_dashboard(
    dashboard: dict[str, Any],
    business_execution_simulation_plan: dict[str, Any] | None = None,
    business_execution_simulation_evidence_package: dict[str, Any] | None = None,
    business_execution_simulation_review: dict[str, Any] | None = None,
    business_execution_simulation_readiness: dict[str, Any] | None = None,
) -> None:
    required = (
        "simulation_dashboard_version", "simulation_dashboard_id",
        "business_execution_simulation_plan_id", "business_execution_simulation_evidence_package_id",
        "business_execution_simulation_review_id", "business_execution_simulation_readiness_id",
        "simulation_status", "readiness_status", "blocker_count", "warning_count",
        "recommended_next_action", "safety_metadata", "dry_run", "write_allowed",
        "automation_allowed", "writes",
    )
    for key in required:
        if key not in dashboard:
            raise ValueError(f"simulation dashboard missing required field: {key}")
    if dashboard["simulation_dashboard_version"] != SIMULATION_DASHBOARD_VERSION:
        raise ValueError("invalid simulation dashboard version")
    if not isinstance(dashboard["simulation_dashboard_id"], str) or not dashboard["simulation_dashboard_id"].startswith("simulation-dashboard-"):
        raise ValueError("invalid simulation dashboard id")
    if dashboard["simulation_status"] not in BUSINESS_EXECUTION_SIMULATION_STATUSES:
        raise ValueError("invalid simulation dashboard status")
    if dashboard["readiness_status"] not in BUSINESS_EXECUTION_SIMULATION_READINESS_STATUSES:
        raise ValueError("invalid simulation dashboard readiness status")
    for field in ("blocker_count", "warning_count"):
        if not isinstance(dashboard[field], int) or dashboard[field] < 0:
            raise ValueError(f"simulation dashboard {field} must be non-negative")
    if dashboard["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("simulation dashboard safety metadata mismatch")
    if dashboard["dry_run"] is not True or dashboard["write_allowed"] is not False:
        raise ValueError("simulation dashboard must be read-only")
    if dashboard["automation_allowed"] is not False or dashboard["writes"] != []:
        raise ValueError("simulation dashboard must not allow automation or writes")
    if all(item is not None for item in (
        business_execution_simulation_plan,
        business_execution_simulation_evidence_package,
        business_execution_simulation_review,
        business_execution_simulation_readiness,
    )):
        validate_business_execution_simulation_plan(business_execution_simulation_plan)
        validate_business_execution_simulation_evidence_package(business_execution_simulation_evidence_package, business_execution_simulation_plan)
        validate_business_execution_simulation_review(business_execution_simulation_review, business_execution_simulation_plan, business_execution_simulation_evidence_package)
        validate_business_execution_simulation_readiness(business_execution_simulation_readiness, business_execution_simulation_review)
        expected_id = make_simulation_dashboard_id(
            business_execution_simulation_plan,
            business_execution_simulation_evidence_package,
            business_execution_simulation_review,
            business_execution_simulation_readiness,
        )
        if dashboard["simulation_dashboard_id"] != expected_id:
            raise ValueError("simulation dashboard id is not deterministic")


def stable_simulation_dashboard_json(dashboard: dict[str, Any]) -> str:
    validate_simulation_dashboard(dashboard)
    return _stable_ruflo_json(dashboard, indent=2) + "\n"


def parse_simulation_dashboard_json(text: str) -> dict[str, Any]:
    import json as _json

    dashboard = _json.loads(text)
    validate_simulation_dashboard(dashboard)
    return dashboard


def make_execution_gap_analysis_id(review: dict[str, Any], readiness: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "business_execution_simulation_readiness_id": readiness["business_execution_simulation_readiness_id"],
        "business_execution_simulation_review_id": review["business_execution_simulation_review_id"],
        "version": EXECUTION_GAP_ANALYSIS_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"execution-gap-analysis-{digest}"


def collect_execution_gap_analysis(
    business_execution_simulation_review: dict[str, Any] | None = None,
    business_execution_simulation_readiness: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Identify what prevents execution in the current simulation."""
    review = business_execution_simulation_review or collect_business_execution_simulation_review()
    validate_business_execution_simulation_review(review)
    readiness = business_execution_simulation_readiness or collect_business_execution_simulation_readiness(review)
    validate_business_execution_simulation_readiness(readiness, review)
    critical_gaps = _normalize_implementation_branch_refs(
        list(review["missing_evidence"]) +
        list(review["missing_approvals"]) +
        [item for item in readiness["blockers"] if "blocked real action" in item]
    )
    moderate_gaps = _normalize_implementation_branch_refs([
        "missing execution review confirmation",
        "missing real source collection evidence",
        "missing final operator approval trail",
    ])
    minor_gaps = _normalize_implementation_branch_refs([
        "missing simulation freshness marker",
        "missing dashboard refresh note",
    ])
    recommended = _normalize_implementation_branch_refs([
        "close missing evidence before runtime design",
        "collect explicit final approvals before external effects",
        "keep blocked real actions disabled until separate boundaries exist",
        "refresh simulation dashboard after upstream governance changes",
    ])
    analysis = {
        "execution_gap_analysis_version": EXECUTION_GAP_ANALYSIS_VERSION,
        "execution_gap_analysis_id": make_execution_gap_analysis_id(review, readiness),
        "business_execution_simulation_review_id": review["business_execution_simulation_review_id"],
        "business_execution_simulation_readiness_id": readiness["business_execution_simulation_readiness_id"],
        "critical_gaps": critical_gaps,
        "moderate_gaps": moderate_gaps,
        "minor_gaps": minor_gaps,
        "recommended_fixes": recommended,
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_gap_analysis(analysis, review, readiness)
    return analysis


def validate_execution_gap_analysis(
    analysis: dict[str, Any],
    business_execution_simulation_review: dict[str, Any] | None = None,
    business_execution_simulation_readiness: dict[str, Any] | None = None,
) -> None:
    required = (
        "execution_gap_analysis_version", "execution_gap_analysis_id",
        "critical_gaps", "moderate_gaps", "minor_gaps", "recommended_fixes",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in analysis:
            raise ValueError(f"execution gap analysis missing required field: {key}")
    if analysis["execution_gap_analysis_version"] != EXECUTION_GAP_ANALYSIS_VERSION:
        raise ValueError("invalid execution gap analysis version")
    if not isinstance(analysis["execution_gap_analysis_id"], str) or not analysis["execution_gap_analysis_id"].startswith("execution-gap-analysis-"):
        raise ValueError("invalid execution gap analysis id")
    for field in ("critical_gaps", "moderate_gaps", "minor_gaps", "recommended_fixes"):
        normalized = _normalize_implementation_branch_refs(analysis[field])
        if not normalized or normalized != analysis[field]:
            raise ValueError(f"execution gap analysis {field} must be normalized and non-empty")
    if analysis["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("execution gap analysis safety metadata mismatch")
    if analysis["dry_run"] is not True or analysis["write_allowed"] is not False:
        raise ValueError("execution gap analysis must be read-only")
    if analysis["automation_allowed"] is not False or analysis["writes"] != []:
        raise ValueError("execution gap analysis must not allow automation or writes")
    if business_execution_simulation_review is not None and business_execution_simulation_readiness is not None:
        validate_business_execution_simulation_review(business_execution_simulation_review)
        validate_business_execution_simulation_readiness(business_execution_simulation_readiness, business_execution_simulation_review)
        expected_id = make_execution_gap_analysis_id(business_execution_simulation_review, business_execution_simulation_readiness)
        if analysis["execution_gap_analysis_id"] != expected_id:
            raise ValueError("execution gap analysis id is not deterministic")


def stable_execution_gap_analysis_json(analysis: dict[str, Any]) -> str:
    validate_execution_gap_analysis(analysis)
    return _stable_ruflo_json(analysis, indent=2) + "\n"


def parse_execution_gap_analysis_json(text: str) -> dict[str, Any]:
    import json as _json

    analysis = _json.loads(text)
    validate_execution_gap_analysis(analysis)
    return analysis


def make_execution_readiness_score_id(dashboard: dict[str, Any], gap_analysis: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "execution_gap_analysis_id": gap_analysis["execution_gap_analysis_id"],
        "simulation_dashboard_id": dashboard["simulation_dashboard_id"],
        "version": EXECUTION_READINESS_SCORE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"execution-readiness-score-{digest}"


def _execution_readiness_grade(score: int) -> str:
    if score >= 90:
        return "A"
    if score >= 75:
        return "B"
    if score >= 60:
        return "C"
    if score >= 40:
        return "D"
    return "F"


def collect_execution_readiness_score(
    simulation_dashboard: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Score simulated execution readiness deterministically from governance state."""
    dashboard = simulation_dashboard or collect_simulation_dashboard()
    validate_simulation_dashboard(dashboard)
    gaps = execution_gap_analysis or collect_execution_gap_analysis()
    validate_execution_gap_analysis(gaps)
    penalty = min(100, len(gaps["critical_gaps"]) * 10 + len(gaps["moderate_gaps"]) * 5 + len(gaps["minor_gaps"]) * 2)
    score_value = max(0, 100 - penalty)
    if dashboard["readiness_status"] == "blocked":
        score_value = min(score_value, 39)
    factors = [
        {"factor_id": "critical_gaps", "value": len(gaps["critical_gaps"]), "impact": "high"},
        {"factor_id": "moderate_gaps", "value": len(gaps["moderate_gaps"]), "impact": "medium"},
        {"factor_id": "minor_gaps", "value": len(gaps["minor_gaps"]), "impact": "low"},
        {"factor_id": "simulation_blockers", "value": dashboard["blocker_count"], "impact": "high"},
        {"factor_id": "simulation_warnings", "value": dashboard["warning_count"], "impact": "medium"},
    ]
    payload = {
        "execution_readiness_score_version": EXECUTION_READINESS_SCORE_VERSION,
        "execution_readiness_score_id": make_execution_readiness_score_id(dashboard, gaps),
        "simulation_dashboard_id": dashboard["simulation_dashboard_id"],
        "execution_gap_analysis_id": gaps["execution_gap_analysis_id"],
        "readiness_score": score_value,
        "readiness_grade": _execution_readiness_grade(score_value),
        "readiness_factors": factors,
        "blockers": list(gaps["critical_gaps"]),
        "recommended_next_action": "Fix critical execution gaps before any real execution runtime is considered.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_readiness_score(payload, dashboard, gaps)
    return payload


def validate_execution_readiness_score(
    score: dict[str, Any],
    simulation_dashboard: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
) -> None:
    required = (
        "execution_readiness_score_version", "execution_readiness_score_id", "readiness_score",
        "readiness_grade", "readiness_factors", "blockers", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in score:
            raise ValueError(f"execution readiness score missing required field: {key}")
    if score["execution_readiness_score_version"] != EXECUTION_READINESS_SCORE_VERSION:
        raise ValueError("invalid execution readiness score version")
    if not isinstance(score["execution_readiness_score_id"], str) or not score["execution_readiness_score_id"].startswith("execution-readiness-score-"):
        raise ValueError("invalid execution readiness score id")
    if not isinstance(score["readiness_score"], int) or not 0 <= score["readiness_score"] <= 100:
        raise ValueError("execution readiness score must be an integer between 0 and 100")
    if score["readiness_grade"] != _execution_readiness_grade(score["readiness_score"]):
        raise ValueError("execution readiness grade does not match score")
    if not isinstance(score["readiness_factors"], list) or not score["readiness_factors"]:
        raise ValueError("execution readiness score must include factors")
    for factor in score["readiness_factors"]:
        if not isinstance(factor, dict):
            raise TypeError("execution readiness factor must be a dict")
        for field in ("factor_id", "value", "impact"):
            if field not in factor:
                raise ValueError(f"execution readiness factor missing {field}")
        if not isinstance(factor["value"], int) or factor["value"] < 0:
            raise ValueError("execution readiness factor value must be non-negative")
    if _normalize_implementation_branch_refs(score["blockers"]) != score["blockers"]:
        raise ValueError("execution readiness score blockers must be normalized")
    if score["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("execution readiness score safety metadata mismatch")
    if score["dry_run"] is not True or score["write_allowed"] is not False:
        raise ValueError("execution readiness score must be read-only")
    if score["automation_allowed"] is not False or score["writes"] != []:
        raise ValueError("execution readiness score must not allow automation or writes")
    if simulation_dashboard is not None and execution_gap_analysis is not None:
        validate_simulation_dashboard(simulation_dashboard)
        validate_execution_gap_analysis(execution_gap_analysis)
        expected_id = make_execution_readiness_score_id(simulation_dashboard, execution_gap_analysis)
        if score["execution_readiness_score_id"] != expected_id:
            raise ValueError("execution readiness score id is not deterministic")


def stable_execution_readiness_score_json(score: dict[str, Any]) -> str:
    validate_execution_readiness_score(score)
    return _stable_ruflo_json(score, indent=2) + "\n"


def parse_execution_readiness_score_json(text: str) -> dict[str, Any]:
    import json as _json

    score = _json.loads(text)
    validate_execution_readiness_score(score)
    return score


def make_operator_simulation_review_package_id(
    dashboard: dict[str, Any],
    gap_analysis: dict[str, Any],
    readiness_score: dict[str, Any],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "execution_gap_analysis_id": gap_analysis["execution_gap_analysis_id"],
        "execution_readiness_score_id": readiness_score["execution_readiness_score_id"],
        "simulation_dashboard_id": dashboard["simulation_dashboard_id"],
        "version": OPERATOR_SIMULATION_REVIEW_PACKAGE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-simulation-review-package-{digest}"


def collect_operator_simulation_review_package(
    simulation_dashboard: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
    execution_readiness_score: dict[str, Any] | None = None,
    business_execution_simulation_review: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Produce one operator-facing package for the simulation analysis layer."""
    dashboard = simulation_dashboard or collect_simulation_dashboard()
    validate_simulation_dashboard(dashboard)
    gaps = execution_gap_analysis or collect_execution_gap_analysis()
    validate_execution_gap_analysis(gaps)
    score = execution_readiness_score or collect_execution_readiness_score(dashboard, gaps)
    validate_execution_readiness_score(score, dashboard, gaps)
    review = business_execution_simulation_review or collect_business_execution_simulation_review()
    validate_business_execution_simulation_review(review)
    blockers = _normalize_implementation_branch_refs(list(gaps["critical_gaps"]) + list(score["blockers"]))
    warnings = _normalize_implementation_branch_refs(list(gaps["moderate_gaps"]) + list(gaps["minor_gaps"]) + list(review["warnings"]))
    required_actions = _normalize_implementation_branch_refs(list(review["required_human_actions"]) + list(gaps["recommended_fixes"]))
    overall = "block" if blockers or dashboard["simulation_status"] == "block" else "review"
    package = {
        "operator_simulation_review_package_version": OPERATOR_SIMULATION_REVIEW_PACKAGE_VERSION,
        "operator_simulation_review_package_id": make_operator_simulation_review_package_id(dashboard, gaps, score),
        "simulation_dashboard_id": dashboard["simulation_dashboard_id"],
        "execution_gap_analysis_id": gaps["execution_gap_analysis_id"],
        "execution_readiness_score_id": score["execution_readiness_score_id"],
        "overall_status": overall,
        "predicted_failures": list(review["predicted_failures"]),
        "blockers": blockers,
        "warnings": warnings,
        "required_human_actions": required_actions,
        "review_recommendation": "execution_not_ready" if overall == "block" else "review_simulation_findings",
        "recommended_next_action": "Address the critical simulation gaps before any real execution capability is designed.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_simulation_review_package(package, dashboard, gaps, score)
    return package


def validate_operator_simulation_review_package(
    package: dict[str, Any],
    simulation_dashboard: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
    execution_readiness_score: dict[str, Any] | None = None,
) -> None:
    required = (
        "operator_simulation_review_package_version", "operator_simulation_review_package_id",
        "simulation_dashboard_id", "execution_gap_analysis_id", "execution_readiness_score_id",
        "overall_status", "predicted_failures", "blockers", "warnings", "required_human_actions",
        "review_recommendation", "recommended_next_action", "safety_metadata", "dry_run",
        "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in package:
            raise ValueError(f"operator simulation review package missing required field: {key}")
    if package["operator_simulation_review_package_version"] != OPERATOR_SIMULATION_REVIEW_PACKAGE_VERSION:
        raise ValueError("invalid operator simulation review package version")
    if not isinstance(package["operator_simulation_review_package_id"], str) or not package["operator_simulation_review_package_id"].startswith("operator-simulation-review-package-"):
        raise ValueError("invalid operator simulation review package id")
    if package["overall_status"] not in BUSINESS_EXECUTION_SIMULATION_STATUSES:
        raise ValueError("invalid operator simulation overall status")
    for field in ("predicted_failures", "blockers", "warnings", "required_human_actions"):
        normalized = _normalize_implementation_branch_refs(package[field])
        if not normalized or normalized != package[field]:
            raise ValueError(f"operator simulation review package {field} must be normalized and non-empty")
    if package["review_recommendation"] not in {"execution_not_ready", "review_simulation_findings"}:
        raise ValueError("invalid operator simulation review recommendation")
    if package["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("operator simulation review package safety metadata mismatch")
    if package["dry_run"] is not True or package["write_allowed"] is not False:
        raise ValueError("operator simulation review package must be read-only")
    if package["automation_allowed"] is not False or package["writes"] != []:
        raise ValueError("operator simulation review package must not allow automation or writes")
    if simulation_dashboard is not None and execution_gap_analysis is not None and execution_readiness_score is not None:
        validate_simulation_dashboard(simulation_dashboard)
        validate_execution_gap_analysis(execution_gap_analysis)
        validate_execution_readiness_score(execution_readiness_score, simulation_dashboard, execution_gap_analysis)
        expected_id = make_operator_simulation_review_package_id(simulation_dashboard, execution_gap_analysis, execution_readiness_score)
        if package["operator_simulation_review_package_id"] != expected_id:
            raise ValueError("operator simulation review package id is not deterministic")


def stable_operator_simulation_review_package_json(package: dict[str, Any]) -> str:
    validate_operator_simulation_review_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_operator_simulation_review_package_json(text: str) -> dict[str, Any]:
    import json as _json

    package = _json.loads(text)
    validate_operator_simulation_review_package(package)
    return package



def make_simulation_remediation_plan_id(
    simulation_dashboard: dict[str, Any],
    execution_gap_analysis: dict[str, Any],
    execution_readiness_score: dict[str, Any],
    operator_simulation_review_package: dict[str, Any],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "execution_gap_analysis_id": execution_gap_analysis["execution_gap_analysis_id"],
        "execution_readiness_score_id": execution_readiness_score["execution_readiness_score_id"],
        "operator_simulation_review_package_id": operator_simulation_review_package["operator_simulation_review_package_id"],
        "simulation_dashboard_id": simulation_dashboard["simulation_dashboard_id"],
        "version": SIMULATION_REMEDIATION_PLAN_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"simulation-remediation-plan-{digest}"


def _collect_simulation_analysis_chain(
    simulation_dashboard: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
    execution_readiness_score: dict[str, Any] | None = None,
    operator_simulation_review_package: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any]]:
    if all(item is None for item in (
        simulation_dashboard,
        execution_gap_analysis,
        execution_readiness_score,
        operator_simulation_review_package,
    )):
        plan, evidence, simulation_review, readiness = _collect_simulation_chain()
        dashboard = collect_simulation_dashboard(plan, evidence, simulation_review, readiness)
        gaps = collect_execution_gap_analysis(simulation_review, readiness)
        score = collect_execution_readiness_score(dashboard, gaps)
        review = collect_operator_simulation_review_package(dashboard, gaps, score, simulation_review)
        return dashboard, gaps, score, review
    dashboard = simulation_dashboard or collect_simulation_dashboard()
    validate_simulation_dashboard(dashboard)
    gaps = execution_gap_analysis or collect_execution_gap_analysis()
    validate_execution_gap_analysis(gaps)
    score = execution_readiness_score or collect_execution_readiness_score(dashboard, gaps)
    validate_execution_readiness_score(score, dashboard, gaps)
    review = operator_simulation_review_package or collect_operator_simulation_review_package(dashboard, gaps, score)
    validate_operator_simulation_review_package(review, dashboard, gaps, score)
    return dashboard, gaps, score, review


def _remediation_step(step_id: str, description: str, priority: str, impact: str, dependencies: list[str], evidence: list[str], approvals: list[str]) -> dict[str, Any]:
    return {
        "remediation_step_id": step_id,
        "description": description,
        "priority": priority,
        "expected_impact": impact,
        "dependencies": _normalize_implementation_branch_refs(dependencies),
        "required_evidence": _normalize_implementation_branch_refs(evidence),
        "required_approvals": _normalize_implementation_branch_refs(approvals),
        "execution_allowed": False,
    }


def collect_simulation_remediation_plan(
    simulation_dashboard: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
    execution_readiness_score: dict[str, Any] | None = None,
    operator_simulation_review_package: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Convert simulation analysis findings into non-executable remediation steps."""
    dashboard, gaps, score, review = _collect_simulation_analysis_chain(
        simulation_dashboard,
        execution_gap_analysis,
        execution_readiness_score,
        operator_simulation_review_package,
    )
    steps = [
        _remediation_step(
            "remediation-step-01-evidence",
            "Close missing real evidence before any future execution runtime design.",
            "critical",
            "removes evidence blockers and improves execution confidence",
            [],
            list(gaps["critical_gaps"][:3]),
            [],
        ),
        _remediation_step(
            "remediation-step-02-approvals",
            "Collect explicit final human approvals for any future external effects.",
            "critical",
            "removes approval blockers and preserves human control",
            ["remediation-step-01-evidence"],
            ["final approval evidence trail"],
            ["operator approval for external effects", "human approval for real business execution"],
        ),
        _remediation_step(
            "remediation-step-03-boundaries",
            "Design separate boundaries for real source, campaign, operations, and execution runtimes.",
            "high",
            "keeps blocked real actions disabled until governed boundaries exist",
            ["remediation-step-01-evidence", "remediation-step-02-approvals"],
            ["runtime boundary review evidence", "blocked action safety review"],
            ["operator approval for runtime boundary design"],
        ),
        _remediation_step(
            "remediation-step-04-refresh",
            "Refresh simulation dashboards after upstream governance and evidence changes.",
            "medium",
            "improves operator visibility and stale artifact confidence",
            ["remediation-step-03-boundaries"],
            ["fresh simulation dashboard", "fresh operator simulation review"],
            ["operator review of refreshed simulation"],
        ),
    ]
    required_evidence = _normalize_implementation_branch_refs([item for step in steps for item in step["required_evidence"]])
    required_approvals = _normalize_implementation_branch_refs([item for step in steps for item in step["required_approvals"]])
    expected_impact = _normalize_implementation_branch_refs([step["expected_impact"] for step in steps])
    plan = {
        "simulation_remediation_plan_version": SIMULATION_REMEDIATION_PLAN_VERSION,
        "simulation_remediation_plan_id": make_simulation_remediation_plan_id(dashboard, gaps, score, review),
        "simulation_dashboard_id": dashboard["simulation_dashboard_id"],
        "execution_gap_analysis_id": gaps["execution_gap_analysis_id"],
        "execution_readiness_score_id": score["execution_readiness_score_id"],
        "operator_simulation_review_package_id": review["operator_simulation_review_package_id"],
        "remediation_steps": steps,
        "priority_levels": list(REMEDIATION_PRIORITIES),
        "required_evidence": required_evidence,
        "required_approvals": required_approvals,
        "expected_impact": expected_impact,
        "blockers": list(review["blockers"]),
        "warnings": list(review["warnings"]),
        "recommended_next_action": "Start with critical evidence remediation, then approvals, before any runtime boundary design.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_simulation_remediation_plan(plan, dashboard, gaps, score, review)
    return plan


def validate_simulation_remediation_plan(
    plan: dict[str, Any],
    simulation_dashboard: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
    execution_readiness_score: dict[str, Any] | None = None,
    operator_simulation_review_package: dict[str, Any] | None = None,
) -> None:
    required = (
        "simulation_remediation_plan_version", "simulation_remediation_plan_id",
        "remediation_steps", "priority_levels", "required_evidence", "required_approvals",
        "expected_impact", "blockers", "warnings", "recommended_next_action", "safety_metadata",
        "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in plan:
            raise ValueError(f"simulation remediation plan missing required field: {key}")
    if plan["simulation_remediation_plan_version"] != SIMULATION_REMEDIATION_PLAN_VERSION:
        raise ValueError("invalid simulation remediation plan version")
    if not isinstance(plan["simulation_remediation_plan_id"], str) or not plan["simulation_remediation_plan_id"].startswith("simulation-remediation-plan-"):
        raise ValueError("invalid simulation remediation plan id")
    if plan["priority_levels"] != list(REMEDIATION_PRIORITIES):
        raise ValueError("simulation remediation priority levels mismatch")
    steps = plan["remediation_steps"]
    if not isinstance(steps, list) or not steps:
        raise ValueError("simulation remediation plan must include steps")
    seen: set[str] = set()
    for step in steps:
        if not isinstance(step, dict):
            raise TypeError("simulation remediation step must be a dict")
        for field in ("remediation_step_id", "description", "priority", "expected_impact", "dependencies", "required_evidence", "required_approvals", "execution_allowed"):
            if field not in step:
                raise ValueError(f"simulation remediation step missing {field}")
        if step["remediation_step_id"] in seen:
            raise ValueError("duplicate simulation remediation step id")
        seen.add(step["remediation_step_id"])
        if step["priority"] not in REMEDIATION_PRIORITIES:
            raise ValueError("invalid simulation remediation priority")
        if step["execution_allowed"] is not False:
            raise ValueError("simulation remediation steps must not allow execution")
        for field in ("dependencies", "required_evidence", "required_approvals"):
            if _normalize_implementation_branch_refs(step[field]) != step[field]:
                raise ValueError(f"simulation remediation step {field} must be normalized")
    for field in ("required_evidence", "expected_impact", "blockers", "warnings"):
        normalized = _normalize_implementation_branch_refs(plan[field])
        if not normalized or normalized != plan[field]:
            raise ValueError(f"simulation remediation plan {field} must be normalized and non-empty")
    if _normalize_implementation_branch_refs(plan["required_approvals"]) != plan["required_approvals"]:
        raise ValueError("simulation remediation plan required_approvals must be normalized")
    if plan["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("simulation remediation plan safety metadata mismatch")
    if plan["dry_run"] is not True or plan["write_allowed"] is not False:
        raise ValueError("simulation remediation plan must be read-only")
    if plan["automation_allowed"] is not False or plan["writes"] != []:
        raise ValueError("simulation remediation plan must not allow automation or writes")
    if all(item is not None for item in (simulation_dashboard, execution_gap_analysis, execution_readiness_score, operator_simulation_review_package)):
        expected_id = make_simulation_remediation_plan_id(simulation_dashboard, execution_gap_analysis, execution_readiness_score, operator_simulation_review_package)
        if plan["simulation_remediation_plan_id"] != expected_id:
            raise ValueError("simulation remediation plan id is not deterministic")


def stable_simulation_remediation_plan_json(plan: dict[str, Any]) -> str:
    validate_simulation_remediation_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_simulation_remediation_plan_json(text: str) -> dict[str, Any]:
    import json as _json

    plan = _json.loads(text)
    validate_simulation_remediation_plan(plan)
    return plan


def make_remediation_dependency_graph_id(plan: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "steps": [step["remediation_step_id"] for step in plan["remediation_steps"]],
        "version": REMEDIATION_DEPENDENCY_GRAPH_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"remediation-dependency-graph-{digest}"


def collect_remediation_dependency_graph(
    simulation_remediation_plan: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Model remediation prerequisites and blocked items without execution."""
    plan = simulation_remediation_plan or collect_simulation_remediation_plan()
    validate_simulation_remediation_plan(plan)
    edges = []
    for step in plan["remediation_steps"]:
        for dep in step["dependencies"]:
            edges.append({"from": dep, "to": step["remediation_step_id"], "relationship": "prerequisite"})
    critical_path = [step["remediation_step_id"] for step in plan["remediation_steps"]]
    blocked = [step["remediation_step_id"] for step in plan["remediation_steps"] if step["dependencies"] or step["priority"] in {"critical", "high"}]
    graph = {
        "remediation_dependency_graph_version": REMEDIATION_DEPENDENCY_GRAPH_VERSION,
        "remediation_dependency_graph_id": make_remediation_dependency_graph_id(plan),
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "dependency_edges": edges,
        "critical_path": critical_path,
        "blocked_items": _normalize_implementation_branch_refs(blocked),
        "recommended_next_action": "Follow the critical path from evidence remediation through approvals before runtime boundary design.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_remediation_dependency_graph(graph, plan)
    return graph


def validate_remediation_dependency_graph(graph: dict[str, Any], simulation_remediation_plan: dict[str, Any] | None = None) -> None:
    required = (
        "remediation_dependency_graph_version", "remediation_dependency_graph_id",
        "dependency_edges", "critical_path", "blocked_items", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in graph:
            raise ValueError(f"remediation dependency graph missing required field: {key}")
    if graph["remediation_dependency_graph_version"] != REMEDIATION_DEPENDENCY_GRAPH_VERSION:
        raise ValueError("invalid remediation dependency graph version")
    if not isinstance(graph["remediation_dependency_graph_id"], str) or not graph["remediation_dependency_graph_id"].startswith("remediation-dependency-graph-"):
        raise ValueError("invalid remediation dependency graph id")
    if not isinstance(graph["dependency_edges"], list):
        raise TypeError("remediation dependency graph edges must be a list")
    for edge in graph["dependency_edges"]:
        if not isinstance(edge, dict) or set(edge) != {"from", "to", "relationship"}:
            raise ValueError("invalid remediation dependency edge")
        if edge["relationship"] != "prerequisite":
            raise ValueError("invalid remediation dependency relationship")
    for field in ("critical_path", "blocked_items"):
        normalized = _normalize_implementation_branch_refs(graph[field])
        if not normalized or normalized != graph[field]:
            raise ValueError(f"remediation dependency graph {field} must be normalized and non-empty")
    if graph["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("remediation dependency graph safety metadata mismatch")
    if graph["dry_run"] is not True or graph["write_allowed"] is not False:
        raise ValueError("remediation dependency graph must be read-only")
    if graph["automation_allowed"] is not False or graph["writes"] != []:
        raise ValueError("remediation dependency graph must not allow automation or writes")
    if simulation_remediation_plan is not None:
        validate_simulation_remediation_plan(simulation_remediation_plan)
        if graph["simulation_remediation_plan_id"] != simulation_remediation_plan["simulation_remediation_plan_id"]:
            raise ValueError("remediation dependency graph plan id mismatch")
        if graph["remediation_dependency_graph_id"] != make_remediation_dependency_graph_id(simulation_remediation_plan):
            raise ValueError("remediation dependency graph id is not deterministic")


def stable_remediation_dependency_graph_json(graph: dict[str, Any]) -> str:
    validate_remediation_dependency_graph(graph)
    return _stable_ruflo_json(graph, indent=2) + "\n"


def parse_remediation_dependency_graph_json(text: str) -> dict[str, Any]:
    import json as _json

    graph = _json.loads(text)
    validate_remediation_dependency_graph(graph)
    return graph


def make_remediation_priority_queue_id(plan: dict[str, Any], graph: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "remediation_dependency_graph_id": graph["remediation_dependency_graph_id"],
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "version": REMEDIATION_PRIORITY_QUEUE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"remediation-priority-queue-{digest}"


def collect_remediation_priority_queue(
    simulation_remediation_plan: dict[str, Any] | None = None,
    remediation_dependency_graph: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Rank remediation fixes by priority, dependency order, and readiness gain."""
    plan = simulation_remediation_plan or collect_simulation_remediation_plan()
    validate_simulation_remediation_plan(plan)
    graph = remediation_dependency_graph or collect_remediation_dependency_graph(plan)
    validate_remediation_dependency_graph(graph, plan)
    priority_rank = {"critical": 0, "high": 1, "medium": 2, "low": 3}
    ordered_steps = sorted(plan["remediation_steps"], key=lambda step: (priority_rank[step["priority"]], len(step["dependencies"]), step["remediation_step_id"]))
    queue_order = [step["remediation_step_id"] for step in ordered_steps]
    gain_map = {"critical": 25, "high": 18, "medium": 10, "low": 5}
    estimates = [
        {"remediation_step_id": step["remediation_step_id"], "estimated_readiness_gain": gain_map[step["priority"]]}
        for step in ordered_steps
    ]
    items = [
        {
            "priority_item_id": f"priority-item-{index:02d}",
            "remediation_step_id": step["remediation_step_id"],
            "priority": step["priority"],
            "description": step["description"],
            "blocked": step["remediation_step_id"] in graph["blocked_items"],
        }
        for index, step in enumerate(ordered_steps, start=1)
    ]
    queue = {
        "remediation_priority_queue_version": REMEDIATION_PRIORITY_QUEUE_VERSION,
        "remediation_priority_queue_id": make_remediation_priority_queue_id(plan, graph),
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "remediation_dependency_graph_id": graph["remediation_dependency_graph_id"],
        "priority_items": items,
        "queue_order": queue_order,
        "readiness_gain_estimates": estimates,
        "recommended_next_action": "Work the queue from critical evidence and approval items before boundary design.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_remediation_priority_queue(queue, plan, graph)
    return queue


def validate_remediation_priority_queue(queue: dict[str, Any], simulation_remediation_plan: dict[str, Any] | None = None, remediation_dependency_graph: dict[str, Any] | None = None) -> None:
    required = (
        "remediation_priority_queue_version", "remediation_priority_queue_id",
        "priority_items", "queue_order", "readiness_gain_estimates", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in queue:
            raise ValueError(f"remediation priority queue missing required field: {key}")
    if queue["remediation_priority_queue_version"] != REMEDIATION_PRIORITY_QUEUE_VERSION:
        raise ValueError("invalid remediation priority queue version")
    if not isinstance(queue["remediation_priority_queue_id"], str) or not queue["remediation_priority_queue_id"].startswith("remediation-priority-queue-"):
        raise ValueError("invalid remediation priority queue id")
    if not isinstance(queue["priority_items"], list) or not queue["priority_items"]:
        raise ValueError("remediation priority queue must include priority items")
    if _normalize_implementation_branch_refs(queue["queue_order"]) != queue["queue_order"]:
        raise ValueError("remediation priority queue order must be normalized")
    if len(queue["queue_order"]) != len(queue["priority_items"]):
        raise ValueError("remediation priority queue order must match item count")
    seen = {item["remediation_step_id"] for item in queue["priority_items"] if isinstance(item, dict) and "remediation_step_id" in item}
    if seen != set(queue["queue_order"]):
        raise ValueError("remediation priority queue items must match queue order")
    if not isinstance(queue["readiness_gain_estimates"], list) or len(queue["readiness_gain_estimates"]) != len(queue["priority_items"]):
        raise ValueError("remediation priority queue gain estimates must match item count")
    for estimate in queue["readiness_gain_estimates"]:
        if not isinstance(estimate, dict) or "estimated_readiness_gain" not in estimate:
            raise ValueError("invalid remediation readiness gain estimate")
        if not isinstance(estimate["estimated_readiness_gain"], int) or estimate["estimated_readiness_gain"] <= 0:
            raise ValueError("readiness gain estimate must be positive")
    if queue["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("remediation priority queue safety metadata mismatch")
    if queue["dry_run"] is not True or queue["write_allowed"] is not False:
        raise ValueError("remediation priority queue must be read-only")
    if queue["automation_allowed"] is not False or queue["writes"] != []:
        raise ValueError("remediation priority queue must not allow automation or writes")
    if simulation_remediation_plan is not None and remediation_dependency_graph is not None:
        validate_simulation_remediation_plan(simulation_remediation_plan)
        validate_remediation_dependency_graph(remediation_dependency_graph, simulation_remediation_plan)
        if queue["remediation_priority_queue_id"] != make_remediation_priority_queue_id(simulation_remediation_plan, remediation_dependency_graph):
            raise ValueError("remediation priority queue id is not deterministic")


def stable_remediation_priority_queue_json(queue: dict[str, Any]) -> str:
    validate_remediation_priority_queue(queue)
    return _stable_ruflo_json(queue, indent=2) + "\n"


def parse_remediation_priority_queue_json(text: str) -> dict[str, Any]:
    import json as _json

    queue = _json.loads(text)
    validate_remediation_priority_queue(queue)
    return queue


def make_operator_remediation_review_id(plan: dict[str, Any], graph: dict[str, Any], queue: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "remediation_dependency_graph_id": graph["remediation_dependency_graph_id"],
        "remediation_priority_queue_id": queue["remediation_priority_queue_id"],
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "version": OPERATOR_REMEDIATION_REVIEW_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-remediation-review-{digest}"


def collect_operator_remediation_review(
    simulation_remediation_plan: dict[str, Any] | None = None,
    remediation_dependency_graph: dict[str, Any] | None = None,
    remediation_priority_queue: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Summarize what should be fixed first in the simulation remediation plan."""
    plan = simulation_remediation_plan or collect_simulation_remediation_plan()
    validate_simulation_remediation_plan(plan)
    graph = remediation_dependency_graph or collect_remediation_dependency_graph(plan)
    validate_remediation_dependency_graph(graph, plan)
    queue = remediation_priority_queue or collect_remediation_priority_queue(plan, graph)
    validate_remediation_priority_queue(queue, plan, graph)
    first = queue["queue_order"][0]
    review = {
        "operator_remediation_review_version": OPERATOR_REMEDIATION_REVIEW_VERSION,
        "operator_remediation_review_id": make_operator_remediation_review_id(plan, graph, queue),
        "remediation_plan_id": plan["simulation_remediation_plan_id"],
        "dependency_graph_id": graph["remediation_dependency_graph_id"],
        "priority_queue_id": queue["remediation_priority_queue_id"],
        "blockers": list(plan["blockers"]),
        "warnings": list(plan["warnings"]),
        "required_human_actions": _normalize_implementation_branch_refs(list(plan["required_approvals"]) + [f"review first remediation step: {first}"]),
        "review_recommendation": "fix_critical_evidence_first",
        "recommended_next_action": f"Start with {first}, then follow the remediation priority queue.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_remediation_review(review, plan, graph, queue)
    return review


def validate_operator_remediation_review(review: dict[str, Any], simulation_remediation_plan: dict[str, Any] | None = None, remediation_dependency_graph: dict[str, Any] | None = None, remediation_priority_queue: dict[str, Any] | None = None) -> None:
    required = (
        "operator_remediation_review_version", "operator_remediation_review_id", "remediation_plan_id",
        "dependency_graph_id", "priority_queue_id", "blockers", "warnings", "required_human_actions",
        "review_recommendation", "recommended_next_action", "safety_metadata", "dry_run",
        "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in review:
            raise ValueError(f"operator remediation review missing required field: {key}")
    if review["operator_remediation_review_version"] != OPERATOR_REMEDIATION_REVIEW_VERSION:
        raise ValueError("invalid operator remediation review version")
    if not isinstance(review["operator_remediation_review_id"], str) or not review["operator_remediation_review_id"].startswith("operator-remediation-review-"):
        raise ValueError("invalid operator remediation review id")
    for field in ("blockers", "warnings", "required_human_actions"):
        normalized = _normalize_implementation_branch_refs(review[field])
        if not normalized or normalized != review[field]:
            raise ValueError(f"operator remediation review {field} must be normalized and non-empty")
    if review["review_recommendation"] != "fix_critical_evidence_first":
        raise ValueError("invalid operator remediation recommendation")
    if review["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("operator remediation review safety metadata mismatch")
    if review["dry_run"] is not True or review["write_allowed"] is not False:
        raise ValueError("operator remediation review must be read-only")
    if review["automation_allowed"] is not False or review["writes"] != []:
        raise ValueError("operator remediation review must not allow automation or writes")
    if simulation_remediation_plan is not None and remediation_dependency_graph is not None and remediation_priority_queue is not None:
        validate_simulation_remediation_plan(simulation_remediation_plan)
        validate_remediation_dependency_graph(remediation_dependency_graph, simulation_remediation_plan)
        validate_remediation_priority_queue(remediation_priority_queue, simulation_remediation_plan, remediation_dependency_graph)
        if review["operator_remediation_review_id"] != make_operator_remediation_review_id(simulation_remediation_plan, remediation_dependency_graph, remediation_priority_queue):
            raise ValueError("operator remediation review id is not deterministic")


def stable_operator_remediation_review_json(review: dict[str, Any]) -> str:
    validate_operator_remediation_review(review)
    return _stable_ruflo_json(review, indent=2) + "\n"


def parse_operator_remediation_review_json(text: str) -> dict[str, Any]:
    import json as _json

    review = _json.loads(text)
    validate_operator_remediation_review(review)
    return review



def _collect_remediation_projection_chain(
    simulation_remediation_plan: dict[str, Any] | None = None,
    remediation_priority_queue: dict[str, Any] | None = None,
    operator_remediation_review: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    plan = simulation_remediation_plan or collect_simulation_remediation_plan()
    validate_simulation_remediation_plan(plan)
    graph = collect_remediation_dependency_graph(plan)
    queue = remediation_priority_queue or collect_remediation_priority_queue(plan, graph)
    validate_remediation_priority_queue(queue, plan, graph)
    review = operator_remediation_review or collect_operator_remediation_review(plan, graph, queue)
    validate_operator_remediation_review(review, plan, graph, queue)
    return plan, queue, review


def make_sandbox_readiness_projection_id(
    remediation_plan: dict[str, Any],
    priority_queue: dict[str, Any],
    remediation_review: dict[str, Any],
    business_execution_review_package: dict[str, Any],
    business_readiness_review_package: dict[str, Any],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "business_execution_review_package_id": business_execution_review_package["business_execution_review_package_id"],
        "business_readiness_review_package_id": business_readiness_review_package["business_readiness_review_package_id"],
        "operator_remediation_review_id": remediation_review["operator_remediation_review_id"],
        "remediation_priority_queue_id": priority_queue["remediation_priority_queue_id"],
        "simulation_remediation_plan_id": remediation_plan["simulation_remediation_plan_id"],
        "version": SANDBOX_READINESS_PROJECTION_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"sandbox-readiness-projection-{digest}"


def collect_sandbox_readiness_projection(
    simulation_remediation_plan: dict[str, Any] | None = None,
    remediation_priority_queue: dict[str, Any] | None = None,
    operator_remediation_review: dict[str, Any] | None = None,
    business_execution_review_package: dict[str, Any] | None = None,
    business_readiness_review_package: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Project readiness after remediation without executing remediation."""
    plan, queue, remediation_review = _collect_remediation_projection_chain(
        simulation_remediation_plan,
        remediation_priority_queue,
        operator_remediation_review,
    )
    readiness_review = business_readiness_review_package or collect_business_readiness_review_package()
    validate_business_readiness_review_package(readiness_review)
    execution_review = business_execution_review_package or collect_business_execution_review_package(business_readiness_review_package=readiness_review)
    validate_business_execution_review_package(execution_review)
    unresolved_blockers = _normalize_implementation_branch_refs([
        blocker for blocker in remediation_review["blockers"]
        if "blocked real action" in blocker or "receipts are intentionally simulated" in blocker
    ])
    projected_warnings = _normalize_implementation_branch_refs(list(remediation_review["warnings"]) + [
        "sandbox projection assumes remediation evidence is completed but not verified by runtime",
        "sandbox projection does not grant execution permission",
    ])
    current_status = readiness_review["readiness_status"]
    projected_status = "ready_for_review" if not unresolved_blockers else "blocked"
    projection = {
        "sandbox_readiness_projection_version": SANDBOX_READINESS_PROJECTION_VERSION,
        "sandbox_readiness_projection_id": make_sandbox_readiness_projection_id(plan, queue, remediation_review, execution_review, readiness_review),
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "remediation_priority_queue_id": queue["remediation_priority_queue_id"],
        "operator_remediation_review_id": remediation_review["operator_remediation_review_id"],
        "business_execution_review_package_id": execution_review["business_execution_review_package_id"],
        "business_readiness_review_package_id": readiness_review["business_readiness_review_package_id"],
        "current_readiness_status": current_status,
        "projected_readiness_status": projected_status,
        "projected_blockers_remaining": unresolved_blockers,
        "projected_warnings_remaining": projected_warnings,
        "readiness_delta": "improves_to_review" if projected_status != current_status else "blocked_real_actions_remain",
        "assumptions": _normalize_implementation_branch_refs([
            "all remediation steps are completed outside this sandbox projection",
            "all required remediation evidence is reviewed by a human",
            "all required approvals are explicitly granted by a human",
            "no real execution action is attempted by the sandbox projection",
        ]),
        "recommended_next_action": "Review remaining projected blockers before deciding whether execution could ever be allowed.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_sandbox_readiness_projection(projection, plan, queue, remediation_review, execution_review, readiness_review)
    return projection


def validate_sandbox_readiness_projection(
    projection: dict[str, Any],
    simulation_remediation_plan: dict[str, Any] | None = None,
    remediation_priority_queue: dict[str, Any] | None = None,
    operator_remediation_review: dict[str, Any] | None = None,
    business_execution_review_package: dict[str, Any] | None = None,
    business_readiness_review_package: dict[str, Any] | None = None,
) -> None:
    required = (
        "sandbox_readiness_projection_version", "sandbox_readiness_projection_id",
        "current_readiness_status", "projected_readiness_status", "projected_blockers_remaining",
        "projected_warnings_remaining", "readiness_delta", "assumptions", "recommended_next_action",
        "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes",
    )
    for key in required:
        if key not in projection:
            raise ValueError(f"sandbox readiness projection missing required field: {key}")
    if projection["sandbox_readiness_projection_version"] != SANDBOX_READINESS_PROJECTION_VERSION:
        raise ValueError("invalid sandbox readiness projection version")
    if not isinstance(projection["sandbox_readiness_projection_id"], str) or not projection["sandbox_readiness_projection_id"].startswith("sandbox-readiness-projection-"):
        raise ValueError("invalid sandbox readiness projection id")
    if projection["current_readiness_status"] not in BUSINESS_READINESS_RECOMMENDATIONS + BUSINESS_OPERATIONS_READINESS_STATUSES + GOVERNANCE_OVERALL_STATUSES:
        raise ValueError("invalid sandbox current readiness status")
    if projection["projected_readiness_status"] not in GOVERNANCE_OVERALL_STATUSES:
        raise ValueError("invalid sandbox projected readiness status")
    for field in ("projected_warnings_remaining", "assumptions"):
        normalized = _normalize_implementation_branch_refs(projection[field])
        if not normalized or normalized != projection[field]:
            raise ValueError(f"sandbox readiness projection {field} must be normalized and non-empty")
    if _normalize_implementation_branch_refs(projection["projected_blockers_remaining"]) != projection["projected_blockers_remaining"]:
        raise ValueError("sandbox readiness projection blockers must be normalized")
    if projection["safety_metadata"] != _read_only_safety_metadata():
        raise ValueError("sandbox readiness projection safety metadata mismatch")
    if projection["dry_run"] is not True or projection["write_allowed"] is not False:
        raise ValueError("sandbox readiness projection must be read-only")
    if projection["automation_allowed"] is not False or projection["writes"] != []:
        raise ValueError("sandbox readiness projection must not allow automation or writes")
    if all(item is not None for item in (simulation_remediation_plan, remediation_priority_queue, operator_remediation_review, business_execution_review_package, business_readiness_review_package)):
        expected_id = make_sandbox_readiness_projection_id(simulation_remediation_plan, remediation_priority_queue, operator_remediation_review, business_execution_review_package, business_readiness_review_package)
        if projection["sandbox_readiness_projection_id"] != expected_id:
            raise ValueError("sandbox readiness projection id is not deterministic")


def stable_sandbox_readiness_projection_json(projection: dict[str, Any]) -> str:
    validate_sandbox_readiness_projection(projection)
    return _stable_ruflo_json(projection, indent=2) + "\n"


def parse_sandbox_readiness_projection_json(text: str) -> dict[str, Any]:
    import json as _json

    projection = _json.loads(text)
    validate_sandbox_readiness_projection(projection)
    return projection


