def make_sandbox_outcome_projection_id(readiness_projection: dict[str, Any], evidence_projection: dict[str, Any], approval_projection: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "sandbox_approval_projection_id": approval_projection["sandbox_approval_projection_id"],
        "sandbox_evidence_projection_id": evidence_projection["sandbox_evidence_projection_id"],
        "sandbox_readiness_projection_id": readiness_projection["sandbox_readiness_projection_id"],
        "version": SANDBOX_OUTCOME_PROJECTION_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"sandbox-outcome-projection-{digest}"


def collect_sandbox_outcome_projection(sandbox_readiness_projection: dict[str, Any] | None = None, sandbox_evidence_projection: dict[str, Any] | None = None, sandbox_approval_projection: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    """Project whether execution could be allowed after remediation assumptions."""
    readiness = sandbox_readiness_projection or collect_sandbox_readiness_projection()
    validate_sandbox_readiness_projection(readiness)
    evidence = sandbox_evidence_projection or collect_sandbox_evidence_projection(readiness)
    validate_sandbox_evidence_projection(evidence)
    approvals = sandbox_approval_projection or collect_sandbox_approval_projection(readiness)
    validate_sandbox_approval_projection(approvals)
    blockers = _normalize_implementation_branch_refs(list(readiness["projected_blockers_remaining"]) + list(evidence["projected_missing_evidence"]) + list(approvals["projected_missing_approvals"]))
    allowed = readiness["projected_readiness_status"] == "ready_for_review" and not blockers
    warnings = list(readiness["projected_warnings_remaining"])
    outcome = {
        "sandbox_outcome_projection_version": SANDBOX_OUTCOME_PROJECTION_VERSION,
        "sandbox_outcome_projection_id": make_sandbox_outcome_projection_id(readiness, evidence, approvals),
        "sandbox_readiness_projection_id": readiness["sandbox_readiness_projection_id"],
        "projected_execution_allowed": allowed,
        "projected_execution_blockers": blockers,
        "projected_execution_warnings": warnings,
        "outcome_summary": "execution remains blocked in sandbox projection" if not allowed else "execution could become reviewable after remediation",
        "recommended_next_action": "Resolve projected blockers before any execution runtime is considered.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_sandbox_outcome_projection(outcome, readiness, evidence, approvals)
    return outcome


def validate_sandbox_outcome_projection(outcome: dict[str, Any], sandbox_readiness_projection: dict[str, Any] | None = None, sandbox_evidence_projection: dict[str, Any] | None = None, sandbox_approval_projection: dict[str, Any] | None = None) -> None:
    required = ("sandbox_outcome_projection_version", "sandbox_outcome_projection_id", "sandbox_readiness_projection_id", "projected_execution_allowed", "projected_execution_blockers", "projected_execution_warnings", "outcome_summary", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in outcome:
            raise ValueError(f"sandbox outcome projection missing required field: {key}")
    if outcome["sandbox_outcome_projection_version"] != SANDBOX_OUTCOME_PROJECTION_VERSION:
        raise ValueError("invalid sandbox outcome projection version")
    if not isinstance(outcome["sandbox_outcome_projection_id"], str) or not outcome["sandbox_outcome_projection_id"].startswith("sandbox-outcome-projection-"):
        raise ValueError("invalid sandbox outcome projection id")
    if not isinstance(outcome["projected_execution_allowed"], bool):
        raise ValueError("sandbox outcome projected_execution_allowed must be bool")
    for field in ("projected_execution_blockers", "projected_execution_warnings"):
        normalized = _normalize_implementation_branch_refs(outcome[field])
        if normalized != outcome[field]:
            raise ValueError(f"sandbox outcome projection {field} must be normalized")
    if outcome["projected_execution_allowed"] and outcome["projected_execution_blockers"]:
        raise ValueError("sandbox outcome cannot allow execution with blockers")
    if outcome["safety_metadata"] != _read_only_safety_metadata() or outcome["dry_run"] is not True or outcome["write_allowed"] is not False or outcome["automation_allowed"] is not False or outcome["writes"] != []:
        raise ValueError("sandbox outcome projection must be read-only")
    if sandbox_readiness_projection is not None and sandbox_evidence_projection is not None and sandbox_approval_projection is not None:
        if outcome["sandbox_outcome_projection_id"] != make_sandbox_outcome_projection_id(sandbox_readiness_projection, sandbox_evidence_projection, sandbox_approval_projection):
            raise ValueError("sandbox outcome projection id is not deterministic")


def stable_sandbox_outcome_projection_json(outcome: dict[str, Any]) -> str:
    validate_sandbox_outcome_projection(outcome)
    return _stable_ruflo_json(outcome, indent=2) + "\n"


def parse_sandbox_outcome_projection_json(text: str) -> dict[str, Any]:
    import json as _json

    outcome = _json.loads(text)
    validate_sandbox_outcome_projection(outcome)
    return outcome


def make_sandbox_review_package_id(readiness: dict[str, Any], evidence: dict[str, Any], approvals: dict[str, Any], outcome: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "sandbox_approval_projection_id": approvals["sandbox_approval_projection_id"],
        "sandbox_evidence_projection_id": evidence["sandbox_evidence_projection_id"],
        "sandbox_outcome_projection_id": outcome["sandbox_outcome_projection_id"],
        "sandbox_readiness_projection_id": readiness["sandbox_readiness_projection_id"],
        "version": SANDBOX_REVIEW_PACKAGE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"sandbox-review-package-{digest}"


def collect_sandbox_review_package(sandbox_readiness_projection: dict[str, Any] | None = None, sandbox_evidence_projection: dict[str, Any] | None = None, sandbox_approval_projection: dict[str, Any] | None = None, sandbox_outcome_projection: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    """Produce an operator-facing sandbox projection review package."""
    readiness = sandbox_readiness_projection or collect_sandbox_readiness_projection()
    validate_sandbox_readiness_projection(readiness)
    evidence = sandbox_evidence_projection or collect_sandbox_evidence_projection(readiness)
    validate_sandbox_evidence_projection(evidence)
    approvals = sandbox_approval_projection or collect_sandbox_approval_projection(readiness)
    validate_sandbox_approval_projection(approvals)
    outcome = sandbox_outcome_projection or collect_sandbox_outcome_projection(readiness, evidence, approvals)
    validate_sandbox_outcome_projection(outcome, readiness, evidence, approvals)
    blockers = list(outcome["projected_execution_blockers"])
    warnings = _normalize_implementation_branch_refs(list(outcome["projected_execution_warnings"]) + ["sandbox projection is not execution authorization"])
    package = {
        "sandbox_review_package_version": SANDBOX_REVIEW_PACKAGE_VERSION,
        "sandbox_review_package_id": make_sandbox_review_package_id(readiness, evidence, approvals, outcome),
        "sandbox_readiness_projection_id": readiness["sandbox_readiness_projection_id"],
        "sandbox_evidence_projection_id": evidence["sandbox_evidence_projection_id"],
        "sandbox_approval_projection_id": approvals["sandbox_approval_projection_id"],
        "sandbox_outcome_projection_id": outcome["sandbox_outcome_projection_id"],
        "current_status": readiness["current_readiness_status"],
        "projected_status": readiness["projected_readiness_status"],
        "blockers_remaining": blockers,
        "warnings_remaining": warnings,
        "required_human_actions": _normalize_implementation_branch_refs(["review sandbox assumptions", "verify projected evidence", "verify projected approvals"]),
        "review_recommendation": "projection_still_blocked" if blockers else "projection_ready_for_boundary_review",
        "recommended_next_action": "Use sandbox projection to decide which remediation evidence and approvals to verify next.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_sandbox_review_package(package, readiness, evidence, approvals, outcome)
    return package


def validate_sandbox_review_package(package: dict[str, Any], sandbox_readiness_projection: dict[str, Any] | None = None, sandbox_evidence_projection: dict[str, Any] | None = None, sandbox_approval_projection: dict[str, Any] | None = None, sandbox_outcome_projection: dict[str, Any] | None = None) -> None:
    required = ("sandbox_review_package_version", "sandbox_review_package_id", "sandbox_readiness_projection_id", "sandbox_evidence_projection_id", "sandbox_approval_projection_id", "sandbox_outcome_projection_id", "current_status", "projected_status", "blockers_remaining", "warnings_remaining", "required_human_actions", "review_recommendation", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in package:
            raise ValueError(f"sandbox review package missing required field: {key}")
    if package["sandbox_review_package_version"] != SANDBOX_REVIEW_PACKAGE_VERSION:
        raise ValueError("invalid sandbox review package version")
    if not isinstance(package["sandbox_review_package_id"], str) or not package["sandbox_review_package_id"].startswith("sandbox-review-package-"):
        raise ValueError("invalid sandbox review package id")
    for field in ("blockers_remaining", "warnings_remaining", "required_human_actions"):
        normalized = _normalize_implementation_branch_refs(package[field])
        if normalized != package[field] or not package[field]:
            raise ValueError(f"sandbox review package {field} must be normalized and non-empty")
    if package["review_recommendation"] not in {"projection_still_blocked", "projection_ready_for_boundary_review"}:
        raise ValueError("invalid sandbox review recommendation")
    if package["safety_metadata"] != _read_only_safety_metadata() or package["dry_run"] is not True or package["write_allowed"] is not False or package["automation_allowed"] is not False or package["writes"] != []:
        raise ValueError("sandbox review package must be read-only")
    if all(item is not None for item in (sandbox_readiness_projection, sandbox_evidence_projection, sandbox_approval_projection, sandbox_outcome_projection)):
        if package["sandbox_review_package_id"] != make_sandbox_review_package_id(sandbox_readiness_projection, sandbox_evidence_projection, sandbox_approval_projection, sandbox_outcome_projection):
            raise ValueError("sandbox review package id is not deterministic")


def stable_sandbox_review_package_json(package: dict[str, Any]) -> str:
    validate_sandbox_review_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_sandbox_review_package_json(text: str) -> dict[str, Any]:
    import json as _json

    package = _json.loads(text)
    validate_sandbox_review_package(package)
    return package



def _decision_priority_effort(priority: str) -> int:
    return {"critical": 3, "high": 2, "medium": 1, "low": 1}.get(priority, 3)


def make_decision_candidate_id(step: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "remediation_step_id": step["remediation_step_id"],
        "priority": step["priority"],
        "version": DECISION_CANDIDATE_SET_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"decision-candidate-{digest}"


def _decision_candidate_from_step(step: dict[str, Any], queue: dict[str, Any], sandbox_review: dict[str, Any], gaps: dict[str, Any], remediation_review: dict[str, Any]) -> dict[str, Any]:
    gain_map = {
        item["remediation_step_id"]: item["estimated_readiness_gain"]
        for item in queue["readiness_gain_estimates"]
    }
    priority_item = next((item for item in queue["priority_items"] if item["remediation_step_id"] == step["remediation_step_id"]), {})
    blockers = []
    if priority_item.get("blocked"):
        blockers.append(f"prerequisites remain for {step['remediation_step_id']}")
    blockers.extend(item for item in remediation_review["blockers"] if "blocked real action" in item)
    blockers = _normalize_implementation_branch_refs(blockers[:5])
    evidence_gain = len(step["required_evidence"]) * 5
    approval_gain = len(step["required_approvals"]) * 5
    risk_reduction = 12 if step["priority"] == "critical" else 9 if step["priority"] == "high" else 5 if step["priority"] == "medium" else 2
    return {
        "decision_candidate_id": make_decision_candidate_id(step),
        "title": step["description"],
        "description": f"Complete {step['remediation_step_id']} to improve projected execution readiness.",
        "source_refs": _normalize_implementation_branch_refs([
            step["remediation_step_id"],
            queue["remediation_priority_queue_id"],
            sandbox_review["sandbox_review_package_id"],
            gaps["execution_gap_analysis_id"],
            remediation_review["operator_remediation_review_id"],
        ]),
        "expected_readiness_gain": gain_map.get(step["remediation_step_id"], 0),
        "expected_risk_reduction": risk_reduction,
        "expected_evidence_gain": evidence_gain,
        "expected_approval_gain": approval_gain,
        "effort_score": _decision_priority_effort(step["priority"]),
        "priority": step["priority"],
        "blockers": blockers,
        "execution_allowed": False,
    }


def make_decision_candidate_set_id(candidates: list[dict[str, Any]], sandbox_review: dict[str, Any], gaps: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "candidate_ids": [candidate["decision_candidate_id"] for candidate in candidates],
        "execution_gap_analysis_id": gaps["execution_gap_analysis_id"],
        "sandbox_review_package_id": sandbox_review["sandbox_review_package_id"],
        "version": DECISION_CANDIDATE_SET_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"decision-candidate-set-{digest}"


def collect_decision_candidate_set(
    simulation_remediation_plan: dict[str, Any] | None = None,
    remediation_priority_queue: dict[str, Any] | None = None,
    sandbox_review_package: dict[str, Any] | None = None,
    execution_gap_analysis: dict[str, Any] | None = None,
    operator_remediation_review: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build deterministic read-only remediation decision candidates."""
    plan = simulation_remediation_plan or collect_simulation_remediation_plan()
    validate_simulation_remediation_plan(plan)
    graph = collect_remediation_dependency_graph(plan)
    queue = remediation_priority_queue or collect_remediation_priority_queue(plan, graph)
    validate_remediation_priority_queue(queue, plan, graph)
    remediation_review = operator_remediation_review or collect_operator_remediation_review(plan, graph, queue)
    validate_operator_remediation_review(remediation_review, plan, graph, queue)
    if sandbox_review_package is None:
        readiness_review = collect_business_readiness_review_package()
        execution_review = collect_business_execution_review_package(business_readiness_review_package=readiness_review)
        readiness = collect_sandbox_readiness_projection(plan, queue, remediation_review, execution_review, readiness_review)
        evidence = collect_sandbox_evidence_projection(readiness, plan)
        approvals = collect_sandbox_approval_projection(readiness, plan)
        outcome = collect_sandbox_outcome_projection(readiness, evidence, approvals)
        sandbox_review = collect_sandbox_review_package(readiness, evidence, approvals, outcome)
    else:
        sandbox_review = sandbox_review_package
    validate_sandbox_review_package(sandbox_review)
    gaps = execution_gap_analysis or collect_execution_gap_analysis()
    validate_execution_gap_analysis(gaps)
    candidates = [_decision_candidate_from_step(step, queue, sandbox_review, gaps, remediation_review) for step in plan["remediation_steps"]]
    blocked = [candidate for candidate in candidates if candidate["blockers"]]
    candidate_set = {
        "decision_candidate_set_version": DECISION_CANDIDATE_SET_VERSION,
        "decision_candidate_set_id": make_decision_candidate_set_id(candidates, sandbox_review, gaps),
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "remediation_priority_queue_id": queue["remediation_priority_queue_id"],
        "sandbox_review_package_id": sandbox_review["sandbox_review_package_id"],
        "execution_gap_analysis_id": gaps["execution_gap_analysis_id"],
        "operator_remediation_review_id": remediation_review["operator_remediation_review_id"],
        "candidates": candidates,
        "blocked_candidates": blocked,
        "decision_context": {
            "question": "If we only do one thing next, what should it be?",
            "candidate_count": len(candidates),
            "blocked_candidate_count": len(blocked),
            "execution_allowed": False,
        },
        "recommended_next_action": "Rank remediation candidates and choose the highest-value read-only next action.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_decision_candidate_set(candidate_set, plan, queue, sandbox_review, gaps, remediation_review)
    return candidate_set


def validate_decision_candidate(candidate: dict[str, Any]) -> None:
    required = ("decision_candidate_id", "title", "description", "source_refs", "expected_readiness_gain", "expected_risk_reduction", "expected_evidence_gain", "expected_approval_gain", "effort_score", "priority", "blockers", "execution_allowed")
    for key in required:
        if key not in candidate:
            raise ValueError(f"decision candidate missing required field: {key}")
    if not isinstance(candidate["decision_candidate_id"], str) or not candidate["decision_candidate_id"].startswith("decision-candidate-"):
        raise ValueError("invalid decision candidate id")
    if candidate["priority"] not in REMEDIATION_PRIORITIES:
        raise ValueError("invalid decision candidate priority")
    for field in ("source_refs", "blockers"):
        if _normalize_implementation_branch_refs(candidate[field]) != candidate[field]:
            raise ValueError(f"decision candidate {field} must be normalized")
    for field in ("expected_readiness_gain", "expected_risk_reduction", "expected_evidence_gain", "expected_approval_gain", "effort_score"):
        if not isinstance(candidate[field], int) or candidate[field] < 0:
            raise ValueError(f"decision candidate {field} must be non-negative integer")
    if candidate["execution_allowed"] is not False:
        raise ValueError("decision candidates must not allow execution")


def validate_decision_candidate_set(candidate_set: dict[str, Any], simulation_remediation_plan: dict[str, Any] | None = None, remediation_priority_queue: dict[str, Any] | None = None, sandbox_review_package: dict[str, Any] | None = None, execution_gap_analysis: dict[str, Any] | None = None, operator_remediation_review: dict[str, Any] | None = None) -> None:
    required = ("decision_candidate_set_version", "decision_candidate_set_id", "candidates", "blocked_candidates", "decision_context", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in candidate_set:
            raise ValueError(f"decision candidate set missing required field: {key}")
    if candidate_set["decision_candidate_set_version"] != DECISION_CANDIDATE_SET_VERSION:
        raise ValueError("invalid decision candidate set version")
    if not isinstance(candidate_set["decision_candidate_set_id"], str) or not candidate_set["decision_candidate_set_id"].startswith("decision-candidate-set-"):
        raise ValueError("invalid decision candidate set id")
    if not isinstance(candidate_set["candidates"], list) or not candidate_set["candidates"]:
        raise ValueError("decision candidate set must include candidates")
    for candidate in candidate_set["candidates"]:
        validate_decision_candidate(candidate)
    if not isinstance(candidate_set["blocked_candidates"], list):
        raise TypeError("blocked decision candidates must be a list")
    for candidate in candidate_set["blocked_candidates"]:
        validate_decision_candidate(candidate)
        if not candidate["blockers"]:
            raise ValueError("blocked decision candidates must include blockers")
    if not isinstance(candidate_set["decision_context"], dict) or candidate_set["decision_context"].get("execution_allowed") is not False:
        raise ValueError("decision context must keep execution disabled")
    if candidate_set["safety_metadata"] != _read_only_safety_metadata() or candidate_set["dry_run"] is not True or candidate_set["write_allowed"] is not False or candidate_set["automation_allowed"] is not False or candidate_set["writes"] != []:
        raise ValueError("decision candidate set must be read-only")
    if all(item is not None for item in (simulation_remediation_plan, remediation_priority_queue, sandbox_review_package, execution_gap_analysis, operator_remediation_review)):
        expected_id = make_decision_candidate_set_id(candidate_set["candidates"], sandbox_review_package, execution_gap_analysis)
        if candidate_set["decision_candidate_set_id"] != expected_id:
            raise ValueError("decision candidate set id is not deterministic")


def stable_decision_candidate_set_json(candidate_set: dict[str, Any]) -> str:
    validate_decision_candidate_set(candidate_set)
    return _stable_ruflo_json(candidate_set, indent=2) + "\n"


def parse_decision_candidate_set_json(text: str) -> dict[str, Any]:
    import json as _json

    candidate_set = _json.loads(text)
    validate_decision_candidate_set(candidate_set)
    return candidate_set


def make_decision_impact_analysis_id(candidate_set: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "candidate_ids": [candidate["decision_candidate_id"] for candidate in candidate_set["candidates"]],
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "version": DECISION_IMPACT_ANALYSIS_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"decision-impact-analysis-{digest}"


def collect_decision_impact_analysis(decision_candidate_set: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    candidate_set = decision_candidate_set or collect_decision_candidate_set()
    validate_decision_candidate_set(candidate_set)
    candidates = candidate_set["candidates"]
    impact_items = [
        {
            "decision_candidate_id": candidate["decision_candidate_id"],
            "readiness_gain": candidate["expected_readiness_gain"],
            "risk_reduction": candidate["expected_risk_reduction"],
            "evidence_gain": candidate["expected_evidence_gain"],
            "approval_gain": candidate["expected_approval_gain"],
            "effort_score": candidate["effort_score"],
            "blocker_count": len(candidate["blockers"]),
        }
        for candidate in candidates
    ]
    highest_readiness = max(candidates, key=lambda candidate: (candidate["expected_readiness_gain"], candidate["decision_candidate_id"]))
    highest_risk = max(candidates, key=lambda candidate: (candidate["expected_risk_reduction"], candidate["decision_candidate_id"]))
    lowest_effort = min(candidates, key=lambda candidate: (candidate["effort_score"], candidate["decision_candidate_id"]))
    analysis = {
        "decision_impact_analysis_version": DECISION_IMPACT_ANALYSIS_VERSION,
        "decision_impact_analysis_id": make_decision_impact_analysis_id(candidate_set),
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "impact_items": impact_items,
        "highest_readiness_gain_candidate_id": highest_readiness["decision_candidate_id"],
        "highest_risk_reduction_candidate_id": highest_risk["decision_candidate_id"],
        "lowest_effort_candidate_id": lowest_effort["decision_candidate_id"],
        "recommended_next_action": "Use deterministic impact analysis as input to candidate ranking.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_decision_impact_analysis(analysis, candidate_set)
    return analysis


def validate_decision_impact_analysis(analysis: dict[str, Any], decision_candidate_set: dict[str, Any] | None = None) -> None:
    required = ("decision_impact_analysis_version", "decision_impact_analysis_id", "decision_candidate_set_id", "impact_items", "highest_readiness_gain_candidate_id", "highest_risk_reduction_candidate_id", "lowest_effort_candidate_id", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in analysis:
            raise ValueError(f"decision impact analysis missing required field: {key}")
    if analysis["decision_impact_analysis_version"] != DECISION_IMPACT_ANALYSIS_VERSION:
        raise ValueError("invalid decision impact analysis version")
    if not isinstance(analysis["decision_impact_analysis_id"], str) or not analysis["decision_impact_analysis_id"].startswith("decision-impact-analysis-"):
        raise ValueError("invalid decision impact analysis id")
    if not isinstance(analysis["impact_items"], list) or not analysis["impact_items"]:
        raise ValueError("decision impact analysis must include impact items")
    for item in analysis["impact_items"]:
        for field in ("decision_candidate_id", "readiness_gain", "risk_reduction", "evidence_gain", "approval_gain", "effort_score", "blocker_count"):
            if field not in item:
                raise ValueError(f"decision impact item missing {field}")
        for field in ("readiness_gain", "risk_reduction", "evidence_gain", "approval_gain", "effort_score", "blocker_count"):
            if not isinstance(item[field], int) or item[field] < 0:
                raise ValueError("decision impact numeric fields must be non-negative integers")
    if analysis["safety_metadata"] != _read_only_safety_metadata() or analysis["dry_run"] is not True or analysis["write_allowed"] is not False or analysis["automation_allowed"] is not False or analysis["writes"] != []:
        raise ValueError("decision impact analysis must be read-only")
    if decision_candidate_set is not None:
        validate_decision_candidate_set(decision_candidate_set)
        if analysis["decision_candidate_set_id"] != decision_candidate_set["decision_candidate_set_id"]:
            raise ValueError("decision impact analysis candidate set id mismatch")
        if analysis["decision_impact_analysis_id"] != make_decision_impact_analysis_id(decision_candidate_set):
            raise ValueError("decision impact analysis id is not deterministic")


def stable_decision_impact_analysis_json(analysis: dict[str, Any]) -> str:
    validate_decision_impact_analysis(analysis)
    return _stable_ruflo_json(analysis, indent=2) + "\n"


def parse_decision_impact_analysis_json(text: str) -> dict[str, Any]:
    import json as _json

    analysis = _json.loads(text)
    validate_decision_impact_analysis(analysis)
    return analysis


def _decision_ranking_score(candidate: dict[str, Any]) -> int:
    return (
        candidate["expected_readiness_gain"] * 4 +
        candidate["expected_risk_reduction"] * 3 +
        candidate["expected_evidence_gain"] * 2 +
        candidate["expected_approval_gain"] * 1 -
        candidate["effort_score"] * 2 -
        len(candidate["blockers"]) * 5
    )


def make_decision_ranking_id(candidate_set: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "formula": "readiness*4+risk*3+evidence*2+approval*1-effort*2-blockers*5",
        "version": DECISION_RANKING_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"decision-ranking-{digest}"


def collect_decision_ranking(decision_candidate_set: dict[str, Any] | None = None, decision_impact_analysis: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    candidate_set = decision_candidate_set or collect_decision_candidate_set()
    validate_decision_candidate_set(candidate_set)
    impact = decision_impact_analysis or collect_decision_impact_analysis(candidate_set)
    validate_decision_impact_analysis(impact, candidate_set)
    ranked = sorted(candidate_set["candidates"], key=lambda candidate: (-_decision_ranking_score(candidate), candidate["effort_score"], candidate["decision_candidate_id"]))
    ranked_candidates = [
        {
            "rank": index,
            "decision_candidate_id": candidate["decision_candidate_id"],
            "score": _decision_ranking_score(candidate),
            "priority": candidate["priority"],
            "title": candidate["title"],
            "execution_allowed": False,
        }
        for index, candidate in enumerate(ranked, start=1)
    ]
    ranking = {
        "decision_ranking_version": DECISION_RANKING_VERSION,
        "decision_ranking_id": make_decision_ranking_id(candidate_set),
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_impact_analysis_id": impact["decision_impact_analysis_id"],
        "ranked_candidates": ranked_candidates,
        "top_candidate_id": ranked_candidates[0]["decision_candidate_id"],
        "ranking_formula": {
            "readiness_gain_weight": 4,
            "risk_reduction_weight": 3,
            "evidence_gain_weight": 2,
            "approval_gain_weight": 1,
            "effort_penalty_weight": -2,
            "blocker_penalty": -5,
        },
        "recommended_next_action": "Review the top-ranked candidate before taking any remediation action.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_decision_ranking(ranking, candidate_set, impact)
    return ranking


def validate_decision_ranking(ranking: dict[str, Any], decision_candidate_set: dict[str, Any] | None = None, decision_impact_analysis: dict[str, Any] | None = None) -> None:
    required = ("decision_ranking_version", "decision_ranking_id", "decision_candidate_set_id", "ranked_candidates", "top_candidate_id", "ranking_formula", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in ranking:
            raise ValueError(f"decision ranking missing required field: {key}")
    if ranking["decision_ranking_version"] != DECISION_RANKING_VERSION:
        raise ValueError("invalid decision ranking version")
    if not isinstance(ranking["decision_ranking_id"], str) or not ranking["decision_ranking_id"].startswith("decision-ranking-"):
        raise ValueError("invalid decision ranking id")
    if not isinstance(ranking["ranked_candidates"], list) or not ranking["ranked_candidates"]:
        raise ValueError("decision ranking must include ranked candidates")
    if ranking["top_candidate_id"] != ranking["ranked_candidates"][0]["decision_candidate_id"]:
        raise ValueError("decision ranking top candidate must match first ranked candidate")
    for item in ranking["ranked_candidates"]:
        for field in ("rank", "decision_candidate_id", "score", "priority", "title", "execution_allowed"):
            if field not in item:
                raise ValueError(f"ranked decision candidate missing {field}")
        if item["execution_allowed"] is not False:
            raise ValueError("ranked decision candidates must not allow execution")
    formula = ranking["ranking_formula"]
    expected_formula = {
        "readiness_gain_weight": 4,
        "risk_reduction_weight": 3,
        "evidence_gain_weight": 2,
        "approval_gain_weight": 1,
        "effort_penalty_weight": -2,
        "blocker_penalty": -5,
    }
    if formula != expected_formula:
        raise ValueError("decision ranking formula mismatch")
    if ranking["safety_metadata"] != _read_only_safety_metadata() or ranking["dry_run"] is not True or ranking["write_allowed"] is not False or ranking["automation_allowed"] is not False or ranking["writes"] != []:
        raise ValueError("decision ranking must be read-only")
    if decision_candidate_set is not None:
        validate_decision_candidate_set(decision_candidate_set)
        if ranking["decision_candidate_set_id"] != decision_candidate_set["decision_candidate_set_id"]:
            raise ValueError("decision ranking candidate set id mismatch")
        if ranking["decision_ranking_id"] != make_decision_ranking_id(decision_candidate_set):
            raise ValueError("decision ranking id is not deterministic")
    if decision_impact_analysis is not None:
        validate_decision_impact_analysis(decision_impact_analysis, decision_candidate_set)


def stable_decision_ranking_json(ranking: dict[str, Any]) -> str:
    validate_decision_ranking(ranking)
    return _stable_ruflo_json(ranking, indent=2) + "\n"


def parse_decision_ranking_json(text: str) -> dict[str, Any]:
    import json as _json

    ranking = _json.loads(text)
    validate_decision_ranking(ranking)
    return ranking


def make_operator_decision_review_id(candidate_set: dict[str, Any], impact: dict[str, Any], ranking: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_impact_analysis_id": impact["decision_impact_analysis_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "version": OPERATOR_DECISION_REVIEW_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-decision-review-{digest}"


def collect_operator_decision_review(decision_candidate_set: dict[str, Any] | None = None, decision_impact_analysis: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    candidate_set = decision_candidate_set or collect_decision_candidate_set()
    validate_decision_candidate_set(candidate_set)
    impact = decision_impact_analysis or collect_decision_impact_analysis(candidate_set)
    validate_decision_impact_analysis(impact, candidate_set)
    ranking = decision_ranking or collect_decision_ranking(candidate_set, impact)
    validate_decision_ranking(ranking, candidate_set, impact)
    top = next(candidate for candidate in candidate_set["candidates"] if candidate["decision_candidate_id"] == ranking["top_candidate_id"])
    blockers = _normalize_implementation_branch_refs(list(top["blockers"]) + ["decision support does not authorize execution"])
    warnings = _normalize_implementation_branch_refs(["ranking is deterministic and local-only", "human review required before remediation action"])
    review = {
        "operator_decision_review_version": OPERATOR_DECISION_REVIEW_VERSION,
        "operator_decision_review_id": make_operator_decision_review_id(candidate_set, impact, ranking),
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_impact_analysis_id": impact["decision_impact_analysis_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "top_candidate_id": ranking["top_candidate_id"],
        "decision_recommendation": f"Focus next on: {top['title']}",
        "blockers": blockers,
        "warnings": warnings,
        "required_human_actions": _normalize_implementation_branch_refs(["review top decision candidate", "confirm remediation remains non-executable"]),
        "recommended_next_action": "Review the top-ranked remediation decision and decide whether to commit to that planning work next.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_decision_review(review, candidate_set, impact, ranking)
    return review


def validate_operator_decision_review(review: dict[str, Any], decision_candidate_set: dict[str, Any] | None = None, decision_impact_analysis: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None) -> None:
    required = ("operator_decision_review_version", "operator_decision_review_id", "decision_candidate_set_id", "decision_impact_analysis_id", "decision_ranking_id", "top_candidate_id", "decision_recommendation", "blockers", "warnings", "required_human_actions", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in review:
            raise ValueError(f"operator decision review missing required field: {key}")
    if review["operator_decision_review_version"] != OPERATOR_DECISION_REVIEW_VERSION:
        raise ValueError("invalid operator decision review version")
    if not isinstance(review["operator_decision_review_id"], str) or not review["operator_decision_review_id"].startswith("operator-decision-review-"):
        raise ValueError("invalid operator decision review id")
    for field in ("blockers", "warnings", "required_human_actions"):
        normalized = _normalize_implementation_branch_refs(review[field])
        if normalized != review[field] or not review[field]:
            raise ValueError(f"operator decision review {field} must be normalized and non-empty")
    if review["safety_metadata"] != _read_only_safety_metadata() or review["dry_run"] is not True or review["write_allowed"] is not False or review["automation_allowed"] is not False or review["writes"] != []:
        raise ValueError("operator decision review must be read-only")
    if all(item is not None for item in (decision_candidate_set, decision_impact_analysis, decision_ranking)):
        validate_decision_candidate_set(decision_candidate_set)
        validate_decision_impact_analysis(decision_impact_analysis, decision_candidate_set)
        validate_decision_ranking(decision_ranking, decision_candidate_set, decision_impact_analysis)
        if review["operator_decision_review_id"] != make_operator_decision_review_id(decision_candidate_set, decision_impact_analysis, decision_ranking):
            raise ValueError("operator decision review id is not deterministic")
        if review["top_candidate_id"] != decision_ranking["top_candidate_id"]:
            raise ValueError("operator decision review top candidate mismatch")


def stable_operator_decision_review_json(review: dict[str, Any]) -> str:
    validate_operator_decision_review(review)
    return _stable_ruflo_json(review, indent=2) + "\n"


def parse_operator_decision_review_json(text: str) -> dict[str, Any]:
    import json as _json

    review = _json.loads(text)
    validate_operator_decision_review(review)
    return review



def make_decision_score_breakdown_id(candidate_set: dict[str, Any], impact: dict[str, Any], ranking: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_impact_analysis_id": impact["decision_impact_analysis_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "version": DECISION_SCORE_BREAKDOWN_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"decision-score-breakdown-{digest}"


def _decision_candidate_score(candidate: dict[str, Any]) -> dict[str, Any]:
    readiness = candidate["expected_readiness_gain"] * 4
    risk = candidate["expected_risk_reduction"] * 3
    evidence = candidate["expected_evidence_gain"] * 2
    approval = candidate["expected_approval_gain"]
    effort = candidate["effort_score"] * -2
    blockers = len(candidate["blockers"]) * -5
    total = readiness + risk + evidence + approval + effort + blockers
    return {
        "decision_candidate_id": candidate["decision_candidate_id"],
        "readiness_gain_score": readiness,
        "risk_reduction_score": risk,
        "evidence_gain_score": evidence,
        "approval_gain_score": approval,
        "effort_penalty": effort,
        "blocker_penalty": blockers,
        "total_score": total,
        "score_explanation": f"{candidate['title']} scored {total} from readiness, risk, evidence, approval, effort, and blocker factors.",
    }


def collect_decision_score_breakdown(decision_candidate_set: dict[str, Any] | None = None, decision_impact_analysis: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    candidate_set = decision_candidate_set or collect_decision_candidate_set()
    validate_decision_candidate_set(candidate_set)
    impact = decision_impact_analysis or collect_decision_impact_analysis(candidate_set)
    validate_decision_impact_analysis(impact, candidate_set)
    ranking = decision_ranking or collect_decision_ranking(candidate_set, impact)
    validate_decision_ranking(ranking, candidate_set, impact)
    scores = [_decision_candidate_score(candidate) for candidate in candidate_set["candidates"]]
    ranking_scores = {item["decision_candidate_id"]: item["score"] for item in ranking["ranked_candidates"]}
    scores.sort(key=lambda item: (-item["total_score"], item["decision_candidate_id"]))
    breakdown = {
        "decision_score_breakdown_version": DECISION_SCORE_BREAKDOWN_VERSION,
        "decision_score_breakdown_id": make_decision_score_breakdown_id(candidate_set, impact, ranking),
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_impact_analysis_id": impact["decision_impact_analysis_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "scoring_formula": dict(ranking["ranking_formula"]),
        "candidate_scores": scores,
        "top_candidate_id": ranking["top_candidate_id"],
        "recommended_next_action": "Review the score breakdown to understand why the top recommendation won.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": {**dict(metadata or {}), "ranking_scores": ranking_scores},
        "writes": [],
    }
    validate_decision_score_breakdown(breakdown, candidate_set, impact, ranking)
    return breakdown


def validate_decision_score_breakdown(breakdown: dict[str, Any], decision_candidate_set: dict[str, Any] | None = None, decision_impact_analysis: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None) -> None:
    required = ("decision_score_breakdown_version", "decision_score_breakdown_id", "decision_ranking_id", "scoring_formula", "candidate_scores", "top_candidate_id", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in breakdown:
            raise ValueError(f"decision score breakdown missing required field: {key}")
    if breakdown["decision_score_breakdown_version"] != DECISION_SCORE_BREAKDOWN_VERSION:
        raise ValueError("invalid decision score breakdown version")
    if not isinstance(breakdown["decision_score_breakdown_id"], str) or not breakdown["decision_score_breakdown_id"].startswith("decision-score-breakdown-"):
        raise ValueError("invalid decision score breakdown id")
    expected_formula = {
        "readiness_gain_weight": 4,
        "risk_reduction_weight": 3,
        "evidence_gain_weight": 2,
        "approval_gain_weight": 1,
        "effort_penalty_weight": -2,
        "blocker_penalty": -5,
    }
    if breakdown["scoring_formula"] != expected_formula:
        raise ValueError("decision score breakdown formula mismatch")
    if not isinstance(breakdown["candidate_scores"], list) or not breakdown["candidate_scores"]:
        raise ValueError("decision score breakdown must include candidate scores")
    for item in breakdown["candidate_scores"]:
        for field in ("decision_candidate_id", "readiness_gain_score", "risk_reduction_score", "evidence_gain_score", "approval_gain_score", "effort_penalty", "blocker_penalty", "total_score", "score_explanation"):
            if field not in item:
                raise ValueError(f"decision candidate score missing {field}")
        expected_total = item["readiness_gain_score"] + item["risk_reduction_score"] + item["evidence_gain_score"] + item["approval_gain_score"] + item["effort_penalty"] + item["blocker_penalty"]
        if item["total_score"] != expected_total:
            raise ValueError("decision candidate score total mismatch")
    if breakdown["safety_metadata"] != _read_only_safety_metadata() or breakdown["dry_run"] is not True or breakdown["write_allowed"] is not False or breakdown["automation_allowed"] is not False or breakdown["writes"] != []:
        raise ValueError("decision score breakdown must be read-only")
    if all(item is not None for item in (decision_candidate_set, decision_impact_analysis, decision_ranking)):
        validate_decision_candidate_set(decision_candidate_set)
        validate_decision_impact_analysis(decision_impact_analysis, decision_candidate_set)
        validate_decision_ranking(decision_ranking, decision_candidate_set, decision_impact_analysis)
        if breakdown["decision_score_breakdown_id"] != make_decision_score_breakdown_id(decision_candidate_set, decision_impact_analysis, decision_ranking):
            raise ValueError("decision score breakdown id is not deterministic")
        if breakdown["top_candidate_id"] != decision_ranking["top_candidate_id"]:
            raise ValueError("decision score breakdown top candidate mismatch")


def stable_decision_score_breakdown_json(breakdown: dict[str, Any]) -> str:
    validate_decision_score_breakdown(breakdown)
    return _stable_ruflo_json(breakdown, indent=2) + "\n"


def parse_decision_score_breakdown_json(text: str) -> dict[str, Any]:
    import json as _json

    breakdown = _json.loads(text)
    validate_decision_score_breakdown(breakdown)
    return breakdown


def make_rejected_alternative_analysis_id(candidate_set: dict[str, Any], ranking: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "top_candidate_id": ranking["top_candidate_id"],
        "version": REJECTED_ALTERNATIVE_ANALYSIS_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"rejected-alternative-analysis-{digest}"


def collect_rejected_alternative_analysis(decision_candidate_set: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None, decision_score_breakdown: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    candidate_set = decision_candidate_set or collect_decision_candidate_set()
    validate_decision_candidate_set(candidate_set)
    impact = collect_decision_impact_analysis(candidate_set)
    ranking = decision_ranking or collect_decision_ranking(candidate_set, impact)
    validate_decision_ranking(ranking, candidate_set, impact)
    breakdown = decision_score_breakdown or collect_decision_score_breakdown(candidate_set, impact, ranking)
    validate_decision_score_breakdown(breakdown, candidate_set, impact, ranking)
    score_map = {item["decision_candidate_id"]: item["total_score"] for item in breakdown["candidate_scores"]}
    top_score = score_map[ranking["top_candidate_id"]]
    rejected = [candidate for candidate in candidate_set["candidates"] if candidate["decision_candidate_id"] != ranking["top_candidate_id"]]
    reasons = [
        {
            "decision_candidate_id": candidate["decision_candidate_id"],
            "reason": f"scored {top_score - score_map[candidate['decision_candidate_id']]} points below the top candidate",
        }
        for candidate in rejected
    ]
    blocker_impacts = [
        {
            "decision_candidate_id": candidate["decision_candidate_id"],
            "blocker_count": len(candidate["blockers"]),
            "blocker_penalty": len(candidate["blockers"]) * -5,
        }
        for candidate in rejected
    ]
    analysis = {
        "rejected_alternative_analysis_version": REJECTED_ALTERNATIVE_ANALYSIS_VERSION,
        "rejected_alternative_analysis_id": make_rejected_alternative_analysis_id(candidate_set, ranking),
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "decision_score_breakdown_id": breakdown["decision_score_breakdown_id"],
        "top_candidate_id": ranking["top_candidate_id"],
        "rejected_candidates": [candidate["decision_candidate_id"] for candidate in rejected],
        "rejection_reasons": reasons,
        "blocker_impacts": blocker_impacts,
        "recommended_next_action": "Review rejected alternatives to confirm the top recommendation is still the right next step.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_rejected_alternative_analysis(analysis, candidate_set, ranking, breakdown)
    return analysis


def validate_rejected_alternative_analysis(analysis: dict[str, Any], decision_candidate_set: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None, decision_score_breakdown: dict[str, Any] | None = None) -> None:
    required = ("rejected_alternative_analysis_version", "rejected_alternative_analysis_id", "top_candidate_id", "rejected_candidates", "rejection_reasons", "blocker_impacts", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in analysis:
            raise ValueError(f"rejected alternative analysis missing required field: {key}")
    if analysis["rejected_alternative_analysis_version"] != REJECTED_ALTERNATIVE_ANALYSIS_VERSION:
        raise ValueError("invalid rejected alternative analysis version")
    if not isinstance(analysis["rejected_alternative_analysis_id"], str) or not analysis["rejected_alternative_analysis_id"].startswith("rejected-alternative-analysis-"):
        raise ValueError("invalid rejected alternative analysis id")
    if not isinstance(analysis["rejected_candidates"], list) or not analysis["rejected_candidates"]:
        raise ValueError("rejected alternative analysis must include rejected candidates")
    if not isinstance(analysis["rejection_reasons"], list) or len(analysis["rejection_reasons"]) != len(analysis["rejected_candidates"]):
        raise ValueError("rejected alternative reasons must match rejected candidates")
    if not isinstance(analysis["blocker_impacts"], list) or len(analysis["blocker_impacts"]) != len(analysis["rejected_candidates"]):
        raise ValueError("rejected alternative blocker impacts must match rejected candidates")
    if analysis["safety_metadata"] != _read_only_safety_metadata() or analysis["dry_run"] is not True or analysis["write_allowed"] is not False or analysis["automation_allowed"] is not False or analysis["writes"] != []:
        raise ValueError("rejected alternative analysis must be read-only")
    if all(item is not None for item in (decision_candidate_set, decision_ranking, decision_score_breakdown)):
        validate_decision_candidate_set(decision_candidate_set)
        validate_decision_ranking(decision_ranking, decision_candidate_set)
        validate_decision_score_breakdown(decision_score_breakdown)
        if analysis["rejected_alternative_analysis_id"] != make_rejected_alternative_analysis_id(decision_candidate_set, decision_ranking):
            raise ValueError("rejected alternative analysis id is not deterministic")
        if analysis["top_candidate_id"] != decision_ranking["top_candidate_id"]:
            raise ValueError("rejected alternative top candidate mismatch")


def stable_rejected_alternative_analysis_json(analysis: dict[str, Any]) -> str:
    validate_rejected_alternative_analysis(analysis)
    return _stable_ruflo_json(analysis, indent=2) + "\n"


def parse_rejected_alternative_analysis_json(text: str) -> dict[str, Any]:
    import json as _json

    analysis = _json.loads(text)
    validate_rejected_alternative_analysis(analysis)
    return analysis


def make_decision_assumption_ledger_id(candidate_set: dict[str, Any], ranking: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "version": DECISION_ASSUMPTION_LEDGER_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"decision-assumption-ledger-{digest}"


def collect_decision_assumption_ledger(decision_candidate_set: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None, operator_decision_review: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    candidate_set = decision_candidate_set or collect_decision_candidate_set()
    validate_decision_candidate_set(candidate_set)
    impact = collect_decision_impact_analysis(candidate_set)
    ranking = decision_ranking or collect_decision_ranking(candidate_set, impact)
    validate_decision_ranking(ranking, candidate_set, impact)
    review = operator_decision_review or collect_operator_decision_review(candidate_set, impact, ranking)
    validate_operator_decision_review(review, candidate_set, impact, ranking)
    ledger = {
        "decision_assumption_ledger_version": DECISION_ASSUMPTION_LEDGER_VERSION,
        "decision_assumption_ledger_id": make_decision_assumption_ledger_id(candidate_set, ranking),
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "operator_decision_review_id": review["operator_decision_review_id"],
        "assumptions": _normalize_implementation_branch_refs([
            "readiness gain estimates come from the remediation priority queue",
            "risk reduction is deterministic by remediation priority",
            "evidence and approval gains use required item counts",
            "blocked real actions remain prohibited",
        ]),
        "weak_assumptions": _normalize_implementation_branch_refs([
            "readiness gain estimates are planning estimates only",
            "no live market or execution evidence is collected",
        ]),
        "required_validation": _normalize_implementation_branch_refs([
            "human review of top candidate",
            "confirm remediation remains non-executable",
            "refresh decision ranking after evidence changes",
        ]),
        "recommended_next_action": "Validate assumptions before using the recommendation to plan remediation work.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_decision_assumption_ledger(ledger, candidate_set, ranking, review)
    return ledger


def validate_decision_assumption_ledger(ledger: dict[str, Any], decision_candidate_set: dict[str, Any] | None = None, decision_ranking: dict[str, Any] | None = None, operator_decision_review: dict[str, Any] | None = None) -> None:
    required = ("decision_assumption_ledger_version", "decision_assumption_ledger_id", "assumptions", "weak_assumptions", "required_validation", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in ledger:
            raise ValueError(f"decision assumption ledger missing required field: {key}")
    if ledger["decision_assumption_ledger_version"] != DECISION_ASSUMPTION_LEDGER_VERSION:
        raise ValueError("invalid decision assumption ledger version")
    if not isinstance(ledger["decision_assumption_ledger_id"], str) or not ledger["decision_assumption_ledger_id"].startswith("decision-assumption-ledger-"):
        raise ValueError("invalid decision assumption ledger id")
    for field in ("assumptions", "weak_assumptions", "required_validation"):
        normalized = _normalize_implementation_branch_refs(ledger[field])
        if normalized != ledger[field] or not ledger[field]:
            raise ValueError(f"decision assumption ledger {field} must be normalized and non-empty")
    if ledger["safety_metadata"] != _read_only_safety_metadata() or ledger["dry_run"] is not True or ledger["write_allowed"] is not False or ledger["automation_allowed"] is not False or ledger["writes"] != []:
        raise ValueError("decision assumption ledger must be read-only")
    if decision_candidate_set is not None and decision_ranking is not None:
        validate_decision_candidate_set(decision_candidate_set)
        validate_decision_ranking(decision_ranking, decision_candidate_set)
        if ledger["decision_assumption_ledger_id"] != make_decision_assumption_ledger_id(decision_candidate_set, decision_ranking):
            raise ValueError("decision assumption ledger id is not deterministic")
    if operator_decision_review is not None:
        validate_operator_decision_review(operator_decision_review)


def stable_decision_assumption_ledger_json(ledger: dict[str, Any]) -> str:
    validate_decision_assumption_ledger(ledger)
    return _stable_ruflo_json(ledger, indent=2) + "\n"


def parse_decision_assumption_ledger_json(text: str) -> dict[str, Any]:
    import json as _json

    ledger = _json.loads(text)
    validate_decision_assumption_ledger(ledger)
    return ledger


def make_operator_decision_trace_package_id(ranking: dict[str, Any], breakdown: dict[str, Any], rejected: dict[str, Any], ledger: dict[str, Any], review: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "assumption_ledger_id": ledger["decision_assumption_ledger_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "operator_decision_review_id": review["operator_decision_review_id"],
        "rejected_alternative_analysis_id": rejected["rejected_alternative_analysis_id"],
        "score_breakdown_id": breakdown["decision_score_breakdown_id"],
        "version": OPERATOR_DECISION_TRACE_PACKAGE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-decision-trace-package-{digest}"


def collect_operator_decision_trace_package(decision_ranking: dict[str, Any] | None = None, decision_score_breakdown: dict[str, Any] | None = None, rejected_alternative_analysis: dict[str, Any] | None = None, decision_assumption_ledger: dict[str, Any] | None = None, operator_decision_review: dict[str, Any] | None = None, decision_candidate_set: dict[str, Any] | None = None, decision_impact_analysis: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    candidate_set = decision_candidate_set or collect_decision_candidate_set()
    validate_decision_candidate_set(candidate_set)
    impact = decision_impact_analysis or collect_decision_impact_analysis(candidate_set)
    validate_decision_impact_analysis(impact, candidate_set)
    ranking = decision_ranking or collect_decision_ranking(candidate_set, impact)
    validate_decision_ranking(ranking, candidate_set, impact)
    breakdown = decision_score_breakdown or collect_decision_score_breakdown(candidate_set, impact, ranking)
    validate_decision_score_breakdown(breakdown, candidate_set, impact, ranking)
    rejected = rejected_alternative_analysis or collect_rejected_alternative_analysis(candidate_set, ranking, breakdown)
    validate_rejected_alternative_analysis(rejected, candidate_set, ranking, breakdown)
    review = operator_decision_review or collect_operator_decision_review(candidate_set, impact, ranking)
    validate_operator_decision_review(review, candidate_set, impact, ranking)
    ledger = decision_assumption_ledger or collect_decision_assumption_ledger(candidate_set, ranking, review)
    validate_decision_assumption_ledger(ledger, candidate_set, ranking, review)
    top_score = next(item for item in breakdown["candidate_scores"] if item["decision_candidate_id"] == ranking["top_candidate_id"])
    package = {
        "operator_decision_trace_package_version": OPERATOR_DECISION_TRACE_PACKAGE_VERSION,
        "operator_decision_trace_package_id": make_operator_decision_trace_package_id(ranking, breakdown, rejected, ledger, review),
        "decision_candidate_set_id": candidate_set["decision_candidate_set_id"],
        "decision_ranking_id": ranking["decision_ranking_id"],
        "score_breakdown_id": breakdown["decision_score_breakdown_id"],
        "rejected_alternative_analysis_id": rejected["rejected_alternative_analysis_id"],
        "assumption_ledger_id": ledger["decision_assumption_ledger_id"],
        "operator_decision_review_id": review["operator_decision_review_id"],
        "top_candidate_id": ranking["top_candidate_id"],
        "explanation_summary": f"The top candidate won with score {top_score['total_score']} because readiness and risk gains outweighed effort and blocker penalties.",
        "blockers": list(review["blockers"]),
        "warnings": _normalize_implementation_branch_refs(list(review["warnings"]) + list(ledger["weak_assumptions"])),
        "required_human_actions": _normalize_implementation_branch_refs(list(review["required_human_actions"]) + list(ledger["required_validation"])),
        "recommended_next_action": "Use this trace to review why Link recommended the top remediation decision.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_decision_trace_package(package, ranking, breakdown, rejected, ledger, review)
    return package


def validate_operator_decision_trace_package(package: dict[str, Any], decision_ranking: dict[str, Any] | None = None, decision_score_breakdown: dict[str, Any] | None = None, rejected_alternative_analysis: dict[str, Any] | None = None, decision_assumption_ledger: dict[str, Any] | None = None, operator_decision_review: dict[str, Any] | None = None) -> None:
    required = ("operator_decision_trace_package_version", "operator_decision_trace_package_id", "decision_ranking_id", "score_breakdown_id", "rejected_alternative_analysis_id", "assumption_ledger_id", "top_candidate_id", "explanation_summary", "blockers", "warnings", "required_human_actions", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in package:
            raise ValueError(f"operator decision trace package missing required field: {key}")
    if package["operator_decision_trace_package_version"] != OPERATOR_DECISION_TRACE_PACKAGE_VERSION:
        raise ValueError("invalid operator decision trace package version")
    if not isinstance(package["operator_decision_trace_package_id"], str) or not package["operator_decision_trace_package_id"].startswith("operator-decision-trace-package-"):
        raise ValueError("invalid operator decision trace package id")
    for field in ("blockers", "warnings", "required_human_actions"):
        normalized = _normalize_implementation_branch_refs(package[field])
        if normalized != package[field] or not package[field]:
            raise ValueError(f"operator decision trace package {field} must be normalized and non-empty")
    if package["safety_metadata"] != _read_only_safety_metadata() or package["dry_run"] is not True or package["write_allowed"] is not False or package["automation_allowed"] is not False or package["writes"] != []:
        raise ValueError("operator decision trace package must be read-only")
    if all(item is not None for item in (decision_ranking, decision_score_breakdown, rejected_alternative_analysis, decision_assumption_ledger, operator_decision_review)):
        if package["operator_decision_trace_package_id"] != make_operator_decision_trace_package_id(decision_ranking, decision_score_breakdown, rejected_alternative_analysis, decision_assumption_ledger, operator_decision_review):
            raise ValueError("operator decision trace package id is not deterministic")
        if package["top_candidate_id"] != decision_ranking["top_candidate_id"]:
            raise ValueError("operator decision trace top candidate mismatch")


def stable_operator_decision_trace_package_json(package: dict[str, Any]) -> str:
    validate_operator_decision_trace_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_operator_decision_trace_package_json(text: str) -> dict[str, Any]:
    import json as _json

    package = _json.loads(text)
    validate_operator_decision_trace_package(package)
    return package



def _operator_action_top_candidate(candidate_set: dict[str, Any], top_candidate_id: str) -> dict[str, Any]:
    for candidate in candidate_set["candidates"]:
        if candidate["decision_candidate_id"] == top_candidate_id:
            return candidate
    raise ValueError("top decision candidate not found for operator action plan")


def make_operator_action_plan_preview_id(trace: dict[str, Any], review: dict[str, Any], plan: dict[str, Any], queue: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "operator_decision_trace_package_id": trace["operator_decision_trace_package_id"],
        "operator_decision_review_id": review["operator_decision_review_id"],
        "remediation_priority_queue_id": queue["remediation_priority_queue_id"],
        "simulation_remediation_plan_id": plan["simulation_remediation_plan_id"],
        "top_candidate_id": trace["top_candidate_id"],
        "version": OPERATOR_ACTION_PLAN_PREVIEW_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-action-plan-preview-{digest}"


def collect_operator_action_plan_preview(operator_decision_trace_package: dict[str, Any] | None = None, operator_decision_review: dict[str, Any] | None = None, simulation_remediation_plan: dict[str, Any] | None = None, remediation_priority_queue: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    """Convert the winning decision trace into a concrete non-executable task plan."""
    remediation_plan = simulation_remediation_plan or collect_simulation_remediation_plan()
    validate_simulation_remediation_plan(remediation_plan)
    graph = collect_remediation_dependency_graph(remediation_plan)
    queue = remediation_priority_queue or collect_remediation_priority_queue(remediation_plan, graph)
    validate_remediation_priority_queue(queue, remediation_plan, graph)
    candidate_set = collect_decision_candidate_set(remediation_plan, queue)
    impact = collect_decision_impact_analysis(candidate_set)
    ranking = collect_decision_ranking(candidate_set, impact)
    review = operator_decision_review or collect_operator_decision_review(candidate_set, impact, ranking)
    validate_operator_decision_review(review, candidate_set, impact, ranking)
    breakdown = collect_decision_score_breakdown(candidate_set, impact, ranking)
    rejected = collect_rejected_alternative_analysis(candidate_set, ranking, breakdown)
    ledger = collect_decision_assumption_ledger(candidate_set, ranking, review)
    trace = operator_decision_trace_package or collect_operator_decision_trace_package(ranking, breakdown, rejected, ledger, review, candidate_set, impact)
    validate_operator_decision_trace_package(trace, ranking, breakdown, rejected, ledger, review)
    top_candidate = _operator_action_top_candidate(candidate_set, trace["top_candidate_id"])
    top_step = next((step for step in remediation_plan["remediation_steps"] if step["remediation_step_id"] in top_candidate["source_refs"]), remediation_plan["remediation_steps"][0])
    required_evidence = _normalize_implementation_branch_refs(list(top_step["required_evidence"]) + list(top_candidate["source_refs"][:2]))
    required_approvals = _normalize_implementation_branch_refs(list(top_step["required_approvals"]) + ["human approval before execution planning"])
    preview = {
        "operator_action_plan_preview_version": OPERATOR_ACTION_PLAN_PREVIEW_VERSION,
        "operator_action_plan_preview_id": make_operator_action_plan_preview_id(trace, review, remediation_plan, queue),
        "operator_decision_trace_package_id": trace["operator_decision_trace_package_id"],
        "operator_decision_review_id": review["operator_decision_review_id"],
        "simulation_remediation_plan_id": remediation_plan["simulation_remediation_plan_id"],
        "remediation_priority_queue_id": queue["remediation_priority_queue_id"],
        "top_candidate_id": trace["top_candidate_id"],
        "action_title": top_candidate["title"],
        "action_summary": f"Plan the next non-executable remediation slice: {top_candidate['title']}",
        "affected_modules": _normalize_implementation_branch_refs(["decision", "link-router", "operator", "simulation"]),
        "likely_affected_files": _normalize_implementation_branch_refs(["link.py", "link_modes/growth/link_growth_console.py", "tests/test_growth_pipeline.py"]),
        "required_evidence": required_evidence,
        "required_approvals": required_approvals,
        "expected_tests": _normalize_implementation_branch_refs([
            "git diff --check -- link.py link_modes/growth/link_growth_console.py tests/test_growth_pipeline.py",
            "python3 -m py_compile link.py link_modes/growth/link_growth_console.py tests/test_growth_pipeline.py",
            "PYTHONDONTWRITEBYTECODE=1 python3 tests/test_growth_pipeline.py",
            "PYTHONDONTWRITEBYTECODE=1 python3 link_healthcheck.py",
        ]),
        "rollback_plan": _normalize_implementation_branch_refs([
            "do not run the planned action automatically",
            "revert only the planned source/test edits if review rejects the slice",
            "keep safe-link-latest unchanged until verification and commit approval",
        ]),
        "execution_allowed": False,
        "recommended_next_action": "Review this action plan, then decide whether to create an approved implementation slice.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_action_plan_preview(preview, trace, review, remediation_plan, queue)
    return preview


def validate_operator_action_plan_preview(preview: dict[str, Any], operator_decision_trace_package: dict[str, Any] | None = None, operator_decision_review: dict[str, Any] | None = None, simulation_remediation_plan: dict[str, Any] | None = None, remediation_priority_queue: dict[str, Any] | None = None) -> None:
    required = ("operator_action_plan_preview_version", "operator_action_plan_preview_id", "operator_decision_trace_package_id", "operator_decision_review_id", "simulation_remediation_plan_id", "remediation_priority_queue_id", "top_candidate_id", "action_title", "action_summary", "affected_modules", "likely_affected_files", "required_evidence", "required_approvals", "expected_tests", "rollback_plan", "execution_allowed", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in preview:
            raise ValueError(f"operator action plan preview missing required field: {key}")
    if preview["operator_action_plan_preview_version"] != OPERATOR_ACTION_PLAN_PREVIEW_VERSION:
        raise ValueError("invalid operator action plan preview version")
    if not isinstance(preview["operator_action_plan_preview_id"], str) or not preview["operator_action_plan_preview_id"].startswith("operator-action-plan-preview-"):
        raise ValueError("invalid operator action plan preview id")
    for field in ("action_title", "action_summary", "recommended_next_action", "top_candidate_id"):
        if not isinstance(preview[field], str) or not preview[field].strip():
            raise ValueError(f"operator action plan preview {field} must be non-empty")
    for field in ("affected_modules", "likely_affected_files", "required_evidence", "required_approvals", "expected_tests", "rollback_plan"):
        if _normalize_implementation_branch_refs(preview[field]) != preview[field] or not preview[field]:
            raise ValueError(f"operator action plan preview {field} must be normalized and non-empty")
    if preview["execution_allowed"] is not False:
        raise ValueError("operator action plan preview must not allow execution")
    if preview["safety_metadata"] != _read_only_safety_metadata() or preview["dry_run"] is not True or preview["write_allowed"] is not False or preview["automation_allowed"] is not False or preview["writes"] != []:
        raise ValueError("operator action plan preview must be read-only")
    if all(item is not None for item in (operator_decision_trace_package, operator_decision_review, simulation_remediation_plan, remediation_priority_queue)):
        validate_operator_decision_trace_package(operator_decision_trace_package)
        validate_operator_decision_review(operator_decision_review)
        validate_simulation_remediation_plan(simulation_remediation_plan)
        validate_remediation_priority_queue(remediation_priority_queue, simulation_remediation_plan)
        expected_id = make_operator_action_plan_preview_id(operator_decision_trace_package, operator_decision_review, simulation_remediation_plan, remediation_priority_queue)
        if preview["operator_action_plan_preview_id"] != expected_id:
            raise ValueError("operator action plan preview id is not deterministic")
        if preview["top_candidate_id"] != operator_decision_trace_package["top_candidate_id"]:
            raise ValueError("operator action plan preview top candidate mismatch")


def stable_operator_action_plan_preview_json(preview: dict[str, Any]) -> str:
    validate_operator_action_plan_preview(preview)
    return _stable_ruflo_json(preview, indent=2) + "\n"


def parse_operator_action_plan_preview_json(text: str) -> dict[str, Any]:
    import json as _json

    preview = _json.loads(text)
    validate_operator_action_plan_preview(preview)
    return preview


def make_operator_action_evidence_checklist_id(action_plan_preview: dict[str, Any], evidence_items: list[str]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "evidence_items": evidence_items,
        "operator_action_plan_preview_id": action_plan_preview["operator_action_plan_preview_id"],
        "version": OPERATOR_ACTION_EVIDENCE_CHECKLIST_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"operator-action-evidence-checklist-{digest}"


def collect_operator_action_evidence_checklist(operator_action_plan_preview: dict[str, Any] | None = None, *, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    preview = operator_action_plan_preview or collect_operator_action_plan_preview()
    validate_operator_action_plan_preview(preview)
    evidence_items = _normalize_implementation_branch_refs(list(preview["required_evidence"]) + list(preview["expected_tests"]))
    missing_evidence = _normalize_implementation_branch_refs(list(preview["required_evidence"]))
    checklist = {
        "operator_action_evidence_checklist_version": OPERATOR_ACTION_EVIDENCE_CHECKLIST_VERSION,
        "operator_action_evidence_checklist_id": make_operator_action_evidence_checklist_id(preview, evidence_items),
        "operator_action_plan_preview_id": preview["operator_action_plan_preview_id"],
        "evidence_items": evidence_items,
        "missing_evidence": missing_evidence,
        "evidence_status": "blocked" if missing_evidence else "ready",
        "blockers": _normalize_implementation_branch_refs(["required evidence has not been collected for this action plan"] if missing_evidence else []),
        "recommended_next_action": "Collect or confirm the required evidence before any execution-capable slice.",
        "safety_metadata": _read_only_safety_metadata(),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_operator_action_evidence_checklist(checklist, preview)
    return checklist


def validate_operator_action_evidence_checklist(checklist: dict[str, Any], operator_action_plan_preview: dict[str, Any] | None = None) -> None:
    required = ("operator_action_evidence_checklist_version", "operator_action_evidence_checklist_id", "operator_action_plan_preview_id", "evidence_items", "missing_evidence", "evidence_status", "blockers", "recommended_next_action", "safety_metadata", "dry_run", "write_allowed", "automation_allowed", "writes")
    for key in required:
        if key not in checklist:
            raise ValueError(f"operator action evidence checklist missing required field: {key}")
    if checklist["operator_action_evidence_checklist_version"] != OPERATOR_ACTION_EVIDENCE_CHECKLIST_VERSION:
        raise ValueError("invalid operator action evidence checklist version")
    if not isinstance(checklist["operator_action_evidence_checklist_id"], str) or not checklist["operator_action_evidence_checklist_id"].startswith("operator-action-evidence-checklist-"):
        raise ValueError("invalid operator action evidence checklist id")
    for field in ("evidence_items", "missing_evidence", "blockers"):
        if _normalize_implementation_branch_refs(checklist[field]) != checklist[field]:
            raise ValueError(f"operator action evidence checklist {field} must be normalized")
    if not checklist["evidence_items"]:
        raise ValueError("operator action evidence checklist must include evidence items")
    if checklist["evidence_status"] not in {"blocked", "ready"}:
        raise ValueError("invalid operator action evidence status")
    if checklist["missing_evidence"] and checklist["evidence_status"] != "blocked":
        raise ValueError("operator action evidence must be blocked when evidence is missing")
    if checklist["safety_metadata"] != _read_only_safety_metadata() or checklist["dry_run"] is not True or checklist["write_allowed"] is not False or checklist["automation_allowed"] is not False or checklist["writes"] != []:
        raise ValueError("operator action evidence checklist must be read-only")
    if operator_action_plan_preview is not None:
        validate_operator_action_plan_preview(operator_action_plan_preview)
        if checklist["operator_action_plan_preview_id"] != operator_action_plan_preview["operator_action_plan_preview_id"]:
            raise ValueError("operator action evidence checklist plan id mismatch")
        if checklist["operator_action_evidence_checklist_id"] != make_operator_action_evidence_checklist_id(operator_action_plan_preview, checklist["evidence_items"]):
            raise ValueError("operator action evidence checklist id is not deterministic")


